import { useEffect, lazy, Suspense } from 'react';
import { Routes, Route, Navigate, useLocation } from 'react-router-dom';
import { LogsProvider } from './context/LogsContext';
import { WorkspaceProvider } from './context/WorkspaceContext';
import { SyncStatusProvider } from './context/SyncStatusContext';
import { useUIStore } from './store/uiStore';
import MobileGate from './components/MobileGate';
import { useState } from 'react';
import ProtectedRoute from './components/common/ProtectedRoute';
import { ConfigurationProvider } from './context/ConfigurationContext';
import ErrorBoundary from './components/ErrorBoundary';

// Layouts
import DashboardLayout from './layouts/DashboardLayout';

// Pages — eagerly load the two most-visited routes; lazy-load the rest
import ProjectsPage     from './pages/ProjectsPage';
import LoginPage        from './pages/LoginPage';

const ExplorePage        = lazy(() => import('./pages/ExplorePage'));
const OntologyPage       = lazy(() => import('./pages/OntologyPage'));
const CreateProjectPage  = lazy(() => import('./pages/CreateProjectPage'));
const EditProjectPage    = lazy(() => import('./pages/EditProjectPage'));
const ProjectConfigPage  = lazy(() => import('./pages/ProjectConfigPage'));
const ProjectJobsPage    = lazy(() => import('./pages/ProjectJobsPage'));
const SettingsPage       = lazy(() => import('./pages/SettingsPage'));
const GlobalConfigPage   = lazy(() => import('./pages/GlobalConfigPage'));
const ProjectDetailPage  = lazy(() => import('./pages/ProjectDetailPage'));
const ComparatorPage     = lazy(() => import('./pages/ComparatorPage'));
const VersionControlPage = lazy(() => import('./pages/VersionControlPage'));
const ForgotPasswordPage = lazy(() => import('./pages/ForgotPasswordPage'));
const ResetPasswordPage  = lazy(() => import('./pages/ResetPasswordPage'));
const UnauthorizedPage   = lazy(() => import('./pages/UnauthorizedPage'));
const AskAiPage          = lazy(() => import('./pages/AskAiPage'));
const GovernanceSuitePage = lazy(() => import('./pages/GovernanceSuitePage'));
const DriftMonitoringPage = lazy(() => import('./pages/DriftMonitoringPage'));

// Old route names redirect to the new ones, keeping any ?query (bookmarks, links in run reports).
function RedirectKeepQuery({ to }) {
  const { search } = useLocation();
  return <Navigate to={`${to}${search}`} replace />;
}

function PageFallback() {
  return (
    <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', height: '100%', color: 'var(--text-tertiary)', fontSize: 13 }}>
      Loading…
    </div>
  );
}

export default function App() {
  const [isMobile, setIsMobile] = useState(false);
  const location = useLocation();
  const hasHydrated = useUIStore(state => state.hasHydrated);
  const lastNavigatedPath = useUIStore(state => state.lastNavigatedPath);
  const setLastNavigatedPath = useUIStore(state => state.setLastNavigatedPath);

  useEffect(() => {
    const checkMobile = () => {
      // Basic mobile detection: checking width and user agent
      const isMobileDevice = /Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(navigator.userAgent);
      setIsMobile(isMobileDevice);
    };

    checkMobile();
    window.addEventListener('resize', checkMobile);
    return () => window.removeEventListener('resize', checkMobile);
  }, []);

  useEffect(() => {
    if (!hasHydrated) return;
    const nextPath = `${location.pathname}${location.search}${location.hash}`;
    if (nextPath === lastNavigatedPath) return;
    setLastNavigatedPath(nextPath || '/projects');
  }, [
    hasHydrated,
    location.pathname,
    location.search,
    location.hash,
    lastNavigatedPath,
    setLastNavigatedPath,
  ]);

  if (isMobile) {
    return <MobileGate />;
  }

  return (
    <div style={{ minHeight: '100vh' }}>
      <Routes>
        <Route path="/login" element={<LoginPage />} />

        {/* Public: Password reset flow */}
        <Route path="/auth/forgot-password" element={<Suspense fallback={<PageFallback />}><ForgotPasswordPage /></Suspense>} />
        <Route path="/auth/reset-password/:token" element={<Suspense fallback={<PageFallback />}><ResetPasswordPage /></Suspense>} />
        <Route path="/unauthorized" element={<Suspense fallback={<PageFallback />}><UnauthorizedPage /></Suspense>} />

        {/* Protected: All app routes — auto-login handles auth transparently */}
        <Route element={<ProtectedRoute />}>
          <Route element={
            <ConfigurationProvider>
              <WorkspaceProvider>
                <LogsProvider>
                  <SyncStatusProvider>
                    <DashboardLayout />
                  </SyncStatusProvider>
                </LogsProvider>
              </WorkspaceProvider>
            </ConfigurationProvider>
          }>
            <Route index element={<Navigate to="/projects" replace />} />
            <Route path="/map"           element={<ErrorBoundary><Suspense fallback={<PageFallback />}><ExplorePage /></Suspense></ErrorBoundary>} />
            <Route path="/explore"       element={<RedirectKeepQuery to="/map" />} />
            <Route path="/ask"           element={<ErrorBoundary><Suspense fallback={<PageFallback />}><AskAiPage /></Suspense></ErrorBoundary>} />
            <Route path="/ontology"          element={<ErrorBoundary><Suspense fallback={<PageFallback />}><OntologyPage mode="explorer" /></Suspense></ErrorBoundary>} />
            <Route path="/metric-comparator" element={<ErrorBoundary><Suspense fallback={<PageFallback />}><OntologyPage mode="comparator" /></Suspense></ErrorBoundary>} />
            <Route path="/blast-radius"      element={<ErrorBoundary><Suspense fallback={<PageFallback />}><OntologyPage mode="blast-radius" /></Suspense></ErrorBoundary>} />
            <Route path="/drift"             element={<ErrorBoundary><Suspense fallback={<PageFallback />}><DriftMonitoringPage /></Suspense></ErrorBoundary>} />
            <Route path="/drift-monitoring"  element={<RedirectKeepQuery to="/drift" />} />
            <Route path="/data-monitoring"   element={<RedirectKeepQuery to="/drift" />} />
            <Route path="/reverse-sync"      element={<ErrorBoundary><Suspense fallback={<PageFallback />}><GovernanceSuitePage mode="reverse-sync" /></Suspense></ErrorBoundary>} />
            <Route path="/bi-truth"          element={<ErrorBoundary><Suspense fallback={<PageFallback />}><GovernanceSuitePage mode="bi-truth" /></Suspense></ErrorBoundary>} />
            <Route path="/cross-platform"    element={<ErrorBoundary><Suspense fallback={<PageFallback />}><GovernanceSuitePage mode="cross-platform" /></Suspense></ErrorBoundary>} />
            <Route path="/projects"      element={<ProjectsPage />} />
            <Route path="/projects/new"  element={<ErrorBoundary><Suspense fallback={<PageFallback />}><CreateProjectPage /></Suspense></ErrorBoundary>} />
            <Route path="/projects/:id" element={<ErrorBoundary><Suspense fallback={<PageFallback />}><ProjectDetailPage /></Suspense></ErrorBoundary>} />
            <Route path="/projects/:id/edit" element={<ErrorBoundary><Suspense fallback={<PageFallback />}><EditProjectPage /></Suspense></ErrorBoundary>} />
            <Route path="/projects/:id/config" element={<ErrorBoundary><Suspense fallback={<PageFallback />}><ProjectConfigPage /></Suspense></ErrorBoundary>} />
            <Route path="/runs"          element={<ErrorBoundary><Suspense fallback={<PageFallback />}><ProjectJobsPage /></Suspense></ErrorBoundary>} />
            <Route path="/jobs"          element={<RedirectKeepQuery to="/runs" />} />
            <Route path="/model-mapping" element={<Navigate to="/projects/new" replace />} />
            <Route path="/compare"       element={<ErrorBoundary><Suspense fallback={<PageFallback />}><ComparatorPage /></Suspense></ErrorBoundary>} />
            <Route path="/comparator"    element={<RedirectKeepQuery to="/compare" />} />
            <Route element={<ProtectedRoute requiredRole="admin" />}>
              <Route path="/settings"      element={<ErrorBoundary><Suspense fallback={<PageFallback />}><SettingsPage /></Suspense></ErrorBoundary>} />
              <Route path="/global-config" element={<ErrorBoundary><Suspense fallback={<PageFallback />}><GlobalConfigPage /></Suspense></ErrorBoundary>} />
            </Route>
            <Route path="/history"       element={<ErrorBoundary><Suspense fallback={<PageFallback />}><VersionControlPage /></Suspense></ErrorBoundary>} />
            <Route path="/version-control" element={<RedirectKeepQuery to="/history" />} />
          </Route>
        </Route>

        {/* Fallback */}
        <Route path="*" element={<Navigate to="/projects" replace />} />
      </Routes>
    </div>
  );
}

import { useState, useEffect, useRef, useMemo } from 'react';
import {
    Search,
    Map,
    GitCommit,
    Bell,
    Settings,
    Layers,
    Plus,
    PlayCircle,
    Sparkles,
    BookOpen,
    FolderOpen,
    Command,
} from 'lucide-react';
import { getSmartQueryError, matchesSmartQuery } from './common/smartSearchQuery.js';

const COMMANDS = [
    { id: 'new-project', label: 'New project', icon: Plus, action: 'newProject', category: 'Actions' },
    { id: 'ask', label: 'Ask AI a question', icon: Sparkles, action: 'askAi', category: 'Actions' },
    { id: 'logs', label: 'Logs & activity', icon: Bell, action: 'toggleLogs', category: 'Actions' },
    { id: 'projects', label: 'Projects', icon: FolderOpen, action: 'openModel', category: 'Go to' },
    { id: 'runs', label: 'Runs', icon: PlayCircle, action: 'openRuns', category: 'Go to' },
    { id: 'ontology', label: 'Ontology', icon: BookOpen, action: 'openOntology', category: 'Go to' },
    { id: 'repo-map', label: 'Model map', icon: Map, action: 'toggleRepoMap', category: 'Go to' },
    { id: 'version', label: 'History', icon: GitCommit, action: 'toggleVersionControl', category: 'Go to' },
    { id: 'settings', label: 'Settings', icon: Settings, action: 'toggleConnections', category: 'Go to' },
];

export default function CommandPalette({
    isOpen,
    onClose,
    onAction,
    models = [],
    queryValue,
    onQueryChange,
}) {
    const [query, setQuery] = useState('');
    const [selectedIndex, setSelectedIndex] = useState(0);
    const inputRef = useRef(null);

    const queryText = queryValue ?? query;
    const setQueryText = onQueryChange ?? setQuery;

    useEffect(() => {
        if (isOpen) {
            setSelectedIndex(0);
            if (!onQueryChange) setQuery('');
            setTimeout(() => inputRef.current?.focus(), 50);
        }
    }, [isOpen, onQueryChange]);

    const regexError = useMemo(() => {
        return getSmartQueryError(queryText);
    }, [queryText]);

    // Global Ctrl+K shortcut
    useEffect(() => {
        const handler = (e) => {
            if ((e.ctrlKey || e.metaKey) && e.key === 'k') {
                e.preventDefault();
                if (isOpen) onClose();
                else onAction?.('openPalette');
            }
            if (e.key === 'Escape' && isOpen) {
                onClose();
            }
        };
        window.addEventListener('keydown', handler);
        return () => window.removeEventListener('keydown', handler);
    }, [isOpen, onClose, onAction]);

    const results = useMemo(() => {
        const q = String(queryText || '').trim();
        const items = [];

        const match = (text) => {
            if (!q) return true;
            if (regexError) return false;
            return matchesSmartQuery(text, q);
        };

        // Search models
        if (q) {
            const matchedModels = models
                .filter(m => match(`${m.name || ''} ${m.id || ''}`))
                .slice(0, 5)
                .map(m => ({
                    id: `model-${m.id}`,
                    label: m.name || m.id,
                    icon: Layers,
                    action: 'openModel',
                    payload: m.id,
                    category: 'Models',
                }));
            items.push(...matchedModels);
        }

        // Search commands
        const matchedCommands = COMMANDS.filter(c =>
            !q || match(`${c.label || ''} ${c.category || ''}`)
        );
        items.push(...matchedCommands);

        return items;
    }, [queryText, models, regexError]);

    useEffect(() => {
        setSelectedIndex(0);
    }, [queryText]);

    const handleSelect = (item) => {
        onClose();
        if (item.action === 'openModel') {
            onAction?.('openModel', item.payload);
        } else {
            onAction?.(item.action);
        }
    };

    const handleKeyDown = (e) => {
        if (e.key === 'ArrowDown') {
            e.preventDefault();
            setSelectedIndex(i => Math.min(i + 1, results.length - 1));
        } else if (e.key === 'ArrowUp') {
            e.preventDefault();
            setSelectedIndex(i => Math.max(i - 1, 0));
        } else if (e.key === 'Enter' && results[selectedIndex]) {
            e.preventDefault();
            handleSelect(results[selectedIndex]);
        }
    };

    if (!isOpen) return null;

    // Group results by category
    const grouped = {};
    results.forEach(r => {
        if (!grouped[r.category]) grouped[r.category] = [];
        grouped[r.category].push(r);
    });

    let flatIndex = 0;

    return (
        <div
            className="fixed inset-0 z-[100] flex items-start justify-center pt-[15vh]"
            style={{ background: 'var(--bg-backdrop)', backdropFilter: 'blur(8px)' }}
            onClick={onClose}
        >
            <div
                className="w-full max-w-2xl rounded-2xl overflow-hidden shadow-2xl border border-main"
                style={{
                    background: 'color-mix(in srgb, var(--bg-surface) 92%, transparent)',
                    boxShadow: '0 25px 50px -12px rgba(0, 0, 0, 0.5), 0 0 0 1px var(--border-main)',
                    backdropFilter: 'blur(16px)',
                }}
                onClick={e => e.stopPropagation()}
            >
                {/* Search Input */}
                <div className="flex items-center gap-4 px-6 py-6 border-b border-main" style={{ background: 'rgba(255,255,255,0.04)' }}>
                    <Search size={22} className="shrink-0" style={{ color: 'var(--accent-blue)' }} />
                    <div className="flex-1 relative flex items-center">
                        <input
                            ref={inputRef}
                            type="text"
                            value={queryText}
                            onChange={e => setQueryText(e.target.value)}
                            onKeyDown={handleKeyDown}
                            placeholder="Search models, commands..."
                            className="w-full outline-none px-5 py-3 rounded-xl transition-all font-medium"
                            style={{
                                background: 'color-mix(in srgb, var(--bg-surface-raised) 70%, transparent)',
                                border: '1px solid var(--border-main)',
                                color: 'var(--text-primary)',
                                fontSize: 18,
                            }}
                        />
                    </div>
                    <kbd className="px-1.5 py-0.5 rounded bg-surface-raised border border-main text-[9px] font-mono text-tertiary">ESC</kbd>
                </div>
                {regexError && (
                    <div className="px-4 py-1 text-[10px]" style={{ color: 'var(--color-error)', borderBottom: '1px solid var(--border-main)' }}>
                        Regex error: {regexError}
                    </div>
                )}

                {/* Results */}
                <div className="max-h-[450px] overflow-y-auto custom-scrollbar py-2">
                    {results.length === 0 ? (
                        <div className="px-4 py-6 text-center text-sm text-tertiary">No results found</div>
                    ) : (
                        Object.entries(grouped).map(([category, items]) => (
                            <div key={category}>
                                <div className="px-4 pt-2 pb-1 text-[10px] font-bold uppercase tracking-wider text-tertiary">{category}</div>
                                {items.map((item) => {
                                    const idx = flatIndex++;
                                    const Icon = item.icon;
                                    return (
                                        <button
                                            key={item.id}
                                            className={`w-full flex items-center gap-4 px-6 py-3 text-sm text-left transition-all outline-none border-none cursor-pointer ${
                                                idx === selectedIndex ? 'text-primary' : 'text-secondary'
                                            }`}
                                            style={idx === selectedIndex
                                                ? { background: 'var(--color-accent-faint)', borderLeft: '3px solid var(--accent-blue)' }
                                                : { background: 'transparent', borderLeft: '3px solid transparent' }}
                                            onMouseEnter={() => setSelectedIndex(idx)}
                                            onClick={() => handleSelect(item)}
                                        >
                                            <Icon size={16} className="shrink-0" style={{ opacity: idx === selectedIndex ? 1 : 0.6, color: idx === selectedIndex ? 'var(--accent-blue)' : undefined }} />
                                            <span className="font-medium flex-1" style={{ transform: idx === selectedIndex ? 'translateX(4px)' : 'none', transition: 'transform 0.15s ease' }}>{item.label}</span>
                                            {item.category && <span className="text-[10px] text-tertiary">{item.category}</span>}
                                        </button>
                                    );
                                })}
                            </div>
                        ))
                    )}
                </div>

                {/* Footer Hint */}
                <div className="flex items-center gap-4 px-4 py-2 border-t border-main text-[10px] text-tertiary">
                    <span>↑↓ Navigate</span>
                    <span>↵ Select</span>
                    <span>ESC Close</span>
                </div>
            </div>
        </div>
    );
}

import { useState, useEffect } from 'react';
import { Save, AlertCircle, FileCode2, SlidersHorizontal } from 'lucide-react';
import { useConfiguration } from '../context/ConfigurationContext';

export default function ConfigEditor() {
  const { config, ghostConfig, saveConfig, isLoading } = useConfiguration();
  const [formData, setFormData] = useState({});
  const [activeTab, setActiveTab] = useState('project');

  useEffect(() => {
    if (config) {
      setFormData(config);
    }
  }, [config]);

  const handleChange = (path, value) => {
    const keys = path.split('.');
    setFormData(prev => {
      const cloned = JSON.parse(JSON.stringify(prev));
      let current = cloned;
      for (let i = 0; i < keys.length - 1; i++) {
        if (!current[keys[i]]) current[keys[i]] = {};
        current = current[keys[i]];
      }
      current[keys[keys.length - 1]] = value;
      return cloned;
    });
  };

  const getValue = (sourceObj, path) => {
    return path.split('.').reduce((obj, key) => (obj && obj[key] !== 'undefined' ? obj[key] : undefined), sourceObj);
  };

  const handleSave = async () => {
    const result = await saveConfig(formData);
    if (!result.success) {
      alert("Failed saving: " + JSON.stringify(result.validationErrors || result.error));
    }
  };

  const renderInput = (label, path) => {
    const projectVal = getValue(formData, path) || '';
    const ghostVal = getValue(ghostConfig, path) || '';
    
    // Ghost indicates global config is overriding null project config
    const isGhosted = projectVal === '' && ghostVal !== '';
    const displayVal = projectVal !== '' ? projectVal : ghostVal;

    return (
      <div style={{ marginBottom: 16 }}>
        <label style={{ display: 'block', fontSize: 12, fontWeight: 600, color: 'var(--text-secondary)', marginBottom: 4 }}>
          {label}
        </label>
        <div style={{ position: 'relative' }}>
          <input 
            type="text" 
            value={displayVal}
            onChange={(e) => handleChange(path, e.target.value)}
            style={{ 
              width: '100%', 
              padding: '8px 12px', 
              borderRadius: 6, 
              border: '1px solid var(--border-color)',
              background: 'var(--bg-app)',
              color: isGhosted ? 'var(--text-tertiary)' : 'var(--text-primary)',
              fontStyle: isGhosted ? 'italic' : 'normal'
            }}
          />
          {isGhosted && (
             <div style={{ position: 'absolute', right: 10, top: 10, fontSize: 10, color: 'var(--text-tertiary)' }}>
               Inherited from Global
             </div>
          )}
        </div>
      </div>
    );
  };

  const handleExport = async () => {
    try {
      const { api } = await import('../utils/api');
      const { stringify } = await import('yaml');
      
      const status = await api.getConnectionsStatus();
      const exportData = { connections: {} };
      
      for (const [key, conn] of Object.entries(status)) {
        if (conn.configured || (conn.credentials && Object.keys(conn.credentials).length > 0)) {
          const safeConn = { type: key };
          if (conn.credentials) {
            const safeCreds = { ...conn.credentials };
            const secretKeys = ['password', 'private_key', 'oauth_client_secret', 'token', 'access_token', 'refresh_token'];
            secretKeys.forEach(k => {
              if (safeCreds[k]) {
                delete safeCreds[k];
              }
            });
            safeConn.credentials = safeCreds;
          }
          exportData.connections[key] = safeConn;
        }
      }
      
      const yamlStr = stringify(exportData);
      const blob = new Blob([yamlStr], { type: 'text/yaml' });
      const url = window.URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = 'connections_export.yaml';
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      window.URL.revokeObjectURL(url);
    } catch (err) {
      alert("Failed to export connections: " + err.message);
    }
  };

  const handleImport = async (e) => {
    const file = e.target.files[0];
    if (!file) return;
    const formData = new FormData();
    formData.append('file', file);
    try {
        const resp = await fetch('/api/project/import', { method: 'POST', body: formData });
        if (resp.ok) {
           window.location.reload();
        } else {
           const err = await resp.json();
           alert('Failed importing: ' + JSON.stringify(err));
        }
    } catch (err) {
        alert('Error importing');
    }
  };

  if (isLoading) return <div style={{ color: 'var(--text-tertiary)', padding: 12 }}>Loading configuration state...</div>;

  return (
    <div style={{ background: 'var(--bg-surface)', border: '1px solid var(--border-color)', borderRadius: 12, padding: 24, fontSize: 13 }}>
       
       <div style={{ display: 'flex', justifyContent: 'flex-end', marginBottom: 24, borderBottom: '1px solid var(--border-color)', paddingBottom: 12 }}>
          <div style={{ display: 'inline-flex', border: '1px solid var(--border-color)', borderRadius: 10, overflow: 'hidden' }}>
            <button
              type="button"
              onClick={() => setActiveTab('project')}
              aria-label="Switch to form view"
              title="Form view"
              style={{
                width: 38,
                height: 34,
                background: activeTab === 'project' ? 'var(--accent-blue)' : 'transparent',
                border: 'none',
                color: activeTab === 'project' ? '#fff' : 'var(--text-primary)',
                cursor: 'pointer',
                display: 'inline-flex',
                alignItems: 'center',
                justifyContent: 'center',
              }}
            >
              <SlidersHorizontal size={14} />
            </button>
            <button
              type="button"
              onClick={() => setActiveTab('yaml')}
              aria-label="Switch to YAML view"
              title="YAML view"
              style={{
                width: 38,
                height: 34,
                background: activeTab === 'yaml' ? 'var(--accent-blue)' : 'transparent',
                border: 'none',
                color: activeTab === 'yaml' ? '#fff' : 'var(--text-primary)',
                cursor: 'pointer',
                display: 'inline-flex',
                alignItems: 'center',
                justifyContent: 'center',
                borderLeft: '1px solid var(--border-color)',
              }}
            >
              <FileCode2 size={14} />
            </button>
          </div>
       </div>

       {activeTab === 'project' && (
         <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 24 }}>
           <div>
              <h3 style={{ fontSize: 14, marginBottom: 16 }}>Source Definition</h3>
              {renderInput('Source Type', 'source.type')}
              {renderInput('Model Pattern', 'source.model')}
           </div>
           <div>
              <h3 style={{ fontSize: 14, marginBottom: 16 }}>Core Settings</h3>
              {renderInput('Repository Path', 'core.repository_path')}
              {renderInput('Concurrency Workers', 'concurrency.max_workers')}
              {renderInput('Log Level', 'logging.level')}
           </div>
         </div>
       )}

       {activeTab === 'yaml' && (
         <div style={{ background: '#1e1e1e', padding: 16, borderRadius: 8, color: '#d4d4d4', fontFamily: 'monospace', whiteSpace: 'pre', overflowX: 'auto' }}>
            {JSON.stringify(formData, null, 2)}
         </div>
       )}

       <div style={{ marginTop: 24, paddingTop: 16, borderTop: '1px solid var(--border-color)', display: 'flex', justifyContent: 'space-between' }}>
          <div style={{ display: 'flex', gap: 12 }}>
             <button onClick={handleExport} style={{ background: 'transparent', border: '1px solid var(--border-color)', color: 'var(--text-primary)', padding: '6px 12px', borderRadius: 6, cursor: 'pointer' }}>Export YAML</button>
             <label style={{ background: 'transparent', border: '1px solid var(--border-color)', color: 'var(--text-primary)', padding: '6px 12px', borderRadius: 6, cursor: 'pointer' }}>
                Import YAML
                <input type="file" accept=".yml,.yaml" onChange={handleImport} style={{ display: 'none' }} />
             </label>
          </div>
          <button 
             onClick={handleSave} 
             style={{ background: 'var(--accent-blue)', color: '#fff', border: 'none', padding: '6px 16px', borderRadius: 6, display: 'flex', gap: 6, alignItems: 'center', cursor: 'pointer', fontWeight: 600 }}
          >
             <Save size={14} /> Save Configuration
          </button>
       </div>

    </div>
  );
}

