                        const modalTitle = currentConfig ? currentConfig.label : (activeTab === 'global-config' ? 'Global Configuration' : 'Settings');
                        const HeaderIcon = currentConfig ? currentConfig.icon : (activeTab === 'global-config' ? FileCode2 : Settings);
