/**
 * MultiFileDryRunStatus — one collapsible section per model for a
 * multi-model (multiple PBIX files OR multiple Fabric models) dry run.
 *
 * Purely presentational: polling, per-file result loading and the per-model
 * rows/edits live in useMultiDryRunJob (owned by CreateProjectPage) and are
 * passed in as `sections` (see utils/multiFileDryRunReadiness.js
 * buildMultiModelSections). Each section's body is a regular
 * DryRunMappingTable instance fed only that model's rows, so every feature of
 * the single-model page (filter bar, edit/rename, collision Fix + Resolve
 * All, synonyms, dropped fields, risk labels) works per model with its own
 * independent filter state. Nothing here is model-specific.
 *
 * A section expanded while its model is still running shows the table as
 * soon as that model's result lands. A failed model shows its real error and
 * a per-model Retry; other models are never hidden by a sibling's failure.
 */
import { useCallback, useMemo, useState } from 'react';
import { ChevronDown, ChevronRight, Loader2, RotateCcw, X, Zap } from 'lucide-react';
import StatusBadge from '../common/StatusBadge';
import DryRunMappingTable from '../DryRunMappingTable';
import UpsertChangesView from '../UpsertChangesView';
import PanelBoundary from '../common/PanelBoundary';
import TableBindingPlan from '../TableBindingPlan';
import { resolveCollisionsForRows } from '../../utils/projectHelpers';

function pluralize(count, word) {
  return `${count} ${word}${count === 1 ? '' : 's'}`;
}

function SectionCounts({ section }) {
  if (!section.loaded) return null;
  const unresolvedCollisions = section.unresolvedCollisions ?? (
    Array.isArray(section.rows)
      ? section.rows.filter((r) => String(r.status || '').toLowerCase() === 'collision').length
      : 0
  );
  return (
    <span style={{ fontSize: 11, color: 'var(--text-tertiary)', whiteSpace: 'nowrap' }}>
      {pluralize(section.columnCount, 'column')} · {pluralize(section.metricCount, 'metric')}
      {unresolvedCollisions > 0 && (
        <>
          {' · '}
          <span style={{ color: 'var(--color-error)', fontWeight: 700 }}>
            {pluralize(unresolvedCollisions, 'unresolved collision')}
          </span>
        </>
      )}
      {' · '}
      <span style={{ color: section.blockingCount > 0 ? 'var(--color-error)' : 'var(--color-success)', fontWeight: 700 }}>
        {section.blockingCount > 0 ? `${section.blockingCount} blocking` : 'no blocking issues'}
      </span>
      {section.ontologyBlockingCount > 0 && (
        <span style={{ color: 'var(--color-error)' }}>
          {` (${pluralize(section.ontologyBlockingCount, 'ontology conflict')})`}
        </span>
      )}
      {section.plan?.view_name && (
        <span title="Where the sync will deploy this model">
          {' · deploys as '}
          <code>{section.plan.view_name}</code>
          {section.plan.physical_namespace ? <> (tables prefixed <code>{section.plan.physical_namespace}_</code>)</> : null}
        </span>
      )}
    </span>
  );
}

export default function MultiFileDryRunStatus({
  sections = [],
  jobStatus = null,
  projectId,
  relationships = [],
  rerunningIds = new Set(),
  rerunErrors = {},
  pollError = '',
  onRetryPolling,
  onEditRow,          // (fileId, rowId, updates?) => void
  onBulkResolved,     // (fileId, resolvedMap) => void
  onSynonymUpdate,    // (fileId, rowId, synonyms) => void
  onRetryFile,        // (fileId) => void
  onRemoveFile,       // (fileId) => void
}) {
  const [expanded, setExpanded] = useState(() => new Set());
  const [bulkResolvingAll, setBulkResolvingAll] = useState(false);
  const [allResolvedToast, setAllResolvedToast] = useState(null);

  const toggle = useCallback((fileId) => {
    setExpanded((prev) => {
      const next = new Set(prev);
      if (next.has(fileId)) next.delete(fileId); else next.add(fileId);
      return next;
    });
  }, []);

  const allExpanded = sections.length > 0 && sections.every((s) => expanded.has(s.fileId));
  const kind = sections.length === 1 ? 'model' : 'models';

  const totalCollisions = useMemo(() => {
    return sections.reduce((sum, s) => {
      const c = s.unresolvedCollisions ?? (
        Array.isArray(s.rows)
          ? s.rows.filter((r) => String(r.status || '').toLowerCase() === 'collision').length
          : 0
      );
      return sum + c;
    }, 0);
  }, [sections]);

  const handleResolveAllModels = useCallback(() => {
    if (!onBulkResolved || !sections.length) return;
    setBulkResolvingAll(true);
    setAllResolvedToast(null);

    try {
      let resolvedTotal = 0;
      let affectedSections = 0;

      for (const section of sections) {
        if (!section.loaded || !Array.isArray(section.rows)) continue;
        const resolvedMap = resolveCollisionsForRows(section.rows);
        const count = Object.keys(resolvedMap).length;
        if (count > 0) {
          onBulkResolved(section.fileId, resolvedMap);
          resolvedTotal += count;
          affectedSections += 1;
        }
      }

      if (resolvedTotal > 0) {
        setAllResolvedToast({
          type: 'success',
          msg: `${resolvedTotal} collision${resolvedTotal !== 1 ? 's' : ''} across ${affectedSections} model${affectedSections !== 1 ? 's' : ''} resolved — unique names applied. Review each model to confirm.`,
        });
      }
    } catch (err) {
      setAllResolvedToast({
        type: 'error',
        msg: `Resolve failed: ${err.message}`,
      });
    } finally {
      setBulkResolvingAll(false);
      setTimeout(() => setAllResolvedToast(null), 6000);
    }
  }, [sections, onBulkResolved]);

  if (!jobStatus && sections.length === 0) {
    return (
      <div style={{ border: '1px solid var(--border-main)', borderRadius: 10, background: 'var(--bg-surface)', padding: 16, fontSize: 12, color: 'var(--text-tertiary)' }}>
        Starting dry-run job…
      </div>
    );
  }

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
      <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
        <div style={{ fontSize: 13, fontWeight: 700, color: 'var(--text-primary)' }}>
          Multi-model dry run — {sections.length} {kind}
        </div>
        {jobStatus?.status && <StatusBadge status={jobStatus.status} size="sm" />}
        <div style={{ marginLeft: 'auto', display: 'flex', alignItems: 'center', gap: 10 }}>
          {sections.length > 1 && (totalCollisions > 0 || bulkResolvingAll) && (
            <button
              id="bulk-resolve-all-models-btn"
              data-testid="resolve-all-for-all-models-btn"
              type="button"
              disabled={bulkResolvingAll}
              onClick={handleResolveAllModels}
              title="Resolve collisions for all models"
              style={{
                display: 'inline-flex',
                alignItems: 'center',
                gap: 6,
                padding: '4px 12px',
                borderRadius: 6,
                border: '1px solid rgba(251,191,36,0.55)',
                background: bulkResolvingAll
                  ? 'rgba(251,191,36,0.06)'
                  : 'rgba(251,191,36,0.12)',
                color: '#fbbf24',
                fontSize: 11,
                fontWeight: 700,
                cursor: bulkResolvingAll ? 'not-allowed' : 'pointer',
                whiteSpace: 'nowrap',
                transition: 'background 0.15s, opacity 0.15s',
                opacity: bulkResolvingAll ? 0.7 : 1,
              }}
            >
              {bulkResolvingAll ? (
                <>
                  <span
                    style={{
                      width: 10,
                      height: 10,
                      border: '2px solid #fbbf24',
                      borderTopColor: 'transparent',
                      borderRadius: '50%',
                      display: 'inline-block',
                      animation: 'spin 0.7s linear infinite',
                    }}
                  />
                  Resolving…
                </>
              ) : (
                <>
                  <Zap size={11} /> Resolve all for all models ({totalCollisions})
                </>
              )}
            </button>
          )}
          <button
            type="button"
            onClick={() => setExpanded(allExpanded ? new Set() : new Set(sections.map((s) => s.fileId)))}
            style={{ background: 'none', border: 'none', color: 'var(--accent-blue)', fontSize: 11, fontWeight: 600, cursor: 'pointer' }}
          >
            {allExpanded ? 'Collapse all' : 'Expand all'}
          </button>
        </div>
      </div>

      {allResolvedToast && (
        <div style={{
          display: 'flex',
          alignItems: 'center',
          gap: 8,
          padding: '8px 12px',
          borderRadius: 6,
          fontSize: 12,
          fontWeight: 600,
          background: allResolvedToast.type === 'error' ? 'rgba(239,68,68,0.12)' : 'rgba(34,197,94,0.12)',
          border: `1px solid ${allResolvedToast.type === 'error' ? 'rgba(239,68,68,0.35)' : 'rgba(34,197,94,0.35)'}`,
          color: allResolvedToast.type === 'error' ? 'var(--color-error)' : 'var(--color-success)',
        }}>
          {allResolvedToast.msg}
        </div>
      )}

      {pollError && (
        <div style={{ display: 'flex', alignItems: 'center', gap: 10, border: '1px solid rgba(239, 68, 68, 0.45)', background: 'rgba(239, 68, 68, 0.10)', color: 'var(--color-error)', borderRadius: 8, padding: '8px 12px', fontSize: 12 }}>
          <span style={{ flex: 1 }}>Lost contact with the dry-run job: {pollError}</span>
          {onRetryPolling && (
            <button type="button" onClick={onRetryPolling} style={{ background: 'none', border: '1px solid var(--border-main)', borderRadius: 6, padding: '3px 8px', fontSize: 11, color: 'var(--text-secondary)', cursor: 'pointer' }}>
              Reconnect
            </button>
          )}
        </div>
      )}

      {sections.map((section) => {
        const isOpen = expanded.has(section.fileId);
        const isRerunning = rerunningIds.has(section.fileId);
        const failed = section.status === 'failed' || Boolean(section.loadError);
        const canRetry = failed && !isRerunning;
        const badgeStatus = isRerunning ? 'running' : section.status;
        const errorText = section.status === 'failed'
          ? (section.error || 'This model failed during the dry run.')
          : section.loadError;
        return (
          <div
            key={section.fileId}
            style={{
              border: `1px solid ${failed ? 'rgba(239, 68, 68, 0.35)' : section.blockingCount > 0 ? 'rgba(251, 191, 36, 0.35)' : 'var(--border-main)'}`,
              borderRadius: 10,
              background: 'var(--bg-surface)',
              overflow: 'hidden',
            }}
          >
            <div
              role="button"
              tabIndex={0}
              aria-expanded={isOpen}
              onClick={() => toggle(section.fileId)}
              onKeyDown={(e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); toggle(section.fileId); } }}
              style={{ display: 'flex', alignItems: 'center', gap: 10, padding: '10px 14px', cursor: 'pointer', userSelect: 'none' }}
            >
              {isOpen
                ? <ChevronDown size={14} style={{ color: 'var(--text-tertiary)', flexShrink: 0 }} />
                : <ChevronRight size={14} style={{ color: 'var(--text-tertiary)', flexShrink: 0 }} />}
              <div style={{ minWidth: 0, flex: 1 }}>
                <div title={section.sourceRef || section.label} style={{ fontSize: 13, fontWeight: 700, color: 'var(--text-primary)', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                  {section.label}
                </div>
                {failed && errorText && !isOpen && (
                  <div title={errorText} style={{ fontSize: 11, color: 'var(--color-error)', marginTop: 2, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                    {errorText}
                  </div>
                )}
                {section.status === 'skipped' && (
                  <div title={section.error} style={{ fontSize: 11, color: 'var(--text-secondary)', marginTop: 2, whiteSpace: 'normal', overflowWrap: 'anywhere' }}>
                    Will be skipped: {section.error || 'this model has no tables.'} The other models still sync.
                  </div>
                )}
              </div>
              <SectionCounts section={section} />
              <StatusBadge status={badgeStatus} size="sm" />
              {canRetry && onRetryFile && (
                <button
                  type="button"
                  onClick={(evt) => { evt.stopPropagation(); onRetryFile(section.fileId); }}
                  style={{
                    display: 'flex', alignItems: 'center', gap: 5,
                    background: 'none', border: '1px solid var(--border-main)', borderRadius: 6,
                    padding: '4px 8px', fontSize: 11, fontWeight: 600, color: 'var(--text-secondary)', cursor: 'pointer',
                  }}
                >
                  <RotateCcw size={11} /> Retry
                </button>
              )}
              {canRetry && onRemoveFile && sections.length > 1 && (
                <button
                  type="button"
                  onClick={(evt) => { evt.stopPropagation(); onRemoveFile(section.fileId); }}
                  title="Remove failed model and continue with the remaining models"
                  style={{
                    display: 'flex', alignItems: 'center', gap: 5,
                    background: 'none', border: '1px solid var(--color-error)', borderRadius: 6,
                    padding: '4px 8px', fontSize: 11, fontWeight: 600, color: 'var(--color-error)', cursor: 'pointer',
                  }}
                >
                  <X size={11} /> Remove
                </button>
              )}
            </div>

            {rerunErrors[section.fileId] && (
              <div style={{ padding: '0 14px 8px', fontSize: 11, color: 'var(--color-error)' }}>
                Retry failed: {rerunErrors[section.fileId]}
              </div>
            )}

            {isOpen && (
              <div style={{ padding: '0 14px 14px', borderTop: '1px solid var(--border-subtle)' }}>
                {(section.status === 'pending' || section.status === 'running' || isRerunning) && (
                  <div style={{ display: 'flex', alignItems: 'center', gap: 8, fontSize: 12, color: 'var(--text-tertiary)', padding: '12px 0' }}>
                    <Loader2 size={13} style={{ animation: 'spin 1s linear infinite' }} />
                    Dry run in progress for this model — results will appear here as soon as it finishes.
                  </div>
                )}
                {section.loading && (
                  <div style={{ display: 'flex', alignItems: 'center', gap: 8, fontSize: 12, color: 'var(--text-tertiary)', padding: '12px 0' }}>
                    <Loader2 size={13} style={{ animation: 'spin 1s linear infinite' }} />
                    Loading results…
                  </div>
                )}
                {failed && errorText && (
                  <div style={{ fontSize: 12, color: 'var(--color-error)', padding: '12px 0', whiteSpace: 'pre-wrap', wordBreak: 'break-word' }}>
                    {errorText}
                  </div>
                )}
                {section.loaded && (
                  <div style={{ paddingTop: 12 }}>
                    <PanelBoundary name="Target tables">
                      <TableBindingPlan plan={section.result?.table_binding_plan} style={{ marginTop: 0, marginBottom: 12 }} />
                    </PanelBoundary>
                    <UpsertChangesView delta={section.result?.upsert_delta} modelLabel={section.result?.model_name || section.label} isDryRun>
                      <DryRunMappingTable
                        // key: a re-run (new attempt) starts with fresh filter state.
                        key={section.attempt}
                        // Rows are already NormalizedRow[] -- useMultiDryRunJob runs
                        // every per-file result through normalizeRows() on load.
                        mappings={section.rows}
                        summary={section.result?.summary}
                        deployedNamesKnown={Boolean(section.result?.deployed_names_known)}
                        relationships={relationships}
                        onEdit={(rowId, updates) => onEditRow?.(section.fileId, rowId, updates)}
                        onBulkResolved={(resolvedMap) => onBulkResolved?.(section.fileId, resolvedMap)}
                        onSynonymUpdate={(rowId, synonyms) => onSynonymUpdate?.(section.fileId, rowId, synonyms)}
                        projectId={section.previewProjectId || section.result?.project_id || projectId}
                        modelName={section.result?.model_name || section.label}
                        schemaConflicts={section.result?.schema_conflicts || []}
                        compatibilityScore={section.compatibilityScore}
                        onReSync={onRetryFile ? () => onRetryFile(section.fileId) : undefined}
                        droppedEntities={section.result?.dropped_entities || []}
                        unresolvedReportFieldReferences={section.result?.unresolved_report_field_references || []}
                      />
                    </UpsertChangesView>
                  </div>
                )}
              </div>
            )}
          </div>
        );
      })}
    </div>
  );
}

/**
 * MultiPbixUpload — multi-file PBIX picker for the source-configuration step.
 *
 * Controlled component: the file list (`entries`) lives in the persisted
 * wizard store (projectWizardStore.pbixFileEntries), so it survives leaving
 * this step and page reloads. Adding files calls `onAddFiles(files)`, which
 * (in CreateProjectPage) records the entries and starts each upload OUTSIDE
 * any React state updater -- an upload still in flight when this component
 * unmounts still lands in the list. `onRemove(entryId)` removes one file
 * (including one that is still uploading; its late result is dropped).
 *
 * Duplicate file names, non-.pbix files and files past the `maxFiles` cap
 * (10, the backend's MAX_PBIX_FILES) are never dropped silently -- the
 * message returned by onAddFiles is shown inline.
 */
import { useCallback, useRef, useState } from 'react';
import { Upload } from 'lucide-react';
import { uploadStatusColors } from './uploadStatusColors';
import { UploadStatusIcon, RemoveFileButton } from './uploadStatusUI';

export default function MultiPbixUpload({ entries = [], onAddFiles, onRemove, maxFiles = 10 }) {
  const [dragging, setDragging] = useState(false);
  const [notice, setNotice] = useState('');
  const inputRef = useRef(null);

  const handleFiles = useCallback((incoming) => {
    const files = Array.from(incoming || []);
    if (files.length === 0) return;
    const message = onAddFiles?.(files) || '';
    setNotice(message);
  }, [onAddFiles]);

  const doneCount = entries.filter((e) => e.status === 'done').length;
  const uploadingCount = entries.filter((e) => e.status === 'uploading').length;

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
      <div
        onDragOver={(e) => { e.preventDefault(); setDragging(true); }}
        onDragLeave={() => setDragging(false)}
        onDrop={(e) => { e.preventDefault(); e.stopPropagation(); setDragging(false); handleFiles(e.dataTransfer.files); }}
        onClick={() => inputRef.current?.click()}
        style={{
          border: `2px dashed ${dragging ? 'var(--accent-blue)' : 'var(--border-main)'}`,
          borderRadius: 10,
          padding: 24,
          textAlign: 'center',
          cursor: 'pointer',
          background: dragging ? 'var(--accent-blue)14' : 'var(--accent-blue)08',
          transition: 'all 0.15s',
        }}
      >
        <Upload size={22} style={{ color: 'var(--text-tertiary)', margin: '0 auto 6px' }} />
        <div style={{ fontSize: 13, color: 'var(--text-secondary)', fontWeight: 500 }}>
          Drag and drop .pbix files here or click to browse
        </div>
        <div style={{ fontSize: 11, color: 'var(--text-tertiary)', marginTop: 4 }}>
          Up to {maxFiles} files — each becomes its own independent semantic view
        </div>
        <input
          ref={inputRef}
          type="file"
          accept=".pbix"
          multiple
          style={{ display: 'none' }}
          onChange={(e) => { handleFiles(e.target.files); e.target.value = ''; }}
        />
      </div>

      {notice && (
        <div role="status" style={{ fontSize: 12, color: 'var(--color-warning)', display: 'flex', alignItems: 'flex-start', gap: 8 }}>
          <span style={{ flex: 1 }}>{notice}</span>
          <button
            type="button"
            onClick={() => setNotice('')}
            style={{ background: 'none', border: 'none', color: 'var(--text-tertiary)', cursor: 'pointer', fontSize: 11 }}
          >
            Dismiss
          </button>
        </div>
      )}

      {entries.length > 0 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 4 }}>
          <div style={{ fontSize: 11, color: 'var(--text-tertiary)' }}>
            {doneCount} of {entries.length} file{entries.length !== 1 ? 's' : ''} uploaded
            {uploadingCount > 0 ? ` · ${uploadingCount} uploading…` : ''}
            {entries.length === 1 && doneCount === 1 ? ' · a single file runs as a single-model project' : ''}
          </div>
          {entries.map((e) => {
            const statusStyle = uploadStatusColors(e.status);
            return (
              <div
                key={e.id || e.name}
                style={{
                  display: 'flex', alignItems: 'center', gap: 8,
                  padding: '6px 10px', borderRadius: 6,
                  background: statusStyle?.background || 'var(--bg-surface-raised)',
                  border: `1px solid ${statusStyle?.border || 'var(--border-subtle)'}`,
                }}
              >
                <UploadStatusIcon status={e.status} size={13} />
                <span title={e.path || e.name} style={{ fontSize: 12, color: 'var(--text-primary)', flex: 1, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                  {e.name}
                </span>
                {e.status === 'error' && (
                  <span style={{ fontSize: 11, color: 'var(--color-error)' }}>{e.error}</span>
                )}
                <RemoveFileButton onClick={() => { onRemove?.(e.id); setNotice(''); }} />
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

import React from 'react';
import { X, Check } from 'lucide-react';
import SourceIcon from '../common/SourceIcon';
import { ConnectorChip } from '../WizardUIComponents';
import { CONNECTOR_TYPES, TARGET_CONNECTOR_TYPES, INTERMEDIATE_FORMAT_TYPES } from '../../utils/constants';

const SECTION_CARD = {
  border: '1px solid var(--border-main)',
  borderRadius: 16,
  padding: '32px 36px',
  background: 'var(--bg-surface)',
  boxShadow: '0 4px 20px rgba(0, 0, 0, 0.08)',
  position: 'relative',
  overflow: 'hidden'
};

export function StepBasicInfo({
  name, setName, description, setDescription,
  sourceConnector, setSourceConnector,
  targetConnectors, setTargetConnectors,
  intermediateFormat, setIntermediateFormat,
  tags, setTags, tagInput, setTagInput,
  showValidation, editMode
}) {
  const isSourceMissing = !sourceConnector;
  const isTargetsMissing = targetConnectors.size === 0;
  const isFormatMissing = !intermediateFormat;

  const LABEL = {
    display: 'block', fontSize: 11, fontWeight: 700,
    color: 'var(--text-tertiary)', marginBottom: 8,
    textTransform: 'uppercase', letterSpacing: '0.05em'
  };
  const INPUT_STYLE = {
    width: '100%', padding: '10px 14px', borderRadius: 8,
    background: 'var(--bg-surface-raised)', border: '1px solid var(--border-main)',
    color: 'var(--text-primary)', fontSize: 13, outline: 'none',
    transition: 'all 0.2s ease',
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 32, paddingBottom: 40 }}>
      {/* 1. Project Identity */}
      <div style={SECTION_CARD}>
        <div style={{ marginBottom: 20 }}>
          <h3 style={{ fontSize: 15, fontWeight: 700, color: 'var(--text-primary)', margin: 0 }}>Project Identity</h3>
          <p style={{ fontSize: 12, color: 'var(--text-tertiary)', marginTop: 4 }}>Basic details to identify this synchronization pipeline.</p>
        </div>

        <div style={{ display: 'grid', gap: 24 }}>
          <div>
            <label style={LABEL}>Project Name</label>
            <input
              type="text" value={name} onChange={e => setName(e.target.value)}
              placeholder="e.g. Sales Analytics Sync"
              style={{ ...INPUT_STYLE, maxWidth: 500 }}
              disabled={editMode}
            />
            {showValidation && !name && (
              <p style={{ color: 'var(--color-error)', fontSize: 11, marginTop: 4 }}>Name is required</p>
            )}
          </div>
          <div>
            <label style={LABEL}>Description (optional)</label>
            <textarea
              value={description} onChange={e => setDescription(e.target.value)}
              placeholder="Describe the purpose of this data pipeline..."
              style={{ ...INPUT_STYLE, minHeight: 80, resize: 'vertical' }}
            />
          </div>

          <div>
            <label style={LABEL}>Project Tags</label>
            <div style={{ display: 'flex', flexWrap: 'wrap', gap: 6, marginBottom: 8 }}>
              {[...tags].map(tag => (
                <div
                  key={tag}
                  style={{
                    display: 'flex', alignItems: 'center', gap: 6,
                    padding: '4px 10px', borderRadius: 6,
                    background: 'rgba(59, 130, 246, 0.1)', color: 'var(--accent-blue)',
                    fontSize: 12, fontWeight: 600,
                  }}
                >
                  {tag}
                  <button
                    type="button"
                    onClick={() => { const next = new Set(tags); next.delete(tag); setTags(next); }}
                    style={{ background: 'none', border: 'none', cursor: 'pointer', color: 'inherit', padding: 0, display: 'flex' }}
                  >
                    <X size={13} />
                  </button>
                </div>
              ))}
            </div>
            <input
              type="text" value={tagInput} onChange={e => setTagInput(e.target.value)}
              onKeyDown={e => {
                if (e.key === 'Enter' && tagInput.trim()) {
                  const next = new Set(tags);
                  next.add(tagInput.trim());
                  setTags(next);
                  setTagInput('');
                }
              }}
              placeholder="Add tag and press Enter..."
              style={INPUT_STYLE}
            />
          </div>
        </div>
      </div>

      {/* 2. Unified Pipeline Configuration Island */}
      <div style={SECTION_CARD}>
        <div style={{ marginBottom: 24 }}>
          <h3 style={{ fontSize: 15, fontWeight: 700, color: 'var(--text-primary)', margin: 0 }}>Pipeline Configuration</h3>
          <p style={{ fontSize: 12, color: 'var(--text-tertiary)', marginTop: 4 }}>Define how data flows from your source to the target destinations.</p>
        </div>

        <div style={{ display: 'flex', flexDirection: 'column', gap: 32 }}>
          {/* Source & Target Row */}
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 32, alignItems: 'stretch' }}>
            {/* Source Column */}
            <div style={{ display: 'flex', flexDirection: 'column' }}>
              <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 16 }}>
                <div style={LABEL}>Source Connector</div>
                <span style={{ fontSize: 10, fontWeight: 700, padding: '2px 8px', borderRadius: 4, background: 'rgba(59, 130, 246, 0.1)', color: 'var(--accent-blue)' }}>SINGLE</span>
              </div>
              <div style={{ display: 'flex', flexDirection: 'column', gap: 10, flex: 1 }}>
                {CONNECTOR_TYPES.map(c => {
                  const isSelected = sourceConnector === c.value;
                  const shouldDim = Boolean(sourceConnector) && !isSelected;
                  return (
                    <button
                      key={c.value} type="button" onClick={() => setSourceConnector(c.value)}
                      style={{
                        display: 'flex', alignItems: 'center', gap: 12, padding: '12px 16px', borderRadius: 10, cursor: 'pointer',
                        background: isSelected ? 'rgba(59, 130, 246, 0.08)' : 'var(--bg-surface-raised)',
                        border: `1.5px solid ${isSelected ? 'var(--accent-blue)' : 'transparent'}`,
                        color: isSelected ? 'var(--accent-blue)' : shouldDim ? 'var(--text-tertiary)' : 'var(--text-secondary)',
                        fontSize: 13, fontWeight: isSelected ? 600 : 400, opacity: shouldDim ? 0.4 : 1, transition: 'all 0.2s ease',
                        boxShadow: isSelected ? '0 0 0 1px rgba(59, 130, 246, 0.2)' : 'none',
                      }}
                    >
                      <div style={{ 
                        width: 16, height: 16, borderRadius: '50%', 
                        border: isSelected ? '5px solid var(--accent-blue)' : '2px solid var(--border-main)',
                        background: 'transparent',
                        transition: 'all 0.2s ease'
                      }} />
                      <SourceIcon source={c.value} size={18} />
                      <span style={{ flex: 1, textAlign: 'left' }}>{c.label}</span>
                    </button>
                  );
                })}
              </div>
              {showValidation && isSourceMissing && (
                <p style={{ color: 'var(--color-error)', fontSize: 11, marginTop: 12 }}>Please select a source</p>
              )}
            </div>

            {/* Target Column */}
            <div style={{ display: 'flex', flexDirection: 'column' }}>
              <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 16 }}>
                <div style={LABEL}>Target Connector(s)</div>
                <span style={{ fontSize: 10, fontWeight: 700, padding: '2px 8px', borderRadius: 4, background: 'rgba(34, 197, 94, 0.1)', color: 'var(--color-success)' }}>MULTIPLE</span>
              </div>
              <div style={{ display: 'flex', flexDirection: 'column', gap: 10, flex: 1 }}>
                {TARGET_CONNECTOR_TYPES.map(t => {
                  const isSelected = targetConnectors.has(t.value);
                  const isDisabled = sourceConnector === t.value;
                  return (
                    <button
                      key={t.value} type="button" disabled={isDisabled}
                      onClick={() => {
                        const next = new Set(targetConnectors);
                        if (next.has(t.value)) next.delete(t.value);
                        else next.add(t.value);
                        setTargetConnectors(next);
                      }}
                      style={{
                        display: 'flex', alignItems: 'center', gap: 12, padding: '12px 16px', borderRadius: 10,
                        cursor: isDisabled ? 'not-allowed' : 'pointer',
                        background: isSelected ? 'rgba(59, 130, 246, 0.08)' : 'var(--bg-surface-raised)',
                        border: `1.5px solid ${isSelected ? 'var(--accent-blue)' : 'transparent'}`,
                        color: isSelected ? 'var(--accent-blue)' : isDisabled ? 'var(--text-tertiary)' : 'var(--text-secondary)',
                        fontSize: 13, fontWeight: isSelected ? 600 : 400, opacity: isDisabled ? 0.2 : 1, transition: 'all 0.2s ease',
                        boxShadow: isSelected ? '0 0 0 1px rgba(59, 130, 246, 0.2)' : 'none',
                      }}
                    >
                      <div style={{ 
                        width: 16, height: 16, borderRadius: 4, 
                        background: isSelected ? 'var(--accent-blue)' : 'transparent', 
                        border: isSelected ? 'none' : '2px solid var(--border-main)', 
                        display: 'flex', alignItems: 'center', justifyContent: 'center',
                        transition: 'all 0.2s ease'
                      }}>
                        {isSelected && <Check size={12} color="white" strokeWidth={3} />}
                      </div>
                      <SourceIcon source={t.value} size={18} />
                      <span style={{ flex: 1, textAlign: 'left' }}>{t.label}</span>
                    </button>
                  );
                })}
              </div>
              {showValidation && isTargetsMissing && (
                <p style={{ color: 'var(--color-error)', fontSize: 11, marginTop: 12 }}>Select at least one target</p>
              )}
            </div>
          </div>

          {/* Format Selection (Bottom Row) */}
          <div style={{ borderTop: '1px solid var(--border-main)', paddingTop: 24 }}>
            <label style={LABEL}>Intermediate Format</label>
            <div style={{ display: 'flex', gap: 12, marginTop: 12 }}>
              {INTERMEDIATE_FORMAT_TYPES.map(t => (
                <ConnectorChip
                  key={t.value} label={t.label}
                  selected={intermediateFormat === t.value}
                  onClick={() => setIntermediateFormat(t.value)}
                />
              ))}
            </div>
            <p style={{ fontSize: 12, color: 'var(--text-tertiary)', marginTop: 16, lineHeight: 1.5 }}>
              The intermediate format determines the schema representation used during the synchronization process. 
              This is critical for cross-platform semantic translation.
            </p>
          </div>
        </div>
      </div>
    </div>
  );
}

import React, { useState, useEffect, useCallback, useMemo, useRef } from 'react';
import { Check, CheckCircle2, ChevronDown, RefreshCw, Loader2, PieChart } from 'lucide-react';
import { api } from '../../utils/api';
import SourceIcon from '../common/SourceIcon';
import SearchableSelect from '../common/SearchableSelect';
import MultiPbixUpload from './MultiPbixUpload';
import { RemoveFileButton } from './uploadStatusUI';
import { CONNECTOR_TYPES, TARGET_CONNECTOR_TYPES, PBIX_SOURCE_MODES } from '../../utils/constants';

const SECTION_CARD = {
  border: '1px solid var(--border-main)',
  borderRadius: 16,
  padding: '32px 36px',
  background: 'var(--bg-surface)',
  boxShadow: '0 4px 20px rgba(0, 0, 0, 0.08)',
  position: 'relative',
  overflow: 'visible'
};

function getAccountLabel(account) {
  const primary = account?.tag || account?.name || account?.identity_email || account?.account || account?.id;
  const secondary = account?.identity_email || account?.account || account?.locator || account?.id;
  if (!primary) return 'Saved account';
  if (!secondary || String(primary) === String(secondary)) return String(primary);
  return `${primary} (${secondary})`;
}

function getAccountId(account) {
  return String(account?.id || account?.identity_id || account?.account_id || '');
}

export function StepConnectorConfig({
  sourceConnector,
  targetConnectors,
  fabricAccountId,
  setFabricAccountId,
  fabricAccounts,
  fabricWorkspaceId,
  setFabricWorkspaceId,
  snowflakeAccountId,
  setSnowflakeAccountId,
  snowflakeAccounts,
  databricksAccountId,
  setDatabricksAccountId,
  databricksAccounts,
  snowflakeDatabase,
  setSnowflakeDatabase,
  snowflakeSchema,
  setSnowflakeSchema,
  targetDatabase,
  setTargetDatabase,
  targetSchema,
  setTargetSchema,
  targetAccount,
  setTargetAccount,
  targetWarehouse,
  setTargetWarehouse,
  pbixFile,
  setPbixFile,
  pbixUploadPath,
  pbixUploading,
  setPbixUploading,
  pbixSourceMode,
  setPbixSourceMode,
  localFolders,
  localFoldersLoading,
  selectedLocalFolderId,
  setSelectedLocalFolderId,
  onUploadSuccess,
  onClearPbix = () => {},
  pbixMultiFileMode = false,
  setPbixMultiFileMode = () => {},
  pbixFileEntries = [],
  onAddPbixFiles = () => '',
  onRemovePbixFile = () => {},
  maxPbixFiles = 10,
  workspaces,
  workspacesLoading,
  isRefreshingWorkspaces,
  fetchFabricWorkspaces,
  workspaceDiscoveryError,
  runWarning,
}) {
  const [pbixDragOver, setPbixDragOver] = useState(false);
  const [pbixUploadError, setPbixUploadError] = useState('');

  // Dynamic Snowflake discovery states
  const [snowflakeWarehouses, setSnowflakeWarehouses] = useState([]);
  const [snowflakeDatabases, setSnowflakeDatabases] = useState([]);
  const [snowflakeSchemas, setSnowflakeSchemas] = useState([]);
  const [snowflakeDiscoveryLoading, setSnowflakeDiscoveryLoading] = useState(false);
  const [snowflakeSchemaLoading, setSnowflakeSchemaLoading] = useState(false);
  const [snowflakeDiscoveryError, setSnowflakeDiscoveryError] = useState('');

  // Race condition protection refs
  const latestAccountIdRef = useRef(snowflakeAccountId);
  const activeSnowflakeDatabase = sourceConnector === 'snowflake' ? snowflakeDatabase : targetDatabase;
  const latestDatabaseRef = useRef(activeSnowflakeDatabase);

  useEffect(() => {
    latestAccountIdRef.current = snowflakeAccountId;
  }, [snowflakeAccountId]);

  useEffect(() => {
    latestDatabaseRef.current = activeSnowflakeDatabase;
  }, [activeSnowflakeDatabase]);

  const handleSnowflakeAccountSelect = (value, role = 'target') => {
    setSnowflakeAccountId(value);
    if (role === 'target') {
      setTargetAccount('');
    }
  };

  const normalizeDiscoveryItems = useCallback((items) => (
    (Array.isArray(items) ? items : [])
      .map((item) => {
        const id = String(item?.id || item?.name || item || '').trim();
        const name = String(item?.name || item?.id || item || '').trim();
        return id ? { id, name } : null;
      })
      .filter(Boolean)
  ), []);

  const uploadPbixFile = async (file) => {
    if (!file) return;
    const fname = String(file.name || '').toLowerCase();
    const isPbix = fname.endsWith('.pbix');
    const isTableau = fname.endsWith('.tds') || fname.endsWith('.tdsx') || fname.endsWith('.twb') || fname.endsWith('.twbx');
    if (!isPbix && !isTableau) {
      setPbixUploadError('Supported files: .pbix, .tds, .tdsx, .twb, .twbx');
      return;
    }

    setPbixUploadError('');
    setPbixUploading(true);
    try {
      const response = await api.uploadPbix(file);
      const uploadedPath = String(response?.path || '').trim();
      setPbixFile(file);
      onUploadSuccess?.({ file, path: uploadedPath });
      if (!uploadedPath) {
        setPbixUploadError('Upload succeeded but server did not return a file path.');
      }
    } catch (err) {
      setPbixUploadError(err?.message || 'PBIX upload failed.');
    } finally {
      setPbixUploading(false);
    }
  };

  const handlePbixDrop = async (event) => {
    event.preventDefault();
    event.stopPropagation();
    setPbixDragOver(false);
    const droppedFile = event.dataTransfer?.files?.[0] || null;
    if (droppedFile) await uploadPbixFile(droppedFile);
  };

  const selectedTargets = [...targetConnectors];
  const sourceLabel = CONNECTOR_TYPES.find(c => c.value === sourceConnector)?.label || sourceConnector;
  const activeLocalFolders = useMemo(
    () => (localFolders || []).filter(folder => folder?.is_active !== false),
    [localFolders],
  );

  // Auto-select folder if pbix source mode is folder tags
  useEffect(() => {
    if (sourceConnector !== 'pbix' || pbixSourceMode !== 'TAG') return;
    if (localFoldersLoading || activeLocalFolders.length === 0) return;

    const hasSelection = activeLocalFolders.some(folder => String(folder.id) === String(selectedLocalFolderId || ''));
    if (!hasSelection) {
      setSelectedLocalFolderId(String(activeLocalFolders[0]?.id || ''));
    }
  }, [
    activeLocalFolders,
    localFoldersLoading,
    pbixSourceMode,
    selectedLocalFolderId,
    setSelectedLocalFolderId,
    sourceConnector,
  ]);

  // Effect to load warehouses and databases on Snowflake Account selection
  useEffect(() => {
    const needsSnowflake = sourceConnector === 'snowflake' || targetConnectors.has('snowflake');
    if (!needsSnowflake || !snowflakeAccountId) {
      setSnowflakeWarehouses([]);
      setSnowflakeDatabases([]);
      setSnowflakeSchemas([]);
      setSnowflakeDiscoveryError('');
      return;
    }

    let active = true;
    setSnowflakeDiscoveryLoading(true);
    setSnowflakeDiscoveryError('');

    Promise.all([
      api.discoverSnowflakeWarehouses(snowflakeAccountId),
      api.discoverSnowflakeDatabases(snowflakeAccountId),
    ])
      .then(([warehouseData, databaseData]) => {
        // Safe check: ignore responses if account ID changed since request started
        if (!active || snowflakeAccountId !== latestAccountIdRef.current) return;

        const warehouses = normalizeDiscoveryItems(warehouseData);
        const databases = normalizeDiscoveryItems(databaseData);
        setSnowflakeWarehouses(warehouses);
        setSnowflakeDatabases(databases);

        const hasWarehouse = warehouses.some(item => item.id === targetWarehouse);
        if (!hasWarehouse) {
          setTargetWarehouse(warehouses[0]?.id || '');
        }

        const hasSourceDatabase = databases.some(item => item.id === snowflakeDatabase);
        if (sourceConnector === 'snowflake' && !hasSourceDatabase) {
          setSnowflakeDatabase(databases[0]?.id || '');
        }

        const hasTargetDatabase = databases.some(item => item.id === targetDatabase);
        if (targetConnectors.has('snowflake') && !hasTargetDatabase) {
          setTargetDatabase(databases[0]?.id || '');
        }
      })
      .catch((err) => {
        if (!active || snowflakeAccountId !== latestAccountIdRef.current) return;
        setSnowflakeWarehouses([]);
        setSnowflakeDatabases([]);
        setSnowflakeSchemas([]);
        setSnowflakeDiscoveryError(err?.message || 'Could not load Snowflake account metadata.');
      })
      .finally(() => {
        if (active && snowflakeAccountId === latestAccountIdRef.current) {
          setSnowflakeDiscoveryLoading(false);
        }
      });

    return () => {
      active = false;
    };
  }, [
    normalizeDiscoveryItems,
    snowflakeAccountId,
    sourceConnector,
    targetConnectors,
    setSnowflakeDatabase,
    setTargetDatabase,
    setTargetWarehouse,
  ]);

  // Effect to load schemas on Database selection
  useEffect(() => {
    const needsSnowflake = sourceConnector === 'snowflake' || targetConnectors.has('snowflake');
    if (!needsSnowflake || !snowflakeAccountId || !activeSnowflakeDatabase) {
      setSnowflakeSchemas([]);
      return;
    }

    let active = true;
    setSnowflakeSchemaLoading(true);

    api.discoverSnowflakeSchemas(activeSnowflakeDatabase, snowflakeAccountId)
      .then((schemaData) => {
        // Safe check: ignore responses if database or account ID has changed
        if (!active || activeSnowflakeDatabase !== latestDatabaseRef.current || snowflakeAccountId !== latestAccountIdRef.current) return;

        const schemas = normalizeDiscoveryItems(schemaData);
        setSnowflakeSchemas(schemas);

        if (sourceConnector === 'snowflake') {
          const hasSchema = schemas.some(item => item.id === snowflakeSchema);
          if (!hasSchema) setSnowflakeSchema(schemas[0]?.id || '');
        }

        if (targetConnectors.has('snowflake')) {
          const hasSchema = schemas.some(item => item.id === targetSchema);
          if (!hasSchema) setTargetSchema(schemas[0]?.id || '');
        }
      })
      .catch((err) => {
        if (!active || activeSnowflakeDatabase !== latestDatabaseRef.current || snowflakeAccountId !== latestAccountIdRef.current) return;
        setSnowflakeSchemas([]);
        setSnowflakeDiscoveryError(err?.message || 'Could not load Snowflake schemas.');
      })
      .finally(() => {
        if (active && activeSnowflakeDatabase === latestDatabaseRef.current && snowflakeAccountId === latestAccountIdRef.current) {
          setSnowflakeSchemaLoading(false);
        }
      });

    return () => {
      active = false;
    };
  }, [
    activeSnowflakeDatabase,
    normalizeDiscoveryItems,
    snowflakeAccountId,
    sourceConnector,
    targetConnectors,
    setSnowflakeSchema,
    setTargetSchema,
  ]);

  const LABEL = {
    display: 'block', fontSize: 11, fontWeight: 700,
    color: 'var(--text-tertiary)', marginBottom: 6,
    textTransform: 'uppercase', letterSpacing: '0.05em'
  };
  const INPUT = {
    width: '100%', padding: '10px 14px', borderRadius: 8,
    background: 'var(--bg-surface-raised)', border: '1px solid var(--border-main)',
    color: 'var(--text-primary)', fontSize: 13, outline: 'none',
    transition: 'all 0.2s ease',
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 24, paddingBottom: 40 }}>
      <div>
        <h2 style={{ fontSize: 17, fontWeight: 700, color: 'var(--text-primary)', margin: '0 0 4px' }}>Connector Configuration</h2>
        <p style={{ fontSize: 13, color: 'var(--text-tertiary)', margin: 0 }}>
          Configure the source and target connectors for your project.
        </p>
      </div>

      <div style={SECTION_CARD}>
        <div style={{ marginBottom: 12 }}>
          <div style={{ fontSize: 13, fontWeight: 700, color: 'var(--text-primary)' }}>1. Source Configuration: {sourceLabel}</div>
        </div>

        {sourceConnector === 'snowflake' && (
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 12 }}>
            <div>
              <label style={LABEL}>Source Snowflake Account</label>
              <select
                value={snowflakeAccountId}
                onChange={e => handleSnowflakeAccountSelect(e.target.value, 'source')}
                style={INPUT}
              >
                {snowflakeAccounts.length === 0 && <option value="">No saved Snowflake accounts</option>}
                {snowflakeAccounts.map(acc => (
                  <option key={getAccountId(acc)} value={getAccountId(acc)}>
                    {getAccountLabel(acc)}
                  </option>
                ))}
              </select>
            </div>
            <div>
              <label style={LABEL}>Source Warehouse</label>
              <select
                value={targetWarehouse}
                onChange={e => setTargetWarehouse(e.target.value)}
                style={INPUT}
                disabled={snowflakeDiscoveryLoading || snowflakeWarehouses.length === 0}
              >
                {snowflakeDiscoveryLoading && <option value="">Loading warehouses...</option>}
                {!snowflakeDiscoveryLoading && snowflakeWarehouses.length === 0 && <option value="">No warehouses found</option>}
                {snowflakeWarehouses.map(item => (
                  <option key={item.id} value={item.id}>{item.name}</option>
                ))}
              </select>
            </div>
            <div style={{ gridColumn: 'span 2', display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 12 }}>
              <div>
                <label style={LABEL}>Source Database</label>
                <select
                  value={snowflakeDatabase}
                  onChange={e => setSnowflakeDatabase(e.target.value)}
                  style={INPUT}
                  disabled={snowflakeDiscoveryLoading || snowflakeDatabases.length === 0}
                >
                  {snowflakeDiscoveryLoading && <option value="">Loading databases...</option>}
                  {!snowflakeDiscoveryLoading && snowflakeDatabases.length === 0 && <option value="">No databases found</option>}
                  {snowflakeDatabases.map(item => (
                    <option key={item.id} value={item.id}>{item.name}</option>
                  ))}
                </select>
              </div>
              <div>
                <label style={LABEL}>Source Schema</label>
                <select
                  value={snowflakeSchema}
                  onChange={e => setSnowflakeSchema(e.target.value)}
                  style={INPUT}
                  disabled={snowflakeSchemaLoading || snowflakeSchemas.length === 0}
                >
                  {snowflakeSchemaLoading && <option value="">Loading schemas...</option>}
                  {!snowflakeSchemaLoading && snowflakeSchemas.length === 0 && <option value="">No schemas found</option>}
                  {snowflakeSchemas.map(item => (
                    <option key={item.id} value={item.id}>{item.name}</option>
                  ))}
                </select>
              </div>
            </div>
            {snowflakeDiscoveryError && (
              <div style={{ gridColumn: 'span 2', color: 'var(--color-error)', fontSize: 11 }}>
                {snowflakeDiscoveryError}
              </div>
            )}
          </div>
        )}

        {sourceConnector === 'fabric' && (
          <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
            <div>
              <label style={LABEL}>Fabric Account</label>
              <select
                value={fabricAccountId}
                onChange={e => {
                  const nextAccountId = e.target.value;
                  setFabricAccountId(nextAccountId);
                  setFabricWorkspaceId('');
                  fetchFabricWorkspaces(nextAccountId);
                }}
                style={INPUT}
              >
                <option value="" disabled>Select Fabric connection</option>
                {fabricAccounts.length === 0 && <option value="" disabled>No accounts available</option>}
                {fabricAccounts.length > 0 && fabricAccounts.map(acc => (
                  <option key={getAccountId(acc)} value={getAccountId(acc)}>
                    {getAccountLabel(acc)}
                  </option>
                ))}
              </select>
            </div>

            <div>
              <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 6 }}>
                <label style={{ ...LABEL, margin: 0 }}>Source Fabric Workspace</label>
                <div style={{ flex: 1 }} />
                <button
                  onClick={() => fetchFabricWorkspaces(fabricAccountId)}
                  disabled={isRefreshingWorkspaces || !fabricAccountId}
                  style={{
                    display: 'flex', alignItems: 'center', gap: 4,
                    background: 'none', border: 'none', cursor: (isRefreshingWorkspaces || !fabricAccountId) ? 'not-allowed' : 'pointer',
                    fontSize: 11, color: 'var(--text-tertiary)', padding: '2px 6px',
                    borderRadius: 4, transition: 'all 0.2s ease',
                    opacity: (isRefreshingWorkspaces || !fabricAccountId) ? 0.6 : 1
                  }}
                  title="Refresh workspaces"
                >
                  <RefreshCw size={12} style={{ animation: isRefreshingWorkspaces ? 'spin 1s linear infinite' : 'none' }} />
                  Refresh
                </button>
              </div>
              <SearchableSelect
                key={`fabric-source-${fabricAccountId || 'none'}-${workspaces.length}-${isRefreshingWorkspaces ? 'loading' : 'ready'}`}
                items={workspaces}
                displayKey="name"
                valueKey="id"
                searchFields={['name', 'id', 'workspace_id']}
                placeholder={isRefreshingWorkspaces ? 'Refreshing...' : "Choose a workspace"}
                value={fabricWorkspaceId}
                onChange={item => setFabricWorkspaceId(item?.id || '')}
                loading={workspacesLoading || isRefreshingWorkspaces}
                clearable={false}
                defaultOpen={sourceConnector === 'fabric' && workspaces.length > 0}
              />
              <p style={{ fontSize: 11, color: 'var(--text-tertiary)', marginTop: 5 }}>
                Select the workspace containing the semantic models you want to migrate.
              </p>
              {workspaceDiscoveryError && (
                <p style={{ fontSize: 11, color: 'var(--color-error)', marginTop: 6 }}>
                  {workspaceDiscoveryError}
                </p>
              )}
            </div>
          </div>
        )}

        {sourceConnector === 'pbix' && (() => {
          const hasUploadedPbix = Boolean(pbixUploadPath || pbixFile) && !pbixUploading && !pbixUploadError;
          return (
            <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
              <div>
                <label style={LABEL}>PBIX Source Mode</label>
                <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap' }}>
                  {PBIX_SOURCE_MODES.map(mode => {
                    const active = pbixSourceMode === mode.value;
                    const isManualTab = mode.value === 'MANUAL';
                    const isSuccessTab = isManualTab && hasUploadedPbix;

                    let borderStyle = `1px solid ${active ? 'var(--accent-blue)' : 'var(--border-main)'}`;
                    let bgStyle = active ? 'var(--accent-blue)14' : 'var(--bg-surface)';
                    let colorStyle = active ? 'var(--accent-blue)' : 'var(--text-secondary)';

                    if (isSuccessTab) {
                      borderStyle = active ? '1px solid #22c55e' : '1px solid rgba(34, 197, 94, 0.6)';
                      bgStyle = active ? 'rgba(34, 197, 94, 0.25)' : 'rgba(34, 197, 94, 0.12)';
                      colorStyle = '#86efac';
                    }

                    return (
                      <button
                        key={mode.value}
                        type="button"
                        onClick={() => setPbixSourceMode(mode.value)}
                        style={{
                          border: borderStyle,
                          background: bgStyle,
                          color: colorStyle,
                          borderRadius: 999,
                          padding: '7px 14px',
                          cursor: 'pointer',
                          fontSize: 12,
                          fontWeight: 700,
                          display: 'inline-flex',
                          alignItems: 'center',
                          gap: 6,
                          transition: 'all 0.2s ease',
                          boxShadow: isSuccessTab ? '0 0 10px rgba(34, 197, 94, 0.25)' : 'none',
                        }}
                      >
                        {isSuccessTab && <CheckCircle2 size={13} style={{ color: '#4ade80' }} />}
                        {mode.label}
                      </button>
                    );
                  })}
                </div>
              </div>

            {pbixSourceMode === 'TAG' ? (
              <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
                <div>
                  <label style={LABEL}>Folder Tag</label>
                  <select
                    value={selectedLocalFolderId}
                    onChange={(event) => setSelectedLocalFolderId(event.target.value)}
                    style={INPUT}
                  >
                    <option value="">Select Folder Tag...</option>
                    {activeLocalFolders.map(folder => (
                      <option key={folder.id} value={folder.id}>
                        {folder.tag_name} ({folder.absolute_path})
                      </option>
                    ))}
                  </select>
                  <p style={{ fontSize: 11, color: 'var(--text-tertiary)', marginTop: 5 }}>
                    {localFoldersLoading
                      ? 'Loading trusted local folders…'
                      : activeLocalFolders.length === 0
                        ? 'No active local folders are registered in Settings yet.'
                        : 'Step 3 will show the PBIX files inside the selected tagged folder.'}
                  </p>
                </div>
              </div>
            ) : (
              <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
                <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
                  <label style={LABEL}>PBIX Upload</label>
                  <div style={{ display: 'flex', gap: 6 }}>
                    {[
                      { value: false, label: 'Single file' },
                      { value: true, label: 'Multiple files' },
                    ].map((opt) => {
                      const active = pbixMultiFileMode === opt.value;
                      return (
                        <button
                          key={String(opt.value)}
                          type="button"
                          onClick={() => setPbixMultiFileMode(opt.value)}
                          style={{
                            border: `1px solid ${active ? 'var(--accent-blue)' : 'var(--border-main)'}`,
                            background: active ? 'var(--accent-blue)14' : 'var(--bg-surface)',
                            color: active ? 'var(--accent-blue)' : 'var(--text-secondary)',
                            borderRadius: 999,
                            padding: '4px 10px',
                            cursor: 'pointer',
                            fontSize: 11,
                            fontWeight: 700,
                          }}
                        >
                          {opt.label}
                        </button>
                      );
                    })}
                  </div>
                </div>

                {pbixMultiFileMode ? (
                  <MultiPbixUpload
                    entries={pbixFileEntries}
                    onAddFiles={onAddPbixFiles}
                    onRemove={onRemovePbixFile}
                    maxFiles={maxPbixFiles}
                  />
                ) : (() => {
                  const hasUploadedPbix = Boolean(pbixUploadPath) && !pbixUploading && !pbixUploadError;
                  return (
                <label
                  onDragOver={(event) => {
                    event.preventDefault();
                    event.stopPropagation();
                    setPbixDragOver(true);
                  }}
                  onDragLeave={(event) => {
                    event.preventDefault();
                    event.stopPropagation();
                    setPbixDragOver(false);
                  }}
                  onDrop={handlePbixDrop}
                  style={{
                    position: 'relative',
                    border: hasUploadedPbix
                      ? '1px dashed #22c55e'
                      : '1px dashed var(--accent-blue)',
                    borderRadius: 12,
                    padding: 18,
                    background: pbixDragOver
                      ? 'var(--accent-blue)14'
                      : hasUploadedPbix
                        ? 'rgba(34, 197, 94, 0.08)'
                        : 'var(--accent-blue)08',
                    color: 'var(--text-secondary)',
                    cursor: pbixUploading ? 'progress' : 'pointer',
                    transition: 'all 0.2s ease',
                  }}
                >
                  <input
                    type="file"
                    accept=".pbix"
                    style={{ display: 'none' }}
                    disabled={pbixUploading}
                    onChange={async (event) => {
                      const nextFile = event.target.files?.[0] || null;
                      if (nextFile) await uploadPbixFile(nextFile);
                    }}
                  />
                  {hasUploadedPbix && (
                    <div style={{ position: 'absolute', top: 10, right: 10 }}>
                      <RemoveFileButton
                        title="Remove file"
                        onClick={() => {
                          setPbixUploadError('');
                          setPbixDragOver(false);
                          onClearPbix();
                        }}
                      />
                    </div>
                  )}
                  <div style={{ fontSize: 13, fontWeight: 600, color: 'var(--text-primary)', marginBottom: 6, display: 'flex', alignItems: 'center', gap: 8 }}>
                    <span>Drag and drop a `.pbix` file here or click to browse</span>
                    {pbixUploading && <Loader2 size={14} style={{ animation: 'spin 1s linear infinite' }} />}
                    {hasUploadedPbix && (
                      <span style={{
                        fontSize: 11,
                        fontWeight: 700,
                        color: '#4ade80',
                        background: 'rgba(34, 197, 94, 0.22)',
                        border: '1px solid rgba(34, 197, 94, 0.45)',
                        borderRadius: 6,
                        padding: '2px 8px',
                        display: 'inline-flex',
                        alignItems: 'center',
                        gap: 4,
                        marginLeft: 'auto',
                      }}>
                        <CheckCircle2 size={12} /> Uploaded Successfully
                      </span>
                    )}
                  </div>
                  <div style={{ fontSize: 12, color: hasUploadedPbix ? '#86efac' : 'var(--text-tertiary)', wordBreak: 'break-all', fontWeight: hasUploadedPbix ? 500 : 400 }}>
                    {pbixUploading
                      ? 'Saving file to server...'
                      : pbixUploadPath
                        ? `Saved path: ${pbixUploadPath}`
                        : pbixFile
                          ? `Selected file: ${pbixFile.name}`
                          : 'The file is uploaded temporarily and passed to LocalPBIXConnector during sync.'}
                  </div>
                  {pbixUploading && (
                    <div style={{ marginTop: 10, width: '100%', height: 6, borderRadius: 999, background: 'var(--border-main)', overflow: 'hidden' }}>
                      <div style={{ width: '100%', height: '100%', background: 'var(--accent-blue)', animation: 'pulse 1.2s ease-in-out infinite' }} />
                    </div>
                  )}
                  {pbixUploadError && (
                    <div style={{ marginTop: 8, fontSize: 12, color: 'var(--color-error)' }}>
                      {pbixUploadError}
                    </div>
                  )}
                </label>
                  );
                })()}
              </div>
            )}
          </div>
        );
        })()}

        {sourceConnector === 'tableau' && (() => {
          const hasUploadedTableau = Boolean(pbixUploadPath || pbixFile) && !pbixUploading && !pbixUploadError;
          return (
            <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
              <div>
                <label style={LABEL}>Tableau Data Source (.tds / .tdsx / .twb / .twbx)</label>
                <div style={{ fontSize: 12, color: 'var(--text-tertiary)', marginBottom: 12 }}>
                  Upload a Tableau data source XML (.tds), packaged data source archive (.tdsx), workbook (.twb), or packaged workbook (.twbx).
                </div>
                <label
                  style={{
                    display: 'block',
                    border: hasUploadedTableau ? '1px dashed #22c55e' : '1px dashed var(--border-main)',
                    borderRadius: 10,
                    padding: '24px 16px',
                    textAlign: 'center',
                    cursor: pbixUploading ? 'progress' : 'pointer',
                    background: hasUploadedTableau ? 'rgba(34, 197, 94, 0.05)' : 'var(--bg-surface)',
                  }}
                >
                  <input
                    type="file"
                    accept=".tds,.tdsx,.twb,.twbx"
                    disabled={pbixUploading}
                    onChange={async (e) => {
                      const nextFile = e.target.files?.[0];
                      if (nextFile) await uploadPbixFile(nextFile);
                    }}
                    style={{ display: 'none' }}
                  />
                  <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 8 }}>
                    <PieChart size={24} color="#E8762D" />
                    <div style={{ fontSize: 13, fontWeight: 600, color: 'var(--text-primary)' }}>
                      {hasUploadedTableau ? 'Tableau File Attached' : 'Click or Drag to Upload Tableau File'}
                    </div>
                    <div style={{ fontSize: 12, color: hasUploadedTableau ? '#86efac' : 'var(--text-tertiary)' }}>
                      {pbixUploading ? 'Uploading file...' : pbixUploadPath ? pbixUploadPath : 'Supported formats: .tds, .tdsx, .twb, .twbx'}
                    </div>
                  </div>
                </label>
                {pbixUploadError && (
                  <div style={{ marginTop: 8, fontSize: 12, color: 'var(--color-error)' }}>
                    {pbixUploadError}
                  </div>
                )}
              </div>
            </div>
          );
        })()}

        {sourceConnector !== 'fabric' && sourceConnector !== 'snowflake' && sourceConnector !== 'pbix' && sourceConnector !== 'tableau' && (
          <div style={{ fontSize: 12, color: 'var(--text-tertiary)', lineHeight: 1.5 }}>
            Source connector defaults will be resolved from the saved global connection.
          </div>
        )}
      </div>

      <div style={SECTION_CARD}>
        <div style={{ marginBottom: 12 }}>
          <div style={{ fontSize: 13, fontWeight: 700, color: 'var(--text-primary)' }}>2. Target Configuration</div>
          <div style={{ fontSize: 11, color: 'var(--text-tertiary)', marginTop: 3 }}>
            Configure each selected target separately. Leave fields empty to use global defaults.
          </div>
        </div>

        {selectedTargets.length === 0 && (
          <div style={{ fontSize: 12, color: 'var(--text-tertiary)' }}>
            No target connector selected. Go back to Basic Info and choose at least one target.
          </div>
        )}

        <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
          {selectedTargets.map(target => {
            const targetMeta = TARGET_CONNECTOR_TYPES.find(t => t.value === target) || { label: target };
            return (
              <details key={target} open style={{ border: '1px solid var(--border-main)', borderRadius: 10 }}>
                <summary
                  style={{
                    listStyle: 'none',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'space-between',
                    gap: 8,
                    padding: '10px 12px',
                    background: 'var(--bg-surface-raised)',
                    color: 'var(--text-primary)',
                    fontSize: 12,
                    fontWeight: 700,
                    cursor: 'pointer',
                  }}
                >
                  <span style={{ display: 'inline-flex', alignItems: 'center', gap: 8 }}>
                    <SourceIcon source={targetMeta.value ?? target} size={16} />
                    {targetMeta.label} Target Configuration
                  </span>
                  <ChevronDown size={14} />
                </summary>

                <div style={{ padding: 12, background: 'var(--bg-surface)' }}>
                  {target === 'snowflake' && (
                    <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 12 }}>
                      <div>
                        <label style={LABEL}>Snowflake Account</label>
                        <select
                          value={snowflakeAccountId}
                          onChange={e => handleSnowflakeAccountSelect(e.target.value, 'target')}
                          style={INPUT}
                        >
                          {snowflakeAccounts.length === 0 && <option value="">No saved Snowflake accounts</option>}
                          {snowflakeAccounts.map(acc => (
                            <option key={getAccountId(acc)} value={getAccountId(acc)}>
                              {getAccountLabel(acc)}
                            </option>
                          ))}
                        </select>
                      </div>
                      <div>
                        <label style={LABEL}>Snowflake Warehouse</label>
                        <select
                          value={targetWarehouse}
                          onChange={e => setTargetWarehouse(e.target.value)}
                          style={INPUT}
                          disabled={snowflakeDiscoveryLoading || snowflakeWarehouses.length === 0}
                        >
                          {snowflakeDiscoveryLoading && <option value="">Loading warehouses...</option>}
                          {!snowflakeDiscoveryLoading && snowflakeWarehouses.length === 0 && <option value="">No warehouses found</option>}
                          {snowflakeWarehouses.map(item => (
                            <option key={item.id} value={item.id}>{item.name}</option>
                          ))}
                        </select>
                      </div>
                      <div>
                        <label style={LABEL}>Snowflake Database</label>
                        <select
                          value={targetDatabase}
                          onChange={e => setTargetDatabase(e.target.value)}
                          style={INPUT}
                          disabled={snowflakeDiscoveryLoading || snowflakeDatabases.length === 0}
                        >
                          {snowflakeDiscoveryLoading && <option value="">Loading databases...</option>}
                          {!snowflakeDiscoveryLoading && snowflakeDatabases.length === 0 && <option value="">No databases found</option>}
                          {snowflakeDatabases.map(item => (
                            <option key={item.id} value={item.id}>{item.name}</option>
                          ))}
                        </select>
                      </div>
                      <div>
                        <label style={LABEL}>Snowflake Schema</label>
                        <select
                          value={targetSchema}
                          onChange={e => setTargetSchema(e.target.value)}
                          style={INPUT}
                          disabled={snowflakeSchemaLoading || snowflakeSchemas.length === 0}
                        >
                          {snowflakeSchemaLoading && <option value="">Loading schemas...</option>}
                          {!snowflakeSchemaLoading && snowflakeSchemas.length === 0 && <option value="">No schemas found</option>}
                          {snowflakeSchemas.map(item => (
                            <option key={item.id} value={item.id}>{item.name}</option>
                          ))}
                        </select>
                      </div>
                      {snowflakeDiscoveryError && (
                        <div style={{ gridColumn: 'span 2', color: 'var(--color-error)', fontSize: 11 }}>
                          {snowflakeDiscoveryError}
                        </div>
                      )}
                    </div>
                  )}

                  {target === 'fabric' && (
                    <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
                      <div>
                        <label style={LABEL}>Fabric Account</label>
                        <select
                          value={fabricAccountId}
                          onChange={e => {
                            const nextAccountId = e.target.value;
                            setFabricAccountId(nextAccountId);
                            setFabricWorkspaceId('');
                            fetchFabricWorkspaces(nextAccountId);
                          }}
                          style={INPUT}
                        >
                          {fabricAccounts.length === 0 && <option value="" disabled>No accounts available</option>}
                          {fabricAccounts.length > 0 && fabricAccounts.map(acc => (
                            <option key={getAccountId(acc)} value={getAccountId(acc)}>
                              {(acc.tag || acc.identity_email || acc.id)} ({acc.identity_email || 'N/A'})
                            </option>
                          ))}
                        </select>
                        <p style={{ fontSize: 11, color: 'var(--text-tertiary)', marginTop: 5 }}>
                          Choose the Fabric identity for target deployment.
                        </p>
                      </div>

                      <div>
                        <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 6 }}>
                          <label style={{ ...LABEL, margin: 0 }}>Target Fabric Workspace</label>
                          <div style={{ flex: 1 }} />
                          <button
                            onClick={() => fetchFabricWorkspaces(fabricAccountId)}
                            disabled={isRefreshingWorkspaces || !fabricAccountId}
                            style={{
                              display: 'flex', alignItems: 'center', gap: 4,
                              background: 'none', border: 'none', cursor: (isRefreshingWorkspaces || !fabricAccountId) ? 'not-allowed' : 'pointer',
                              fontSize: 11, color: 'var(--text-tertiary)', padding: '2px 6px',
                              borderRadius: 4, transition: 'all 0.2s ease',
                              opacity: (isRefreshingWorkspaces || !fabricAccountId) ? 0.6 : 1
                            }}
                            title="Refresh workspaces"
                          >
                            <RefreshCw size={12} style={{ animation: isRefreshingWorkspaces ? 'spin 1s linear infinite' : 'none' }} />
                            Refresh
                          </button>
                        </div>

                        <SearchableSelect
                          key={`fabric-target-${fabricAccountId || 'none'}-${workspaces.length}-${isRefreshingWorkspaces ? 'loading' : 'ready'}`}
                          items={workspaces}
                          displayKey="name"
                          valueKey="id"
                          searchFields={['name', 'id', 'workspace_id']}
                          placeholder={isRefreshingWorkspaces ? 'Refreshing...' : 'Choose a target workspace'}
                          value={fabricWorkspaceId}
                          onChange={item => {
                            const newId = item?.id || '';
                            setFabricWorkspaceId(newId);
                          }}
                          loading={workspacesLoading || isRefreshingWorkspaces}
                          clearable={false}
                          defaultOpen={targetConnectors.has('fabric') && workspaces.length > 0}
                        />

                        <p style={{ fontSize: 11, color: 'var(--text-tertiary)', marginTop: 5 }}>
                          Choose the destination Fabric workspace for this target sync.
                        </p>
                        {workspaceDiscoveryError && (
                          <p style={{ fontSize: 11, color: 'var(--color-error)', marginTop: 6 }}>
                            {workspaceDiscoveryError}
                          </p>
                        )}
                      </div>
                    </div>
                  )}

                  {target === 'databricks' && (
                    <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
                      {databricksAccounts.length > 0 && (
                        <div>
                          <label style={LABEL}>Databricks Account</label>
                          <select
                            value={databricksAccountId}
                            onChange={e => setDatabricksAccountId(e.target.value)}
                            style={INPUT}
                          >
                            {databricksAccounts.map(acc => (
                              <option key={getAccountId(acc)} value={getAccountId(acc)}>
                                {(acc.tag || acc.identity_email || acc.id)} ({acc.identity_email || 'N/A'})
                              </option>
                            ))}
                          </select>
                          <p style={{ fontSize: 11, color: 'var(--text-tertiary)', marginTop: 5 }}>
                            Select which Databricks identity to use for deployment.
                          </p>
                        </div>
                      )}
                      {databricksAccounts.length === 0 && (
                        <div style={{ fontSize: 12, color: 'var(--text-tertiary)', lineHeight: 1.5 }}>
                          No Databricks accounts configured. This target will use global connection defaults from Settings.
                        </div>
                      )}
                    </div>
                  )}

                  {target !== 'snowflake' && target !== 'fabric' && target !== 'databricks' && (
                    <div style={{ fontSize: 12, color: 'var(--text-tertiary)', lineHeight: 1.5 }}>
                      This target will use global connection defaults from Settings.
                    </div>
                  )}
                </div>
              </details>
            );
          })}
        </div>
      </div>

    </div>
  );
}

import React from 'react';
import { Check, Loader2, Settings2 } from 'lucide-react';
import { ToggleOption, footerBtn } from '../WizardUIComponents';

export function StepFinish({
  name,
  saving,
  createReverseProject,
  setCreateReverseProject,
  createdProject,
  createError,
  runWarning,
  sourceConnector,
  targetConnectors,
  intermediateFormat,
  selectedWorkspace,
  navigate,
  editMode,
  diff,
  selectedModels,
  savedModels,
  selectedModelNameByKey,
  pbixSourceLabels = [],
  savedPbixSourceLabels = [],
  onClear,
}) {
  const createdProjectId = createdProject?.id || createdProject?.project_id;

  if (saving && !createdProject) {
    return (
      <div style={{ textAlign: 'center', padding: '40px 0' }}>
        <div style={{ width: 56, height: 56, borderRadius: '50%', background: 'var(--accent-blue)20', display: 'flex', alignItems: 'center', justifyContent: 'center', margin: '0 auto 16px' }}>
          <Loader2 size={28} style={{ color: 'var(--accent-blue)', animation: 'spin 1s linear infinite' }} />
        </div>
        <h2 style={{ fontSize: 18, fontWeight: 700, color: 'var(--text-primary)', marginBottom: 8 }}>{editMode ? 'Saving Changes' : 'Creating Project'}</h2>
        <p style={{ fontSize: 13, color: 'var(--text-tertiary)', marginBottom: 24 }}>
          {editMode ? `Updating configuration for "${name}"...` : `Setting up configurations and initializing "${name}"...`}
        </p>
      </div>
    );
  }

  if (createdProject) {
    return (
      <div style={{ display: 'flex', flexDirection: 'column', gap: 20, padding: '20px 0' }}>
        <div style={{ textAlign: 'center' }}>
          <div style={{ width: 56, height: 56, borderRadius: '50%', background: 'var(--color-success)20', display: 'flex', alignItems: 'center', justifyContent: 'center', margin: '0 auto 16px' }}>
            <Check size={28} style={{ color: 'var(--color-success)' }} />
          </div>
          <h2 style={{ fontSize: 18, fontWeight: 700, color: 'var(--text-primary)', marginBottom: 8 }}>{editMode ? 'Project Updated!' : 'Project Created!'}</h2>
          <p style={{ fontSize: 13, color: 'var(--text-tertiary)', marginBottom: 24 }}>
            {editMode ? `Project "${name}" has been updated successfully. You can now review your configuration or start your first sync.` : `Project "${name}" has been created successfully. You can now review your configuration or start your first sync.`}
          </p>
        </div>
        {runWarning && (
          <div style={{ maxWidth: 640, padding: '12px 14px', borderRadius: 10, background: 'var(--bg-surface)', border: '1px solid var(--border-main)', color: 'var(--text-secondary)', fontSize: 12, lineHeight: 1.5, textAlign: 'left' }}>
            {runWarning}
          </div>
        )}

        <div style={{ display: 'flex', gap: 10, justifyContent: 'center' }}>
          <button onClick={() => { onClear?.(); navigate('/projects'); }} style={footerBtn('secondary')}>Back to Projects</button>
          {createdProjectId ? (
            <button onClick={() => navigate(`/projects/${createdProjectId}/config`)} style={footerBtn('primary')}>
              Go to Config &amp; Sync
            </button>
          ) : (
            <button disabled style={{ ...footerBtn('secondary'), opacity: 0.6, cursor: 'not-allowed' }}>
              Configure Project (ID unavailable)
            </button>
          )}
        </div>
      </div>
    );
  }

  const renderDiff = (key, label) => {
    if (!diff || !diff[key]) return null;
    return (
      <div style={{ padding: '12px 14px', borderRadius: 8, background: 'var(--bg-surface-raised)', border: '1px solid var(--accent-blue)40', marginBottom: 12 }}>
        <div style={{ fontSize: 11, fontWeight: 700, color: 'var(--accent-blue)', textTransform: 'uppercase', marginBottom: 6, display: 'flex', alignItems: 'center', gap: 6 }}>
          <Settings2 size={12} /> Edited: {label}
        </div>
        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 16 }}>
          <div>
            <div style={{ fontSize: 10, color: 'var(--text-tertiary)', marginBottom: 2 }}>Original</div>
            <div style={{ fontSize: 12, color: 'var(--text-secondary)', textDecoration: 'line-through' }}>{diff[key].old || <span style={{ fontStyle: 'italic', opacity: 0.5 }}>Empty</span>}</div>
          </div>
          <div>
            <div style={{ fontSize: 10, color: 'var(--text-tertiary)', marginBottom: 2 }}>New</div>
            <div style={{ fontSize: 12, color: 'var(--text-primary)', fontWeight: 500 }}>{diff[key].new || <span style={{ fontStyle: 'italic', opacity: 0.5 }}>Empty</span>}</div>
          </div>
        </div>
      </div>
    );
  };

  const showDiffs = editMode && diff && Object.keys(diff).length > 0;

  const isPbix = String(sourceConnector || '').toLowerCase() === 'pbix';
  // De-duplicated display names (a model selected under both its name and
  // its GUID is listed once).
  const namesFor = (keys) => [...new Set(Array.from(keys || [])
    .map(id => selectedModelNameByKey?.[id] || String(id).split('::').pop()))]
    .sort()
    .join(', ');

  // PBIX: list the actual file(s) that will be saved -- never "Everything (*)".
  const currentSelectionNames = isPbix
    ? (pbixSourceLabels.length > 0 ? pbixSourceLabels.join(', ') : 'No PBIX file selected')
    : (selectedModels?.size > 0 ? namesFor(selectedModels) : 'Everything (*)');

  const wasSelectionNames = isPbix
    ? (savedPbixSourceLabels.length > 0 ? savedPbixSourceLabels.join(', ') : 'No PBIX file selected')
    : (savedModels?.size > 0 ? namesFor(savedModels) : 'Everything (*)');

  const modelsChanged = editMode && currentSelectionNames !== wasSelectionNames;

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 20 }}>
      <div>
        <h2 style={{ fontSize: 17, fontWeight: 700, color: 'var(--text-primary)', margin: '0 0 4px' }}>
          {editMode ? 'Review Changes' : 'Ready to Create'}
        </h2>
        <p style={{ fontSize: 13, color: 'var(--text-tertiary)', margin: 0 }}>
          {editMode ? 'Review your changes and save the project configuration.' : 'Review your choices and create the project.'}
        </p>
      </div>

      {showDiffs && (
        <div style={{ padding: '16px', borderRadius: 10, background: 'var(--bg-surface)', border: '1px solid var(--border-main)' }}>
          <div style={{ fontSize: 12, fontWeight: 700, color: 'var(--text-primary)', marginBottom: 12, textTransform: 'uppercase' }}>Configuration Changes</div>
          {renderDiff('name', 'Project Name')}
          {renderDiff('description', 'Description')}
          {renderDiff('tags', 'Tags')}
          {renderDiff('sourceConnector', 'Source Connector')}
          {renderDiff('targetConnectors', 'Target Connector(s)')}
        </div>
      )}

      {/* The beautiful summary layout */}
      <div style={{ padding: '16px', borderRadius: 10, background: 'var(--bg-surface)', border: '1px solid var(--border-main)', display: 'grid', gap: 16 }}>
        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 16 }}>
          <div>
            <div style={{ fontSize: 10, fontWeight: 700, color: 'var(--text-tertiary)', textTransform: 'uppercase', marginBottom: 4 }}>Project Name</div>
            <div style={{ fontSize: 13, fontWeight: 600, color: 'var(--text-primary)' }}>{name}</div>
          </div>
          <div>
            <div style={{ fontSize: 10, fontWeight: 700, color: 'var(--text-tertiary)', textTransform: 'uppercase', marginBottom: 4 }}>Source</div>
            <div style={{ fontSize: 13, fontWeight: 600, color: 'var(--text-primary)' }}>{sourceConnector}</div>
          </div>
        </div>
        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 16 }}>
          <div>
