const hasOntologyChanges = (c) => Boolean(c && typeof c === 'object' && (
  Object.values(c.applied || {}).some((n) => Number(n) > 0) ||
  ['descriptions', 'synonyms', 'verified_queries', 'formula_overrides_ignored'].some((k) => Array.isArray(c[k]) && c[k].length > 0)
));

const ONTOLOGY_API_BASE = (import.meta.env.VITE_API_BASE_URL || '/api').replace(/\/$/, '');

async function ontologyConflictRequest(projectId, body) {
  const url = `${ONTOLOGY_API_BASE}/ontology/projects/${encodeURIComponent(projectId)}/conflict-resolution`;
  const res = await authFetch(url, body
    ? { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) }
    : {});
  const data = await res.json().catch(() => ({}));
  if (!res.ok) {
    const detail = data?.detail;
    const msg = Array.isArray(detail?.errors) ? detail.errors.join('; ')
      : (typeof detail === 'string' ? detail : detail?.message);
    throw new Error(msg || `Request failed (${res.status})`);
  }
  return data;
}

/**
 * Choose how metrics defined with different formulas in several attached
 * domains are resolved: domain priority order (first wins) or namespacing
 * (every definition kept, prefixed by its domain). Saved per project and used
 * by the dry run and the deploy.
 */
function OntologyConflictResolver({ projectId, blockers = [], resolution, onApplied }) {
  const [state, setState] = useState(null);
  const [mode, setMode] = useState('priority');
  const [order, setOrder] = useState([]);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');
  const enabled = Boolean(projectId && projectId !== 'preview');

  useEffect(() => {
    if (!enabled) return undefined;
    let alive = true;
    ontologyConflictRequest(projectId)
      .then((s) => {
        if (!alive) return;
        setState(s);
        setMode(s?.mode || 'priority');
        setOrder(s?.priority || []);
      })
      .catch((e) => alive && setError(e.message));
    return () => { alive = false; };
  }, [enabled, projectId]);

  const resolved = resolution?.resolved || [];
  if (!blockers.length && !resolved.length) return null;

  const move = (i, d) => setOrder((prev) => {
    const next = [...prev];
    const j = i + d;
    if (j < 0 || j >= next.length) return prev;
    [next[i], next[j]] = [next[j], next[i]];
    return next;
  });

  const save = async () => {
    setSaving(true);
    setError('');
    try {
      const s = await ontologyConflictRequest(projectId, { mode, priority: mode === 'priority' ? order : null });
      setState(s);
      setSaving(false);
      await onApplied?.();
    } catch (e) {
      setSaving(false);
      setError(e.message);
    }
  };

  const box = { marginTop: 6, padding: 10, borderRadius: 8, border: '1px solid var(--border-main)', background: 'var(--bg-surface)', display: 'flex', flexDirection: 'column', gap: 6 };
  const small = { fontSize: 11.5, color: 'var(--text-secondary)' };
  const btnStyle = { fontSize: 11, padding: '2px 8px', borderRadius: 6, border: '1px solid var(--border-main)', background: 'var(--bg-surface-raised, var(--bg-surface))', color: 'var(--text-primary)', cursor: 'pointer' };

  return (
    <div style={box}>
      {resolved.map((r, i) => (
        <div key={`res-${i}`} style={{ ...small, color: 'var(--color-success, var(--text-secondary))' }}>Resolved: {r.message}</div>
      ))}
      {!enabled ? (
        <div style={small}>Save the project first to choose how conflicting metric definitions are resolved.</div>
      ) : (
        <>
          <div style={{ fontSize: 12, fontWeight: 600, color: 'var(--text-primary)' }}>Resolve conflicting metric definitions</div>
          <label style={{ ...small, display: 'flex', gap: 6, alignItems: 'center' }}>
            <input type="radio" name="ontology-conflict-mode" checked={mode === 'priority'} onChange={() => setMode('priority')} />
            Domain priority: the first domain in this order defines the metric
          </label>
          {mode === 'priority' && order.length > 0 && (
            <ol style={{ margin: '0 0 0 22px', padding: 0, display: 'flex', flexDirection: 'column', gap: 3 }}>
              {order.map((d, i) => (
                <li key={d} style={{ ...small, display: 'flex', gap: 6, alignItems: 'center' }}>
                  <span style={{ minWidth: 120, color: 'var(--text-primary)' }}>{i + 1}. {d}</span>
                  <button type="button" style={btnStyle} disabled={i === 0} onClick={() => move(i, -1)} aria-label={`Move ${d} up`}>Up</button>
                  <button type="button" style={btnStyle} disabled={i === order.length - 1} onClick={() => move(i, 1)} aria-label={`Move ${d} down`}>Down</button>
                </li>
              ))}
            </ol>
          )}
          <label style={{ ...small, display: 'flex', gap: 6, alignItems: 'center' }}>
            <input type="radio" name="ontology-conflict-mode" checked={mode === 'namespace'} onChange={() => setMode('namespace')} />
            Keep every definition, prefixed by its domain (e.g. Finance_Revenue, Sales_Revenue)
          </label>
          <div style={{ display: 'flex', gap: 8, alignItems: 'center' }}>
            <button type="button" style={{ ...btnStyle, fontWeight: 600 }} disabled={saving} onClick={save}>
              {saving ? 'Saving…' : 'Save choice and re-run dry run'}
            </button>
            {state?.mode && <span style={small}>Saved choice: {state.mode}</span>}
          </div>
        </>
      )}
      {error && <div style={{ ...small, color: 'var(--color-error, #dc2626)' }}>{error}</div>}
    </div>
  );
}

export function StepMappingOptions({
  autoRelationships,
  setAutoRelationships,
  generateDescriptions,
  setGenerateDescriptions,
  detectedMappings,
  mappingLoading,
  mappingError,
  dryRunStatus,
  dryRunError,
  unmappedAcknowledged,
  setUnmappedAcknowledged,
  selectedModelNames,
  sourceConnector,
  onRunDryRun,
  onClearMappings,
  onRowsChange,
  onProceedStateChange,
  primaryTargetConnector,
  // New dry-run → edit → deploy props
  dryRunData,
  editingRow,
  setEditingRow,
  isSavingEdit,
  isDeploying,
  deployError,
  onFieldEdit,
  onDeployMappings,
  targetConnectors,
  onBulkResolved,
  onSynonymUpdate,
  projectId,
  // Multi-model dry run (multiple PBIX files or multiple Fabric models):
  // when set, a background dry-run job is in flight/complete -- render one
  // collapsible section per model instead of the single-model table below.
  // Per-model state (sections) is owned by CreateProjectPage's
  // useMultiDryRunJob; every handler below is scoped to one model's file_id.
  multiDryRunJob,
  multiSections = [],
  multiJobStatus = null,
  multiPollError = '',
  onRetryMultiPolling,
  multiRerunningIds,
  multiRerunErrors,
  onMultiEditRow,
  onMultiBulkResolved,
  onMultiSynonymUpdate,
  onRetryMultiFile,
  onRemoveMultiFile,
}) {
  const [autoMappingMode, setAutoMappingMode] = useState(true);
  const [rows, setRows] = useState([]);
  const [needsRefresh, setNeedsRefresh] = useState(false);
  // The full mapping grid is one click away ("See all mappings"), not the default view.
  const [showAllMappings, setShowAllMappings] = useState(false);
  const mappingTableRef = useRef(null);
  const aiToggleInitRef = useRef(false);

  // Multi-model readiness: the job being CREATED (dryRunStatus='success' in
  // the parent) is not the job being DONE. Gate on every model's own
  // status + loaded result + blocking rows instead (see
  // utils/multiFileDryRunReadiness.js resolveMultiModelReadiness).
  const isMultiFileRun = Boolean(multiDryRunJob?.job_id);
  const multiReadiness = useMemo(() => resolveMultiModelReadiness(multiSections || []), [multiSections]);
  const multiRows = useMemo(
    () => (isMultiFileRun ? flattenSectionRows(multiSections || []) : []),
    [isMultiFileRun, multiSections],
  );
  const multiJobRunning = isMultiFileRun && multiReadiness.running;
  const multiJobSucceeded = isMultiFileRun && multiReadiness.allSucceeded;
  const multiJobHasFailures = isMultiFileRun && multiReadiness.hasFailures;

  const dryRunCompleted = isMultiFileRun ? multiJobSucceeded : dryRunStatus === 'success';
  const dryRunFailed = isMultiFileRun ? multiJobHasFailures : dryRunStatus === 'failed';
  const hasDryRunResult = dryRunCompleted;

  useEffect(() => {
    onRowsChange?.(rows);
  }, [rows]); // eslint-disable-line react-hooks/exhaustive-deps

  // If AI options change after initial mount, prompt a quick refresh.
  useEffect(() => {
    if (!aiToggleInitRef.current) {
      aiToggleInitRef.current = true;
      return;
    }
    setNeedsRefresh(true);
  }, [autoRelationships, generateDescriptions, aiToggleInitRef]);

  // Sync internal rows from detectedMappings when the parent updates it (e.g. after handleDryRun)
  useEffect(() => {
    if (Array.isArray(detectedMappings) && detectedMappings.length > 0) {
      setRows(detectedMappings);
      setNeedsRefresh(false);
    }
  }, [detectedMappings]); // eslint-disable-line react-hooks/exhaustive-deps

  // Rows every summary below is computed over: the single-model table's rows,
  // or every model's rows for a multi-model run.
  const effectiveRows = isMultiFileRun ? multiRows : rows;

  const singleBlockingCount = useMemo(
    () => rows.filter((row) => isBlockingRow(row)).length,
    [rows],
  );
  const blockingCount = isMultiFileRun ? multiReadiness.totalBlocking : singleBlockingCount;

  const sourceModel = useMemo(() => ({
    name: isMultiFileRun
      ? `${(multiSections || []).length} models`
      : (selectedModelNames?.[0] || 'Selected Sources'),
    type: sourceConnector || 'Source Model',
    field_count: effectiveRows.length,
  }), [effectiveRows.length, isMultiFileRun, multiSections, selectedModelNames, sourceConnector]);

  const targetModel = useMemo(() => ({
    name: primaryTargetConnector || 'Target Model',
    type: primaryTargetConnector || 'Target Connector',
    field_count: effectiveRows.filter(row => String(row.target_field || '').trim()).length,
  }), [primaryTargetConnector, effectiveRows]);
  const targetDestination = useMemo(() => {
    const firstMapped = effectiveRows.find((row) => String(row?.target_field || '').trim());
    if (firstMapped?.target_field) return firstMapped.target_field;
    return `${String(primaryTargetConnector || 'target').toUpperCase()}.PUBLIC.<TABLE>`;
  }, [effectiveRows, primaryTargetConnector]);

  const explicitTables = useMemo(() => {
    const names = isMultiFileRun
      ? (multiSections || []).map((section) => section.label)
      : (selectedModelNames || []);
    return Array.from(new Set(names.map(name => String(name || '').trim()).filter(Boolean)));
  }, [isMultiFileRun, multiSections, selectedModelNames]);

  const inferredTables = useMemo(() => {
    const explicitUpper = new Set(explicitTables.map(name => name.toUpperCase()));
    const rowTables = effectiveRows.flatMap((row) => {
      if (row.field_type === 'measure') return Array.isArray(row.measure_source_tables) ? row.measure_source_tables : [];
      return row.source_table_name ? [row.source_table_name] : [];
    });
    return Array.from(new Set(
      rowTables
          .map(name => String(name || '').trim())
          .filter(Boolean)
          .filter(name => !explicitUpper.has(name.toUpperCase()))
    ));
  }, [explicitTables, effectiveRows]);
  const visibleInferredTables = useMemo(() => {
    if (!autoMappingMode && !autoRelationships) return [];
    return inferredTables;
  }, [autoMappingMode, autoRelationships, inferredTables]);

  const counts = useMemo(() => {
    const summary = { all: effectiveRows.length, auto: 0, manual: 0, unmapped: 0, collision: 0 };
    effectiveRows.forEach(row => {
      if (summary[row.status] !== undefined) summary[row.status] += 1;
    });
    return summary;
  }, [effectiveRows]);
  const estimatedVolume = useMemo(() => {
    const totalFields = isMultiFileRun
      ? effectiveRows.length
      : Number(dryRunData?.summary?.total_fields || rows.length || 0);
    return `${totalFields} mapped fields`;
  }, [dryRunData, effectiveRows.length, isMultiFileRun, rows.length]);

  const isLoading =
    mappingLoading ||
    (isMultiFileRun
      ? multiJobRunning
      : dryRunStatus === "loading" || dryRunStatus === "running");

  // Real signals from the dry-run result — must be declared before readyToProceed / readiness / checkState
  const compatScore  = isMultiFileRun
    ? multiReadiness.minCompatibilityScore
    : (typeof dryRunData?.compatibility_score === 'number' ? dryRunData.compatibility_score : null);
  const schemaIssues = isMultiFileRun
    ? multiReadiness.totalSchemaConflicts
    : (Array.isArray(dryRunData?.schema_conflicts) ? dryRunData.schema_conflicts.length : 0);
  const hasIssues    = blockingCount > 0 || dryRunFailed || schemaIssues > 0 || (compatScore !== null && compatScore < 90);

  // The dry-run check must have completed (at least once) before the user can
  // proceed — regardless of mapping mode.  Without this guard the bar shows
  // green immediately because compatScore is null before any run has run.
  // Multi-model: every model succeeded, every result is loaded, and no model
  // has blocking rows or a sub-70 compatibility score.
  const readyToProceed = isMultiFileRun
    ? multiReadiness.ready
    : (dryRunCompleted &&
      blockingCount === 0 &&
      (compatScore === null || compatScore >= 70));

  useEffect(() => {
    onProceedStateChange?.(readyToProceed);
  }, [readyToProceed]); // eslint-disable-line react-hooks/exhaustive-deps

  const toggleAutoMappingMode = useCallback(() => {
    setAutoMappingMode((prev) => {
      const next = !prev;
      if (!next) {
        onClearMappings?.();
        setRows([]);
      }
      return next;
    });
  }, [onClearMappings]);

  const runDryRun = useCallback(async () => {
    await onRunDryRun?.();
  }, [onRunDryRun]);

  const handleInlineTargetChange = useCallback((rowId, value) => {
    const projectId = 'preview';
    // Optimistic update
    setRows((prev) => prev.map((row) => {
      if (row.id !== rowId) return row;
      const validation = validateTargetName(value, primaryTargetConnector, row.source_type, row.target_type, targetNameKind(row));
      if (validation.isValid) {
        return {
          ...row,
          target_field: value,
          status: 'manual',
          validation_status: 'valid',
          validation_code: 'OK',
          validation_message: '',
          suggested_target_name: validation.suggestion,
          collision_detected: false,
          isDirty: true,
        };
      }
      return {
        ...row,
        target_field: value,
        status: 'collision',
        validation_status: 'invalid',
        validation_code: 'INVALID_IDENTIFIER',
        validation_message: validation.error,
        suggested_target_name: validation.suggestion,
        collision_detected: true,
        isDirty: true,
      };
    }));

    // Call API
    api.updateMapping(projectId, rowId, value).catch(err => {
      console.error('Failed to update mapping:', err);
    });
  }, [primaryTargetConnector]);

  const applySuggestion = useCallback((rowId) => {
    setRows((prev) => prev.map((row) => {
      if (row.id !== rowId) return row;
      const suggested = String(row.suggested_target_name || '').trim();
      if (!suggested) return row;
      return {
        ...row,
        target_field: suggested,
        status: 'manual',
        validation_status: 'valid',
        validation_code: 'OK',
        validation_message: '',
        collision_detected: false,
        isDirty: true,
      };
    }));
  }, []);

  const readiness = (() => {
    if (isLoading) {
      return {
        message: isMultiFileRun
          ? `Dry run in progress — validating ${multiReadiness.total} models (${multiReadiness.succeededCount + multiReadiness.failedCount} of ${multiReadiness.total} finished)…`
          : 'Dry run in progress — validating schema…',
        background: 'rgba(245, 158, 11, 0.12)',
        border: '1px solid rgba(245, 158, 11, 0.35)',
        color: 'var(--accent-orange)',
      };
    }
    // Checked before requiring dryRunCompleted (which only ever means
    // "finished AND succeeded") -- a run that finished with failures must
    // show as an issue, not silently fall through to the generic
    // "run the check" prompt as if nothing had been attempted yet.
    if (dryRunFailed || (dryRunCompleted && hasIssues)) {
      const parts = [];
      if (blockingCount > 0) parts.push(`${blockingCount} collision${blockingCount !== 1 ? 's' : ''}`);
      if (schemaIssues > 0) parts.push(`${schemaIssues} schema gap${schemaIssues !== 1 ? 's' : ''}`);
      if (isMultiFileRun && multiJobHasFailures) {
        parts.push(`${multiReadiness.failedCount} model${multiReadiness.failedCount !== 1 ? 's' : ''} failed`);
      }
      if (isMultiFileRun && multiReadiness.blockedModels.length > 0) {
        parts.push(`blocking items in ${multiReadiness.blockedModels.join(', ')}`);
      }
      if (isMultiFileRun && multiReadiness.lowCompatModels.length > 0) {
        parts.push(`low compatibility in ${multiReadiness.lowCompatModels.join(', ')}`);
      }
      const detail = parts.length ? ` — ${parts.join(', ')}` : '';
      return {
        message: `Issues detected${detail}. Review before proceeding.`,
        background: 'rgba(239, 68, 68, 0.10)',
        border: '1px solid rgba(239, 68, 68, 0.35)',
        color: '#ef4444',
      };
    }
    if (dryRunCompleted && !hasIssues) {
      return {
        message: compatScore !== null
          ? `${compatScore}% compatible — ready to proceed`
          : 'Ready to proceed — mapping validation complete',
        background: 'rgba(34, 197, 94, 0.12)',
        border: '1px solid rgba(34, 197, 94, 0.35)',
        color: 'var(--color-success)',
      };
    }
    return {
      message: 'Run the check to validate your schema mappings before proceeding.',
      background: 'rgba(59, 130, 246, 0.12)',
      border: '1px solid rgba(59, 130, 246, 0.35)',
      color: 'var(--accent-blue)',
    };
  })();

  const checkState = useMemo(() => {
    if (isLoading) return 'running';
    if (dryRunFailed) return 'issues';
    if (!dryRunCompleted) return 'pending';
    if (hasIssues) return 'issues';
    return 'success';
  }, [isLoading, dryRunFailed, dryRunCompleted, hasIssues]);

  const card = { border: '1px solid var(--border-main)', borderRadius: 10, background: 'var(--bg-surface)', padding: 14, display: 'flex', flexDirection: 'column', gap: 8, minWidth: 0 };
  const lbl = { fontSize: 10, fontWeight: 700, letterSpacing: '0.07em', color: 'var(--text-tertiary)', textTransform: 'uppercase' };
  const smallBtn = { display: 'inline-flex', alignItems: 'center', gap: 5, padding: '4px 10px', borderRadius: 6, border: '1px solid var(--border-main)', background: 'var(--bg-surface)', color: 'var(--text-primary)', fontSize: 11.5, fontWeight: 600, cursor: 'pointer', whiteSpace: 'nowrap' };
  const mapped = counts.auto + counts.manual;
  const barTotal = Math.max(1, mapped + counts.unmapped + counts.collision);
  const statusPill = {
    pending: ['Not checked yet', 'var(--accent-blue)'],
    running: ['Checking…', 'var(--accent-blue)'],
    issues: ['Needs attention', 'var(--color-warning)'],
    success: ['Ready to migrate', 'var(--color-success)'],
  }[checkState];
  const openGrid = () => {
    setShowAllMappings(true);
    setTimeout(() => mappingTableRef.current?.scrollIntoView({ behavior: 'smooth', block: 'start' }), 50);
  };
  // What the user still has to decide before continuing, in plain words.
  const decisions = [];
  if (dryRunFailed && !isMultiFileRun) {
    decisions.push({ tone: 'error', text: <><b>The check failed.</b> {dryRunError || mappingError || 'See the error above, fix the connection, then run the check again.'}</>, action: null });
  }
  if (isMultiFileRun && multiJobHasFailures) {
    decisions.push({ tone: 'error', text: <><b>{multiReadiness.failedCount} model{multiReadiness.failedCount === 1 ? '' : 's'} failed the check</b></>, action: ['Review', 'grid'] });
  }
  if (blockingCount > 0) {
    decisions.push({ tone: 'error', text: <><b>{blockingCount} name collision{blockingCount === 1 ? '' : 's'}</b> must be renamed before migrating</>, action: ['Fix now', 'grid'] });
  }
  if (schemaIssues > 0) {
    decisions.push({ tone: 'warning', text: <><b>{schemaIssues} column{schemaIssues === 1 ? '' : 's'}</b> differ from the target schema</>, action: ['Review', 'grid'] });
  }
  if (dryRunCompleted && counts.unmapped > 0) {
    decisions.push({
      tone: unmappedAcknowledged ? 'ok' : 'warning',
      text: <><b>{counts.unmapped} field{counts.unmapped === 1 ? ' has' : 's have'} no clear match</b>{unmappedAcknowledged ? ' · you chose to skip them' : ' · map them, or skip them'}</>,
      action: unmappedAcknowledged
        ? ['Undo', 'unskip']
        : ['Skip them', 'skip'],
      secondary: unmappedAcknowledged ? null : ['Map now', 'grid'],
    });
  }
  const runDecision = (kind) => {
    if (kind === 'grid') openGrid();
    else if (kind === 'skip') setUnmappedAcknowledged?.(true);
    else if (kind === 'unskip') setUnmappedAcknowledged?.(false);
  };
  const toneColor = { error: 'var(--color-error)', warning: 'var(--color-warning)', ok: 'var(--color-success)' };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
      <div style={{ display: 'flex', alignItems: 'flex-start', gap: 12, flexWrap: 'wrap' }}>
        <div style={{ flex: 1, minWidth: 260 }}>
          <h2 style={{ fontSize: 17, fontWeight: 700, color: 'var(--text-primary)', margin: '0 0 4px' }}>Check before you migrate</h2>
          <p style={{ fontSize: 13, color: 'var(--text-tertiary)', margin: 0 }}>
            We test every table, column and measure in the models you chose against {targetModel.type || 'the target'}, without changing anything there.
          </p>
        </div>
        <div style={{ display: 'flex', gap: 8, alignItems: 'center' }}>
          {needsRefresh && <span style={{ fontSize: 11, color: 'var(--color-warning)' }}>AI settings changed. Run the check again to apply them.</span>}
          <button
            type="button"
            onClick={runDryRun}
            disabled={isLoading || mappingLoading}
            style={{
              display: 'inline-flex', alignItems: 'center', gap: 7, padding: '8px 14px', borderRadius: 8, fontSize: 12, fontWeight: 700,
              border: '1px solid var(--accent-blue)',
              background: checkState === 'pending' ? 'var(--accent-blue)' : 'var(--bg-surface)',
              color: checkState === 'pending' ? '#fff' : 'var(--text-primary)',
              cursor: isLoading ? 'not-allowed' : 'pointer', opacity: isLoading ? 0.65 : 1,
            }}
          >
            {isLoading ? <Loader2 size={14} style={{ animation: 'spin 1s linear infinite' }} /> : (checkState === 'pending' ? <Play size={14} /> : <RefreshCw size={14} />)}
            {isLoading ? 'Checking…' : (checkState === 'pending' ? 'Run check' : 'Re-run check')}
          </button>
        </div>
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: 'minmax(0, 1.4fr) minmax(0, 1fr) minmax(0, 1fr)', gap: 12 }}>
        {/* Readiness */}
        <div style={card}>
          <span style={lbl}>Readiness</span>
          <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
            <span style={{ fontSize: 24, fontWeight: 700, color: 'var(--text-primary)', fontVariantNumeric: 'tabular-nums' }}>
              {compatScore !== null ? `${compatScore}%` : (dryRunCompleted ? '✓' : '—')}
            </span>
            <span style={{ fontSize: 10.5, fontWeight: 700, padding: '1px 8px', borderRadius: 999, color: statusPill[1], background: `color-mix(in srgb, ${statusPill[1]} 14%, transparent)` }}>
              {statusPill[0]}
            </span>
          </div>
          <div style={{ display: 'flex', height: 12, borderRadius: 5, overflow: 'hidden', background: 'var(--bg-surface-raised)' }}>
            {checkState === 'running' && <i style={{ width: '35%', background: 'var(--accent-blue)', opacity: 0.6, animation: 'pulse 1s ease-in-out infinite' }} />}
            {checkState !== 'running' && counts.all > 0 && (
              <>
                <i style={{ width: `${(100 * mapped) / barTotal}%`, background: 'var(--color-success)' }} />
                <i style={{ width: `${(100 * counts.unmapped) / barTotal}%`, background: 'var(--color-warning)' }} />
                <i style={{ width: `${(100 * counts.collision) / barTotal}%`, background: 'var(--color-error)' }} />
              </>
            )}
          </div>
          <div style={{ display: 'flex', flexWrap: 'wrap', gap: '4px 12px', fontSize: 11, color: 'var(--text-tertiary)' }}>
            {counts.all > 0 ? (
              <>
                <span><i style={{ display: 'inline-block', width: 8, height: 8, borderRadius: 2, background: 'var(--color-success)', marginRight: 5 }} />{mapped} map directly</span>
                <span><i style={{ display: 'inline-block', width: 8, height: 8, borderRadius: 2, background: 'var(--color-warning)', marginRight: 5 }} />{counts.unmapped} unclear</span>
                <span><i style={{ display: 'inline-block', width: 8, height: 8, borderRadius: 2, background: 'var(--color-error)', marginRight: 5 }} />{counts.collision} collisions</span>
              </>
            ) : <span>{readiness.message}</span>}
          </div>
        </div>

        {/* What's included */}
        <div style={card}>
          <span style={lbl}>What's included</span>
          <div style={{ display: 'flex', alignItems: 'center', gap: 6, fontSize: 12.5, fontWeight: 600, color: 'var(--text-primary)', flexWrap: 'wrap' }}>
            <SourceIcon source={sourceModel.type} size={14} />
            {sourceModel.type === 'fabric' ? 'Microsoft Fabric' : sourceModel.type}
            <span style={{ color: 'var(--text-tertiary)' }}>→</span>
            <SourceIcon source={targetModel.type} size={14} />
            {targetModel.type}
          </div>
          <span style={{ fontSize: 12, color: 'var(--text-secondary)' }}>
            {explicitTables.length || 1} model{(explicitTables.length || 1) === 1 ? '' : 's'}{counts.all ? ` · ${counts.all} fields` : ''}
          </span>
          <span style={{ fontSize: 11.5, color: 'var(--text-tertiary)', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }} title={targetDestination}>
            Target: {targetDestination}
          </span>
          <span style={{ fontSize: 11.5, color: 'var(--text-tertiary)' }}>{estimatedVolume}</span>
        </div>

        {/* AI assistance */}
        <div style={card}>
          <span style={lbl}>AI assistance</span>
          <ToggleOption
            label="Fill gaps in column mapping"
            description="Matches source and target fields by meaning."
            checked={autoMappingMode}
            onChange={toggleAutoMappingMode}
          />
          <ToggleOption
            label="Find missing relationships"
            description="Suggests joins the source didn't declare."
            checked={autoRelationships}
            onChange={setAutoRelationships}
          />
          <label style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 10, fontSize: 12, fontWeight: 600, color: 'var(--text-primary)', cursor: 'pointer' }}>
            <span title="Drafts descriptions for tables and fields during the run.">Write descriptions <Info size={12} color="var(--text-tertiary)" style={{ verticalAlign: 'middle' }} /></span>
            <input type="checkbox" checked={generateDescriptions} onChange={(e) => setGenerateDescriptions(e.target.checked)} />
          </label>
        </div>
      </div>

      {/* To decide before continuing */}
      <div style={{ ...card, gap: 0, padding: 0 }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 8, padding: '10px 14px' }}>
          <span style={lbl}>To decide before continuing</span>
          {decisions.length > 0 && (
            <span style={{ fontSize: 10.5, fontWeight: 700, padding: '0 7px', borderRadius: 999, background: 'var(--color-warning-bg)', color: 'var(--color-warning)' }}>{decisions.filter(d => d.tone !== 'ok').length}</span>
          )}
          <span style={{ flex: 1 }} />
          {counts.all > 0 && (
            <button type="button" onClick={() => (showAllMappings ? setShowAllMappings(false) : openGrid())} style={{ ...smallBtn, border: 'none', background: 'transparent', color: 'var(--accent-blue)' }}>
              {showAllMappings ? 'Hide mappings' : `See all ${counts.all} mappings →`}
            </button>
          )}
        </div>
        {decisions.length === 0 && (
          <div style={{ padding: '10px 14px', borderTop: '1px solid var(--border-light)', fontSize: 12, color: 'var(--text-tertiary)' }}>
            {checkState === 'pending' ? 'Run the check to see what needs a decision.' : checkState === 'running' ? 'Checking…' : 'Nothing to decide — everything maps.'}
          </div>
        )}
        {decisions.map((d, i) => (
          <div key={i} style={{ display: 'grid', gridTemplateColumns: 'auto 1fr auto', gap: 10, alignItems: 'center', padding: '9px 14px', borderTop: '1px solid var(--border-light)', fontSize: 12, color: 'var(--text-secondary)' }}>
            <span style={{ width: 8, height: 8, borderRadius: '50%', background: toneColor[d.tone] }} />
            <span style={{ minWidth: 0 }}>{d.text}</span>
            <span style={{ display: 'flex', gap: 6 }}>
              {d.secondary && <button type="button" style={smallBtn} onClick={() => runDecision(d.secondary[1])}>{d.secondary[0]}</button>}
              {d.action && <button type="button" style={smallBtn} onClick={() => runDecision(d.action[1])}>{d.action[0]}</button>}
            </span>
          </div>
        ))}
      </div>

      {mappingError && !mappingLoading && !dryRunFailed && (
        <div style={{ border: '1px solid rgba(239, 68, 68, 0.45)', background: 'rgba(239, 68, 68, 0.12)', color: 'var(--color-error)', borderRadius: 8, padding: '10px 12px', fontSize: 12 }}>
          {mappingError}
        </div>
      )}

      {deployError && (
        <div style={{ border: '1px solid rgba(239, 68, 68, 0.45)', background: 'rgba(239, 68, 68, 0.12)', color: 'var(--color-error)', borderRadius: 8, padding: '10px 12px', fontSize: 12 }}>
          {deployError}
        </div>
      )}

      {/* ── Multi-PBIX per-file status list — replaces the single-file table
           entirely when a background dry-run job is active for this
           project (see CreateProjectPage.jsx's handleDryRun). ─────────── */}
      {multiDryRunJob?.job_id && (showAllMappings || isLoading || multiJobHasFailures) && (
        <div ref={mappingTableRef}>
          <MultiFileDryRunStatus
            sections={multiSections}
            jobStatus={multiJobStatus}
            projectId={projectId}
            relationships={(() => {
              try {
                const stored = sessionStorage.getItem('detectedRelationships');
                return stored ? JSON.parse(stored) : [];
              } catch { return []; }
            })()}
            rerunningIds={multiRerunningIds}
            rerunErrors={multiRerunErrors}
            pollError={multiPollError}
            onRetryPolling={onRetryMultiPolling}
            onEditRow={onMultiEditRow}
            onBulkResolved={onMultiBulkResolved}
            onSynonymUpdate={onMultiSynonymUpdate}
            onRetryFile={onRetryMultiFile}
            onRemoveFile={onRemoveMultiFile}
          />
        </div>
      )}

      {/* ── New DryRunMappingTable — shown after a successful dry run ─────── */}
      {!multiDryRunJob?.job_id && showAllMappings && dryRunStatus === 'success' && detectedMappings.length > 0 && (
        <div ref={mappingTableRef}>
          <PanelBoundary name="Target tables">
            <TableBindingPlan plan={dryRunData?.table_binding_plan} style={{ marginTop: 0, marginBottom: 12 }} />
          </PanelBoundary>
          {(dryRunData?.blocking_conflicts?.length > 0 ||
            dryRunData?.ontology_changes?.conflict_resolution?.resolved?.length > 0 ||
            hasOntologyChanges(dryRunData?.ontology_changes)) && (
            <div className="mb-3 p-3 rounded-lg border border-main bg-surface-raised text-xs space-y-1.5">
              <div className="font-bold text-primary">Ontology changes</div>
              {(dryRunData?.blocking_conflicts || []).map((b, i) => (
                <div key={`blk-${i}`} className="text-red-500 font-medium">
                  Blocker: {b.message} (Choose a namespace or priority order before deploying.)
                </div>
              ))}
              <OntologyConflictResolver
                projectId={projectId}
                blockers={dryRunData?.blocking_conflicts || []}
                resolution={dryRunData?.ontology_changes?.conflict_resolution}
                onApplied={onRunDryRun}
              />
              {/* UPSERT: the per-item changes are listed in the delta view below. */}
              <OntologyChangesList
                changes={dryRunData?.upsert_delta
                  ? { applied: dryRunData?.ontology_changes?.applied, domains: dryRunData?.ontology_changes?.domains, formula_overrides_ignored: dryRunData?.ontology_changes?.formula_overrides_ignored }
                  : dryRunData?.ontology_changes}
              />
            </div>
          )}
          <UpsertChangesView delta={dryRunData?.upsert_delta} modelLabel={dryRunData?.model_name || dryRunData?.label} isDryRun>
            <DryRunMappingTable
              mappings={detectedMappings}
              summary={dryRunData?.summary}
              deployedNamesKnown={Boolean(dryRunData?.deployed_names_known)}
              relationships={(() => {
                try {
                  const stored = sessionStorage.getItem('detectedRelationships');
                  return stored ? JSON.parse(stored) : [];
                } catch { return []; }
              })()}
              onEdit={(rowId) => {
                const row = detectedMappings.find(r => r.id === rowId);
                if (row) setEditingRow(row);
              }}
              onBulkResolved={onBulkResolved}
              onSynonymUpdate={onSynonymUpdate}
              projectId={projectId}
              schemaConflicts={dryRunData?.schema_conflicts || []}
              compatibilityScore={dryRunData?.compatibility_score ?? null}
              onReSync={onRunDryRun}
              droppedEntities={dryRunData?.dropped_entities || []}
              unresolvedReportFieldReferences={dryRunData?.unresolved_report_field_references || []}
            />
          </UpsertChangesView>
        </div>
      )}

      {/* ── FieldMappingEditor modal — shown when a row is being edited ───── */}
      {editingRow && (
        <FieldMappingEditor
          row={editingRow}
          onSave={onFieldEdit}
          onClose={() => setEditingRow(null)}
          targetPlatform={Array.from(targetConnectors || new Set())[0] || 'snowflake'}
          isSaving={isSavingEdit}
        />
      )}

      {mappingLoading && (
        <div style={{ border: '1px solid var(--border-main)', borderRadius: 10, background: 'var(--bg-surface)', padding: 10 }}>
          <div style={{ fontSize: 11, color: 'var(--text-tertiary)', marginBottom: 8 }}>Generating Mappings...</div>
          <div style={{ width: '100%', height: 6, borderRadius: 999, background: 'rgba(71,85,105,0.35)', overflow: 'hidden' }}>
            <div style={{ width: '40%', height: '100%', background: 'var(--accent-blue)', borderRadius: 999, animation: 'pulse 1.2s ease-in-out infinite' }} />
          </div>
        </div>
      )}

    </div>
  );
}

/**
 * Wizard step 4 — Ontology review, BEFORE the dry run.
 *
 * Reads the selected source models (no target calls), then shows:
 *  - duplicates: measures with the same formula under different names
 *    (or the same measure copied into several reports) -> Merge / Keep separate
 *  - conflicts: same name, different formula, vs. the existing ontology
 *    (use the governed definition / keep as a new metric / decide later)
 *    or between the selected models (reported; first definition kept)
 *  - glossary gaps: business metrics with no description -> write one
 *  - new metrics: not in any domain yet; they go into the new domain
 * "Save ontology" stores the result as a new domain (attached to the project
 * once it exists). The step is optional: Continue without saving skips it.
 *
 * State lives in the parent (`review`, `setReview`) so Back/Next keeps it.
 */
import React, { useCallback, useEffect, useMemo, useState } from 'react';
import { Loader2, AlertTriangle, CheckCircle2, Info, GitMerge, RefreshCw } from 'lucide-react';
import { api } from '../../utils/api';

const card = {
  background: 'var(--bg-surface)', border: '1px solid var(--border-main)', borderRadius: 9,
  padding: '12px 14px', display: 'flex', flexDirection: 'column', gap: 6, minWidth: 0,
};
const label = { fontSize: 10, fontWeight: 700, letterSpacing: '0.07em', textTransform: 'uppercase', color: 'var(--text-tertiary)' };
const big = { fontSize: 22, fontWeight: 700, lineHeight: 1.1, fontVariantNumeric: 'tabular-nums', color: 'var(--text-primary)' };
const faint = { fontSize: 11.5, color: 'var(--text-tertiary)' };
const chip = {
  fontFamily: 'var(--font-mono, ui-monospace, monospace)', fontSize: 11, padding: '1px 6px', borderRadius: 5,
  border: '1px solid var(--border-main)', background: 'var(--bg-surface-raised)', color: 'var(--text-secondary)',
  maxWidth: '100%', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap', display: 'inline-block',
};
const input = {
  fontSize: 12, padding: '5px 8px', borderRadius: 6, border: '1px solid var(--border-main)',
  background: 'var(--bg-input)', color: 'var(--text-primary)', outline: 'none', minWidth: 0,
};
function btn(variant = 'secondary', active = false) {
  return {
    display: 'inline-flex', alignItems: 'center', gap: 5, whiteSpace: 'nowrap',
    padding: '4px 10px', borderRadius: 6, fontSize: 11.5, fontWeight: 600, cursor: 'pointer',
    border: variant === 'primary' || active ? '1px solid var(--accent-blue)' : '1px solid var(--border-main)',
    background: variant === 'primary' ? 'var(--accent-blue)' : active ? 'var(--color-accent-faint)' : 'var(--bg-surface)',
    color: variant === 'primary' ? '#fff' : active ? 'var(--accent-blue)' : 'var(--text-primary)',
  };
}

function SummaryCards({ s }) {
  const items = [
    ['Measures found', s.measures_found, `→ ${s.business_metrics} unique business metrics`],
    ['Duplicates', s.duplicate_groups, `${s.duplicate_measures} extra copies`, s.duplicate_groups ? 'var(--color-warning)' : null],
    ['Conflicts', s.conflicts, 'same name, different formula', s.conflicts ? 'var(--color-error)' : null],
    ['Glossary', `${Math.round(s.glossary_coverage_pct)}%`, 'have a business description'],
    ['Already governed', s.governed, 'match an existing metric', s.governed ? 'var(--color-success)' : null],
  ];
  return (
    <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(150px, 1fr))', gap: 10 }}>
      {items.map(([k, v, sub, color]) => (
        <div key={k} style={card}>
          <span style={label}>{k}</span>
          <span style={{ ...big, color: color || big.color }}>{v}</span>
          <span style={faint}>{sub}</span>
        </div>
      ))}
    </div>
  );
}

function DuplicateGroup({ group, decision, onChange }) {
  const merged = decision?.decision === 'merge';
  const separate = decision?.decision === 'separate';
  const name = decision?.name ?? group.suggested_id;
  return (
    <div style={{ ...card, gap: 8, borderColor: merged ? 'var(--color-success)' : 'var(--border-main)' }}>
      <div style={{ display: 'flex', alignItems: 'center', gap: 8, flexWrap: 'wrap' }}>
        <b style={{ fontSize: 13 }}>{group.suggested_name}</b>
        <span style={{ fontSize: 10.5, fontWeight: 700, padding: '1px 7px', borderRadius: 999, background: 'var(--color-warning-bg)', color: 'var(--color-warning)' }}>
          {group.kind === 'same_name' ? `same measure in ${group.members.length} models` : `${group.members.length} names, one formula`}
        </span>
        <span style={{ flex: 1 }} />
        <span style={chip} title={group.expression}>{group.expression}</span>
      </div>
      <div style={{ display: 'flex', flexDirection: 'column', gap: 3 }}>
        {group.members.map((m, i) => (
          <div key={`${m.name}-${m.source}-${i}`} style={{ display: 'grid', gridTemplateColumns: 'minmax(140px, 1fr) minmax(140px, 1fr)', gap: 10, fontSize: 12 }}>
            <span style={{ color: 'var(--text-primary)' }}>{m.label}</span>
            <span style={faint}>{m.source || '—'}</span>
          </div>
        ))}
      </div>
      <div style={{ display: 'flex', alignItems: 'center', gap: 8, flexWrap: 'wrap' }}>
        {merged ? (
          <>
            <CheckCircle2 size={13} color="var(--color-success)" />
            <span style={{ fontSize: 12 }}>Merged as <b>{name}</b>; the other names become synonyms.</span>
            <span style={{ flex: 1 }} />
            <button type="button" style={btn()} onClick={() => onChange(null)}>Undo</button>
          </>
        ) : (
          <>
            <label style={{ fontSize: 12, color: 'var(--text-secondary)' }} htmlFor={`dup-${group.id}`}>Keep as</label>
            <input
              id={`dup-${group.id}`}
              style={{ ...input, width: 180 }}
              value={name}
              onChange={e => onChange({ decision: decision?.decision || null, name: e.target.value })}
            />
            <span style={faint}>{separate ? 'Kept as separate metrics.' : ''}</span>
            <span style={{ flex: 1 }} />
            <button type="button" style={btn('secondary', separate)} onClick={() => onChange({ decision: 'separate', name })}>Keep separate</button>
            <button type="button" style={btn('primary')} disabled={!name.trim()} onClick={() => onChange({ decision: 'merge', name: name.trim() })}>
              <GitMerge size={12} /> Merge
            </button>
          </>
        )}
      </div>
    </div>
  );
}

function ConflictCard({ conflict, decision, onChange }) {
  if (conflict.kind === 'source') {
    return (
      <div style={{ ...card, gap: 8 }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
          <AlertTriangle size={13} color="var(--color-error)" />
          <b style={{ fontSize: 13 }}>{conflict.name}</b>
          <span style={faint}>has different formulas in the selected models</span>
        </div>
        {conflict.variants.map((v, i) => (
          <div key={i} style={{ display: 'grid', gridTemplateColumns: '160px 1fr', gap: 10, fontSize: 12, alignItems: 'center' }}>
            <span style={faint}>{v.source || '—'}</span>
            <span style={chip} title={v.expression}>{v.expression}</span>
          </div>
        ))}
        <span style={faint}>The first definition is kept. Rename one of them in the source report, or fix it in the project's Ontology tab afterwards.</span>
      </div>
    );
  }
  const res = decision?.resolution || null;
  const newName = decision?.new_name ?? conflict.suggested_new_name;
  const ex = conflict.existing || {};
  const inc = conflict.incoming || {};
  return (
    <div style={{ ...card, gap: 8, borderColor: res ? 'var(--border-main)' : 'var(--color-error)' }}>
      <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
        <AlertTriangle size={13} color="var(--color-error)" />
        <b style={{ fontSize: 13 }}>{conflict.name}</b>
        <span style={faint}>is already defined differently in the {ex.domain} domain</span>
      </div>
      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 10 }}>
        <div style={{ border: '1px solid var(--border-main)', borderRadius: 7, padding: 8, display: 'flex', flexDirection: 'column', gap: 4, minWidth: 0 }}>
          <span style={label}>{ex.domain} · governed</span>
          <span style={chip} title={ex.expression}>{ex.expression || '—'}</span>
          <span style={faint}>{ex.owner ? `Owner: ${ex.owner}` : 'No owner set'}</span>
        </div>
        <div style={{ border: '1px solid var(--border-main)', borderRadius: 7, padding: 8, display: 'flex', flexDirection: 'column', gap: 4, minWidth: 0 }}>
          <span style={label}>{inc.source || 'Selected model'}</span>
          <span style={chip} title={inc.expression}>{inc.expression || '—'}</span>
          <span style={faint}>{inc.description || 'No description'}</span>
        </div>
      </div>
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: 6, alignItems: 'center' }}>
        <button type="button" style={btn('secondary', res === 'use_existing')} onClick={() => onChange({ resolution: 'use_existing' })}>
          Use the {ex.domain} definition
        </button>
        <button type="button" style={btn('secondary', res === 'keep_new')} onClick={() => onChange({ resolution: 'keep_new', new_name: newName })}>
          Keep as a new metric
        </button>
        {res === 'keep_new' && (
          <input
            aria-label="New metric name"
            style={{ ...input, width: 220 }}
            value={newName}
            onChange={e => onChange({ resolution: 'keep_new', new_name: e.target.value })}
          />
        )}
        <button type="button" style={btn('secondary', res === 'defer')} onClick={() => onChange({ resolution: 'defer' })}>
          Decide later
        </button>
      </div>
    </div>
  );
}

function GlossaryGaps({ gaps, descriptions, onChange, onFillAll, onClearAll }) {
  const [showAll, setShowAll] = useState(false);
  const shown = showAll ? gaps : gaps.slice(0, 25);
  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
      <div style={{ display: 'flex', alignItems: 'center', gap: 8, flexWrap: 'wrap' }}>
        <span style={faint}>Suggested descriptions are pre-filled from metric names &amp; formulas — edit freely before saving.</span>
        <span style={{ flex: 1 }} />
        <button type="button" style={btn()} onClick={onFillAll}>Use all suggestions</button>
        <button type="button" style={btn()} onClick={onClearAll}>Clear all</button>
      </div>
      <div style={{ ...card, padding: 0, gap: 0 }}>
        {shown.map((g, i) => {
          const val = descriptions[g.name] ?? '';
          const isSuggested = Boolean(g.suggested_description && val === g.suggested_description);
          return (
            <div key={`${g.name}-${i}`} style={{ display: 'grid', gridTemplateColumns: 'minmax(160px, 220px) 1fr auto', gap: 10, padding: '8px 12px', borderTop: i ? '1px solid var(--border-light)' : 'none', alignItems: 'center' }}>
              <div style={{ minWidth: 0 }}>
                <div style={{ fontSize: 12.5, fontWeight: 600 }}>{g.label}</div>
                <div style={{ ...faint, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }} title={g.expression}>{g.source} · {g.expression}</div>
              </div>
              <input
                aria-label={`Description for ${g.label}`}
                style={{ ...input, width: '100%' }}
                placeholder={g.suggested_description || 'What does this metric mean to the business?'}
                value={val}
                onChange={e => onChange(g.name, e.target.value)}
              />
              {isSuggested ? (
                <span style={{ fontSize: 10, fontWeight: 700, padding: '2px 7px', borderRadius: 999, background: 'var(--color-accent-faint)', color: 'var(--accent-blue)' }}>Suggested</span>
              ) : g.suggested_description && !val ? (
                <button type="button" style={btn()} onClick={() => onChange(g.name, g.suggested_description)}>Suggest</button>
              ) : (
                <span style={{ fontSize: 10, color: 'var(--text-tertiary)', padding: '2px 6px' }}>Edited</span>
              )}
            </div>
          );
        })}
        {gaps.length > 25 && (
          <div style={{ padding: 10, borderTop: '1px solid var(--border-light)' }}>
            <button type="button" style={btn()} onClick={() => setShowAll(v => !v)}>
              {showAll ? 'Show fewer' : `Show all ${gaps.length}`}
            </button>
          </div>
        )}
      </div>
    </div>
  );
}

export function StepOntologyReview({ review, setReview, sourceConnector, buildRequest, projectName, projectId }) {
  const [tab, setTab] = useState('duplicates');
  const [sfSim, setSfSim] = useState({ loading: false, data: null, error: '' });
  const request = useMemo(() => buildRequest(), [buildRequest]);
  const signature = useMemo(() => JSON.stringify(request), [request]);
  const patch = useCallback((p) => setReview(prev => ({ ...prev, ...(typeof p === 'function' ? p(prev) : p) })), [setReview]);

  const analyze = useCallback(async () => {
    patch({ status: 'loading', message: '', signature, saved: null, saveError: '' });
    try {
      const res = await api.analyzeOntologyReview({ ...request, project_id: projectId || undefined });
      if (res?.supported === false) {
        patch({ status: 'unsupported', message: res.message || '', analysis: null });
        return;
      }
      const suggested = {};
      for (const g of res?.glossary_gaps || []) {
        if (g.name && g.suggested_description) suggested[g.name] = g.suggested_description;
      }
      patch(prev => ({
        status: 'ready',
        analysis: res,
        merges: {},
        conflicts: {},
        descriptions: suggested,
        domainName: prev.domainName || projectName || '',
      }));
    } catch (err) {
      const raw = err?.message || '';
      // A 404 here means the running backend predates the Ontology review
      // endpoints (it needs a restart), not that the files are missing.
      const message = /\b404\b/.test(raw)
        ? 'The backend does not have the Ontology review yet. Restart the backend server (make dev / uvicorn) and try again, or continue without the review.'
        : (raw || 'The selected models could not be read.');
      patch({ status: 'error', message });
    }
  }, [patch, request, signature, projectId, projectName]);

  useEffect(() => {
    if (review.signature !== signature && review.status !== 'loading') analyze();
  }, [signature]); // eslint-disable-line react-hooks/exhaustive-deps

  const a = review.analysis;
  const dups = a?.duplicates || [];
  const conflicts = a?.conflicts || [];
  const gaps = a?.glossary_gaps || [];
  const unassigned = a?.unassigned || [];
  const exactMergeable = dups.filter(d => !review.merges[d.id]);
  const decided = Object.values(review.merges).filter(m => m?.decision).length
    + Object.values(review.conflicts).filter(c => c?.resolution).length;
  const openConflicts = conflicts.filter(c => c.kind === 'ontology' && !review.conflicts[c.id]?.resolution).length;

  const setMerge = (id, v) => patch(prev => ({ merges: { ...prev.merges, [id]: v }, saved: null }));
  const setConflict = (id, v) => patch(prev => ({ conflicts: { ...prev.conflicts, [id]: { ...prev.conflicts[id], ...v } }, saved: null }));
  const setDescription = (name, text) => patch(prev => ({ descriptions: { ...prev.descriptions, [name]: text }, saved: null }));
  const mergeAll = () => patch(prev => {
    const merges = { ...prev.merges };
    dups.forEach(d => { if (!merges[d.id]) merges[d.id] = { decision: 'merge', name: d.suggested_id }; });
    return { merges, saved: null };
  });

  const save = async () => {
    patch({ saving: true, saveError: '' });
    try {
      const body = {
        analysis_id: a.analysis_id,
        ...request,
        project_id: projectId || undefined,
        domain_name: review.domainName.trim(),
        owner: review.owner.trim() || undefined,
        merges: dups
          .filter(d => review.merges[d.id]?.decision === 'merge')
          .map(d => ({ name: review.merges[d.id].name, members: [...new Set(d.members.map(m => m.name))] })),
        conflicts: conflicts
          .filter(c => c.kind === 'ontology' && review.conflicts[c.id]?.resolution)
          .map(c => ({ name: c.incoming.name, resolution: review.conflicts[c.id].resolution, new_name: review.conflicts[c.id].new_name })),
        descriptions: Object.fromEntries(Object.entries(review.descriptions).filter(([, v]) => String(v || '').trim())),
      };
      const res = await api.applyOntologyReview(body);
      patch({ saving: false, saved: res });
    } catch (err) {
      patch({ saving: false, saveError: err?.message || 'The ontology could not be saved.' });
    }
  };

  // ── states ──────────────────────────────────────────────────────────────
  const header = (
    <div style={{ display: 'flex', alignItems: 'flex-start', gap: 12, flexWrap: 'wrap' }}>
      <div style={{ flex: 1, minWidth: 260 }}>
        <h2 style={{ fontSize: 17, fontWeight: 700, margin: 0, color: 'var(--text-primary)' }}>Review business definitions</h2>
        <p style={{ fontSize: 12.5, color: 'var(--text-secondary)', margin: '4px 0 0', maxWidth: 680 }}>
          Before the dry run, we compare the measures in the models you chose with each other and with your existing ontology,
          so each business metric is migrated once, under one name, with a description. This step is optional.
        </p>
      </div>
      {review.status === 'ready' && (
        <button type="button" style={btn()} onClick={analyze}><RefreshCw size={12} /> Read again</button>
      )}
    </div>
  );

  if (review.status === 'loading' || review.status === 'idle') {
    return (
      <div style={{ display: 'flex', flexDirection: 'column', gap: 14 }}>
        {header}
        <div style={{ ...card, flexDirection: 'row', alignItems: 'center', gap: 10 }}>
          <Loader2 size={15} className="animate-spin" />
          <span style={{ fontSize: 12.5 }}>Reading the measures in the selected models…</span>
        </div>
      </div>
    );
  }
  if (review.status === 'unsupported' || review.status === 'error') {
    const unsupported = review.status === 'unsupported';
    return (
      <div style={{ display: 'flex', flexDirection: 'column', gap: 14 }}>
        {header}
        <div style={{ ...card, flexDirection: 'row', alignItems: 'flex-start', gap: 10 }}>
          {unsupported ? <Info size={15} color="var(--color-info)" /> : <AlertTriangle size={15} color="var(--color-error)" />}
          <div style={{ display: 'flex', flexDirection: 'column', gap: 6, fontSize: 12.5 }}>
            <span>{review.message}</span>
            <span style={faint}>
              {unsupported
                ? `Continue to run the dry run${sourceConnector ? ` for ${sourceConnector}` : ''}. You can review the ontology from the project's Ontology tab afterwards.`
                : 'Check that the selected files exist, then try again, or continue without the review.'}
            </span>
            {!unsupported && <div><button type="button" style={btn()} onClick={analyze}><RefreshCw size={12} /> Try again</button></div>}
          </div>
        </div>
      </div>
    );
  }

  const fillAllSuggestions = () => {
    const next = { ...(review.descriptions || {}) };
    for (const g of gaps) {
      if (g.name && g.suggested_description) next[g.name] = g.suggested_description;
    }
    patch({ descriptions: next, saved: null });
  };
  const clearAllDescriptions = () => patch({ descriptions: {}, saved: null });

  const runSnowflakeCheck = async () => {
    setSfSim({ loading: true, data: null, error: '' });
    try {
      const candidateMap = new Map();
      for (const g of gaps) candidateMap.set(g.name, { name: g.name, label: g.label, expression: g.expression || '' });
      for (const u of unassigned) {
        if (!candidateMap.has(u)) candidateMap.set(u, { name: u, label: u, expression: '' });
      }
      const res = await api.checkSnowflakeSimilarity({
        project_id: projectId || undefined,
        metrics: Array.from(candidateMap.values()).slice(0, 150),
      });
      setSfSim({ loading: false, data: res, error: '' });
      setTab('snowflake');
    } catch (err) {
      setSfSim({ loading: false, data: null, error: err?.message || 'Snowflake similarity check failed.' });
    }
  };

  const sfMatches = sfSim.data?.matches || [];
  const sfHitCount = sfMatches.filter(m => m.status !== 'NEW').length;

  const tabs = [
    ['duplicates', 'Duplicates', dups.length, 'var(--color-warning)'],
    ['conflicts', 'Conflicts', conflicts.length, 'var(--color-error)'],
    ['glossary', 'Glossary gaps', gaps.length, null],
    ['new', 'New metrics', unassigned.length, null],
    ['snowflake', 'Snowflake match', sfSim.data ? sfHitCount : '?', sfHitCount ? 'var(--accent-blue)' : null],
  ];

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 14 }}>
      {header}
      {(a.errors || []).length > 0 && (
        <div style={{ ...card, flexDirection: 'row', gap: 8, alignItems: 'center', borderColor: 'var(--color-warning)' }}>
          <AlertTriangle size={13} color="var(--color-warning)" />
          <span style={{ fontSize: 12 }}>
            {a.errors.length} model{a.errors.length === 1 ? '' : 's'} could not be read: {a.errors.map(e => e.source).join(', ')}. They are left out of this review.
          </span>
        </div>
      )}
      <SummaryCards s={a.summary} />

      <div role="tablist" style={{ display: 'flex', gap: 18, borderBottom: '1px solid var(--border-main)' }}>
        {tabs.map(([id, text, n, color]) => (
          <button
            key={id}
            role="tab"
            type="button"
            aria-selected={tab === id}
            onClick={() => setTab(id)}
            style={{
              background: 'none', border: 'none', cursor: 'pointer', padding: '6px 0 9px', marginBottom: -1, fontSize: 12.5,
              borderBottom: `2px solid ${tab === id ? 'var(--accent-blue)' : 'transparent'}`,
              color: tab === id ? 'var(--text-primary)' : 'var(--text-tertiary)', fontWeight: tab === id ? 700 : 500,
              display: 'inline-flex', gap: 6, alignItems: 'center',
            }}
          >
            {text}
            <span style={{ fontSize: 10.5, fontWeight: 700, padding: '0 6px', borderRadius: 999, background: n && color ? `color-mix(in srgb, ${color} 15%, transparent)` : 'var(--bg-surface-raised)', color: n && color ? color : 'var(--text-tertiary)' }}>{n}</span>
          </button>
        ))}
      </div>

      {tab === 'duplicates' && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
          {dups.length === 0 && <span style={faint}>No duplicate measures found.</span>}
          {dups.length > 0 && (
            <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
              <span style={faint}>Merging keeps one metric bound to every copy, so all reports get the same business name and description.</span>
              <span style={{ flex: 1 }} />
              {exactMergeable.length > 0 && (
                <button type="button" style={btn()} onClick={mergeAll}><GitMerge size={12} /> Merge all ({exactMergeable.length})</button>
              )}
            </div>
          )}
          {dups.map(d => (
            <DuplicateGroup key={d.id} group={d} decision={review.merges[d.id]} onChange={v => setMerge(d.id, v)} />
          ))}
        </div>
      )}

      {tab === 'conflicts' && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
          {conflicts.length === 0 && <span style={faint}>No conflicting definitions.</span>}
          {conflicts.map(c => (
            <ConflictCard key={c.id} conflict={c} decision={review.conflicts[c.id]} onChange={v => setConflict(c.id, v)} />
          ))}
        </div>
      )}

      {tab === 'glossary' && (
        gaps.length === 0
          ? <span style={faint}>Every business metric has a description.</span>
          : (
            <>
              <span style={faint}>Descriptions are saved to the ontology and sent to the target as comments on each metric.</span>
              <GlossaryGaps
                gaps={gaps}
                descriptions={review.descriptions}
                onChange={setDescription}
                onFillAll={fillAllSuggestions}
                onClearAll={clearAllDescriptions}
              />
            </>
          )
      )}

      {tab === 'new' && (
        <div style={{ ...card }}>
          <span style={faint}>These metrics are not in any domain yet. Saving adds them to the new domain below.</span>
          <div style={{ display: 'flex', flexWrap: 'wrap', gap: 6 }}>
            {unassigned.slice(0, 200).map(n => <span key={n} style={chip}>{n}</span>)}
            {unassigned.length > 200 && <span style={faint}>+{unassigned.length - 200} more</span>}
          </div>
        </div>
      )}

      {tab === 'snowflake' && (
        <div style={{ ...card, gap: 10 }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 8, flexWrap: 'wrap' }}>
            <span style={faint}>
              Checks whether incoming metrics already exist or are similar in Snowflake Semantic Views / ontology.
            </span>
            <span style={{ flex: 1 }} />
            <button type="button" style={btn('primary')} disabled={sfSim.loading} onClick={runSnowflakeCheck}>
              {sfSim.loading ? <Loader2 size={12} className="animate-spin" /> : <RefreshCw size={12} />}
              {sfSim.loading ? 'Checking Snowflake…' : 'Check Snowflake'}
            </button>
          </div>
          {sfSim.error && <span style={{ fontSize: 12, color: 'var(--color-error)' }}>{sfSim.error}</span>}
          {sfSim.data && (
            <>
              <span style={faint}>
                {sfSim.data.snowflake_connected
                  ? `Connected to Snowflake · ${sfSim.data.views_scanned} semantic view(s) scanned · ${sfHitCount} existing/similar metric(s) found.`
                  : `Snowflake offline (${sfSim.data.snowflake_error || 'no credentials'}) · matched against governed ontology (${sfHitCount} hit(s)).`}
              </span>
              <div style={{ display: 'flex', flexDirection: 'column', gap: 6, maxHeight: 280, overflowY: 'auto' }}>
                {sfMatches.map((m, i) => (
                  <div key={`${m.name}-${i}`} style={{ display: 'grid', gridTemplateColumns: 'minmax(160px, 1fr) auto minmax(180px, 1fr)', gap: 10, alignItems: 'center', fontSize: 12, padding: '6px 8px', borderRadius: 6, background: 'var(--bg-surface-raised)' }}>
                    <strong style={{ overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{m.label}</strong>
                    <span style={{
                      fontSize: 10.5, fontWeight: 700, padding: '1px 8px', borderRadius: 999,
                      background: m.status === 'EXACT_MATCH' ? 'var(--color-success-bg)' : m.status === 'SIMILAR_EXISTS' ? 'var(--color-warning-bg)' : 'var(--bg-surface)',
                      color: m.status === 'EXACT_MATCH' ? 'var(--color-success)' : m.status === 'SIMILAR_EXISTS' ? 'var(--color-warning)' : 'var(--text-tertiary)',
                    }}>
                      {m.status === 'EXACT_MATCH' ? 'Already in Snowflake' : m.status === 'SIMILAR_EXISTS' ? `Similar (${m.similarity_pct}%)` : 'New'}
                    </span>
                    <span style={{ ...faint, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }} title={m.matched_view || ''}>
                      {m.matched_metric ? `${m.matched_metric} · ${m.matched_view}` : '—'}
                    </span>
                  </div>
                ))}
              </div>
            </>
          )}
        </div>
      )}

      {/* Save bar */}
      <div style={{ ...card, flexDirection: 'row', alignItems: 'center', gap: 10, flexWrap: 'wrap', position: 'sticky', bottom: 0, boxShadow: 'var(--shadow-md)' }}>
        <label htmlFor="onto-domain" style={{ fontSize: 12, fontWeight: 600 }}>Model</label>
        <input
          id="onto-domain"
          style={{ ...input, width: 200 }}
          value={review.domainName}
          onChange={e => patch({ domainName: e.target.value, saved: null })}
          placeholder="e.g. Sales"
        />
        <label htmlFor="onto-owner" style={{ fontSize: 12, fontWeight: 600 }}>Owner</label>
        <input
          id="onto-owner"
          style={{ ...input, width: 160 }}
          value={review.owner}
          onChange={e => patch({ owner: e.target.value, saved: null })}
          placeholder="Team or person"
        />
        <span style={faint}>
          {decided} decision{decided === 1 ? '' : 's'} made
          {openConflicts ? ` · ${openConflicts} conflict${openConflicts === 1 ? '' : 's'} still open` : ''}
        </span>
        <span style={{ flex: 1 }} />
        {review.saved ? (
          <span style={{ display: 'inline-flex', alignItems: 'center', gap: 6, fontSize: 12, color: 'var(--color-success)' }}>
            <CheckCircle2 size={14} />
            {Array.isArray(review.saved.domains) && review.saved.domains.length > 1
              ? <>Saved one domain per model: {review.saved.domains.map((d, i) => (
                  <span key={d.id || d.domain}>{i > 0 ? ', ' : ''}<b>{d.model_name || d.domain}</b> ({d.metric_count} metrics)</span>
                ))}. Continue to the dry run.</>
              : review.saved.synced_existing
                ? <>This project already has domain <b>{review.saved.domain}</b>; the review was merged into it ({review.saved.metric_count} metrics). Continue to the dry run.</>
                : <>Saved as domain <b>{review.saved.domain}</b> ({review.saved.metric_count} metrics). Continue to the dry run.</>}
          </span>
        ) : (
          <button type="button" style={btn('primary')} disabled={review.saving || !review.domainName.trim()} onClick={save}>
            {review.saving ? <Loader2 size={12} className="animate-spin" /> : null} Save ontology
          </button>
        )}
      </div>
      {review.saveError && (
        <div style={{ ...card, flexDirection: 'row', gap: 8, alignItems: 'center', borderColor: 'var(--color-error)', fontSize: 12 }}>
          <AlertTriangle size={13} color="var(--color-error)" /> {review.saveError}
        </div>
      )}
      {!review.saved && (
        <span style={faint}>Continue without saving to skip this review; the project's ontology will show as not reviewed.</span>
      )}
    </div>
  );
}

import { Loader2, CheckSquare, Square } from 'lucide-react';
import SmartSearchBar from '../common/SmartSearchBar';
import { matchesSmartQuery } from '../common/smartSearchQuery';
import { isModelSelected, selectionIdentities } from '../../utils/modelSelection';
import { UploadStatusIcon } from './uploadStatusUI';

export function StepSourceBrowser({
  sourceConnector, selectedWorkspace, wsLoading,
  wsModels,
  selectedModels, toggleModel, clearSelectedModels,
  modelQuery, setModelQuery,
  modelQueryRegex, setModelQueryRegex,
  snowflakeResults,
  pbixSourceMode = 'TAG',
  selectedLocalFolderTag = '',
  pbixFiles = [],
  pbixFilesLoading = false,
  pbixFilesError = '',
  selectedPbixFilePath = '',
  pbixUploadPath = '',
  onSelectPbixFile = () => { },
  // Databricks props
  databricksObjects = [],
  databricksLoading = false,
  selectedDatabricksTables = new Set(),
  setSelectedDatabricksTables = () => { },
  databricksQuery = '',
  setDatabricksQuery = () => { },
  databricksQueryRegex = false,
  setDatabricksQueryRegex = () => { },
  savedModels = new Set(),
  selectedModelNameByKey = {},
  selectionNotice = '',
  maxSelectedModels = 10,
  pbixManualFileLabels = [],
}) {
  // A model counts once however many keys (name / GUID) refer to it.
  const selectedCount = selectionIdentities(Array.from(selectedModels || []), selectedModelNameByKey).length;
  const isSelected = (m) => isModelSelected({ id: m.id, name: m.name }, Array.from(selectedModels || []), selectedModelNameByKey);
  const isSaved = (m) => Boolean(savedModels?.has(m.id) || (m.name && (savedModels?.has(m.name) || savedModels?.has(m.name.trim()))));

  if (sourceConnector === 'tableau') {
    return (
      <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
        <div>
          <h2 style={{ fontSize: 17, fontWeight: 700, color: 'var(--text-primary)', margin: '0 0 4px' }}>Tableau Source Ready</h2>
          <p style={{ fontSize: 13, color: 'var(--text-tertiary)', margin: 0 }}>
            Tableau data source parsing extracts relations, joins, and Level-of-Detail (LOD) formulas into the canonical OSI model. Continue to the next step to review ontology mappings and targets.
          </p>
        </div>
        <div style={{ padding: '18px 20px', borderRadius: 12, border: '1px solid var(--border-main)', background: 'var(--bg-surface)' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
            <UploadStatusIcon status={pbixUploadPath || selectedPbixFilePath ? 'ready' : 'pending'} size={14} />
            <span style={{ fontSize: 13, color: 'var(--text-primary)', fontWeight: 600 }}>
              {pbixUploadPath ? pbixUploadPath.split('/').pop() : 'Tableau Datasource (.tds / .tdsx / .twb / .twbx)'}
            </span>
          </div>
          {pbixUploadPath && (
            <div style={{ marginTop: 6, fontSize: 11, color: 'var(--text-tertiary)' }}>
              Source path: {pbixUploadPath}
            </div>
          )}
        </div>
      </div>
    );
  }

  if (sourceConnector === 'pbix') {
    if (pbixSourceMode === 'MANUAL') {
      return (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
          <div>
            <h2 style={{ fontSize: 17, fontWeight: 700, color: 'var(--text-primary)', margin: '0 0 4px' }}>PBIX Source Ready</h2>
            <p style={{ fontSize: 13, color: 'var(--text-tertiary)', margin: 0 }}>
              PBIX sync skips model discovery. Continue to the finish step to launch the pipeline and monitor Extraction, OSI Conversion, SML Generation, and Snowflake Deployment.
            </p>
          </div>
          <div style={{ padding: '18px 20px', borderRadius: 12, border: '1px solid var(--border-main)', background: 'var(--bg-surface)' }}>
            {pbixManualFileLabels.length === 0 ? (
              <div style={{ fontSize: 12, color: 'var(--text-secondary)', lineHeight: 1.6 }}>
                Upload the `.pbix` file in Connector Config, then use Start Sync after the project is created.
              </div>
            ) : (
              <div style={{ display: 'flex', flexDirection: 'column', gap: 6 }}>
                <div style={{ fontSize: 11, fontWeight: 700, color: 'var(--text-tertiary)', textTransform: 'uppercase' }}>
                  {pbixManualFileLabels.length} PBIX file{pbixManualFileLabels.length !== 1 ? 's' : ''} attached
                </div>
                {pbixManualFileLabels.map((file) => (
                  <div key={file.name} style={{ display: 'flex', alignItems: 'center', gap: 8, fontSize: 12, color: 'var(--text-primary)' }}>
                    <UploadStatusIcon status={file.status} size={13} />
                    <span>{file.name}</span>
                    {file.status === 'error' && file.error && (
                      <span style={{ fontSize: 11, color: 'var(--color-error)' }}>{file.error}</span>
                    )}
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>
      );
    }

    return (
      <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
        <div>
          <h2 style={{ fontSize: 17, fontWeight: 700, color: 'var(--text-primary)', margin: '0 0 4px' }}>Select PBIX File</h2>
          <p style={{ fontSize: 13, color: 'var(--text-tertiary)', margin: 0 }}>
            Choose a file from the tagged folder before continuing. The selected row will populate the final `pbix_file_path`.
          </p>
        </div>

        <div style={{ padding: '14px 16px', borderRadius: 12, border: '1px solid var(--border-main)', background: 'var(--bg-surface)' }}>
          <div style={{ fontSize: 12, color: 'var(--text-secondary)' }}>
            Folder tag: <span style={{ color: 'var(--text-primary)', fontWeight: 700 }}>{selectedLocalFolderTag || 'Not selected'}</span>
          </div>
        </div>

        {pbixFilesError && (
          <div style={{ padding: '10px 12px', borderRadius: 8, border: '1px solid var(--color-error)30', background: 'var(--color-error-bg)', color: 'var(--color-error)', fontSize: 12 }}>
            {pbixFilesError}
          </div>
        )}

        <div className="custom-scrollbar" style={{ maxHeight: 420, overflowY: 'auto', border: '1px solid var(--border-main)', borderRadius: 8 }}>
          {pbixFilesLoading ? (
            <div style={{ padding: '32px 0', textAlign: 'center', color: 'var(--text-tertiary)', fontSize: 12 }}>
              <Loader2 size={18} style={{ animation: 'spin 1s linear infinite', margin: '0 auto 8px', display: 'block' }} />
              Discovering PBIX files…
            </div>
          ) : pbixFiles.length === 0 ? (
            <div style={{ padding: '32px 0', textAlign: 'center', color: 'var(--text-tertiary)', fontSize: 12 }}>
              No `.pbix` files were found in the selected folder.
            </div>
          ) : pbixFiles.map(file => {
            const isSelected = selectedPbixFilePath === file.path;
            return (
              <div
                key={file.path}
                onClick={() => onSelectPbixFile(file.path)}
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  gap: 12,
                  padding: '12px 14px',
                  cursor: 'pointer',
                  borderBottom: '1px solid var(--border-subtle)',
                  background: isSelected ? 'var(--accent-blue)0a' : 'transparent',
                }}
                onMouseEnter={e => { if (!isSelected) e.currentTarget.style.background = 'var(--bg-surface-hover)'; }}
                onMouseLeave={e => { if (!isSelected) e.currentTarget.style.background = 'transparent'; }}
              >
                <input type="radio" checked={isSelected} readOnly style={{ accentColor: 'var(--accent-blue)' }} />
                <div style={{ minWidth: 0, flex: 1 }}>
                  <div style={{ fontSize: 13, fontWeight: 700, color: 'var(--text-primary)' }}>{file.name}</div>
                  <div style={{ fontSize: 11, color: 'var(--text-tertiary)', marginTop: 3 }}>
                    {file.modified_at ? `Last modified ${new Date(file.modified_at).toLocaleString()}` : file.path}
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      </div>
    );
  }

  if (sourceConnector === 'databricks') {
    // Flatten all tables for search
    const allTables = (databricksObjects || []).flatMap(obj =>
      (obj.tables || []).map(tbl => ({
        catalog: obj.catalog,
        schema: obj.schema,
        table: tbl,
        key: `${obj.catalog}.${obj.schema}.${tbl}`
      }))
    );
    const filteredTables = databricksQuery
      ? allTables.filter(t =>
        matchesSmartQuery(
          `${t.table || ''} ${t.schema || ''} ${t.catalog || ''}`,
          databricksQuery,
          databricksQueryRegex,
        )
      )
      : allTables;

    return (
      <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
        <div>
          <h2 style={{ fontSize: 17, fontWeight: 700, color: 'var(--text-primary)', margin: '0 0 4px' }}>Select Databricks Tables</h2>
          <p style={{ fontSize: 13, color: 'var(--text-tertiary)', margin: 0 }}>
            Choose which Databricks tables to include. Leave all unchecked to include everything.
          </p>
        </div>
        <SmartSearchBar
          value={databricksQuery}
          onChange={setDatabricksQuery}
          useRegex={databricksQueryRegex}
          onToggleRegex={setDatabricksQueryRegex}
          placeholder="Search Databricks tables"
        />
        {selectedDatabricksTables.size > 0 && (
          <div style={{ fontSize: 11, color: 'var(--accent-blue)', padding: '4px 0' }}>
            {selectedDatabricksTables.size} table{selectedDatabricksTables.size !== 1 ? 's' : ''} selected
            <button onClick={() => setSelectedDatabricksTables(new Set())} style={{ marginLeft: 8, background: 'none', border: 'none', cursor: 'pointer', color: 'var(--text-tertiary)', fontSize: 11 }}>
              Clear
            </button>
          </div>
        )}
        <div className="custom-scrollbar" style={{ maxHeight: 400, overflowY: 'auto', border: '1px solid var(--border-main)', borderRadius: 8 }}>
          {databricksLoading ? (
            <div style={{ padding: '32px 0', textAlign: 'center', color: 'var(--text-tertiary)', fontSize: 12 }}>
              <Loader2 size={18} style={{ animation: 'spin 1s linear infinite', margin: '0 auto 8px', display: 'block' }} />
              Discovering Databricks tables…
            </div>
          ) : filteredTables.length === 0 ? (
            <div style={{ padding: '32px 0', textAlign: 'center', color: 'var(--text-tertiary)', fontSize: 12 }}>
              No Databricks tables found. Check connector setup in Settings.
            </div>
          ) : (
            filteredTables.map(t => (
              <div
                key={t.key}
                onClick={() => {
                  setSelectedDatabricksTables(prev => {
                    const s = new Set(prev);
                    s.has(t.key) ? s.delete(t.key) : s.add(t.key);
                    return s;
                  });
                }}
                style={{
                  display: 'flex', alignItems: 'center', gap: 8,
                  padding: '7px 12px', cursor: 'pointer', userSelect: 'none',
                  background: selectedDatabricksTables.has(t.key) ? 'var(--accent-blue)0a' : 'transparent',
                  borderBottom: '1px solid var(--border-subtle)'
                }}
                onMouseEnter={e => { if (!selectedDatabricksTables.has(t.key)) e.currentTarget.style.background = 'var(--bg-surface-hover)'; }}
                onMouseLeave={e => { if (!selectedDatabricksTables.has(t.key)) e.currentTarget.style.background = 'transparent'; }}
              >
                {selectedDatabricksTables.has(t.key)
                  ? <CheckSquare size={14} style={{ color: 'var(--accent-blue)', flexShrink: 0 }} />
                  : <Square size={14} style={{ color: 'var(--text-tertiary)', flexShrink: 0 }} />}
                <span style={{ fontSize: 12, color: 'var(--text-primary)' }}>{t.table}</span>
                <span style={{ fontSize: 10, color: 'var(--text-tertiary)', marginLeft: 'auto' }}>{t.catalog}.{t.schema}</span>
              </div>
            ))
          )}
        </div>
      </div>
    );
  }

  if (sourceConnector === 'fabric') {
    if (!selectedWorkspace) {
      return (
        <div style={{ padding: '40px 0', textAlign: 'center', color: 'var(--text-tertiary)', fontSize: 13 }}>
          Choose a Fabric workspace in Connector Config before selecting models.
        </div>
      );
    }

    const fabricModels = wsModels[selectedWorkspace.id] || [];
    const displayModels = modelQuery
      ? fabricModels.filter(m =>
        matchesSmartQuery(
          `${m.name || ''} ${m.id || ''} ${m.description || ''}`,
          modelQuery,
          modelQueryRegex,
        )
      )
      : fabricModels.map(m => ({ ...m, _id: m.id }));

    if (wsLoading) {
      return (
        <div className="custom-scrollbar" style={{ maxHeight: 400, overflowY: 'auto', border: '1px solid var(--border-main)', borderRadius: 8 }}>
          <div style={{ padding: '32px 0', textAlign: 'center', color: 'var(--text-tertiary)', fontSize: 12 }}>
            <Loader2 size={18} style={{ animation: 'spin 1s linear infinite', margin: '0 auto 8px', display: 'block' }} />
            Discovering Fabric semantic models…
          </div>
        </div>
      );
    }

    if (displayModels.length > 0) {
      return (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
          <div>
            <h2 style={{ fontSize: 17, fontWeight: 700, color: 'var(--text-primary)', margin: '0 0 4px' }}>Select Models</h2>
            <p style={{ fontSize: 13, color: 'var(--text-tertiary)', margin: 0 }}>
              Choose which Fabric semantic models to include from {selectedWorkspace.name}. Select at least one model (up to {maxSelectedModels}); each selected model is dry-run and deployed as its own semantic view.
            </p>
          </div>
          <SmartSearchBar
            value={modelQuery}
            onChange={setModelQuery}
            useRegex={modelQueryRegex}
            onToggleRegex={setModelQueryRegex}
            placeholder={`Search models in ${selectedWorkspace.name}`}
          />
          {selectedCount > 0 ? (
            <div style={{ fontSize: 11, color: 'var(--accent-blue)', padding: '4px 0' }}>
              {selectedCount} of {maxSelectedModels} model{maxSelectedModels !== 1 ? 's' : ''} selected
              <button onClick={clearSelectedModels} style={{ marginLeft: 8, background: 'none', border: 'none', cursor: 'pointer', color: 'var(--text-tertiary)', fontSize: 11 }}>
                Clear
              </button>
            </div>
          ) : (
            <div style={{ fontSize: 11, color: 'var(--color-warning)', padding: '4px 0' }}>
              Select at least one semantic model to continue.
            </div>
          )}
          {selectionNotice && (
            <div role="status" style={{ fontSize: 12, color: 'var(--color-warning)' }}>{selectionNotice}</div>
          )}
          <div className="custom-scrollbar" style={{ maxHeight: 400, overflowY: 'auto', border: '1px solid var(--border-main)', borderRadius: 8 }}>
            {displayModels.map(m => {
              const modelId = m._id || m.id;
              return (
                <ModelRow
                  key={modelId}
                  model={{ ...m, _id: modelId }}
                  selected={isSelected(m)}
                  isSaved={isSaved(m)}
                  onToggle={() => toggleModel({ id: m.id, name: m.name || m.id })}
                />
              );
            })}
          </div>
        </div>
      );
    }

    return (
      <div className="custom-scrollbar" style={{ maxHeight: 400, overflowY: 'auto', border: '1px solid var(--border-main)', borderRadius: 8 }}>
        <div style={{ padding: '32px 0', textAlign: 'center', color: 'var(--text-tertiary)', fontSize: 12 }}>
          No Fabric semantic models found. Check connector setup in Settings.
        </div>
      </div>
    );
  }

  if (sourceConnector === 'snowflake') {
    const snowflakeModels = wsModels.snowflake || [];
    const displayModels = modelQuery ? snowflakeResults : snowflakeModels.map(m => ({ ...m, _id: m.id }));

    return (
      <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
        <div>
          <h2 style={{ fontSize: 17, fontWeight: 700, color: 'var(--text-primary)', margin: '0 0 4px' }}>Select Sources</h2>
          <p style={{ fontSize: 13, color: 'var(--text-tertiary)', margin: 0 }}>
            Choose which Snowflake semantic objects to include. Leave all unchecked to include everything.
          </p>
        </div>

        <SmartSearchBar
          value={modelQuery}
          onChange={setModelQuery}
          useRegex={modelQueryRegex}
          onToggleRegex={setModelQueryRegex}
          placeholder="Search Snowflake semantic objects"
        />

        {selectedCount > 0 && (
          <div style={{ fontSize: 11, color: 'var(--accent-blue)', padding: '4px 0' }}>
            {selectedCount} object{selectedCount !== 1 ? 's' : ''} selected
            <button onClick={clearSelectedModels} style={{ marginLeft: 8, background: 'none', border: 'none', cursor: 'pointer', color: 'var(--text-tertiary)', fontSize: 11 }}>
              Clear
            </button>
          </div>
        )}

        <div className="custom-scrollbar" style={{ maxHeight: 400, overflowY: 'auto', border: '1px solid var(--border-main)', borderRadius: 8 }}>
          {wsLoading ? (
            <div style={{ padding: '32px 0', textAlign: 'center', color: 'var(--text-tertiary)', fontSize: 12 }}>
              <Loader2 size={18} style={{ animation: 'spin 1s linear infinite', margin: '0 auto 8px', display: 'block' }} />
              Discovering Snowflake semantic objects…
            </div>
          ) : displayModels.length === 0 ? (
            <div style={{ padding: '32px 0', textAlign: 'center', color: 'var(--text-tertiary)', fontSize: 12 }}>
              No Snowflake semantic objects found. Check connector setup in Settings.
            </div>
          ) : (
            displayModels.map(m => {
              const modelId = m._id || m.id;
              return (
                <ModelRow
                  key={modelId}
                  model={{ ...m, _id: modelId }}
                  selected={isSelected({ id: modelId, name: m.name })}
                  isSaved={isSaved({ id: modelId, name: m.name })}
                  onToggle={() => toggleModel({ id: modelId, name: m.name || modelId })}
                />
              );
            })
          )}
        </div>
      </div>
    );
  }

  return null;
}

function ModelRow({ model, selected, onToggle, indent, showWs, isSaved }) {
  return (
    <div
      onClick={onToggle}
      style={{
        display: 'flex', alignItems: 'center', gap: 8,
        padding: `7px ${indent ? 32 : 12}px`,
        cursor: 'pointer', userSelect: 'none',
        background: selected ? 'var(--accent-blue)0a' : 'transparent',
        borderBottom: '1px solid var(--border-subtle)',
      }}
      onMouseEnter={e => { if (!selected) e.currentTarget.style.background = 'var(--bg-surface-hover)'; }}
      onMouseLeave={e => { if (!selected) e.currentTarget.style.background = 'transparent'; }}
    >
      {selected
        ? <CheckSquare size={14} style={{ color: 'var(--accent-blue)', flexShrink: 0 }} />
        : <Square size={14} style={{ color: 'var(--text-tertiary)', flexShrink: 0 }} />}
      <span style={{ fontSize: 12, color: 'var(--text-primary)' }}>{model.name || model.id}</span>
      {isSaved && (
        <span style={{ fontSize: 9, fontWeight: 700, color: 'var(--accent-blue)', background: 'var(--accent-blue)15', border: '1px solid var(--accent-blue)30', padding: '2px 6px', borderRadius: 4, textTransform: 'uppercase', marginLeft: 4 }}>Previously Synced</span>
      )}
      {showWs && <span style={{ fontSize: 10, color: 'var(--text-tertiary)', marginLeft: 'auto' }}>{model.wsid}</span>}
    </div>
  );
}

import React from 'react';
import { ArrowLeft, ArrowRight, Save, Loader2 } from 'lucide-react';

export function WizardFooter({ createdProject, step, goBack, goNext, canAdvance, saving, mappingLoading, editMode }) {
  if (createdProject) return null;

  return (
    <footer style={{
      height: 72,
      position: 'fixed',
      bottom: 0,
      left: 0,
      right: 0,
      background: 'var(--bg-surface)',
      backdropFilter: 'blur(16px)',
      borderTop: '1px solid var(--border-main)',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      zIndex: 1000,
      boxShadow: 'var(--shadow-md)'
    }}>
      <div style={{
        width: '100%',
        maxWidth: (step >= 3 && step <= 5) ? 1400 : 900,
        padding: '0 36px',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'space-between'
      }}>
        {step > 1 ? (
          <button
            type="button"
            onClick={goBack}
            className="flex items-center gap-2 px-5 py-2.5 text-xs font-semibold transition-all rounded-lg border border-[var(--border-main)] bg-[var(--bg-surface-raised)] hover:bg-[var(--bg-surface-hover)] text-[var(--text-secondary)] hover:text-[var(--text-primary)] cursor-pointer"
          >
            <ArrowLeft size={14} /> BACK
          </button>
        ) : <div />}

        <div style={{ display: 'flex', gap: 12, alignItems: 'center' }}>
          <button
            type="button"
            onClick={goNext}
            disabled={!canAdvance || saving || mappingLoading}
            className={`flex items-center gap-2 px-7 py-2.5 text-xs font-bold transition-all rounded-lg cursor-pointer ${
              !canAdvance || saving || mappingLoading
                ? 'bg-[var(--bg-surface-raised)] text-[var(--text-tertiary)] border border-[var(--border-main)] cursor-not-allowed opacity-50'
                : 'bg-[var(--accent-blue)] text-white hover:bg-[var(--accent-blue-hover)] shadow-sm'
            }`}
          >
            {(saving || mappingLoading) && <Loader2 size={14} className="animate-spin" />}
            {step === 6 ? (
              <>
                <Save size={14} />
                {saving ? 'SAVING…' : (editMode ? 'SAVE CHANGES' : 'CREATE PROJECT')}
              </>
            ) : (
              <>
                CONTINUE
                <ArrowRight size={14} />
              </>
            )}
          </button>
        </div>
      </div>
    </footer>
  );
}

import React from 'react';
import { X, Check, Layers, Sparkles } from 'lucide-react';
import { STEPS } from '../../utils/constants';
import { useProjectWizardStore } from '../../store/projectWizardStore';

export function WizardHeader({ editMode, hasMeaningfulData, clearWizardState, navigate, name, step, canUpsert = false }) {
  const setWizardState = useProjectWizardStore(state => state.setWizardState);

  return (
    <header style={{
      height: 72,
      padding: '0 36px',
      background: 'var(--bg-surface)',
      backdropFilter: 'blur(16px)',
      borderBottom: '1px solid var(--border-main)',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'space-between',
      position: 'sticky',
      top: 0,
      zIndex: 100,
      boxShadow: 'var(--shadow-sm)'
    }}>
      <div style={{ display: 'flex', alignItems: 'center', gap: 18 }}>
        <button
          onClick={() => {
            if (hasMeaningfulData && !editMode) {
              if (window.confirm('Discard project draft?')) {
                clearWizardState();
                navigate('/projects');
              }
            } else {
              navigate('/projects');
            }
          }}
          className="flex items-center justify-center w-9 h-9 rounded-lg border border-[var(--border-main)] bg-[var(--bg-surface-raised)] hover:bg-[var(--bg-surface-hover)] text-[var(--text-secondary)] hover:text-[var(--text-primary)] transition-all cursor-pointer shadow-xs"
          title="Exit Wizard"
        >
          <X size={16} strokeWidth={2.2} />
        </button>

        <div style={{ display: 'flex', flexDirection: 'column' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
            <h1 style={{
              fontSize: 17,
              fontWeight: 700,
              color: 'var(--text-primary)',
              margin: 0,
              letterSpacing: '-0.02em',
              lineHeight: 1.2
            }}>
              {editMode ? 'Edit project' : 'New project'}
            </h1>
            {name.trim() && (
              <span style={{
                background: 'var(--color-accent-faint)',
                color: 'var(--accent-blue)',
                padding: '2px 8px',
                borderRadius: 6,
                fontSize: 11,
                fontWeight: 600,
                border: '1px solid var(--border-focus)'
              }}>
                {name}
              </span>
            )}
          </div>
          <div style={{
            fontSize: 11,
            color: 'var(--text-tertiary)',
            marginTop: 3,
            display: 'flex',
            alignItems: 'center',
            gap: 6
          }}>
            <span style={{ color: 'var(--accent-blue)', fontWeight: 600 }}>Step {step} of {STEPS.length}</span>
            <span style={{ color: 'var(--border-main)' }}>•</span>
            <span>{STEPS[step - 1]?.label}</span>
          </div>
        </div>

        {/* Sync Strategy Control */}
        {editMode ? (
          <div style={{
            background: 'var(--bg-surface-raised)',
            padding: '6px 12px',
            borderRadius: 8,
            border: '1px solid var(--border-main)',
            display: 'flex',
            alignItems: 'center',
            gap: 10
          }}>
            <span style={{ fontSize: 11, fontWeight: 700, color: 'var(--text-secondary)' }}>Strategy:</span>
            <div style={{ display: 'flex', gap: 6 }}>
              {['copy', 'upsert'].map((opt) => {
                const isUpsertDisabled = opt === 'upsert' && !canUpsert;
                const active = (useProjectWizardStore.getState().wizard.write_strategy || 'copy') === opt;
                return (
                  <button
                    key={opt}
                    type="button"
                    disabled={isUpsertDisabled}
                    title={isUpsertDisabled ? 'Upsert requires at least one prior deployment to create target views.' : undefined}
                    onClick={() => !isUpsertDisabled && setWizardState({ write_strategy: opt })}
                    style={{
                      padding: '4px 10px',
                      borderRadius: 6,
                      border: '1px solid',
                      borderColor: active ? 'transparent' : 'var(--border-main)',
                      cursor: isUpsertDisabled ? 'not-allowed' : 'pointer',
                      opacity: isUpsertDisabled ? 0.45 : 1,
                      background: active ? (opt === 'upsert' ? 'var(--accent-orange)' : 'var(--accent-blue)') : 'var(--bg-surface)',
                      color: active ? '#ffffff' : 'var(--text-secondary)',
                      fontWeight: 600,
                      fontSize: 11,
                      transition: 'all 0.15s ease'
                    }}
                  >
                    {opt === 'copy' ? 'Copy (Replace)' : 'Upsert (Delta)'}
                  </button>
                );
              })}
            </div>
          </div>
        ) : (
          <div style={{
            background: 'var(--bg-surface-raised)',
            padding: '5px 12px',
            borderRadius: 20,
            border: '1px solid var(--border-main)',
            display: 'flex',
            alignItems: 'center',
            gap: 8,
            fontSize: 11,
            color: 'var(--text-secondary)'
          }}>
            <span style={{
              width: 6,
              height: 6,
              borderRadius: '50%',
              background: 'var(--accent-cyan)',
              display: 'inline-block'
            }} />
            <span style={{ fontWeight: 600, color: 'var(--text-primary)' }}>Sync Mode:</span>
            <span style={{
              fontWeight: 700,
              color: 'var(--accent-cyan)',
              fontFamily: 'monospace',
              letterSpacing: '0.05em'
            }}>
              BASELINE COPY
            </span>
            <span style={{ color: 'var(--text-tertiary)' }}>· Establishes initial target schema</span>
          </div>
        )}
      </div>

      {/* Stepper Progress Badges */}
      <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
        {STEPS.map((s, idx) => {
          const targetStep = idx + 1;
          const isCompleted = step > targetStep;
          const isActive = step === targetStep;
          const canJump = editMode || targetStep <= step;
          return (
            <div key={s.id} style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
              <button
                type="button"
                disabled={!canJump}
                onClick={() => canJump && setWizardState({ step: targetStep })}
                title={canJump ? `Go to Step ${targetStep}: ${s.label}` : `Step ${targetStep}: ${s.label}`}
                style={{
                  width: isActive ? 28 : 24,
                  height: isActive ? 28 : 24,
                  borderRadius: '50%',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  fontSize: 11,
                  fontWeight: 700,
                  padding: 0,
                  cursor: canJump ? 'pointer' : 'default',
                  transition: 'all 0.2s ease',
                  background: isActive
                    ? 'var(--accent-blue)'
                    : isCompleted
                    ? 'var(--color-success-bg)'
                    : 'var(--bg-surface-raised)',
                  color: isActive
                    ? '#ffffff'
                    : isCompleted
                    ? 'var(--color-success)'
                    : 'var(--text-quaternary)',
                  border: isActive
                    ? '2px solid var(--border-focus)'
                    : isCompleted
                    ? '1.5px solid var(--color-success)'
                    : '1.5px solid var(--border-main)',
                  boxShadow: isActive ? '0 0 12px var(--color-accent-faint)' : 'none'
                }}
              >
                {isCompleted ? <Check size={13} strokeWidth={2.8} /> : targetStep}
              </button>
              {idx < STEPS.length - 1 && (
                <div
                  style={{
                    width: 18,
                    height: 2,
                    borderRadius: 1,
                    background: step > idx + 1 ? 'var(--color-success)' : 'var(--border-main)',
                    transition: 'background 0.3s ease'
                  }}
                />
              )}
            </div>
          );
        })}
      </div>
    </header>
  );
}

/**
 * Shared "what does an uploading/succeeded/failed PBIX file look like"
 * components -- the status icon and the remove ("X") button, used by BOTH
 * the single-file dropzone (StepConnectorConfig.jsx) and the multi-file
 * list (MultiPbixUpload.jsx). See uploadStatusColors.js for the shared
 * success/error color treatment (kept in its own file, not here, purely so
 * this file only exports components -- required for Vite fast refresh).
 *
 * Extracted after the same single-vs-multi visual drift happened twice:
 * first the green "uploaded" treatment existed in one mode but not the
 * other, then the remove button did too. Each mode still owns its own
 * idle/dragging layout (a big dropzone panel vs. a compact list row) --
 * only the parts both modes should always agree on live here.
 */
import { CheckCircle2, AlertCircle, Loader2, X } from 'lucide-react';

export function UploadStatusIcon({ status, size = 14 }) {
  if (status === 'uploading') {
    return <Loader2 size={size} style={{ color: 'var(--text-tertiary)', animation: 'spin 1s linear infinite', flexShrink: 0 }} />;
  }
  if (status === 'done') {
    return <CheckCircle2 size={size} style={{ color: 'var(--color-success)', flexShrink: 0 }} />;
  }
  if (status === 'error') {
    return <AlertCircle size={size} style={{ color: 'var(--color-error)', flexShrink: 0 }} />;
  }
  return null;
}

/**
 * Clears an uploaded/uploading/errored file. `preventDefault` + `stopPropagation`
 * matter here specifically because this button is used inside both a
 * clickable `<div onClick>` row (multi-file) AND a native `<label>` wrapping
 * a hidden file `<input>` (single-file) -- without preventDefault, clicking
 * X inside the label would also trigger the label's default "activate the
 * associated file input" behavior and reopen the file picker.
 */
export function RemoveFileButton({ onClick, size = 12, title = 'Remove file' }) {
  return (
    <button
      type="button"
      onClick={(evt) => {
        evt.preventDefault();
        evt.stopPropagation();
        onClick?.();
      }}
      title={title}
      style={{
        background: 'none', border: 'none', cursor: 'pointer',
        color: 'var(--text-tertiary)', padding: 2, flexShrink: 0,
        display: 'inline-flex', alignItems: 'center',
      }}
    >
      <X size={size} />
    </button>
  );
}

import { useState, useMemo } from 'react';
import { Search, Split, Layers, ArrowRight, Minus, Plus } from 'lucide-react';

export default function DiffViewer({ leftContent = '', rightContent = '', leftTitle = 'Previous', rightTitle = 'Current' }) {
    const [viewMode, setViewMode] = useState('split'); // 'split' or 'unified'

    const leftLines = useMemo(() => leftContent.split('\n'), [leftContent]);
    const rightLines = useMemo(() => rightContent.split('\n'), [rightContent]);

    // Simple line-by-line diff for demonstration
    // In a production app, we would use a more robust library like 'diff' or 'jsdiff'
    const diffResult = useMemo(() => {
        const maxLen = Math.max(leftLines.length, rightLines.length);
        const result = [];
        for (let i = 0; i < maxLen; i++) {
            const left = leftLines[i] || '';
            const right = rightLines[i] || '';
            const type = left === right ? 'equal' : (left && !right ? 'deleted' : (!left && right ? 'added' : 'modified'));
            result.push({ left, right, type, line: i + 1 });
        }
        return result;
    }, [leftLines, rightLines]);

    return (
        <div className="flex flex-col h-full bg-[#0b1120] text-slate-300 font-mono text-[13px] border border-white/5 rounded-lg overflow-hidden">
            {/* Toolbar */}
            <div className="flex items-center justify-between px-4 py-2 bg-white/2 border-b border-white/5">
                <div className="flex items-center gap-4">
                    <span className="text-[11px] font-bold uppercase tracking-widest text-slate-500">Diff Viewer</span>
                    <div className="flex items-center gap-2">
                        <button
                            onClick={() => setViewMode('split')}
                            className={`px-2 py-1 rounded flex items-center gap-1.5 transition-all ${viewMode === 'split' ? 'bg-indigo-600/20 text-indigo-400' : 'text-slate-500 hover:text-slate-300'}`}
                        >
                            <Split size={14} /> Split
                        </button>
                        <button
                            onClick={() => setViewMode('unified')}
                            className={`px-2 py-1 rounded flex items-center gap-1.5 transition-all ${viewMode === 'unified' ? 'bg-indigo-600/20 text-indigo-400' : 'text-slate-500 hover:text-slate-300'}`}
                        >
                            <Layers size={14} /> Unified
                        </button>
                    </div>
                </div>
                <div className="flex items-center gap-3 text-[11px]">
                    <span className="text-emerald-500 font-bold">+{diffResult.filter(r => r.type === 'added').length}</span>
                    <span className="text-red-500 font-bold">-{diffResult.filter(r => r.type === 'deleted').length}</span>
                </div>
            </div>

            {/* Diff Content */}
            <div className="flex-1 overflow-auto custom-scrollbar">
                {viewMode === 'split' ? (
                    <div className="flex min-w-full">
                        {/* Left Panel */}
                        <div className="flex-1 border-r border-white/5">
                            <div className="px-3 py-1 bg-white/2 border-b border-white/5 text-[10px] font-bold text-slate-500 sticky top-0 z-10">{leftTitle}</div>
                            {diffResult.map((res, i) => (
                                <div key={i} className={`flex px-2 ${res.type === 'deleted' ? 'bg-red-500/10' : (res.type === 'modified' ? 'bg-indigo-500/5' : '')}`}>
                                    <span className="w-8 shrink-0 text-slate-600 text-right select-none pr-2 border-r border-white/5">{res.line}</span>
                                    <pre className={`pl-2 whitespace-pre ${res.type === 'deleted' ? 'text-red-400' : ''}`}>
                                        {res.type === 'deleted' && '- '}{res.left}
                                    </pre>
                                </div>
                            ))}
                        </div>
                        {/* Right Panel */}
                        <div className="flex-1">
                            <div className="px-3 py-1 bg-white/2 border-b border-white/5 text-[10px] font-bold text-slate-500 sticky top-0 z-10">{rightTitle}</div>
                            {diffResult.map((res, i) => (
                                <div key={i} className={`flex px-2 ${res.type === 'added' ? 'bg-emerald-500/10' : (res.type === 'modified' ? 'bg-indigo-500/5' : '')}`}>
                                    <span className="w-8 shrink-0 text-slate-600 text-right select-none pr-2 border-r border-white/5">{res.line}</span>
                                    <pre className={`pl-2 whitespace-pre ${res.type === 'added' ? 'text-emerald-400' : ''}`}>
                                        {res.type === 'added' && '+ '}{res.right}
                                    </pre>
                                </div>
                            ))}
                        </div>
                    </div>
                ) : (
                    <div className="min-w-full">
                        {/* Unified View */}
                        {diffResult.map((res, i) => (
                            <div key={i}>
                                {res.type === 'deleted' && (
                                    <div className="flex px-2 bg-red-500/10">
                                        <span className="w-8 shrink-0 text-slate-600 text-right select-none pr-2 border-r border-white/5">{res.line}</span>
                                        <pre className="pl-2 text-red-400">- {res.left}</pre>
                                    </div>
                                )}
                                {res.type === 'added' && (
                                    <div className="flex px-2 bg-emerald-500/10">
                                        <span className="w-8 shrink-0 text-slate-600 text-right select-none pr-2 border-r border-white/5">{res.line}</span>
                                        <pre className="pl-2 text-emerald-400">+ {res.right}</pre>
                                    </div>
                                )}
                                {res.type === 'equal' && (
                                    <div className="flex px-2">
                                        <span className="w-8 shrink-0 text-slate-600 text-right select-none pr-2 border-r border-white/5">{res.line}</span>
                                        <pre className="pl-2 whitespace-pre">  {res.left}</pre>
                                    </div>
                                )}
                            </div>
                        ))}
                    </div>
                )}
            </div>
        </div>
    );
}

import { useState, useRef, useEffect } from 'react';
import { ChevronDown } from 'lucide-react';

export default function DropdownMenu({ label, items }) {
    const [isOpen, setIsOpen] = useState(false);
    const dropdownRef = useRef(null);

    // Close when clicking outside
    useEffect(() => {
        function handleClickOutside(event) {
            if (dropdownRef.current && !dropdownRef.current.contains(event.target)) {
                setIsOpen(false);
            }
        }
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    return (
        <div className="relative inline-block text-left" ref={dropdownRef}>
            <button
                onClick={() => setIsOpen(!isOpen)}
                className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-medium cursor-pointer transition-all duration-200 border-none outline-none"
                style={{
                    background: isOpen ? 'var(--bg-surface-hover)' : 'transparent',
                    color: 'var(--text-secondary)',
                }}
                onMouseEnter={e => {
                    if (!isOpen) e.currentTarget.style.background = 'var(--bg-surface-hover)';
                }}
                onMouseLeave={e => {
                    if (!isOpen) e.currentTarget.style.background = 'transparent';
                }}
            >
                {label}
                <ChevronDown size={12} className={`transition-transform duration-200 ${isOpen ? 'rotate-180' : ''}`} />
            </button>

            {isOpen && (
                <div
                    className="absolute left-0 mt-1 w-48 rounded-xl shadow-lg ring-1 ring-black ring-opacity-5 focus:outline-none z-50 overflow-hidden"
                    style={{
                        background: 'var(--bg-surface)',
                        border: '1px solid var(--border-main)',
                        boxShadow: 'var(--shadow-lg)',
                    }}
                >
                    <div className="py-1">
                        {items.map((item, index) => (
                            <button
                                key={index}
                                onClick={() => {
                                    if (item.onClick) item.onClick();
                                    setIsOpen(false);
                                }}
                                className={`flex items-center w-full px-4 py-2 text-xs font-medium theme-transition border-none outline-none cursor-pointer ${item.danger ? 'text-red-500' : 'text-primary'
                                    }`}
                                onMouseEnter={e => { e.currentTarget.style.background = 'var(--bg-surface-hover)'; }}
                                onMouseLeave={e => { e.currentTarget.style.background = 'transparent'; }}
                            >
                                {item.icon && <item.icon size={14} className="mr-2 opacity-70" />}
                                {item.label}
                                {item.shortcut && (
                                    <span className="ml-auto text-[10px] opacity-40 font-mono">{item.shortcut}</span>
                                )}
                            </button>
                        ))}
                    </div>
                </div>
            )}
        </div>
    );
}

