        )}
        {/* AI self-reported estimate -- Tier-5-only, never shown for a
            Tier 1-4 (deterministic) metric since llm_self_reported_
            confidence is always null there. Deliberately NOT a colored
            StatusBadge pill: this is the LLM's own unverified guess, not
            a validated risk signal, and must never be visually confused
            with the badge above it. Shown as a short always-visible form
            with the full "(not independently verified)" qualifier moved to
            the native tooltip (title) -- getSelfReportedEstimateText()
            still always returns the full qualified string, so the caveat
            is reachable on hover/focus, never removed, and row height no
            longer depends on how long that sentence happens to be. */}
        {selfReportedEstimateText && (
          <span
            title={selfReportedEstimateText}
            tabIndex={0}
            style={{
              display: 'inline-flex',
              alignItems: 'center',
              gap: 3,
              fontSize: 10,
              fontWeight: 500,
              fontStyle: 'italic',
              color: 'var(--text-tertiary)',
              whiteSpace: 'nowrap',
              cursor: 'help',
            }}
          >
            AI estimate: {selfReportedEstimatePct}%
            <Info size={10} style={{ flexShrink: 0 }} />
          </span>
        )}
        {/* Enrichment-column-unverifiable caveat -- a metric whose SQL
            already translated correctly, referencing a flag column
            (e.g. IS_YTD) that only exists on the enriched view
            _create_enriched_view builds at real-deploy time. Dry-run has
            no live connection to confirm it, so this is neither a risk
            signal (staticRiskBadge) nor an AI guess
            (selfReportedEstimateText) -- a third, distinct, non-error
            tone (info, not warning/error) so it can't be mistaken for
            either. Same short-label + tooltip treatment as the estimate
            above, for the same row-height reason; getEnrichmentUnverifiableCaveat()
            still returns the full sentence, surfaced via title. */}
        {enrichmentUnverifiableCaveat && (
          <span
            title={enrichmentUnverifiableCaveat}
            tabIndex={0}
            style={{
              display: 'inline-flex',
              alignItems: 'center',
              gap: 3,
              fontSize: 10,
              fontWeight: 500,
              color: '#3B82F6',
              whiteSpace: 'nowrap',
              cursor: 'help',
            }}
          >
            Enrichment unverifiable
            <Info size={10} style={{ flexShrink: 0 }} />
          </span>
        )}
        {/* Same column name in several tables: deploys fine as TABLE.NAME,
            but a bare NAME is ambiguous when queried. Info only, never
            blocks; the full sentence is in the tooltip. */}
        {sharedNameNote && (
          <span
            title={sharedNameNote}
            tabIndex={0}
            style={{
              display: 'inline-flex',
              alignItems: 'center',
              gap: 3,
              fontSize: 10,
              fontWeight: 500,
              color: 'var(--text-tertiary)',
              whiteSpace: 'nowrap',
              cursor: 'help',
            }}
          >
            Also in {row.shared_name_tables.length - 1} other table{row.shared_name_tables.length > 2 ? 's' : ''}
            <Info size={10} style={{ flexShrink: 0 }} />
          </span>
        )}
      </div>

      {/* Action */}
      <div style={{ display: 'flex', justifyContent: 'flex-end', gap: 6, flexWrap: 'nowrap' }}>
        {isCollision ? (
          <button
            type="button"
            onClick={() => setExpandedCollision(expandedCollision === row.id ? null : row.id)}
            style={{
              display: 'inline-flex',
              alignItems: 'center',
              gap: 5,
              padding: '4px 10px',
              borderRadius: 6,
              border: expandedCollision === row.id
                ? '1px solid rgba(251,191,36,0.55)'
                : '1px solid rgba(239, 68, 68, 0.45)',
              background: expandedCollision === row.id
                ? 'rgba(251,191,36,0.12)'
                : 'rgba(239, 68, 68, 0.10)',
              color: expandedCollision === row.id ? '#fbbf24' : 'var(--color-error)',
              fontSize: 11,
              fontWeight: 700,
              cursor: 'pointer',
              whiteSpace: 'nowrap',
              transition: 'all 0.2s',
            }}
          >
            {expandedCollision === row.id ? <><X size={11} /> Close</> : <><ChevronRight size={11} /> Fix</>}
          </button>
        ) : (
          <div style={{ display: 'flex', gap: 6 }}>
            {isMeasure && (
              <button
                type="button"
                onClick={() => {
                  const next = !expandedMeasure;
                  setExpandedMeasure(next);
                  if (!next) setRevealSynonymsOnOpen(false);
                }}
                style={{
                  display: 'inline-flex',
                  alignItems: 'center',
                  gap: 5,
                  padding: '4px 10px',
                  borderRadius: 6,
                  border: expandedMeasure
                    ? '1px solid rgba(56, 189, 248, 0.55)'
                    : '1px solid rgba(56, 189, 248, 0.45)',
                  background: expandedMeasure
                    ? 'rgba(56, 189, 248, 0.15)'
                    : 'rgba(56, 189, 248, 0.05)',
                  color: '#7dd3fc',
                  fontSize: 11,
                  fontWeight: 600,
                  cursor: 'pointer',
                  whiteSpace: 'nowrap',
                  transition: 'all 0.2s',
                }}
              >
                {expandedMeasure ? 'Hide SQL' : 'View SQL'}
              </button>
            )}
            <button
              type="button"
              onClick={() => onEdit?.(row.id)}
              style={{
                display: 'inline-flex',
                alignItems: 'center',
                gap: 5,
                padding: '4px 10px',
                borderRadius: 6,
                border: '1px solid var(--border-main)',
                background: 'var(--bg-surface-raised)',
                color: 'var(--text-secondary)',
                fontSize: 11,
                fontWeight: 600,
                cursor: 'pointer',
                whiteSpace: 'nowrap',
                transition: 'all 0.2s',
              }}
            >
              <Edit2 size={11} />
              {row.target_field ? 'Edit' : 'Map'}
            </button>
          </div>
        )}
      </div>
    </div>
    {/* ── Inline collision fix panel ── */}
    {isCollision && expandedCollision === row.id && (
      <div style={{ padding: '0 14px 10px' }}>
        <CollisionPanel
          row={row}
          allRows={allRows}
          pendingRename={pendingRenames[row.id] ?? ''}
          onRenameChange={val => setPendingRenames(prev => ({ ...prev, [row.id]: val }))}
          onApply={() => onApplyRename(row.id)}
          applying={applyingRename === row.id}
        />
      </div>
    )}
    {/* ── Inline measure translation panel ── */}
    {hasDetails && expandedMeasure && (
      <div style={{ padding: '0 14px 10px' }}>
        <MeasureTranslationPanel row={row} forceRevealSynonyms={revealSynonymsOnOpen} />
      </div>
    )}
    </div>
  );
}

// ─── Measure translation detail panel ─────────────────────────────────────────
const SYNONYM_SOURCE_LABELS = {
  manual_override: 'Manual Override',
  tmsl_authored: 'TMSL-Authored',
  auto_generated: 'Auto-Generated',
  report_alias: 'Report Alias',
  renamed_field_reference: 'Renamed Field',
};

function synonymSourceLabel(source) {
  if (SYNONYM_SOURCE_LABELS[source]) return SYNONYM_SOURCE_LABELS[source];
  const word = String(source || '').replace(/[_-]+/g, ' ').trim();
  return word ? word.replace(/\b\w/g, (c) => c.toUpperCase()) : null;
}

function MeasureTranslationPanel({ row, forceRevealSynonyms = false }) {
  const isMeasure = String(row.field_type || row.entity_kind || '').toLowerCase() === 'measure';
  const hasTargetExpr = Boolean(String(row.target_expression || '').trim());
  const isFailed = row.sync_enabled === false || !!row.sync_failure_reason || (isMeasure && !hasTargetExpr);
  // Opening the panel via the row's "N detected" pill IS the explicit,
  // deliberate action the toggle below normally requires -- so it starts
  // already revealed in that case, instead of requiring a second click to
  // find the same synonyms the pill's count was just about.
  const [showAllSynonymSources, setShowAllSynonymSources] = useState(forceRevealSynonyms);

  // A synonym only shows under "Report Aliases" when its source is confirmed
  // as a genuine PBIX report-layer visual alias. Anything else (manual
  // override, TMSL-authored, mechanically auto-generated) is a coincidental
  // lookalike at best and must not be visually indistinguishable from a real
  // report alias — it's hidden behind an explicit toggle instead, sub-labeled
  // by its actual source. Driven entirely by row.synonym_sources; no
  // hardcoded field or source names.
  const allSynonyms = Array.isArray(row.synonyms) ? row.synonyms : [];
  const synonymSources = row.synonym_sources || {};
  const reportAliases = allSynonyms.filter((s) => synonymSources[s] === 'report_alias');
  const otherSynonyms = allSynonyms.filter((s) => synonymSources[s] !== 'report_alias');

  return (
    <div style={{
      gridColumn: '1 / -1',
      margin: '0 0 4px',
      padding: '14px 16px',
      borderRadius: 8,
      background: 'rgba(56, 189, 248, 0.03)',
      border: '1px solid rgba(56, 189, 248, 0.15)',
      display: 'flex',
      flexDirection: 'column',
      gap: 12,
    }}>
      {/* ── Status Banner (Measures only) ── */}
      {isMeasure && (
        isFailed ? (
          <div style={{
            display: 'flex',
            alignItems: 'center',
            gap: 8,
            padding: '8px 12px',
            borderRadius: 6,
            background: 'rgba(239, 68, 68, 0.08)',
            border: '1px solid rgba(239, 68, 68, 0.25)',
            color: 'var(--color-error)',
            fontSize: 11,
            fontWeight: 600,
          }}>
            <AlertTriangle size={13} style={{ flexShrink: 0 }} />
            <span>Translation Warning: {row.sync_failure_reason || 'This measure is too complex to translate to SQL automatically.'}</span>
          </div>
        ) : (
          <div style={{
            display: 'flex',
            alignItems: 'center',
            gap: 8,
            padding: '8px 12px',
            borderRadius: 6,
            background: 'rgba(34, 197, 94, 0.08)',
            border: '1px solid rgba(34, 197, 94, 0.25)',
            color: 'var(--color-success)',
            fontSize: 11,
            fontWeight: 600,
          }}>
            <CheckCircle size={13} style={{ flexShrink: 0 }} />
            <span>Translated successfully to Snowflake SQL</span>
          </div>
        )
      )}

      {/* ── No synonyms at all for this field — say so explicitly rather
          than silently omitting both sections below. ── */}
      {allSynonyms.length === 0 && (
        <div style={{ fontSize: 11, fontStyle: 'italic', color: 'var(--text-tertiary)' }}>
          No synonym
        </div>
      )}

      {/* ── Report Aliases (Columns and Measures if present) — genuine
          report-layer matches only; anything else is behind the toggle below ── */}
      {reportAliases.length > 0 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 6 }}>
          <span style={{ fontSize: 10, fontWeight: 700, color: 'var(--text-tertiary)', textTransform: 'uppercase', letterSpacing: '0.05em' }}>Report Aliases</span>
          <div style={{
            display: 'flex',
            flexDirection: 'column',
            gap: 4,
            padding: '10px 12px',
            borderRadius: 6,
            background: 'var(--bg-main)',
            border: '1px solid var(--border-main)',
            color: 'var(--text-secondary)',
            fontSize: 12,
          }}>
            {reportAliases.map((alias, index) => (
              <div key={`${row.id}-${alias}-${index}`} style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
                <span style={{ color: 'var(--text-tertiary)' }}>•</span>
                <span>{alias}</span>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* ── Other synonym sources — hidden by default. This page has no
          role gating (any authenticated user can reach it), so a
          manual-override/TMSL-authored/auto-generated synonym must never be
          shown next to genuine report aliases without an explicit,
          deliberate action to reveal it. ── */}
      {otherSynonyms.length > 0 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 6 }}>
          <button
            type="button"
            onClick={() => setShowAllSynonymSources((prev) => !prev)}
            style={{
              display: 'inline-flex',
              alignItems: 'center',
              gap: 5,
              alignSelf: 'flex-start',
              padding: '3px 8px',
              borderRadius: 5,
              border: '1px solid var(--border-main)',
              background: 'transparent',
              color: 'var(--text-tertiary)',
              fontSize: 10,
              fontWeight: 600,
              cursor: 'pointer',
            }}
          >
            {showAllSynonymSources
              ? 'Hide other synonym sources'
              : `Show all synonym sources (${otherSynonyms.length})`}
          </button>
          {showAllSynonymSources && (
            <div style={{
              display: 'flex',
              flexDirection: 'column',
              gap: 4,
              padding: '10px 12px',
              borderRadius: 6,
              background: 'var(--bg-main)',
              border: '1px solid var(--border-main)',
              color: 'var(--text-secondary)',
              fontSize: 12,
            }}>
              {otherSynonyms.map((alias, index) => {
                const labelText = synonymSourceLabel(synonymSources[alias]);
                return (
                  <div key={`${row.id}-other-${alias}-${index}`} style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
                    <span style={{ color: 'var(--text-tertiary)' }}>•</span>
                    <span>{alias}</span>
                    {labelText && (
                      <span style={{
                        fontSize: 9,
                        fontWeight: 700,
                        textTransform: 'uppercase',
                        letterSpacing: '0.03em',
                        color: 'var(--text-tertiary)',
                        border: '1px solid var(--border-main)',
                        borderRadius: 4,
                        padding: '1px 5px',
                        marginLeft: 'auto',
                      }}>
                        {labelText}
                      </span>
                    )}
                  </div>
                );
              })}
            </div>
          )}
        </div>
      )}

      {/* ── Side-by-Side Code Blocks (Measures only) ── */}
      {isMeasure && (
        <div style={{
          display: 'grid',
          gridTemplateColumns: '1fr 1fr',
          gap: '12px',
          marginTop: (reportAliases.length > 0 || otherSynonyms.length > 0) ? '6px' : '0',
        }}>
          {/* Source DAX */}
          <div style={{ display: 'flex', flexDirection: 'column', gap: 6 }}>
            <span style={{ fontSize: 10, fontWeight: 700, color: 'var(--text-tertiary)', textTransform: 'uppercase', letterSpacing: '0.05em' }}>Source Expression (DAX)</span>
            <div style={{
              fontFamily: 'monospace',
              fontSize: 11,
              padding: '10px 12px',
              borderRadius: 6,
              background: 'var(--bg-main)',
              border: '1px solid var(--border-main)',
              color: '#a5f3fc',
              minHeight: '48px',
              whiteSpace: 'pre-wrap',
              wordBreak: 'break-all',
            }}>
              {row.measure_expression || '—'}
            </div>
          </div>

          {/* Target SQL */}
          <div style={{ display: 'flex', flexDirection: 'column', gap: 6 }}>
            <span style={{ fontSize: 10, fontWeight: 700, color: 'var(--text-tertiary)', textTransform: 'uppercase', letterSpacing: '0.05em' }}>Snowflake Translation (SQL)</span>
            <div style={{
              fontFamily: 'monospace',
              fontSize: 11,
              padding: '10px 12px',
              borderRadius: 6,
              background: 'var(--bg-main)',
              border: '1px solid var(--border-main)',
              color: isFailed ? 'var(--text-tertiary)' : '#86efac',
              minHeight: '48px',
              whiteSpace: 'pre-wrap',
              wordBreak: 'break-all',
            }}>
              {isFailed ? '— Translation unavailable —' : (row.target_expression || '—')}
            </div>
          </div>
        </div>
      )}

      {/* ── Dependencies (Measures only) ── */}
      {isMeasure && Array.isArray(row.depends_on_measures) && row.depends_on_measures.length > 0 && (
        <div style={{
          display: 'flex',
          alignItems: 'center',
          gap: 6,
          fontSize: 11,
          color: 'var(--text-secondary)',
        }}>
          <GitMerge size={12} style={{ color: 'var(--text-tertiary)' }} />
          <span style={{ fontWeight: 600 }}>Depends on measures:</span>
          <div style={{ display: 'flex', gap: 6, flexWrap: 'wrap' }}>
            {row.depends_on_measures.map(dep => (
              <span key={dep} style={{
                fontFamily: 'monospace',
                fontSize: 10,
                padding: '2px 6px',
                borderRadius: 4,
                background: 'rgba(255,255,255,0.05)',
                border: '1px solid var(--border-main)',
                color: 'var(--text-primary)',
              }}>
                {dep}
              </span>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

// ─── Relationships section ────────────────────────────────────────────────────
function RelationshipsSection({ relationships }) {
  const [expanded, setExpanded] = useState(true);
  if (!relationships || relationships.length === 0) return null;

  return (
    <div style={{
      border: '1px solid var(--border-main)',
      borderRadius: 10,
      overflow: 'hidden',
      background: 'var(--bg-surface)',
    }}>
      {/* Header */}
      <button
        type="button"
        onClick={() => setExpanded(v => !v)}
        style={{
          width: '100%',
          display: 'flex',
          alignItems: 'center',
          gap: 8,
          padding: '10px 14px',
          background: 'var(--bg-surface-raised)',
          border: 'none',
          borderBottom: expanded ? '1px solid var(--border-main)' : 'none',
          cursor: 'pointer',
          textAlign: 'left',
        }}
      >
        <GitMerge size={14} style={{ color: 'var(--accent-blue)', flexShrink: 0 }} />
        <span style={{ fontSize: 12, fontWeight: 700, color: 'var(--text-primary)' }}>
          Detected Relationships
        </span>
        <span style={{
          fontSize: 11,
          fontWeight: 600,
          padding: '1px 7px',
          borderRadius: 999,
          background: 'var(--accent-blue)20',
          color: 'var(--accent-blue)',
        }}>
          {relationships.length}
        </span>
        <span style={{ marginLeft: 'auto', fontSize: 11, color: 'var(--text-tertiary)' }}>
          {expanded ? '▲ Hide' : '▼ Show'}
        </span>
      </button>

      {expanded && (
        <div>
          {relationships.map((rel, i) => (
            <div
              key={i}
              style={{
                display: 'grid',
                gridTemplateColumns: '1fr auto 1fr auto',
                gap: 8,
                padding: '10px 14px',
                borderBottom: i < relationships.length - 1 ? '1px solid var(--border-main)' : 'none',
                alignItems: 'center',
                fontSize: 12,
              }}
            >
              <div style={{ fontWeight: 600, color: 'var(--text-primary)', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                {rel.source}
              </div>
              <div style={{
                padding: '2px 8px',
                borderRadius: 4,
                background: 'var(--bg-surface-raised)',
                border: '1px solid var(--border-main)',
                fontSize: 10,
                fontWeight: 700,
                color: 'var(--text-secondary)',
                whiteSpace: 'nowrap',
              }}>
                {rel.joinType || rel.join_type || 'JOIN'}
              </div>
              <div style={{ fontWeight: 600, color: 'var(--text-primary)', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                {rel.target}
              </div>
              <div style={{
                fontSize: 10,
                fontWeight: 600,
                padding: '2px 7px',
                borderRadius: 999,
                background: 'var(--accent-blue)14',
                color: 'var(--accent-blue)',
                whiteSpace: 'nowrap',
              }}>
                {rel.confidence || 'auto'}
              </div>
              {rel.condition && (
                <div style={{
                  gridColumn: '1 / -1',
                  fontSize: 10,
                  fontFamily: 'monospace',
                  color: 'var(--text-tertiary)',
                  padding: '4px 8px',
                  borderRadius: 4,
                  background: 'var(--bg-main)',
                  overflow: 'hidden',
                  textOverflow: 'ellipsis',
                  whiteSpace: 'nowrap',
                }}>
                  {rel.condition}
                </div>
              )}
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

// ─── Collision resolution panel ───────────────────────────────────────────────
function CollisionPanel({ row, allRows, pendingRename, onRenameChange, onApply, applying }) {
  const { suggestions, peers } = suggestCollisionResolutions(row, allRows);
  const peerLabel = peers.length > 0
    ? peers.map(p => `${p.source_table_name ? p.source_table_name + '.' : ''}${p.source_field}`).join(', ')
    : 'another field';

  const inputValid = pendingRename.trim().length > 0 &&
    /^[A-Za-z_][A-Za-z0-9_]*$/.test(pendingRename.trim());

  return (
    <div style={{
      gridColumn: '1 / -1',
      margin: '0 0 4px',
      padding: '14px 16px',
      borderRadius: 8,
      background: 'rgba(251,191,36,0.06)',
      border: '1px solid rgba(251,191,36,0.30)',
      display: 'flex',
      flexDirection: 'column',
      gap: 12,
    }}>
      {/* ── Why is this a collision? ── */}
      {peers.length === 0 && row.validation_message && !/^name collision/i.test(row.validation_message) ? (
        // Clashes with no peer row of the same kind (a column renamed during
        // conversion, a metric hiding a column of its table): the backend
        // explains it.
        <div style={{ fontSize: 12, color: 'var(--text-secondary)' }}>
          <span style={{ fontWeight: 700, color: '#fbbf24' }}>Naming conflict</span>
          {' '}— {row.validation_message}
        </div>
      ) : (
        <div style={{ fontSize: 12, color: 'var(--text-secondary)' }}>
          <span style={{ fontWeight: 700, color: '#fbbf24' }}>Naming conflict</span>
          {' '}— <code style={{ fontSize: 11, background: 'rgba(0,0,0,0.25)', padding: '1px 5px', borderRadius: 3 }}>{row.target_field || row.source_field}</code>
          {' '}is also claimed by{' '}
          <span style={{ fontWeight: 700, color: 'var(--text-primary)' }}>{peerLabel}</span>.
          {' '}Choose a unique target name for this field:
        </div>
      )}

      {/* ── Suggestion chips ── */}
      <div style={{ display: 'flex', alignItems: 'center', gap: 8, flexWrap: 'wrap' }}>
        <span style={{ fontSize: 11, fontWeight: 600, color: 'var(--text-tertiary)', whiteSpace: 'nowrap' }}>Suggestions:</span>
        {suggestions.map((s) => (
          <button
            key={s.id}
            type="button"
            title={s.description}
            onClick={() => onRenameChange(s.label)}
            style={{
              display: 'inline-flex',
              alignItems: 'center',
              gap: 4,
              padding: '4px 10px',
              borderRadius: 6,
              border: pendingRename === s.label
                ? '1px solid #fbbf24'
                : '1px solid rgba(251,191,36,0.35)',
              background: pendingRename === s.label
                ? 'rgba(251,191,36,0.20)'
                : 'rgba(251,191,36,0.07)',
              color: pendingRename === s.label ? '#fbbf24' : 'var(--text-secondary)',
              fontSize: 11,
              fontWeight: 700,
              fontFamily: 'monospace',
              cursor: 'pointer',
              transition: 'all 0.15s',
            }}
          >
            {s.id === 'table_prefix' && <ChevronRight size={10} />}
            {s.label}
          </button>
        ))}
      </div>

      {/* ── Manual input + Apply ── */}
      <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
        <input
          type="text"
          value={pendingRename}
          onChange={e => onRenameChange(normalizeTypedName(e.target.value))}
          placeholder="Or type a custom name…"
          style={{
            flex: 1,
            padding: '6px 10px',
            borderRadius: 6,
            border: pendingRename && !inputValid
              ? '1px solid rgba(239,68,68,0.6)'
              : '1px solid var(--border-main)',
            background: 'var(--bg-main)',
            color: 'var(--text-primary)',
            fontSize: 12,
            fontFamily: 'monospace',
            outline: 'none',
          }}
        />
        <button
          type="button"
          disabled={!inputValid || applying}
          onClick={onApply}
          style={{
            display: 'inline-flex',
            alignItems: 'center',
            gap: 6,
            padding: '6px 14px',
            borderRadius: 6,
            border: '1px solid rgba(34,197,94,0.45)',
            background: inputValid && !applying ? 'rgba(34,197,94,0.12)' : 'rgba(34,197,94,0.04)',
            color: inputValid && !applying ? 'var(--color-success)' : 'var(--text-tertiary)',
            fontSize: 12,
            fontWeight: 700,
            cursor: inputValid && !applying ? 'pointer' : 'not-allowed',
            whiteSpace: 'nowrap',
            transition: 'all 0.15s',
          }}
        >
          {applying
            ? <span style={{ width: 11, height: 11, border: '2px solid currentColor', borderTopColor: 'transparent', borderRadius: '50%', display: 'inline-block', animation: 'spin 0.7s linear infinite' }} />
            : <CheckCircle size={12} />}
          {applying ? 'Applying…' : 'Apply rename'}
        </button>
      </div>

      {pendingRename && !inputValid && (
        <div style={{ fontSize: 11, color: 'var(--color-error)' }}>
          Use only letters, numbers, and underscores. Must start with a letter or underscore.
        </div>
      )}
      {pendingRename && inputValid && finalizeTypedName(pendingRename, 'snowflake', row.field_type || row.entity_kind) !== pendingRename.trim() && (
        <div style={{ fontSize: 11, color: 'var(--text-secondary)' }}>
          Will be deployed as <code>{finalizeTypedName(pendingRename, 'snowflake', row.field_type || row.entity_kind)}</code> (Snowflake identifier rules).
        </div>
      )}
      {pendingRename && inputValid && renameImpactNote(row, finalizeTypedName(pendingRename, 'snowflake', row.field_type || row.entity_kind)) && (
        <RenameImpactNote text={renameImpactNote(row, finalizeTypedName(pendingRename, 'snowflake', row.field_type || row.entity_kind))} />
      )}
    </div>
  );
}

// ─── Main component ───────────────────────────────────────────────────────────
const PANEL = {
  border: '1px solid var(--border-main)',
  borderRadius: 10,
  background: 'var(--bg-surface)',
  marginBottom: 12,
  overflow: 'hidden',
};
const PANEL_HEADER = {
  display: 'flex', alignItems: 'center', gap: 8, width: '100%',
  padding: '10px 14px', background: 'none', border: 'none', cursor: 'pointer',
  color: 'var(--text-primary)', fontSize: 13, fontWeight: 600, textAlign: 'left',
};
const CHANGE_TONE = {
  naming_rules: 'var(--text-tertiary)',
  renamed_by_you: 'var(--accent-blue)',
  clash_resolved: '#fbbf24',
  renamed_in_snowflake: '#f87171',
};

/**
 * NameChangesPanel — collapsed by default. Lists every field whose deployed
 * name differs from its source name (naming rules, resolved clashes, user
 * renames), why, and an Edit action that opens the normal field editor.
 */
function NameChangesPanel({ rows, onEdit, deployedNamesKnown = false }) {
  const [open, setOpen] = useState(false);
  const changes = useMemo(() => collectNameChanges(rows), [rows]);
  // Columns renamed in Snowflake vs the last deploy (COL_DATE -> DATE): when
  // the last deployed names are unknown, one project-level note instead.
  const legacyNote = useMemo(() => legacyNamingNote(rows, deployedNamesKnown), [rows, deployedNamesKnown]);
  const renamedInSnowflake = changes.filter(({ reason }) => reason.kind === 'renamed_in_snowflake').length;
  if (changes.length === 0 && !legacyNote) return null;
  return (
    <div style={PANEL}>
      {(legacyNote || renamedInSnowflake > 0) && (
        <div
          role="note"
          style={{
            display: 'flex', gap: 8, padding: '10px 14px', fontSize: 12, color: 'var(--text-secondary)',
            borderBottom: '1px solid var(--border-subtle)',
          }}
        >
          <Info size={14} style={{ flexShrink: 0, marginTop: 1, color: CHANGE_TONE.renamed_in_snowflake }} />
          <span>
            {renamedInSnowflake > 0
              ? `${renamedInSnowflake} column${renamedInSnowflake > 1 ? 's are' : ' is'} renamed in Snowflake by this sync `
                + '(see "Renamed in Snowflake" below). Queries, reports, dashboards or Cortex verified queries that use '
                + 'the old names must be updated.'
              : legacyNote}
          </span>
        </div>
      )}
      <button type="button" aria-expanded={open} onClick={() => setOpen((v) => !v)} style={PANEL_HEADER}>
        <ChevronRight size={14} style={{ transform: open ? 'rotate(90deg)' : 'none', transition: 'transform 0.15s' }} />
        Name changes ({changes.length})
        <span style={{ fontWeight: 400, color: 'var(--text-tertiary)', fontSize: 12 }}>
          — fields that will appear under a different name in Snowflake. Any of them can be edited.
        </span>
      </button>
      {open && (
        <div style={{ borderTop: '1px solid var(--border-subtle)', maxHeight: 320, overflowY: 'auto' }}>
          {changes.map(({ row, reason }) => (
            <div
              key={row.id}
              style={{
                display: 'grid', gridTemplateColumns: 'minmax(0, 1.2fr) minmax(0, 1fr) minmax(0, 1.6fr) auto',
                gap: 12, alignItems: 'center', padding: '8px 14px', fontSize: 12,
                borderBottom: '1px solid var(--border-subtle)',
              }}
            >
              <span style={{ overflowWrap: 'anywhere', color: 'var(--text-secondary)' }}>
                {row.source_table_name ? `${row.source_table_name}.` : ''}{row.renamed_from || row.source_field}
              </span>
              <code style={{ overflowWrap: 'anywhere', color: 'var(--text-primary)' }}>{row.target_field}</code>
              <span style={{ overflowWrap: 'anywhere', color: 'var(--text-tertiary)' }} title={reason.detail}>
                <span style={{ fontWeight: 600, color: CHANGE_TONE[reason.kind] }}>{reason.label}</span>
                {' — '}{reason.detail}
              </span>
              {onEdit && (
                <button
                  type="button"
                  onClick={() => onEdit(row.id)}
                  style={{
                    display: 'inline-flex', alignItems: 'center', gap: 4, padding: '3px 9px', borderRadius: 6,
                    border: '1px solid var(--border-main)', background: 'var(--bg-surface-raised)',
                    color: 'var(--text-secondary)', fontSize: 11, fontWeight: 600, cursor: 'pointer',
                  }}
                >
                  <Edit2 size={11} /> Edit
                </button>
              )}
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

/** One line for the cross-table shared names (never blocking). */
function SharedNamesNote({ rows }) {
  const names = useMemo(() => {
    const seen = new Map();
    (rows || []).forEach((row) => {
      if (Array.isArray(row.shared_name_tables) && row.shared_name_tables.length > 1) {
        seen.set(String(row.target_field || '').toUpperCase(), row.shared_name_tables);
      }
    });
    return [...seen.entries()];
  }, [rows]);
  if (names.length === 0) return null;
  const sample = names.slice(0, 3).map(([name, tables]) => `${name} (${tables.join(', ')})`).join('; ');
  return (
    <div style={{ ...PANEL, padding: '10px 14px', fontSize: 12, color: 'var(--text-secondary)', display: 'flex', gap: 8 }}>
      <Info size={14} style={{ flexShrink: 0, marginTop: 1, color: 'var(--text-tertiary)' }} />
      <span>
        {names.length} column name{names.length > 1 ? 's are' : ' is'} used in more than one table: {sample}
        {names.length > 3 ? ` and ${names.length - 3} more` : ''}. They deploy fine as TABLE.NAME; rename one
        (Edit) only if people query the view by the bare name.
      </span>
    </div>
  );
}

export default function DryRunMappingTable({
  mappings = [],
  onEdit,
  onSynonymUpdate,
  projectId = 'preview',
  modelName = '',
  onBulkResolved,     // (resolvedMap: Record<rowId, suggestedTarget>) => void
  summary,
  relationships = [],
  schemaConflicts = [],       // DIMENSION_MISSING conflicts from backend
  compatibilityScore = null,  // 0–100 float from backend
  onReSync,                   // () => void — trigger a re-sync after auto-add
  droppedEntities = [],       // DropRecord[] — entities excluded from deployed DDL (see DropLedger)
  deployedNamesKnown = false, // backend read the last deploy's names (rows carry deployed_name_change)
  unresolvedReportFieldReferences = [], // [{field, field_type, table, occurrences}] — report queries a name absent from the current schema (see LocalPBIXConnector._detect_unresolved_field_references); table-scoped only, never auto-attached to a specific column
}) {
  // ── Dev-only guardrail: catch un-normalized rows reaching this component ────
  // A raw /dry-run API row has `source_name`/`target_name` keys; a normalized
  // row (utils/normalizeRows.js) renames them to source_field/target_field.
  // Seeing the raw shape means a caller skipped normalizeRows() and every row
  // would silently render placeholders. Dev builds only.
  if (import.meta.env?.DEV && mappings.length > 0) {
    const rawShaped = mappings.find((row) => row && ('source_name' in row || 'target_name' in row) && !('source_field' in row));
    if (rawShaped) {
      console.error(
        '[DryRunMappingTable] Received un-normalized row(s) -- pass `mappings` through ' +
        'utils/normalizeRows.js before rendering this component. Offending row:',
        rawShaped,
      );
    }
  }

  // ── Tier 1 (field type, single-select) / Tier 2 (status, multi-select) ──────
  const [activeFieldType, setActiveFieldType] = useState('all');
  const [activeStatuses, setActiveStatuses] = useState(() => new Set());
  const [search, setSearch] = useState('');
  const [useRegex, setUseRegex] = useState(false);
  const [bulkResolving, setBulkResolving] = useState(false);
  const [bulkToast, setBulkToast] = useState(null); // { type: 'success'|'error', msg }
  const [synonymModal, setSynonymModal] = useState(null);
  const [schemaFixing, setSchemaFixing] = useState({}); // { conflictId: 'pending'|'done'|'error' }
  const [schemaToast, setSchemaToast] = useState(null);
  // ── Per-collision inline fix panel ─────────────────────────────────────────
  const [expandedCollision, setExpandedCollision] = useState(null); // rowId
  const [pendingRenames, setPendingRenames]       = useState({});   // { rowId: newName }
  const [applyingRename, setApplyingRename]       = useState(null); // rowId

  // ── Tier 1 groups: whatever field-type values are actually in the data ─────
  const fieldGroups = useMemo(() => groupRowsByFieldType(mappings), [mappings]);
  // Kept for the two places that still want a raw measure/column split (badges, search haystack).
  const { columns, measures } = useMemo(() => {
    const cols = [];
    const meas = [];
    mappings.forEach((row) => {
      const kind = String(row?.field_type || row?.entity_kind || '').toLowerCase();
      if (kind === 'measure' || kind === 'metric') meas.push(row); else cols.push(row);
    });
    return { columns: cols, measures: meas };
  }, [mappings]);

  // ── Unresolved report-layer field references, grouped by table ─────────────
  // Backend already resolves each stale name to at most one current
  // column/measure by name similarity (LocalPBIXConnector
  // ._best_matching_field) — entries with no confident resolution
  // (`resolved_target_field` is null, or ambiguous) are dropped here too,
  // so nothing ever gets broadcast across multiple rows. Columns are keyed
  // by "table::resolvedField" (a name can repeat across tables); measures
  // have no table to scope by, so they're keyed by "measure::resolvedField"
  // (measure names are globally unique). Displayed through the same
  // synonyms/synonym_sources mechanism every other source already uses
  // (see `enrichRowWithUnresolvedRefs` below) -- no bespoke UI, just
  // another entry under "Show all synonym sources," same as an
  // auto-generated or TMSL-authored one.
  const unresolvedNamesByRowKey = useMemo(() => {
    const byKey = {};
    unresolvedReportFieldReferences.forEach((ref) => {
      if (!ref?.resolved_target_field) return;
      const isColumn = ref.field_type === 'column';
      if (isColumn && !ref.table) return;
      const rowKey = isColumn
        ? `${ref.table}::${ref.resolved_target_field}`
        : `measure::${ref.resolved_target_field}`;
      (byKey[rowKey] ||= []).push(ref.field);
    });
    return byKey;
  }, [unresolvedReportFieldReferences]);

  const rowSuggestionKey = useCallback((row) => (
    ['measure', 'metric'].includes(String(row.field_type || row.entity_kind || '').toLowerCase())
      ? `measure::${row.source_field}`
      : `${row.source_table_name}::${row.source_field}`
  ), []);

  // Merge in resolved renamed-field names as ordinary synonyms, tagged with
  // their own source so they display (behind "Show all synonym sources,"
  // same as auto-generated/TMSL-authored) without any new UI.
  const enrichRowWithUnresolvedRefs = useCallback((row) => {
    const staleNames = unresolvedNamesByRowKey[rowSuggestionKey(row)];
    if (!staleNames || staleNames.length === 0) return row;
    const existingSynonyms = Array.isArray(row.synonyms) ? row.synonyms : [];
    const newNames = staleNames.filter((n) => !existingSynonyms.includes(n));
    if (newNames.length === 0) return row;
    return {
      ...row,
      synonyms: [...existingSynonyms, ...newNames],
      synonym_sources: {
        ...(row.synonym_sources || {}),
        ...Object.fromEntries(newNames.map((n) => [n, 'renamed_field_reference'])),
      },
    };
  }, [unresolvedNamesByRowKey, rowSuggestionKey]);

  // ── Reset both filter tiers whenever a *new* dry run lands (not on row edits —
  //    edits only touch `mappings`/`detectedMappings`, never the `summary` object).
  //    Adjusted during render (React's documented pattern for "reset state when a
  //    prop changes") rather than in an effect, to avoid an extra render pass. ──
  const [lastSummary, setLastSummary] = useState(summary);
  if (summary !== lastSummary) {
    setLastSummary(summary);
    setActiveFieldType('all');
    setActiveStatuses(new Set());
  }

  // ── Rows in scope for Tier 2 facet computation (the selected Tier 1 group) ──
  const scopedRows = useMemo(() => {
    const group = fieldGroups.find((g) => g.key === activeFieldType);
    return group ? group.rows : mappings;
  }, [fieldGroups, activeFieldType, mappings]);

  // ── Tier 2 options: a small, fixed, non-overlapping set (Collisions,
  //    Expression Converted, Expression Not Converted, Needs Attention) from
  //    buildFilterOptions, plus Predicted Failure -- kept as its own chip
  //    (not folded into buildFilterOptions) because it's keyed off
  //    static_risk_tier, an orthogonal signal from a different computation
  //    (see getStaticRiskBadge/riskLabels.js) than row.status, so its
  //    row-set can never duplicate another chip's -- plus the always-present
  //    schema-issues toggle (structurally not a row status either) ──
  const tier2Options = useMemo(() => {
    const options = buildFilterOptions(scopedRows);
    const predictedFailureCount = scopedRows.filter((r) => r?.static_risk_tier === 'predicted_failure').length;
    if (predictedFailureCount > 0) {
      options.push({ key: 'predicted_failure', label: 'Predicted Failure', count: predictedFailureCount, kind: 'risk' });
    }
    if (schemaConflicts.length > 0) {
      options.push({ key: 'schema_issues', label: 'Schema Issues', count: schemaConflicts.length, kind: 'schema' });
    }
    return options;
  }, [scopedRows, schemaConflicts.length]);

  const toggleStatus = useCallback((key) => {
    setActiveStatuses((prev) => {
      const next = new Set(prev);
      if (next.has(key)) next.delete(key); else next.add(key);
      return next;
    });
  }, []);

  // ── Derived counts (over all mappings + schema issues) ──────────────────────
  const counts = useMemo(() => {
    const c = { all: mappings.length, auto: 0, manual: 0, unmapped: 0, collision: 0, schema_issues: schemaConflicts.length };
    mappings.forEach((row) => {
      const s = String(row?.status || '').toLowerCase();
      if (c[s] !== undefined) c[s] += 1;
    });
    return c;
  }, [mappings, schemaConflicts]);

  // ── Auto-add handler ─────────────────────────────────────────────────────────
  const handleAutoAdd = useCallback(async (conflict) => {
    const cid = conflict.conflict_id;
    setSchemaFixing(prev => ({ ...prev, [cid]: 'pending' }));
    setSchemaToast(null);
    try {
      await api.addMissingDimensionColumn(
        projectId,
        conflict.model_name,
        conflict.column_name,
        'VARCHAR',
      );
      setSchemaFixing(prev => ({ ...prev, [cid]: 'done' }));
      setSchemaToast({ type: 'success', msg: `Column '${conflict.column_name}' added. Re-running sync…` });
      setTimeout(() => {
        setSchemaToast(null);
        onReSync?.();
      }, 1500);
    } catch (err) {
      setSchemaFixing(prev => ({ ...prev, [cid]: 'error' }));
      setSchemaToast({ type: 'error', msg: `Failed: ${err.message}` });
      setTimeout(() => setSchemaToast(null), 5000);
    }
  }, [projectId, onReSync]);

  // ── Per-collision apply rename ───────────────────────────────────────────────
  const applyRename = useCallback(async (rowId) => {
    // Store the name exactly as it will deploy (the emitter's to_alias
    // rules), so no later sanitization renames what the user picked.
    const renamedRow = mappings.find((r) => r.id === rowId);
    const newName = finalizeTypedName(
      (pendingRenames[rowId] || '').trim(), 'snowflake', renamedRow?.field_type || renamedRow?.entity_kind,
    );
    if (!newName) return;
    setApplyingRename(rowId);
    try {
      await onEdit?.(rowId, {
        target_field: newName,
        target_name:  newName,
        status:       'manual',
        collision_detected: false,
      });
      setExpandedCollision(null);
      setPendingRenames(prev => { const n = { ...prev }; delete n[rowId]; return n; });
    } finally {
      setApplyingRename(null);
    }
  }, [pendingRenames, onEdit, mappings]);

  // ── Bulk resolve handler — uses table-prefix names, not hashes ──────────────
  const handleBulkResolve = useCallback(() => {
    const collisionRows = mappings.filter(
      r => String(r?.status || '').toLowerCase() === 'collision'
    );
    if (!collisionRows.length) return;

    setBulkResolving(true);
    setBulkToast(null);

    try {
      const resolvedMap = resolveCollisionsForRows(mappings);
      onBulkResolved?.(resolvedMap);
      setBulkToast({
        type: 'success',
        msg: `${collisionRows.length} collision${collisionRows.length !== 1 ? 's' : ''} resolved — unique names applied. Review each field to confirm.`,
      });
    } catch (err) {
      setBulkToast({ type: 'error', msg: `Resolve failed: ${err.message}` });
    } finally {
      setBulkResolving(false);
      setTimeout(() => setBulkToast(null), 6000);
    }
  }, [mappings, onBulkResolved]);

  const openSynonymModal = useCallback(async (row) => {
    const tableName = row.source_table_name || row.measure_source_tables?.[0] || row.parent_table || '';
    const modalData = {
      rowId: row.id,
      projectId: row.project_id || projectId || 'preview',
      modelName: row.model_name || row.modelName || modelName || 'default',
      tableName,
      columnName: row.source_field,
      currentSynonyms: row.synonym_overrides || row.synonymOverrides || [],
    };
    setSynonymModal(modalData);
    try {
      const response = await api.getSynonymOverride(modalData);
      setSynonymModal((current) => current?.rowId === row.id
        ? { ...current, currentSynonyms: response?.synonyms || [] }
        : current);
    } catch {
      // Missing override table or row should not block the edit dialog.
    }
  }, [projectId, modelName]);

  const handleSynonymSave = useCallback((synonyms) => {
    if (!synonymModal?.rowId) return;
    onSynonymUpdate?.(synonymModal.rowId, synonyms);
  }, [synonymModal, onSynonymUpdate]);

  // ── Filtered rows ───────────────────────────────────────────────────────────
  const matchesTier2 = useCallback((row) => {
    if (activeStatuses.size === 0) return true;
    if (activeStatuses.has('collision') && rowIsCollision(row)) return true;
    const conversionKey = rowConversionOutcome(row);
    if (conversionKey && activeStatuses.has(conversionKey)) return true;
    if (activeStatuses.has('needs_attention') && rowNeedsAttention(row)) return true;
    if (activeStatuses.has('predicted_failure') && row?.static_risk_tier === 'predicted_failure') return true;
    // 'schema_issues' never matches a row — it has no per-row status; selecting it
    // alongside real statuses still shows those via OR, selecting it alone shows none
    // (the always-visible schema-conflicts panel below carries that information instead).
    return false;
  }, [activeStatuses]);

  const filterRow = useCallback((row) => {
    if (activeFieldType !== 'all' && normalizeFieldTypeKey(row) !== activeFieldType) return false;
    if (!matchesTier2(row)) return false;
    if (search.trim()) {
      const haystack = [
        row.source_field,
        row.target_field,
        row.source_type,
        row.target_type,
        row.source_table_name,
        row.status,
        row.measure_expression,
        ...(row.measure_source_tables || []),
      ].filter(Boolean).join(' ');
      if (!matchesSmartQuery(haystack, search, useRegex)) return false;
    }
    return true;
  }, [activeFieldType, matchesTier2, search, useRegex]);

  // ── Visible field-type sections: the selected Tier 1 group, or all of them ──
  const visibleGroups = useMemo(() => {
    const groups = fieldGroups.filter((g) => g.key !== 'all'
      && (activeFieldType === 'all' || activeFieldType === g.key));
    return groups.map((g) => ({ ...g, filteredRows: g.rows.filter(filterRow) }));
  }, [fieldGroups, activeFieldType, filterRow]);

  // ── Summary bar values ──────────────────────────────────────────────────────
  const totalFields  = summary?.total_fields  ?? mappings.length;
  const autoMapped   = summary?.auto_mapped   ?? counts.auto;
  const unmappedCnt  = summary?.unmapped      ?? counts.unmapped;
  const collisionCnt = summary?.collisions    ?? counts.collision;
  const score = typeof compatibilityScore === 'number' ? compatibilityScore : null;
  const scoreColor = score === null ? 'var(--text-tertiary)'
    : score >= 90 ? 'var(--color-success)'
    : score >= 70 ? '#f59e0b'
    : '#ef4444';

  // Build a plain-English breakdown to show next to the score
  const totalIssues = counts.collision + counts.unmapped + schemaConflicts.length;
  const scoreLabel = score === null ? null
    : score === 100 ? 'All checks passed'
    : totalIssues === 0 ? (score >= 90 ? 'Minor issues detected' : 'Issues detected')
    : `${totalIssues} issue${totalIssues !== 1 ? 's' : ''} found — ${
        counts.collision > 0 ? `${counts.collision} collision${counts.collision !== 1 ? 's' : ''}` : ''
      }${counts.collision > 0 && (counts.unmapped > 0 || schemaConflicts.length > 0) ? ', ' : ''}${
        counts.unmapped > 0 ? `${counts.unmapped} unmapped` : ''
      }${counts.unmapped > 0 && schemaConflicts.length > 0 ? ', ' : ''}${
        schemaConflicts.length > 0 ? `${schemaConflicts.length} schema gap${schemaConflicts.length !== 1 ? 's' : ''}` : ''
      }`;

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>

      {/* ── Compatibility score bar ─────────────────────────────────────────── */}
      {score !== null && (
        <div style={{
          display: 'flex',
          alignItems: 'center',
          gap: 10,
          padding: '10px 14px',
          borderRadius: 8,
          background: 'var(--bg-surface)',
          border: `1px solid ${scoreColor}40`,
        }}>
          <span style={{ fontSize: 12, fontWeight: 700, color: 'var(--text-secondary)', whiteSpace: 'nowrap' }}>
            Sync Compatibility
          </span>
          <div style={{ flex: 1, height: 8, borderRadius: 4, background: 'var(--bg-main)', overflow: 'hidden' }}>
            <div style={{
              height: '100%',
              width: `${score}%`,
              borderRadius: 4,
              background: scoreColor,
              transition: 'width 0.6s ease',
            }} />
          </div>
          <span style={{ fontSize: 13, fontWeight: 800, color: scoreColor, minWidth: 46, textAlign: 'right' }}>
            {score}%
          </span>
          {scoreLabel && (
            <span style={{ fontSize: 11, color: score === 100 ? 'var(--color-success)' : 'var(--text-tertiary)' }}>
              {scoreLabel}
            </span>
          )}
        </div>
      )}

      {/* ── Summary bar ──────────────────────────────────────────────────────── */}
      <div style={{
        display: 'flex',
        alignItems: 'center',
        gap: 6,
        padding: '8px 12px',
        borderRadius: 8,
        background: 'var(--bg-surface)',
        border: '1px solid var(--border-main)',
        fontSize: 12,
        color: 'var(--text-secondary)',
        flexWrap: 'wrap',
      }}>
        <span style={{ fontWeight: 700, color: 'var(--text-primary)' }}>
          {totalFields} field{totalFields !== 1 ? 's' : ''}
        </span>
        <span style={{ color: 'var(--text-tertiary)' }}>—</span>
        <span style={{ color: 'var(--text-tertiary)', fontWeight: 600 }}>
          {columns.length} column{columns.length !== 1 ? 's' : ''}
        </span>
        <span style={{ color: 'var(--text-tertiary)' }}>·</span>
        <span style={{ color: '#7dd3fc', fontWeight: 600 }}>
          {measures.length} measure{measures.length !== 1 ? 's' : ''}
        </span>
        {collisionCnt > 0 && (
          <>
            <span style={{ color: 'var(--text-tertiary)' }}>·</span>
            <span style={{ color: 'var(--color-error)', fontWeight: 600 }}>
              {collisionCnt} collision{collisionCnt !== 1 ? 's' : ''}
            </span>
          </>
        )}
        {schemaConflicts.length > 0 && (
          <>
            <span style={{ color: 'var(--text-tertiary)' }}>·</span>
            <span style={{ color: '#f59e0b', fontWeight: 600 }}>
              {schemaConflicts.length} schema issue{schemaConflicts.length !== 1 ? 's' : ''}
            </span>
          </>
        )}
      </div>

      <div style={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', gap: 8, flexWrap: 'wrap' }}>
        <div style={{ display: 'flex', flexDirection: 'column', gap: 6 }}>
          {/* Tier 1 — field type (single-select), built from whatever field types are in the data */}
          <div className="filter-tabs" style={{ marginBottom: 0 }}>
            {fieldGroups.map((group) => {
              const active = activeFieldType === group.key;
              const count = group.rows.length;
              return (
                <button
                  key={group.key}
                  type="button"
                  className={`filter-tab${active ? ' active' : ''}`}
                  onClick={() => setActiveFieldType(group.key)}
                >
                  {group.label} ({count})
                </button>
              );
            })}
          </div>

          {/* Tier 2 — status (multi-select, OR), scoped to the selected Tier 1 group.
              A small fixed set (Collisions, Expression Converted, Expression Not
              Converted, Needs Attention, Schema Issues) — see buildFilterOptions —
              each option's row-set is mutually exclusive with the others. */}
          <div className="filter-checks">
            {tier2Options.map((option) => {
              const checked = activeStatuses.has(option.key);
              return (
                <button
                  key={option.key}
                  type="button"
                  className={`filter-check${checked ? ' active' : ''}${option.key === 'collision' ? ' collision-check' : ''}${option.key === 'needs_attention' ? ' attention-check' : ''}`}
                  onClick={() => toggleStatus(option.key)}
                >
                  {option.label} ({option.count})
                </button>
              );
            })}
          </div>
        </div>

        <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
          {/* ── Resolve All button — only shown when collisions exist ─────── */}
          {counts.collision > 0 && (
            <button
              id="bulk-resolve-btn"
              type="button"
              disabled={bulkResolving}
              onClick={handleBulkResolve}
              style={{
                display: 'inline-flex',
                alignItems: 'center',
                gap: 6,
                padding: '6px 14px',
                borderRadius: 7,
                border: '1px solid rgba(251,191,36,0.55)',
                background: bulkResolving
                  ? 'rgba(251,191,36,0.06)'
                  : 'rgba(251,191,36,0.12)',
                color: '#fbbf24',
                fontSize: 12,
                fontWeight: 700,
                cursor: bulkResolving ? 'not-allowed' : 'pointer',
                whiteSpace: 'nowrap',
                transition: 'background 0.15s, opacity 0.15s',
                opacity: bulkResolving ? 0.7 : 1,
              }}
            >
              {bulkResolving
                ? <>
                    <span style={{
                      width: 11, height: 11, border: '2px solid #fbbf24',
                      borderTopColor: 'transparent', borderRadius: '50%',
                      display: 'inline-block',
                      animation: 'spin 0.7s linear infinite',
                    }} />
                    Resolving…
                  </>
                : <><Zap size={12} /> Resolve All ({counts.collision})</>}
            </button>
          )}

          <div style={{ width: 300 }}>
            <SmartSearchBar
              value={search}
              onChange={setSearch}
              useRegex={useRegex}
              onToggleRegex={setUseRegex}
              placeholder="Search fields..."
            />
          </div>
        </div>
      </div>

      {/* ── Bulk-resolve toast ───────────────────────────────────────────────── */}
      {bulkToast && (
        <div style={{
          display: 'flex',
          alignItems: 'center',
          gap: 8,
          padding: '9px 14px',
          borderRadius: 8,
          border: bulkToast.type === 'success'
            ? '1px solid rgba(34,197,94,0.4)'
            : '1px solid rgba(239,68,68,0.4)',
          background: bulkToast.type === 'success'
            ? 'rgba(34,197,94,0.09)'
            : 'rgba(239,68,68,0.09)',
          color: bulkToast.type === 'success' ? 'var(--color-success)' : 'var(--color-error)',
          fontSize: 12,
          fontWeight: 600,
        }}>
          {bulkToast.type === 'success' && <CheckCircle size={13} />}
          {bulkToast.msg}
        </div>
      )}

      {/* ── Dropped fields panel (placed under model/filters, above columns & metrics) ── */}
      {Array.isArray(droppedEntities) && droppedEntities.length > 0 && (
        <DroppedFieldsPanel entries={droppedEntities} />
      )}

      {/* ── Every name that will deploy differently from the source (even
          when nothing needed fixing), with the reason and an Edit action. ── */}
      <NameChangesPanel rows={mappings} onEdit={onEdit} deployedNamesKnown={deployedNamesKnown} />

      {/* ── Same column name in several tables (info only). ── */}
      <SharedNamesNote rows={mappings} />

      {/* ── Columns table ────────────────────────────────────────────────────── */}
      {mappings.length === 0 ? (
        <div style={{
          padding: '48px 24px',
          textAlign: 'center',
          color: 'var(--text-tertiary)',
          fontSize: 13,
          border: '1px solid var(--border-main)',
          borderRadius: 10,
          background: 'var(--bg-surface)',
        }}>
          <div style={{ fontSize: 15, fontWeight: 700, color: 'var(--text-primary)', marginBottom: 6 }}>
            No fields found for the selected models
          </div>
          <div>Go back to Step 3 and select different models, then run the dry run again.</div>
        </div>
      ) : (
        <>
          {/* One section per field-type group present in the data (Tier 1 = 'all' shows every
              group; a specific selection isolates just that one). 'measure' keeps its existing
              cyan "fx" branding; any other/unforeseen group key gets the neutral default look. */}
          {visibleGroups.map((group) => {
            const isMeasureGroup = group.key === 'measure';
            return (
              <div
                key={group.key}
                style={{
                  border: isMeasureGroup ? '1px solid rgba(56, 189, 248, 0.3)' : '1px solid var(--border-main)',
                  borderRadius: 10,
                  overflow: 'hidden',
                  background: 'var(--bg-surface)',
                  marginBottom: 16,
                }}
              >
                <div style={{
                  padding: '10px 14px',
                  background: isMeasureGroup ? 'rgba(56, 189, 248, 0.05)' : 'rgba(255, 255, 255, 0.03)',
                  borderBottom: isMeasureGroup ? '1px solid rgba(56, 189, 248, 0.2)' : '1px solid var(--border-main)',
                  fontSize: 11,
                  fontWeight: 800,
                  color: isMeasureGroup ? '#7dd3fc' : 'var(--text-primary)',
                  textTransform: 'uppercase',
                  letterSpacing: '0.08em',
                  display: 'flex',
                  alignItems: 'center',
                  gap: 8,
                }}>
                  {isMeasureGroup
                    ? <div style={{ fontSize: 14, color: '#7dd3fc' }}>fx</div>
                    : <div style={{ width: 8, height: 8, borderRadius: 2, background: 'var(--accent-blue)' }} />}
                  {group.label} ({group.filteredRows.length})
                </div>
                <TableHeader />
                {group.filteredRows.length === 0 ? (
                  <div style={{ padding: '24px 0', textAlign: 'center', color: 'var(--text-tertiary)', fontSize: 13 }}>
                    No {group.label.toLowerCase()} match the current filter or search.
                  </div>
                ) : (
                  group.filteredRows.map(row => (
                    <MappingRow
                      key={row.id}
                      row={enrichRowWithUnresolvedRefs(row)}
                      onEdit={onEdit}
                      onSynonymEdit={openSynonymModal}
                      allRows={mappings}
                      expandedCollision={expandedCollision}
                      setExpandedCollision={setExpandedCollision}
                      pendingRenames={pendingRenames}
                      setPendingRenames={setPendingRenames}
                      applyingRename={applyingRename}
                      onApplyRename={applyRename}
                    />
                  ))
                )}
              </div>
            );
          })}
        </>
      )}

      {/* ── Schema Issues panel (DIMENSION_MISSING conflicts) ───────────────── */}
      {activeStatuses.has('schema_issues') && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
          {schemaToast && (
            <div style={{
              padding: '8px 12px', borderRadius: 6, fontSize: 12, fontWeight: 600,
              background: schemaToast.type === 'success' ? 'rgba(34,197,94,0.12)' : 'rgba(239,68,68,0.12)',
              border: `1px solid ${schemaToast.type === 'success' ? 'rgba(34,197,94,0.4)' : 'rgba(239,68,68,0.4)'}`,
              color: schemaToast.type === 'success' ? '#4ade80' : '#f87171',
            }}>
              {schemaToast.msg}
            </div>
          )}
          {schemaConflicts.length === 0 ? (
            <div style={{ padding: '24px', textAlign: 'center', color: 'var(--text-tertiary)', fontSize: 13 }}>
              ✓ No schema issues detected
            </div>
          ) : schemaConflicts.map((conflict) => {
            const fixState = schemaFixing[conflict.conflict_id];
            const isDone = fixState === 'done';
            const isPending = fixState === 'pending';
            return (
              <div key={conflict.conflict_id} style={{
                padding: '14px 16px',
                borderRadius: 8,
                background: 'var(--bg-surface)',
                border: `1px solid ${isDone ? 'rgba(34,197,94,0.4)' : 'rgba(245,158,11,0.35)'}`,
                opacity: isDone ? 0.6 : 1,
                transition: 'all 0.2s',
              }}>
                <div style={{ display: 'flex', alignItems: 'flex-start', gap: 10 }}>
                  <AlertTriangle size={15} style={{ color: '#f59e0b', flexShrink: 0, marginTop: 2 }} />
                  <div style={{ flex: 1, minWidth: 0 }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 4 }}>
                      <span style={{ fontFamily: 'monospace', fontSize: 12, fontWeight: 700, color: 'var(--text-primary)' }}>
                        {conflict.column_name}
                      </span>
                      <span style={{ fontSize: 10, padding: '1px 6px', borderRadius: 4, background: 'rgba(245,158,11,0.15)', color: '#f59e0b', fontWeight: 700, border: '1px solid rgba(245,158,11,0.3)' }}>
                        DIMENSION MISSING
                      </span>
                      {conflict.model_name && (
                        <span style={{ fontSize: 11, color: 'var(--text-tertiary)' }}>
                          in <span style={{ fontFamily: 'monospace' }}>{conflict.model_name}</span>
                        </span>
                      )}
                    </div>
                    <p style={{ margin: 0, fontSize: 12, color: 'var(--text-secondary)', lineHeight: 1.5 }}>
                      {conflict.description}
                    </p>
                    {/* Resolution options */}
                    <div style={{ display: 'flex', gap: 8, marginTop: 10, flexWrap: 'wrap' }}>
                      {/* Option A: Skip */}
                      <div style={{
                        padding: '8px 12px',
                        borderRadius: 6,
                        border: '1px solid var(--border-main)',
                        background: 'var(--bg-main)',
                        flex: '1 1 200px',
                        minWidth: 180,
                      }}>
                        <div style={{ display: 'flex', alignItems: 'center', gap: 6, marginBottom: 3 }}>
                          <SkipForward size={12} style={{ color: 'var(--text-tertiary)' }} />
                          <span style={{ fontSize: 11, fontWeight: 700, color: 'var(--text-secondary)' }}>
                            Option A — Skip
                          </span>
                        </div>
                        <p style={{ margin: 0, fontSize: 11, color: 'var(--text-tertiary)' }}>
                          Exclude from Snowflake DIMENSIONS. Column absent from semantic queries.
                        </p>
                        <div style={{ marginTop: 6, fontSize: 11, color: 'var(--text-tertiary)', fontStyle: 'italic' }}>
                          Default behaviour (no action needed)
                        </div>
                      </div>
                      {/* Option B: Auto-add */}
                      <div style={{
                        padding: '8px 12px',
                        borderRadius: 6,
                        border: isDone ? '1px solid rgba(34,197,94,0.45)' : '1px solid rgba(56,189,248,0.35)',
                        background: isDone ? 'rgba(34,197,94,0.08)' : 'rgba(56,189,248,0.08)',
                        flex: '1 1 200px',
                        minWidth: 180,
                      }}>
                        <div style={{ display: 'flex', alignItems: 'center', gap: 6, marginBottom: 3 }}>
                          <PlusCircle size={12} style={{ color: isDone ? '#4ade80' : '#7dd3fc' }} />
                          <span style={{ fontSize: 11, fontWeight: 700, color: isDone ? '#4ade80' : '#7dd3fc' }}>
                            Option B — Auto-add to Snowflake
                          </span>
                        </div>
                        <p style={{ margin: 0, fontSize: 11, color: 'var(--text-secondary)' }}>
                          Run <code style={{ fontSize: 10 }}>ALTER TABLE ADD COLUMN</code> on the physical table, then re-sync to include in DIMENSIONS.
                        </p>
                        <button
                          type="button"
                          disabled={isPending || isDone}
                          onClick={() => handleAutoAdd(conflict)}
                          style={{
                            marginTop: 8,
                            display: 'inline-flex',
                            alignItems: 'center',
                            gap: 5,
                            padding: '5px 12px',
                            borderRadius: 5,
                            border: 'none',
                            background: isDone ? 'rgba(34,197,94,0.2)' : isPending ? 'rgba(56,189,248,0.1)' : 'rgba(56,189,248,0.2)',
                            color: isDone ? '#4ade80' : '#7dd3fc',
                            fontSize: 11,
                            fontWeight: 700,
                            cursor: (isPending || isDone) ? 'not-allowed' : 'pointer',
                            opacity: (isPending || isDone) ? 0.8 : 1,
                            transition: 'all 0.15s',
                          }}
                        >
                          {isPending ? (
                            <>
                              <span style={{ width: 10, height: 10, border: '2px solid #7dd3fc', borderTopColor: 'transparent', borderRadius: '50%', display: 'inline-block', animation: 'spin 0.7s linear infinite' }} />
                              Adding…
                            </>
                          ) : isDone ? (
                            <>✓ Added — re-syncing</>
                          ) : (
                            <><PlusCircle size={11} /> Add Column &amp; Re-sync</>
                          )}
                        </button>
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      )}

      {/* ── Relationships section ─────────────────────────────────────────────── */}
      {!activeStatuses.has('schema_issues') && (
        <RelationshipsSection relationships={relationships} />
      )}
      <SynonymEditModal
        open={Boolean(synonymModal)}
        onClose={() => setSynonymModal(null)}
        projectId={synonymModal?.projectId || projectId}
        modelName={synonymModal?.modelName || modelName || 'default'}
        tableName={synonymModal?.tableName || ''}
        columnName={synonymModal?.columnName || ''}
        currentSynonyms={synonymModal?.currentSynonyms || []}
        onSave={handleSynonymSave}
      />
    </div>
  );
}

import { AlertTriangle, X, ChevronDown, ChevronUp } from 'lucide-react';

export default function ErrorPanel({ errors, isOpen, onToggle }) {
    if (errors.length === 0) return null;

    return (
        <div
            className="theme-transition shrink-0 overflow-hidden"
            style={{
                background: 'var(--bg-surface-raised)',
                borderTop: '2px solid var(--color-danger)',
                height: isOpen ? '160px' : '32px',
                transition: 'height var(--transition-normal)'
            }}
        >
            {/* Header */}
            <div
                className="flex items-center justify-between px-3 h-8 cursor-pointer select-none"
                onClick={onToggle}
            >
                <div className="flex items-center gap-2">
                    <AlertTriangle size={14} className="text-red-500" />
                    <span className="text-[11px] font-bold text-red-500 uppercase tracking-wider">
                        Validation Errors ({errors.length})
                    </span>
                </div>
                <div className="flex items-center gap-2">
                    {isOpen ? <ChevronDown size={14} className="text-slate-500" /> : <ChevronUp size={14} className="text-slate-500" />}
                </div>
            </div>

            {/* Content */}
            {isOpen && (
                <div className="px-3 pb-3 overflow-y-auto h-[128px] custom-scrollbar">
                    <div className="space-y-1 mt-1">
                        {errors.map((err, i) => (
                            <div
                                key={i}
                                className="flex items-start gap-2 p-2 rounded bg-red-500/5 border border-red-500/10"
                            >
                                <span className="text-[10px] font-mono font-bold text-red-400 bg-red-400/10 px-1 rounded">
                                    Line {err.line}
                                </span>
                                <p className="text-[11px] text-secondary leading-normal">
                                    {err.message}
                                </p>
                            </div>
                        ))}
                    </div>
                </div>
            )}
        </div>
    );
}

/**
 * FieldMappingEditor — modal for editing a single field mapping's target name
 * and data type.
 *
 * Props:
 *   row            : NormalizedRow | null  — the row being edited
 *   onSave         : (rowId: string, { target_name, target_data_type }) => void
 *   onClose        : () => void
 *   targetPlatform : string  — e.g. "snowflake", "fabric", "databricks"
 *   isSaving       : boolean — shows loading/disabled state while saving
 */
import { useState, useEffect } from 'react';
import { AlertTriangle, CheckCircle, Loader2 } from 'lucide-react';
import Modal from './common/Modal';
import { targetNameKind, validateTargetName } from '../utils/validateTargetName';
import { renameImpactNote } from '../utils/nameChanges';
import RenameImpactNote from './common/RenameImpactNote';

// Common data type options used across the project
const DATA_TYPE_OPTIONS = [
  'VARCHAR',
  'TEXT',
  'NUMBER',
  'INTEGER',
  'BIGINT',
  'FLOAT',
  'DECIMAL',
  'BOOLEAN',
  'DATE',
  'TIMESTAMP',
  'TIMESTAMP_NTZ',
  'VARIANT',
  'OBJECT',
  'ARRAY',
];

const LABEL = {
  display: 'block',
  fontSize: 12,
  fontWeight: 600,
  color: 'var(--text-secondary)',
  marginBottom: 6,
};

const INPUT = {
  display: 'block',
  width: '100%',
  background: 'var(--bg-input)',
  border: '1px solid var(--border-main)',
  borderRadius: 8,
  color: 'var(--text-primary)',
  padding: '8px 12px',
  fontSize: 13,
  outline: 'none',
  fontFamily: 'inherit',
  boxSizing: 'border-box',
};

const INPUT_READONLY = {
  ...INPUT,
  background: 'var(--bg-surface-raised)',
  color: 'var(--text-secondary)',
  cursor: 'default',
};

export default function FieldMappingEditor({
  row,
  onSave,
  onClose,
  targetPlatform = '',
  isSaving = false,
}) {
  const [targetName, setTargetName] = useState('');
  const [targetDataType, setTargetDataType] = useState('');
  const [validationResult, setValidationResult] = useState(null);

  // Initialise controlled fields whenever the row changes
  useEffect(() => {
    if (!row) return;
    setTargetName(String(row.target_field || ''));
    setTargetDataType(String(row.target_type || ''));
    setValidationResult(null);
  }, [row]);

  // ── Handlers ────────────────────────────────────────────────────────────────

  function handleTargetNameChange(e) {
    const value = e.target.value;
    setTargetName(value);
    const result = validateTargetName(
      value,
      targetPlatform,
      row?.source_type || '',
      targetDataType,
      targetNameKind(row),
    );
    setValidationResult(result);
  }

  function handleTargetDataTypeChange(e) {
    setTargetDataType(e.target.value);
    // Re-validate target name against the new data type
    if (targetName) {
      const result = validateTargetName(
        targetName,
        targetPlatform,
        row?.source_type || '',
        e.target.value,
        targetNameKind(row),
      );
      setValidationResult(result);
    }
  }

  function handleSubmit(e) {
    e.preventDefault();
    // Run validation on submit in case the user hasn't typed yet
    const result = validateTargetName(
      targetName,
      targetPlatform,
      row?.source_type || '',
      targetDataType,
      targetNameKind(row),
    );
    setValidationResult(result);
    if (!result.isValid) return; // keep modal open, error already shown
    onSave?.(row.id, { target_name: targetName, target_data_type: targetDataType });
  }

  function handleApplySuggestion() {
    if (!validationResult?.suggestion) return;
    const suggested = validationResult.suggestion;
    setTargetName(suggested);
    const result = validateTargetName(
      suggested,
      targetPlatform,
      row?.source_type || '',
      targetDataType,
      targetNameKind(row),
    );
    setValidationResult(result);
  }

  // ── Derived state ────────────────────────────────────────────────────────────
  const isInvalid = validationResult !== null && !validationResult.isValid;
  const isValid   = validationResult !== null && validationResult.isValid;
  const submitDisabled = isSaving || isInvalid;

  // ── Footer ───────────────────────────────────────────────────────────────────
  const footer = (
    <>
      <button
        type="button"
        onClick={onClose}
        disabled={isSaving}
        style={{
          padding: '8px 16px',
          borderRadius: 8,
          border: '1px solid var(--border-main)',
          background: 'var(--bg-surface-raised)',
          color: 'var(--text-secondary)',
          fontSize: 13,
          fontWeight: 600,
          cursor: isSaving ? 'not-allowed' : 'pointer',
          opacity: isSaving ? 0.6 : 1,
        }}
      >
        Cancel
      </button>
      <button
        type="submit"
        form="field-mapping-editor-form"
        disabled={submitDisabled}
        style={{
          display: 'inline-flex',
          alignItems: 'center',
          gap: 6,
          padding: '8px 16px',
          borderRadius: 8,
          border: '1px solid var(--accent-blue)',
          background: 'var(--accent-blue)',
          color: '#fff',
          fontSize: 13,
          fontWeight: 700,
          cursor: submitDisabled ? 'not-allowed' : 'pointer',
          opacity: submitDisabled ? 0.55 : 1,
        }}
      >
        {isSaving && <Loader2 size={13} style={{ animation: 'spin 1s linear infinite' }} />}
        {isSaving ? 'Saving…' : 'Save'}
      </button>
    </>
  );

  return (
    <Modal
      open={Boolean(row)}
      onClose={isSaving ? undefined : onClose}
      title="Edit Field Mapping"
      size="md"
      footer={footer}
    >
      <form id="field-mapping-editor-form" onSubmit={handleSubmit}>
        {/* ── Read-only source info ─────────────────────────────────────────── */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: 16, marginBottom: 24 }}>
          <div style={{
            padding: '12px 14px',
            borderRadius: 8,
            background: 'var(--bg-surface-raised)',
            border: '1px solid var(--border-main)',
            display: 'flex',
            flexDirection: 'column',
            gap: 10,
          }}>
            <div style={{
              fontSize: 11,
              fontWeight: 700,
              color: 'var(--text-tertiary)',
              textTransform: 'uppercase',
              letterSpacing: '0.06em',
              marginBottom: 2,
            }}>
              Source (read-only)
            </div>

            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr 1fr', gap: 12 }}>
              {/* source_name */}
              <div>
                <label style={LABEL}>Source Name</label>
                <input
                  readOnly
                  tabIndex={-1}
                  value={String(row?.source_field || '')}
                  style={INPUT_READONLY}
                  aria-label="Source name (read-only)"
                />
              </div>

              {/* source_table */}
              <div>
                <label style={LABEL}>Source Table</label>
                <input
                  readOnly
                  tabIndex={-1}
                  value={String(row?.source_table_name || '—')}
                  style={INPUT_READONLY}
                  aria-label="Source table (read-only)"
                />
              </div>

              {/* source_type */}
              <div>
                <label style={LABEL}>Source Type</label>
                <input
                  readOnly
