// ────────────────────────────────────────────
// Dagre hierarchical layout
// ────────────────────────────────────────────
function applyDagreLayout(nodes, edges, direction = 'LR', opts = {}) {
    // Use LR (left-to-right) for ER/table view for Power BI/dbdiagram style
    const {
        nodeWidth = 260,
        nodeHeight = 110,
        nodeSep = 120,
        rankSep = 180,
    } = opts;
    const g = new dagre.graphlib.Graph();
    g.setDefaultEdgeLabel(() => ({}));
    g.setGraph({ rankdir: direction, nodesep: nodeSep, ranksep: rankSep });

    nodes.forEach(n => {
        g.setNode(n.id, { width: nodeWidth, height: nodeHeight });
    });

    edges.forEach(e => {
        g.setEdge(e.source, e.target);
    });

    dagre.layout(g);

    return nodes.map(n => {
        const pos = g.node(n.id);
        return {
            ...n,
            position: { x: pos.x - (nodeWidth / 2), y: pos.y - (nodeHeight / 2) },
        };
    });
}

// ────────────────────────────────────────────
// Simple force-directed simulation (lightweight)
// ────────────────────────────────────────────
function applyForceLayout(nodes) {
    // Place nodes in a roughly circular pattern
    const cx = 500, cy = 400;
    const radius = Math.max(250, nodes.length * 30);
    return nodes.map((n, i) => {
        const angle = (2 * Math.PI * i) / nodes.length;
        return {
            ...n,
            position: {
                x: cx + radius * Math.cos(angle),
                y: cy + radius * Math.sin(angle),
            },
        };
    });
}

// ────────────────────────────────────────────
// Compact ER grid layout (Power BI-like readability)
// ────────────────────────────────────────────
function applyERGridLayout(nodes, edges) {
    const degree = new Map();
    nodes.forEach(n => degree.set(n.id, 0));
    edges.forEach(e => {
        degree.set(e.source, (degree.get(e.source) || 0) + 1);
        degree.set(e.target, (degree.get(e.target) || 0) + 1);
    });

    const ordered = [...nodes].sort((a, b) => {
        const d = (degree.get(b.id) || 0) - (degree.get(a.id) || 0);
        if (d !== 0) return d;
        return String(a?.data?.label || a.id).localeCompare(String(b?.data?.label || b.id));
    });

    const count = Math.max(1, ordered.length);
    const cols = Math.max(3, Math.min(7, Math.ceil(Math.sqrt(count))));
    const cellW = 260;
    const cellH = 150;
    const startX = 100;
    const startY = 80;

    const posById = new Map();
    ordered.forEach((n, i) => {
        const row = Math.floor(i / cols);
        const col = i % cols;
        posById.set(n.id, {
            x: startX + col * cellW,
            y: startY + row * cellH,
        });
    });

    return nodes.map(n => ({
        ...n,
        position: posById.get(n.id) || n.position,
    }));
}

// ────────────────────────────────────────────
// Dense model grid layout (for very large model counts)
// ────────────────────────────────────────────
function applyModelGridLayout(nodes, denseMode = false) {
    const ordered = [...nodes].sort((a, b) =>
        String(a?.data?.label || a.id).localeCompare(String(b?.data?.label || b.id))
    );

    const count = Math.max(1, ordered.length);
    const cols = denseMode
        ? Math.max(10, Math.min(36, Math.ceil(Math.sqrt(count * 1.8))))
        : Math.max(6, Math.min(24, Math.ceil(Math.sqrt(count * 1.6))));
    const cellW = denseMode ? 132 : 180;
    const cellH = denseMode ? 68 : 92;
    const startX = 60;
    const startY = 60;

    const posById = new Map();
    ordered.forEach((n, i) => {
        const row = Math.floor(i / cols);
        const col = i % cols;
        posById.set(n.id, {
            x: startX + col * cellW,
            y: startY + row * cellH,
        });
    });

    return nodes.map(n => ({
        ...n,
        position: posById.get(n.id) || n.position,
    }));
}

// ────────────────────────────────────────────
// Dense table grid layout (for table-only browsing)
// ────────────────────────────────────────────
function applyTableGridLayout(nodes, edges) {
    const degree = new Map();
    nodes.forEach(n => degree.set(n.id, 0));
    edges.forEach(e => {
        degree.set(e.source, (degree.get(e.source) || 0) + 1);
        degree.set(e.target, (degree.get(e.target) || 0) + 1);
    });

    const ordered = [...nodes].sort((a, b) => {
        const d = (degree.get(b.id) || 0) - (degree.get(a.id) || 0);
        if (d !== 0) return d;
        return String(a?.data?.label || a.id).localeCompare(String(b?.data?.label || b.id));
    });

    const count = Math.max(1, ordered.length);
    const dense = count > 260;
    const cols = dense
        ? Math.max(8, Math.min(28, Math.ceil(Math.sqrt(count * 1.5))))
        : Math.max(5, Math.min(18, Math.ceil(Math.sqrt(count * 1.3))));
    const cellW = dense ? 210 : 250;
    const cellH = dense ? 132 : 154;
    const startX = 70;
    const startY = 70;

    const posById = new Map();
    ordered.forEach((n, i) => {
        const row = Math.floor(i / cols);
        const col = i % cols;
        posById.set(n.id, {
            x: startX + col * cellW,
            y: startY + row * cellH,
        });
    });

    return nodes.map(n => ({
        ...n,
        position: posById.get(n.id) || n.position,
    }));
}

/**
 * DependencyGraph — the React Flow canvas for the DAG.
 */
export default function DependencyGraph({
    graphData,
    layout,
    erMode = false,
    selectedModelId = '__all__',
    selectedTableId = '__all__',
    searchQuery,
    filterType,
    showVersionBadges,
    onNodeClick,
    isLoading = false,
    snapshotId = null,
    diffMode = false,
    onRequestFullScreen,
    showFullScreenButton = false,
}) {
    const { getNodes } = useReactFlow?.() || {};
    const [nodes, setNodes, onNodesChange] = useNodesState([]);
    const [edges, setEdges, onEdgesChange] = useEdgesState([]);
    const [versionCounts, setVersionCounts] = useState({});
    const [mappingOpen, setMappingOpen] = useState(false);

    const tableRows = useMemo(() => {
        const allNodes = Array.isArray(graphData?.nodes) ? graphData.nodes : [];
        let rows = allNodes.filter(n => n?.data?.nodeType === 'table');

        if (selectedModelId && selectedModelId !== '__all__') {
            rows = rows.filter(n => {
                const mid = String(n?.data?.model_id || '').trim();
                if (!mid) return true;
                return mid === String(selectedModelId);
            });
        }

        if (selectedTableId && selectedTableId !== '__all__') {
            rows = rows.filter(n => String(n?.id || '') === String(selectedTableId));
        }

        const q = String(searchQuery || '').trim().toLowerCase();
        if (q) {
            rows = rows.filter(n => {
                const d = n?.data || {};
                const name = String(d.label || '').toLowerCase();
                const schema = String(d.schema || '').toLowerCase();
                const source = String(d.source_type || '').toLowerCase();
                const cols = Array.isArray(d.columns)
                    ? d.columns.map(c => String(c?.name || '')).join(' ').toLowerCase()
                    : '';
                return name.includes(q) || schema.includes(q) || source.includes(q) || cols.includes(q);
            });
        }

        return rows.sort((a, b) => {
            const as = String(a?.data?.schema || 'PUBLIC');
            const bs = String(b?.data?.schema || 'PUBLIC');
            const bySchema = as.localeCompare(bs);
            if (bySchema !== 0) return bySchema;
            return String(a?.data?.label || a?.id || '').localeCompare(String(b?.data?.label || b?.id || ''));
        });
    }, [graphData, selectedModelId, selectedTableId, searchQuery]);

    const mappingRows = useMemo(() => {
        const allNodes = Array.isArray(graphData?.nodes) ? graphData.nodes : [];
        const allEdges = Array.isArray(graphData?.edges) ? graphData.edges : [];
        const byId = new Map(allNodes.map(n => [String(n.id), n]));

        let rels = allEdges.filter(e => String(e?.id || '').startsWith('rel-'));
        if (selectedModelId && selectedModelId !== '__all__') {
            rels = rels.filter(e => {
                const s = byId.get(String(e.source));
                const t = byId.get(String(e.target));
                return String(s?.data?.model_id || '') === String(selectedModelId)
                    || String(t?.data?.model_id || '') === String(selectedModelId);
            });
        }
        if (selectedTableId && selectedTableId !== '__all__') {
            rels = rels.filter(e => String(e.source) === String(selectedTableId) || String(e.target) === String(selectedTableId));
        }

        return rels.map(e => {
            const s = byId.get(String(e.source));
            const t = byId.get(String(e.target));
            return {
                id: e.id,
                fromTable: s?.data?.label || e.source,
                fromSchema: s?.data?.schema || 'PUBLIC',
                fromColumn: e?.data?.from_column || '-',
                toTable: t?.data?.label || e.target,
                toSchema: t?.data?.schema || 'PUBLIC',
                toColumn: e?.data?.to_column || '-',
                cardinality: e?.data?.cardinality || '-',
            };
        });
    }, [graphData, selectedModelId, selectedTableId]);

    // ── Load version counts ──
    useEffect(() => {
        if (!showVersionBadges) return;
        (async () => {
            try {
                const versions = await api.getModelVersions('', '', 500);
                const counts = {};
                (versions || []).forEach(v => {
                    counts[v.model_id] = (counts[v.model_id] || 0) + 1;
                });
                setVersionCounts(counts);
            } catch { /* ignore */ }
        })();
    }, [showVersionBadges]);

    // ── Apply filter + search + layout ──────────
    useEffect(() => {
        if (!graphData) return;

        let filteredNodes = [...graphData.nodes];
        let filteredEdges = [...graphData.edges];

        // Scope graph to one model when requested (mainly for ER readability)
        if (selectedModelId && selectedModelId !== '__all__') {
            const modelNode = filteredNodes.find(n =>
                n?.data?.nodeType === 'model' &&
                (String(n?.data?.model_id || '') === String(selectedModelId) || String(n?.id || '') === `model-${selectedModelId}`)
            );

            if (modelNode) {
                const modelNodeId = modelNode.id;

                const attachedTableIds = new Set(
                    filteredEdges
                        .filter(e => (e?.source === modelNodeId || e?.target === modelNodeId))
                        .map(e => (e.source === modelNodeId ? e.target : e.source))
                );

                const scopedNodeIds = new Set([modelNodeId, ...attachedTableIds]);

                const scopedNodes = filteredNodes.filter(n => {
                    if (scopedNodeIds.has(n.id)) return true;
                    // Keep measures connected to this model
                    if (n?.data?.nodeType === 'measure') {
                        return filteredEdges.some(e =>
                            (e.source === modelNodeId && e.target === n.id) ||
                            (e.target === modelNodeId && e.source === n.id)
                        );
                    }
                    return false;
                });

                const scopedNodeIdSet = new Set(scopedNodes.map(n => n.id));
                const scopedEdges = filteredEdges.filter(e =>
                    scopedNodeIdSet.has(e.source) && scopedNodeIdSet.has(e.target)
                );

                filteredNodes = scopedNodes;
                filteredEdges = scopedEdges;
            }
        }

        // ER View (Power BI-like): table-centric with relationship links only
        if (erMode) {
            const tableNodes = filteredNodes.filter(n => n?.data?.nodeType === 'table');
            const tableIds = new Set(tableNodes.map(n => n.id));
            const relationshipEdges = filteredEdges.filter(e => {
                const isRel = String(e?.id || '').startsWith('rel-');
                return isRel && tableIds.has(e.source) && tableIds.has(e.target);
            });

            filteredNodes = tableNodes;
            filteredEdges = relationshipEdges;

            if (selectedTableId && selectedTableId !== '__all__') {
                const focusedId = String(selectedTableId);
                const selectedExists = filteredNodes.some(n => String(n.id) === focusedId);
                if (selectedExists) {
                    const keep = new Set([focusedId]);
                    filteredEdges.forEach(e => {
                        if (String(e.source) === focusedId) keep.add(String(e.target));
                        if (String(e.target) === focusedId) keep.add(String(e.source));
                    });
                    filteredNodes = filteredNodes.filter(n => keep.has(String(n.id)));
                    filteredEdges = filteredEdges.filter(e => keep.has(String(e.source)) && keep.has(String(e.target)));
                }
            }
        }

        // Filter by type
        if (filterType === 'models') {
            const ids = new Set(filteredNodes.filter(n => n.data.nodeType === 'model').map(n => n.id));
            filteredNodes = filteredNodes.filter(n => n.data.nodeType === 'model');
            filteredEdges = filteredEdges.filter(e => ids.has(e.source) && ids.has(e.target));
        } else if (filterType === 'tables') {
            const ids = new Set(filteredNodes.filter(n => n.data.nodeType === 'table').map(n => n.id));
            filteredNodes = filteredNodes.filter(n => n.data.nodeType === 'table');
            filteredEdges = filteredEdges.filter(e => ids.has(e.source) && ids.has(e.target));
        } else if (filterType === 'broken') {
            filteredNodes = filteredNodes.filter(n =>
                n.data.status === 'broken' || n.data.nodeType === 'model' && n.data.status === 'broken'
            );
            const ids = new Set(filteredNodes.map(n => n.id));
            filteredEdges = filteredEdges.filter(e => ids.has(e.source) || ids.has(e.target));
        }

        // Search — highlight / dim
        if (searchQuery.trim()) {
            const q = searchQuery.toLowerCase();
            filteredNodes = filteredNodes.map(n => {
                const label = (n.data.label || '').toLowerCase();
                const modelId = (n.data.model_id || '').toLowerCase();
                const wsId = (n.data.workspace_id || '').toLowerCase();
                const match = label.includes(q) || modelId.includes(q) || wsId.includes(q);
                return {
                    ...n,
                    style: {
                        ...n.style,
                        opacity: match ? 1 : 0.2,
                        transition: 'opacity .25s ease',
                    },
                };
            });
        }

        // Version badges — inject into model nodes
        if (showVersionBadges) {
            filteredNodes = filteredNodes.map(n => {
                if (n.data.nodeType === 'model' && n.data.model_id) {
                    return {
                        ...n,
                        data: {
                            ...n.data,
                            versionCount: versionCounts[n.data.model_id] || 0,
                        },
                    };
                }
                return n;
            });
        }

        // Layout
        const modelView = filterType === 'models';
        const tableView = filterType === 'tables';
        const denseModelView = modelView && filteredNodes.length > 350;
        const denseTableView = tableView && filteredNodes.length > 260;

        if (erMode || tableView) {
            // Use LR dagre for ER/table view for best readability
            filteredNodes = applyDagreLayout(
                filteredNodes,
                filteredEdges,
                'LR',
                { nodeWidth: 260, nodeHeight: 110, nodeSep: 120, rankSep: 180 }
            );
        } else if (modelView) {
            filteredNodes = applyModelGridLayout(filteredNodes, denseModelView);
        } else if (layout === 'hierarchical') {
            filteredNodes = applyDagreLayout(
                filteredNodes,
                filteredEdges,
                'TB',
                { nodeWidth: 240, nodeHeight: 80, nodeSep: 60, rankSep: 100 }
            );
        } else {
            filteredNodes = applyForceLayout(filteredNodes);
        }

        const styledNodes = filteredNodes.map(n => {
            const status = n?.data?.diffStatus;
            const baseData = {
                ...n.data,
                compactModelView: modelView,
                denseModelView,
                compactTableView: tableView,
                denseTableView,
            };
            if (status === 'added') {
                return {
                    ...n,
                    data: { ...baseData, diffStatus: status },
                };
            }
            if (status === 'removed') {
                return {
                    ...n,
                    data: { ...baseData, diffStatus: status },
                    style: {
                        ...(n.style || {}),
                        opacity: 0.75,
                    },
                };
            }
            if (status === 'modified') {
                return {
                    ...n,
                    data: { ...baseData, diffStatus: status },
                };
            }
            return { ...n, data: baseData };
        });

        const styledEdges = filteredEdges.map(e => {
            const status = e?.data?.diffStatus;
            const isRelationship = String(e?.id || '').startsWith('rel-');
            if (status === 'added') {
                return {
                    ...e,
                    animated: false,
                    style: {
                        ...(e.style || {}),
                        stroke: '#22C55E',
                        strokeWidth: 2.5,
                    },
                };
            }
            if (status === 'removed') {
                return {
                    ...e,
                    animated: false,
                    style: {
                        ...(e.style || {}),
                        stroke: '#EF4444',
                        strokeDasharray: '6 4',
                        strokeWidth: 2,
                    },
                };
            }
            if (status === 'modified') {
                return {
                    ...e,
                    animated: false,
                    style: {
                        ...(e.style || {}),
                        stroke: '#EAB308',
                        strokeWidth: 2.5,
                    },
                };
            }
            if (isRelationship) {
                return {
                    ...e,
                    type: 'smoothstep',
                    animated: false,
                    style: {
                        ...(e.style || {}),
                        stroke: (e.style && e.style.stroke) || 'var(--er-edge-stroke)',
                        strokeWidth: 1.5,
                    },
                    labelStyle: {
                        fill: 'var(--er-edge-label-text)',
                        fontSize: 10,
                        fontWeight: 600,
                        fontFamily: "'Inter', sans-serif",
                    },
                    labelBgStyle: {
                        fill: 'var(--er-edge-label-bg)',
                    },
                    labelBgPadding: [6, 3],
                    labelBgBorderRadius: 6,
                };
            }
            return e;
        });

        setNodes(styledNodes);
        setEdges(styledEdges);
    }, [graphData, layout, erMode, selectedModelId, selectedTableId, searchQuery, filterType, showVersionBadges, versionCounts, setNodes, setEdges]);

    // ── Node click handler ──────────────────────
    const handleNodeClick = useCallback((_, node) => {
        onNodeClick?.({ ...(node?.data || {}), id: node?.id });
    }, [onNodeClick]);

    if (filterType === 'tables' && !erMode) {
        return (
            <div style={{ width: '100%', height: '100%', position: 'relative', overflow: 'auto', background: 'var(--bg-app)' }}>
                <div style={{ padding: '10px 12px' }}>
                    <div style={{
                        border: '1px solid var(--border-color)',
                        borderRadius: 10,
                        overflow: 'hidden',
                        background: 'var(--bg-surface)',
                    }}>
                        <div style={{
                            display: 'flex',
                            alignItems: 'center',
                            justifyContent: 'space-between',
                            padding: '10px 12px',
                            borderBottom: '1px solid var(--border-color)',
                            fontSize: 12,
                            color: 'var(--text-secondary)',
                            fontWeight: 700,
                        }}>
                            <span>Tables</span>
                            <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
                                <span style={{ color: 'var(--text-tertiary)', fontWeight: 600 }}>{tableRows.length} total</span>
                                <button
                                    onClick={() => setMappingOpen(true)}
                                    style={{
                                        border: '1px solid rgba(129,140,248,.5)',
                                        background: 'rgba(129,140,248,.12)',
                                        color: '#A5B4FC',
                                        borderRadius: 6,
                                        padding: '4px 8px',
                                        fontSize: 11,
                                        cursor: 'pointer',
                                        fontWeight: 600,
                                    }}
                                >
                                    Mapping View
                                </button>
                            </div>
                        </div>

                        <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: 12 }}>
                            <thead>
                                <tr>
                                    <th style={thStyle}>Table</th>
                                    <th style={thStyle}>Model</th>
                                    <th style={thStyle}>Schema</th>
                                    <th style={thStyle}>Columns</th>
                                    <th style={thStyle}>Rows</th>
                                    <th style={thStyle}>Details</th>
                                </tr>
                            </thead>
                            <tbody>
                                {tableRows.map((n) => {
                                    const d = n.data || {};
                                    const columns = Array.isArray(d.columns) ? d.columns : [];
                                    const rowCount = d.row_count || '-';
                                    return (
                                        <tr key={n.id}>
                                            <td style={tdStyle}>{d.label}</td>
                                            <td style={tdStyle}>{d.model_label || d.model_name || d.model_id || '-'}</td>
                                            <td style={tdStyle}>{d.schema || 'PUBLIC'}</td>
                                            <td style={tdStyle}>{columns.length}</td>
                                            <td style={tdStyle}>{rowCount}</td>
                                            <td style={{ ...tdStyle, color: 'var(--text-tertiary)' }}>
                                                <details style={{ cursor: 'pointer' }}>
                                                    <summary style={{ userSelect: 'none', color: '#A5B4FC', fontWeight: 600 }}>
                                                        {columns.length > 0 ? 'View Schema' : 'No columns'}
                                                    </summary>
                                                    {columns.length > 0 && (
                                                        <div style={{
                                                            marginTop: 8,
                                                            paddingTop: 8,
                                                            borderTop: '1px solid var(--border-color)',
                                                            maxHeight: 300,
                                                            overflowY: 'auto',
                                                        }}>
                                                            <table style={{
                                                                width: '100%',
                                                                borderCollapse: 'collapse',
                                                                fontSize: 11,
                                                                marginTop: 4,
                                                            }}>
                                                                <thead>
                                                                    <tr>
                                                                        <th style={{
                                                                            textAlign: 'left',
                                                                            padding: '4px 6px',
                                                                            color: 'var(--text-tertiary)',
                                                                            fontSize: 10,
                                                                            fontWeight: 600,
                                                                            textTransform: 'uppercase',
                                                                            borderBottom: '1px solid var(--border-color)',
                                                                        }}>Name</th>
                                                                        <th style={{
                                                                            textAlign: 'left',
                                                                            padding: '4px 6px',
                                                                            color: 'var(--text-tertiary)',
                                                                            fontSize: 10,
                                                                            fontWeight: 600,
                                                                            textTransform: 'uppercase',
                                                                            borderBottom: '1px solid var(--border-color)',
                                                                        }}>Type</th>
                                                                    </tr>
                                                                </thead>
                                                                <tbody>
                                                                    {columns.map((col, idx) => {
                                                                        const colName = typeof col === 'string' ? col : (col?.name || col?.label || `col_${idx}`);
                                                                        const colType = col?.type || col?.data_type || col?.dtype || '-';
                                                                        return (
                                                                            <tr key={`${n.id}-col-${idx}`}>
                                                                                <td style={{
                                                                                    padding: '4px 6px',
                                                                                    color: 'var(--text-secondary)',
                                                                                    borderBottom: '1px solid rgba(129,140,248,.1)',
                                                                                }}>
                                                                                    {colName}
                                                                                </td>
                                                                                <td style={{
                                                                                    padding: '4px 6px',
                                                                                    color: 'var(--text-tertiary)',
                                                                                    borderBottom: '1px solid rgba(129,140,248,.1)',
                                                                                    fontSize: 10,
                                                                                }}>
                                                                                    {colType}
                                                                                </td>
                                                                            </tr>
                                                                        );
                                                                    })}
                                                                </tbody>
                                                            </table>
                                                        </div>
                                                    )}
                                                </details>
                                            </td>
                                        </tr>
                                    );
                                })}
                                {tableRows.length === 0 && (
                                    <tr>
                                        <td colSpan={6} style={{ ...tdStyle, textAlign: 'center', color: 'var(--text-tertiary)' }}>
                                            No tables found for current filter/search.
                                        </td>
                                    </tr>
                                )}
                            </tbody>
                        </table>
                    </div>
                </div>

                {isLoading && (
                    <div style={{
                        position: 'absolute',
                        inset: 0,
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'center',
                        background: 'rgba(2, 6, 23, 0.55)',
                        backdropFilter: 'blur(2px)',
                        zIndex: 5,
                    }}>
                        <div style={{
                            display: 'flex',
                            alignItems: 'center',
                            gap: 8,
                            padding: '10px 14px',
                            borderRadius: 10,
                            background: 'var(--bg-surface)',
                            border: '1px solid var(--border-color)',
                            color: 'var(--text-secondary)',
                            fontSize: 12,
                        }}>
                            <Loader2 size={14} style={{ animation: 'spin 1s linear infinite', color: '#818CF8' }} />
                            <span>Loading tables...</span>
                        </div>
                    </div>
                )}

                {mappingOpen && (
                    <div style={{
                        position: 'fixed',
                        inset: 0,
                        background: 'rgba(0,0,0,.45)',
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'center',
                        padding: 16,
                        zIndex: 1200,
                    }}>
                        <div style={{
                            width: '96vw',
                            height: '86vh',
                            background: 'var(--bg-surface)',
                            border: '1px solid var(--border-color)',
                            borderRadius: 10,
                            overflow: 'hidden',
                            display: 'flex',
                            flexDirection: 'column',
                        }}>
                            <div style={{
                                padding: '10px 12px',
                                borderBottom: '1px solid var(--border-color)',
                                display: 'flex',
                                alignItems: 'center',
                                justifyContent: 'space-between',
                                background: 'var(--bg-app)',
                            }}>
                                <span style={{ fontSize: 13, fontWeight: 700, color: 'var(--text-secondary)' }}>Table Mapping View</span>
                                <button onClick={() => setMappingOpen(false)} style={{ border: 'none', background: 'transparent', color: 'var(--text-tertiary)', cursor: 'pointer', fontSize: 16 }}>✕</button>
                            </div>
                            <div style={{ overflow: 'auto', flex: 1 }}>
                                <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: 12 }}>
                                    <thead>
                                        <tr>
                                            <th style={thStyle}>From</th>
                                            <th style={thStyle}>From Column</th>
                                            <th style={thStyle}>To</th>
                                            <th style={thStyle}>To Column</th>
                                            <th style={thStyle}>Cardinality</th>
                                        </tr>
                                    </thead>
                                    <tbody>
                                        {mappingRows.map((m) => (
                                            <tr key={m.id}>
                                                <td style={tdStyle}>{m.fromSchema}.{m.fromTable}</td>
                                                <td style={tdStyle}>{m.fromColumn}</td>
                                                <td style={tdStyle}>{m.toSchema}.{m.toTable}</td>
                                                <td style={tdStyle}>{m.toColumn}</td>
                                                <td style={tdStyle}>{m.cardinality}</td>
                                            </tr>
                                        ))}
                                        {mappingRows.length === 0 && (
                                            <tr><td colSpan={5} style={{ ...tdStyle, textAlign: 'center', color: 'var(--text-tertiary)' }}>No relationships available for current selection.</td></tr>
                                        )}
                                    </tbody>
                                </table>
                            </div>
                        </div>
                    </div>
                )}
            </div>
        );
    }

    const shouldAutoFitView = true;

    return (
        <div style={{ width: '100%', height: '100%', position: 'relative' }}>
            <ReactFlow
                nodes={nodes}
                edges={edges}
                onNodesChange={onNodesChange}
                onEdgesChange={onEdgesChange}
                onNodeClick={handleNodeClick}
                nodeTypes={nodeTypes}
                fitView={shouldAutoFitView}
                fitViewOptions={{ padding: 0.16 }}
                minZoom={0.02}
                maxZoom={2}
                defaultEdgeOptions={{
                    type: 'smoothstep',
                    animated: !erMode,
                }}
                style={{ background: 'var(--bg-app)' }}
            >
                {snapshotId && (
                    <Panel position="top-left">
                        <div style={{
                            background: 'var(--bg-surface)',
                            border: '1px solid var(--border-color)',
                            borderRadius: 8,
                            padding: '8px 10px',
                            display: 'flex',
                            alignItems: 'center',
                            gap: 6,
                            fontSize: 11,
                            color: 'var(--text-secondary)',
                        }}>
                            <Database size={12} style={{ color: 'var(--accent-blue)' }} />
                            <span style={{ textTransform: 'uppercase', letterSpacing: '.04em', fontWeight: 700, color: 'var(--text-tertiary)' }}>Snapshot</span>
                            <span style={{ color: 'var(--accent-blue)', fontFamily: 'ui-monospace, SFMono-Regular, Menlo, Consolas, monospace' }}>
                                {String(snapshotId).slice(0, 8)}
                            </span>
                        </div>
                    </Panel>
                )}

                <Controls
                    position="bottom-left"
                    style={{ margin: 16 }}
                />
                <MiniMap
                    position="bottom-right"
                    style={{
                        margin: 16,
                        background: 'var(--bg-surface)',
                        border: '1px solid var(--border-main)',
                        borderRadius: 10,
                        overflow: 'hidden',
                        boxShadow: 'var(--shadow-md)',
                    }}
                    nodeColor={n => {
                        if (n.data?.nodeType === 'model') return 'var(--accent-blue)';
                        if (n.data?.nodeType === 'table') return '#10B981';
                        if (n.data?.nodeType === 'measure') return '#F59E0B';
                        return 'var(--text-tertiary)';
                    }}
                    nodeStrokeWidth={1}
                    maskColor="rgba(0, 0, 0, 0.45)"
                />
                <Background gap={24} size={1} color="var(--er-canvas-dots)" />

                {/* Legend & Fullscreen Panel */}
                <Panel position="top-right">
                    <div style={{
                        display: 'flex', flexDirection: 'column', alignItems: 'flex-end', gap: 8,
                    }}>
                        {/* Full Screen Button above legend */}
                        {showFullScreenButton && (
                            <button
                                onClick={onRequestFullScreen}
                                title="Full Screen Relationship Diagram"
                                style={{
                                    display: 'inline-flex',
                                    alignItems: 'center',
                                    gap: 6,
                                    padding: '6px 12px',
                                    background: 'var(--bg-surface)',
                                    color: 'var(--text-primary)',
                                    border: '1px solid var(--border-main)',
                                    borderRadius: 8,
                                    fontSize: 11,
                                    fontWeight: 600,
                                    boxShadow: 'var(--shadow-md)',
                                    cursor: 'pointer',
                                    backdropFilter: 'blur(8px)',
                                    transition: 'all 0.15s ease',
                                }}
                                onMouseEnter={e => { e.currentTarget.style.borderColor = 'var(--accent-blue)'; e.currentTarget.style.transform = 'translateY(-1px)'; }}
                                onMouseLeave={e => { e.currentTarget.style.borderColor = 'var(--border-main)'; e.currentTarget.style.transform = 'none'; }}
                            >
                                <Maximize2 size={13} style={{ color: 'var(--accent-blue)' }} />
                                <span>Full Screen</span>
                            </button>
                        )}
                        <div style={{
                            background: 'var(--bg-surface)',
                            border: '1px solid var(--border-main)',
                            borderRadius: 10,
                            padding: '10px 14px',
                            fontSize: 11,
                            boxShadow: 'var(--shadow-md)',
                            backdropFilter: 'blur(8px)',
                            display: 'flex', flexDirection: 'column', gap: 5,
                            minWidth: 140,
                        }}>
                            <span style={{ fontWeight: 700, fontSize: 10, textTransform: 'uppercase', letterSpacing: '.05em', color: 'var(--text-tertiary)' }}>
                                Legend
                            </span>
                            {[
                                ...(erMode ? [] : [{ color: '#3B82F6', label: 'Semantic Model' }]),
                                { color: '#22C55E', label: 'Source Table' },
                                ...(erMode ? [{ color: 'var(--accent-blue)', label: 'Relationship' }] : [{ color: '#EAB308', label: 'Metric / Measure' }]),
                                { color: '#EF4444', label: 'Broken Reference' },
                                ...(diffMode ? [
                                    { color: '#22C55E', label: 'Diff: Added (green)' },
                                    { color: '#EAB308', label: 'Diff: Modified (yellow)' },
                                    { color: '#EF4444', label: 'Diff: Removed (red/dotted)' },
                                ] : []),
                            ].map(item => (
                                <div key={item.label} style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
                                    <span style={{
                                        width: 10, height: 10, borderRadius: 3,
                                        background: item.color, flexShrink: 0,
                                    }} />
                                    <span style={{ color: 'var(--text-secondary)' }}>{item.label}</span>
                                </div>
                            ))}
                        </div>
                    </div>
                </Panel>
            </ReactFlow>

            {isLoading && (
                <div style={{
                    position: 'absolute',
                    inset: 0,
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    background: 'rgba(2, 6, 23, 0.55)',
                    backdropFilter: 'blur(2px)',
                    zIndex: 5,
                }}>
                    <div style={{
                        display: 'flex',
                        alignItems: 'center',
                        gap: 8,
                        padding: '10px 14px',
                        borderRadius: 10,
                        background: 'var(--bg-surface)',
                        border: '1px solid var(--border-color)',
                        color: 'var(--text-secondary)',
                        fontSize: 12,
                    }}>
                        <Loader2 size={14} style={{ animation: 'spin 1s linear infinite', color: 'var(--accent-blue)' }} />
                        <span>{snapshotId ? 'Loading snapshot graph...' : 'Loading dependency graph...'}</span>
                    </div>
                </div>
            )}

            {!isLoading && nodes.length === 0 && (
                <div style={{
                    position: 'absolute',
                    inset: 0,
                    display: 'flex',
                    flexDirection: 'column',
                    alignItems: 'center',
                    justifyContent: 'center',
                    pointerEvents: 'none',
                    zIndex: 4,
                }}>
                    <div style={{
                        display: 'flex',
                        flexDirection: 'column',
                        alignItems: 'center',
                        gap: 8,
                        padding: '24px 32px',
                        borderRadius: 12,
                        background: 'var(--bg-surface)',
                        border: '1px solid var(--border-color)',
                        boxShadow: 'var(--shadow-md)',
                        maxWidth: 420,
                        textAlign: 'center',
                    }}>
                        <Database size={28} style={{ color: 'var(--text-tertiary)' }} />
                        <span style={{ fontSize: 13, fontWeight: 700, color: 'var(--text-primary)' }}>
                            No Semantic Objects Found
                        </span>
                        <span style={{ fontSize: 11, color: 'var(--text-tertiary)', lineHeight: 1.5 }}>
                            Select a different connector or model from the top bar, or sync a project to visualize table relationships, foreign keys, and metrics.
                        </span>
                    </div>
                </div>
            )}
        </div>
    );
}

import {
    X, Box, Database, BarChart3,
    FileCode, Clock, HardDrive, Link2,
} from 'lucide-react';
import { useState } from 'react';

// ── styles ──
const closeBtnStyle = {
    border: 'none', background: 'transparent', cursor: 'pointer',
    color: 'var(--text-tertiary)', display: 'flex', padding: 2,
};
const tableCardStyle = {
    display: 'flex', alignItems: 'flex-start', gap: 8,
    padding: '8px 10px',
    borderRadius: 6,
    background: 'var(--bg-app)',
    border: '1px solid var(--border-color)',
    marginBottom: 4,
};
const colThStyle = {
    textAlign: 'left', padding: '6px 0', fontSize: 10.5, fontWeight: 700,
    textTransform: 'uppercase', letterSpacing: '.05em', color: 'var(--text-tertiary)',
    borderBottom: '1px solid var(--border-main)',
};
const colTdStyle = { padding: '6px 0', borderBottom: '1px solid var(--border-light, var(--border-main))' };

/**
 * DetailPanel — right sidebar showing:
 *   • File preview (syntax-highlighted raw content) when a file is selected.
 *   • Node detail with Columns | Measures | Lineage tabs when a graph node is clicked.
 */
export default function DetailPanel({ filePreview, selectedNode, workspaceNames = {}, onClose }) {
    // Active tab; null = default for the node type. Parent re-keys this panel per node.
    const [tab, setTab] = useState(null);

    // ── File preview ────────────────────────────
    if (filePreview) {
        return (
            <div style={{ display: 'flex', flexDirection: 'column', height: '100%' }}>
                {/* Header */}
                <div style={{
                    display: 'flex', alignItems: 'center', justifyContent: 'space-between',
                    padding: '10px 14px',
                    borderBottom: '1px solid var(--border-color)',
                }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
                        <FileCode size={14} style={{ color: 'var(--accent-blue)' }} />
                        <span style={{ fontSize: 12, fontWeight: 700 }}>
                            {filePreview.name}
                        </span>
                    </div>
                    <button onClick={onClose} style={closeBtnStyle}>
                        <X size={14} />
                    </button>
                </div>

                <div style={{
                    display: 'flex', alignItems: 'center', gap: 6,
                    padding: '8px 14px',
                    borderBottom: '1px solid var(--border-color)',
                    background: 'var(--bg-surface)',
                    color: 'var(--text-secondary)',
                    fontSize: 10,
                    fontWeight: 600,
                }}>
                    <Link2 size={11} style={{ color: 'var(--accent-blue)' }} />
                    Inspector Source: Snapshot Explorer File Selection
                </div>

                {/* Meta */}
                <div style={{
                    display: 'flex', gap: 12, padding: '6px 14px',
                    fontSize: 10, color: 'var(--text-tertiary)',
                    borderBottom: '1px solid var(--border-color)',
                }}>
                    {filePreview.size != null && (
                        <span style={{ display: 'flex', alignItems: 'center', gap: 3 }}>
                            <HardDrive size={10} />
                            {(filePreview.size / 1024).toFixed(1)} KB
                        </span>
                    )}
                    {filePreview.modified && (
                        <span style={{ display: 'flex', alignItems: 'center', gap: 3 }}>
                            <Clock size={10} />
                            {new Date(filePreview.modified).toLocaleString()}
                        </span>
                    )}
                </div>

                {/* Code */}
                <div style={{
                    flex: 1, overflow: 'auto',
                    padding: '10px 14px',
                }}>
                    <pre style={{
                        margin: 0,
                        fontSize: 11.5,
                        lineHeight: 1.55,
                        fontFamily: '"Fira Code", "JetBrains Mono", "Cascadia Code", Consolas, monospace',
                        color: 'var(--text-primary)',
                        whiteSpace: 'pre-wrap',
                        wordBreak: 'break-word',
                        background: 'var(--bg-app)',
                        padding: 12,
                        borderRadius: 8,
                        border: '1px solid var(--border-color)',
                    }}>
                        {filePreview.content}
                    </pre>
                </div>
            </div>
        );
    }

    // ── Node detail: compact header + Columns | Measures | Lineage tabs ──
    if (selectedNode) {
        const rawNodeType = String(selectedNode.nodeType || '').toLowerCase();
        const nodeType = ['model', 'table', 'measure'].includes(rawNodeType) ? rawNodeType : 'model';
        const nodeTypeLabel = nodeType.charAt(0).toUpperCase() + nodeType.slice(1);
        // Prefer the pre-resolved name in node data, fall back to workspaceNames map, then raw GUID
        const resolvedWsName = selectedNode.workspace_name || workspaceNames[selectedNode.workspace_id] || selectedNode.workspace_id || 'local';
        const isBroken = selectedNode.status === 'broken';
        const TypeIcon = nodeType === 'model' ? Box : nodeType === 'table' ? Database : BarChart3;
        const typeTone = nodeType === 'model' ? 'var(--accent-blue)' : nodeType === 'table' ? 'var(--color-success)' : 'var(--color-warning)';

        const columns = Array.isArray(selectedNode.columns) ? selectedNode.columns : [];
        const measures = Array.isArray(selectedNode.measures) ? selectedNode.measures : [];
        const sourceTables = Array.isArray(selectedNode.source_tables) ? selectedNode.source_tables : [];

        const subtitleParts = [];
        if (nodeType === 'table') {
            subtitleParts.push(`${columns.length} col${columns.length === 1 ? '' : 's'}`);
            if (measures.length) subtitleParts.push(`${measures.length} measure${measures.length === 1 ? '' : 's'}`);
        } else if (nodeType === 'model') {
            subtitleParts.push(`${sourceTables.length} table${sourceTables.length === 1 ? '' : 's'}`);
            subtitleParts.push(`${measures.length} measure${measures.length === 1 ? '' : 's'}`);
        } else if (selectedNode.parent_model) {
            subtitleParts.push(`in ${selectedNode.parent_model}`);
        }

        const defaultTab = nodeType === 'measure' ? 'measures' : 'columns';
        const activeTab = tab || defaultTab;
        const tabs = [
            { id: 'columns', label: 'Columns' },
            { id: 'measures', label: 'Measures' },
            { id: 'lineage', label: 'Lineage' },
        ];

        return (
            <div style={{ display: 'flex', flexDirection: 'column', height: '100%', minHeight: 0 }}>
                {/* Header */}
                <div style={{
                    display: 'flex', alignItems: 'flex-start', gap: 10,
                    padding: '14px 16px 10px',
                    borderBottom: '1px solid var(--border-main)',
                }}>
                    <div style={{
                        width: 30, height: 30, borderRadius: 8, flexShrink: 0,
                        display: 'flex', alignItems: 'center', justifyContent: 'center',
                        background: 'var(--bg-surface-raised)', border: '1px solid var(--border-main)',
                    }}>
                        <TypeIcon size={15} style={{ color: typeTone }} />
                    </div>
                    <div style={{ flex: 1, minWidth: 0 }}>
                        <div style={{
                            fontSize: 14, fontWeight: 700, color: 'var(--text-primary)',
                            fontFamily: 'var(--font-mono, ui-monospace, monospace)',
                            wordBreak: 'break-word', lineHeight: 1.3,
                        }}>
                            {selectedNode.label}
                        </div>
                        <div style={{ display: 'flex', alignItems: 'center', gap: 6, marginTop: 3, fontSize: 11.5, color: 'var(--text-tertiary)', flexWrap: 'wrap' }}>
                            <span>{nodeTypeLabel}</span>
                            {subtitleParts.map(p => <span key={p}>· {p}</span>)}
                            {isBroken && (
                                <span style={{ color: 'var(--color-error)', fontWeight: 600 }}>· broken reference</span>
                            )}
                        </div>
                    </div>
                    <button onClick={onClose} style={closeBtnStyle} title="Close" aria-label="Close details">
                        <X size={16} />
                    </button>
                </div>

                {/* Tabs */}
                <div role="tablist" style={{ display: 'flex', gap: 2, padding: '0 12px', borderBottom: '1px solid var(--border-main)' }}>
                    {tabs.map(t => (
                        <button
                            key={t.id}
                            role="tab"
                            aria-selected={activeTab === t.id}
                            onClick={() => setTab(t.id)}
                            style={{
                                border: 'none', background: 'transparent', cursor: 'pointer',
                                padding: '9px 10px', fontSize: 12.5, fontWeight: 600,
                                color: activeTab === t.id ? 'var(--text-primary)' : 'var(--text-tertiary)',
                                borderBottom: `2px solid ${activeTab === t.id ? 'var(--accent-blue)' : 'transparent'}`,
                                marginBottom: -1,
                            }}
                        >
                            {t.label}
                        </button>
                    ))}
                </div>

                <div style={{ flex: 1, overflow: 'auto', padding: '12px 16px 16px' }}>
                    {/* ── Columns ── */}
                    {activeTab === 'columns' && (
                        <>
                            {nodeType === 'table' && (columns.length > 0 ? (
                                <ColumnTable columns={columns} />
                            ) : (
                                <EmptyHint text="No columns are available for this table in the current snapshot." />
                            ))}
                            {nodeType === 'model' && (sourceTables.length > 0 ? (
                                sourceTables.map((t, i) => (
                                    <Section key={`${t.schema}.${t.table}.${i}`} title={`${t.schema ? `${t.schema}.` : ''}${t.table}`}>
                                        {t.columns?.length > 0
                                            ? <ColumnTable columns={t.columns} />
                                            : <EmptyHint text="No columns recorded for this table." />}
                                    </Section>
                                ))
                            ) : (
                                <EmptyHint text="No source tables were detected for this model." />
                            ))}
                            {nodeType === 'measure' && (
                                <EmptyHint text="Measures don't have columns. See the Measures tab for the formula." />
                            )}
                        </>
                    )}

                    {/* ── Measures ── */}
                    {activeTab === 'measures' && (
                        <>
                            {nodeType === 'measure' ? (
                                <>
                                    <Section title="Formula">
                                        <pre style={{
                                            margin: 0, padding: '10px 12px',
                                            background: 'var(--bg-app)', borderRadius: 6,
                                            border: '1px solid var(--border-main)',
                                            fontSize: 11.5, fontFamily: 'var(--font-mono, ui-monospace, monospace)',
                                            color: 'var(--text-primary)', whiteSpace: 'pre-wrap', wordBreak: 'break-word',
                                            maxHeight: 320, overflow: 'auto',
                                        }}>
                                            {selectedNode.expression || 'No expression found for this measure.'}
                                        </pre>
                                    </Section>
                                    {selectedNode.data_type && <Row label="Data type" value={selectedNode.data_type} />}
                                </>
                            ) : measures.length > 0 ? (
                                measures.map((m, i) => (
                                    <div key={`${m.name || m.label}-${i}`} style={tableCardStyle}>
                                        <BarChart3 size={12} style={{ color: 'var(--color-warning)', flexShrink: 0, marginTop: 2 }} />
                                        <div style={{ flex: 1, minWidth: 0 }}>
                                            <div style={{ fontWeight: 600, fontSize: 12 }}>{m.name || m.label}</div>
                                            {m.expression && (
                                                <code style={{ display: 'block', marginTop: 2, fontSize: 10.5, color: 'var(--text-secondary)', wordBreak: 'break-word' }}>
                                                    {m.expression}
                                                </code>
                                            )}
                                        </div>
                                    </div>
                                ))
                            ) : (
                                <EmptyHint text={`No measures are attached to this ${nodeType} yet.`} />
                            )}
                        </>
                    )}

                    {/* ── Lineage ── */}
                    {activeTab === 'lineage' && (
                        <>
                            {nodeType === 'table' && (
                                <>
                                    <Row label="Table" value={selectedNode.table_name || selectedNode.label} code />
                                    <Row label="Schema" value={selectedNode.schema || 'PUBLIC'} />
                                    <Row label="Comes from" value={selectedNode.source_type || '—'} />
                                    {selectedNode.model_id && <Row label="Model" value={selectedNode.model_label || selectedNode.model_name || selectedNode.model_id} />}
                                    <Row label="Origin" value={<OriginBadge tableName={selectedNode.table_name || selectedNode.label} schema={selectedNode.schema} />} />
                                    <Row label="Status" value={<StatusBadge status={selectedNode.status} />} />
                                </>
                            )}
                            {nodeType === 'model' && (
                                <>
                                    <Row label="Model ID" value={selectedNode.model_id} code />
                                    <Row label="Workspace" value={resolvedWsName !== 'local' ? resolvedWsName : '—'} />
                                    <Row label="Source platform" value={sourceTables[0]?.source_type || selectedNode.source_type || '—'} />
                                    <Row label="Status" value={<StatusBadge status={selectedNode.status} />} />
                                    {selectedNode.description && <Row label="Description" value={selectedNode.description} />}
                                    {sourceTables.length > 0 && (
                                        <div style={{ marginTop: 14 }}>
                                            <Section title="Built from">
                                                {sourceTables.map((t, i) => (
                                                    <div key={`${t.table}-${i}`} style={tableCardStyle}>
                                                        <Database size={12} style={{ color: 'var(--color-success)', flexShrink: 0, marginTop: 2 }} />
                                                        <div style={{ flex: 1, minWidth: 0 }}>
                                                            <div style={{ fontWeight: 600, fontSize: 12 }}>{t.table}</div>
                                                            <div style={{ fontSize: 10.5, color: 'var(--text-tertiary)' }}>
                                                                {[t.schema, t.source_type].filter(Boolean).join(' · ')}
                                                            </div>
                                                        </div>
                                                    </div>
                                                ))}
                                            </Section>
                                        </div>
                                    )}
                                </>
                            )}
                            {nodeType === 'measure' && (
                                <>
                                    <Row label="Measure" value={selectedNode.label} code />
                                    <Row label="Model" value={selectedNode.parent_model || '—'} />
                                    {selectedNode.dataset && <Row label="Table" value={selectedNode.dataset} />}
                                    <Row label="Status" value={<StatusBadge status={selectedNode.status} />} />
                                </>
                            )}
                        </>
                    )}
                </div>
            </div>
        );
    }

    return null;
}

// ── Shared sub-components ──

function ColumnTable({ columns }) {
    return (
        <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: 12 }}>
            <thead>
                <tr>
                    <th style={colThStyle}>Column</th>
                    <th style={{ ...colThStyle, textAlign: 'right' }}>Type</th>
                </tr>
            </thead>
            <tbody>
                {columns.map((col, i) => {
                    const colName = typeof col === 'string'
                        ? col
                        : (col.unique_name || col.label || col.name || col.column_name || '');
                    const colType = typeof col === 'string' ? '' : (col.data_type || col.type || '');
                    return (
                        <tr key={(typeof col === 'object' && col.id) || colName || i}>
                            <td style={{ ...colTdStyle, color: 'var(--text-primary)', wordBreak: 'break-word' }}>{colName}</td>
                            <td style={{ ...colTdStyle, textAlign: 'right', color: 'var(--text-tertiary)', fontFamily: 'var(--font-mono, ui-monospace, monospace)', fontSize: 11 }}>{colType}</td>
                        </tr>
                    );
                })}
            </tbody>
        </table>
    );
}

function Section({ title, children }) {
    return (
        <div style={{ marginBottom: 14 }}>
            <div style={{
                fontSize: 9, fontWeight: 800,
                textTransform: 'uppercase',
                letterSpacing: '.06em',
                color: 'var(--text-tertiary)',
                marginBottom: 8,
                padding: '0 0 4px 0',
            }}>
                {title}
            </div>
            {children}
        </div>
    );
}

function Row({ label, value, code }) {
    return (
        <div style={{
            display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start',
            padding: '8px 0',
            borderBottom: '1px solid var(--border-color)',
            fontSize: 12,
            gap: 8,
        }}>
            <span style={{ color: 'var(--text-secondary)', fontWeight: 600, flexShrink: 0 }}>{label}</span>
            <div style={{
                color: 'var(--text-primary)',
                textAlign: 'right',
                maxWidth: '60%',
                overflow: 'auto',
                ...(code && {
                    fontFamily: 'monospace',
                    fontSize: 11,
                    background: 'var(--bg-app)',
                    padding: '4px 6px',
                    borderRadius: 4,
                    border: '1px solid var(--border-color)',
                    color: 'var(--accent-blue)',
                    letterSpacing: '.2px',
                })
            }}>
                {value}
            </div>
        </div>
    );
}

function StatusBadge({ status }) {
    const isBroken = status === 'broken';
    return (
        <span style={{
            display: 'inline-flex', alignItems: 'center', gap: 4,
            padding: '2px 8px',
            borderRadius: 10,
            fontSize: 10, fontWeight: 700,
            background: isBroken ? 'rgba(239,68,68,.15)' : 'rgba(34,197,94,.15)',
            color: isBroken ? '#EF4444' : '#22C55E',
            border: `1px solid ${isBroken ? 'rgba(239,68,68,.3)' : 'rgba(34,197,94,.3)'}`,
        }}>
            {isBroken ? '✕ Broken' : '✓ Valid'}
        </span>
    );
}

function OriginBadge({ tableName, schema }) {
    const fullName = `${schema ? `${schema}.` : ''}${tableName || ''}`.toLowerCase();
    const isSystem =
        fullName.startsWith('information_schema.') ||
        fullName.startsWith('pg_') ||
        fullName.startsWith('sqlite_') ||
        fullName.startsWith('duckdb_') ||
        fullName.startsWith('sys.') ||
        fullName.startsWith('__');

    return (
        <span style={{
            display: 'inline-flex',
            alignItems: 'center',
            gap: 4,
            padding: '2px 8px',
            borderRadius: 10,
            fontSize: 10,
            fontWeight: 700,
            background: isSystem ? 'rgba(245,158,11,.15)' : 'rgba(99,102,241,.15)',
            color: isSystem ? '#F59E0B' : 'var(--accent-blue)',
            border: `1px solid ${isSystem ? 'rgba(245,158,11,.35)' : 'rgba(99,102,241,.35)'}`,
        }}>
            {isSystem ? 'System Generated' : 'Original Schema'}
        </span>
    );
}


function EmptyHint({ text }) {
    return (
        <div style={{
            border: '1px dashed var(--border-color)',
            borderRadius: 8,
            padding: '10px 12px',
            fontSize: 11,
            color: 'var(--text-tertiary)',
            background: 'var(--bg-app)',
        }}>
            {text}
        </div>
    );
}

import { useState, memo } from 'react';
import {
    ChevronRight, ChevronDown,
    Folder, FolderOpen,
    FileCode, FileJson, FileText, FileType,
    Database, Settings, Globe, Hash,
} from 'lucide-react';

const ICON_MAP = {
    folder: Folder,
    python: FileCode,
    yaml: FileType,
    json: FileJson,
    sql: Database,
    markdown: FileText,
    config: Settings,
    javascript: FileCode,
    typescript: FileCode,
    css: Globe,
    html: Globe,
    text: FileText,
    file: Hash,
};

const COLOR_MAP = {
    python: '#3B82F6',
    yaml: '#F59E0B',
    json: '#8B5CF6',
    sql: '#10B981',
    markdown: '#6B7280',
    config: '#EF4444',
    javascript: '#EAB308',
    typescript: '#3B82F6',
    css: '#EC4899',
    html: '#F97316',
    folder: '#818CF8',
};

function formatSize(bytes) {
    if (bytes < 1024) return `${bytes} B`;
    if (bytes < 1048576) return `${(bytes / 1024).toFixed(1)} KB`;
    return `${(bytes / 1048576).toFixed(1)} MB`;
}

function formatDate(iso) {
    if (!iso) return '';
    try {
        return new Date(iso).toLocaleDateString(undefined, {
            year: 'numeric', month: 'short', day: 'numeric',
            hour: '2-digit', minute: '2-digit',
        });
    } catch { return ''; }
}

const UUID_REGEX = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

function formatNodeName(name) {
    if (!name) return '';
    if (UUID_REGEX.test(name)) {
        return `Workspace (${name.slice(0, 8)}…)`;
    }
    return name;
}

/**
 * A single tree node (file or folder).
 */
const TreeNode = memo(function TreeNode({
    node, depth, onFileClick, selectedPath,
}) {
    const [expanded, setExpanded] = useState(depth < 1);

    if (!node) return null;

    const isDir = node.type === 'directory';
    const isSelected = node.path === selectedPath;
    const IconComp = isDir
        ? (expanded ? FolderOpen : Folder)
        : (ICON_MAP[node.icon] || FileText);
    const iconColor = isDir
        ? (expanded ? 'var(--accent-blue)' : 'var(--text-tertiary)')
        : (COLOR_MAP[node.icon] || 'var(--text-tertiary)');

    const handleClick = () => {
        if (isDir) {
            setExpanded(e => !e);
        } else {
            onFileClick(node.path);
        }
    };

    const displayName = formatNodeName(node.name);

    return (
        <>
            <div
                onClick={handleClick}
                title={
                    isDir
                        ? node.name
                        : `${node.name}\n${formatSize(node.size || 0)}\n${formatDate(node.modified)}`
                }
                style={{
                    display: 'flex', alignItems: 'center', gap: 6,
                    padding: '5px 8px 5px ' + (10 + depth * 14) + 'px',
                    margin: '1px 6px',
                    cursor: 'pointer',
                    fontSize: 11.5,
                    color: isSelected ? 'var(--accent-blue)' : 'var(--text-primary)',
                    background: isSelected
                        ? 'var(--color-accent-faint)'
                        : 'transparent',
                    border: isSelected ? '1px solid var(--accent-blue)' : '1px solid transparent',
                    borderRadius: 6,
                    transition: 'all .14s ease',
                    userSelect: 'none',
                    overflow: 'hidden',
                    whiteSpace: 'nowrap',
                }}
                onMouseEnter={e => {
                    if (!isSelected) e.currentTarget.style.background = 'var(--bg-surface-hover)';
                }}
                onMouseLeave={e => {
                    if (!isSelected) e.currentTarget.style.background = 'transparent';
                }}
            >
                {/* Chevron for directories */}
                {isDir ? (
                    expanded
                        ? <ChevronDown size={12} style={{ flexShrink: 0, opacity: .6, color: 'var(--text-tertiary)' }} />
                        : <ChevronRight size={12} style={{ flexShrink: 0, opacity: .6, color: 'var(--text-tertiary)' }} />
                ) : (
                    <span style={{ width: 12, flexShrink: 0 }} />
                )}

                <IconComp
                    size={14}
                    style={{ flexShrink: 0, color: iconColor }}
                />

                <span style={{
                    overflow: 'hidden', textOverflow: 'ellipsis',
                    fontWeight: isSelected ? 600 : isDir ? 600 : 450,
                    minWidth: 0,
                    flex: 1,
                    letterSpacing: '-0.01em',
                }}>
                    {displayName}
                </span>

                {/* File size badge */}
                {!isDir && node.size != null && (
                    <span style={{
                        fontSize: 9.5, opacity: .5,
                        flexShrink: 0,
                        marginLeft: 4,
                        fontFamily: 'monospace',
                    }}>
                        {formatSize(node.size)}
                    </span>
                )}
            </div>

            {/* Children */}
            {isDir && expanded && node.children && (
                <div>
                    {node.children.map((child, i) => (
                        <TreeNode
                            key={child.path || i}
                            node={child}
                            depth={depth + 1}
                            onFileClick={onFileClick}
                            selectedPath={selectedPath}
                        />
                    ))}
                </div>
            )}
        </>
    );
});

/**
 * FileTreePanel — the left sidebar showing the repo file tree.
 */
export default function FileTreePanel({ tree, onFileClick, selectedPath }) {
    if (!tree) {
        return (
            <div style={{ padding: 16, fontSize: 12, color: 'var(--text-tertiary)' }}>
                No tree data available.
            </div>
        );
    }

    return (
        <div style={{ paddingTop: 6, paddingBottom: 12 }}>
            {/* Section header */}
            <div style={{
                padding: '6px 12px',
                fontSize: 10, fontWeight: 700,
                textTransform: 'uppercase',
                letterSpacing: '0.08em',
                color: 'var(--text-tertiary)',
            }}>
                Explorer
            </div>

            {/* Render the root's children (skip root node itself) */}
            {tree.children
                ? tree.children.map((child, i) => (
                    <TreeNode
                        key={child.path || i}
                        node={child}
                        depth={0}
                        onFileClick={onFileClick}
                        selectedPath={selectedPath}
                    />
                ))
                : <TreeNode
                    node={tree}
                    depth={0}
                    onFileClick={onFileClick}
                    selectedPath={selectedPath}
                />
            }
        </div>
    );
}

