        statusBorder = 'var(--er-node-border-hover)';
    }

    const cardShadow = selected
        ? '0 0 0 2px #F59E0B, var(--shadow-lg)'
        : hovered
            ? 'var(--shadow-md), 0 4px 16px rgba(0, 0, 0, 0.15)'
