function MetricList({ entries = [], renderDetail }) {
  const items = Array.isArray(entries) ? entries : [];
  if (items.length === 0) return null;
  return (
    <ul style={{ listStyle: 'none', margin: 0, padding: 0, display: 'flex', flexDirection: 'column', gap: 8 }}>
      {items.map((entry, index) => (
        <li
          key={`${entry.name}-${index}`}
          style={{
            padding: '10px 12px',
            borderRadius: 6,
            background: 'var(--bg-surface-raised)',
            fontSize: 13,
          }}
        >
          <div style={{ fontWeight: 600, color: 'var(--text-primary)' }}>{entry.name}</div>
          {renderDetail(entry)}
        </li>
      ))}
    </ul>
  );
}

function AdvisoryDetail(entry) {
  if (!entry.advisory_msgs || entry.advisory_msgs.length === 0) return null;
  return (
    <div style={{ marginTop: 4, color: 'var(--text-secondary)', fontStyle: 'italic' }}>
      {entry.advisory_msgs.join(' ')}
    </div>
  );
}

function AiAssistedDetail(entry) {
  const bits = [];
  if (typeof entry.confidence === 'number') {
    bits.push(`AI's self-reported confidence: ${Math.round(entry.confidence * 100)}%`);
  }
  if (entry.risky) {
    bits.push('Matches a pattern that has caused problems before — review closely.');
  }
  if (entry.advisory_msgs?.length) bits.push(...entry.advisory_msgs);
  if (!bits.length) return null;
  return (
    <div style={{ marginTop: 4, color: 'var(--text-secondary)', fontStyle: 'italic' }}>
      {bits.join(' ')}
    </div>
  );
}

function CrashedNotice({ unavailable, error }) {
  // Short, plain-language line by default; the longer technical
  // explanation (data.error, from run_report_service.py) stays available
  // one click away via "Why?" rather than always-visible body text.
  const [showDetails, setShowDetails] = useState(false);
  const shortMessage = unavailable
    ? "✅ This run completed successfully. (Detailed breakdown isn't available right now — try Raw Report below, or Download Raw .md.)"
    : '❌ This run failed. See Raw Report for details.';

  return (
    <div style={{ padding: 16 }}>
      <p style={{ color: unavailable ? 'var(--text-primary)' : 'var(--color-error)', margin: 0, fontWeight: 600 }}>
        {shortMessage}
      </p>
      {error && (
        <>
          <button
            type="button"
            onClick={() => setShowDetails((prev) => !prev)}
            style={{
              marginTop: 6,
              background: 'none',
              border: 'none',
              padding: 0,
              color: 'var(--accent-blue)',
              fontSize: 12,
              fontWeight: 600,
              cursor: 'pointer',
              textDecoration: 'underline',
            }}
          >
            {showDetails ? 'Hide details' : 'Why?'}
          </button>
          {showDetails && (
            <p style={{ marginTop: 8, color: unavailable ? 'var(--text-secondary)' : 'var(--color-error)', fontSize: 12, lineHeight: 1.5 }}>
              {error}
            </p>
          )}
        </>
      )}
    </div>
  );
}

function DroppedSection({ groups = [] }) {
  const groupList = Array.isArray(groups) ? groups : [];
  if (groupList.length === 0) return null;
  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 14 }}>
      {groupList.map((group) => (
        <div key={group.stage}>
