export default function SecretsPanel() {
  const [secrets, setSecrets] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [modalOpen, setModalOpen] = useState(false);
  const [editKey, setEditKey] = useState('');
  const [deletingKey, setDeletingKey] = useState(null);   // key pending confirm
  const [deletingInFlight, setDeletingInFlight] = useState(null); // key being deleted

  const refresh = useCallback(async () => {
    setLoading(true);
    setError('');
    try {
      const data = await api.listSecrets();
      setSecrets(Array.isArray(data) ? data : []);
    } catch (err) {
      setError(err?.message || 'Failed to load secrets.');
      setSecrets([]);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => { refresh(); }, [refresh]);

  const openAdd = () => { setEditKey(''); setModalOpen(true); };
  const openEdit = (key) => { setEditKey(key); setModalOpen(true); };

  const handleSaved = (result) => {
    setSecrets(prev => {
      const existing = prev.find(s => s.key === result.key);
      if (existing) return prev.map(s => s.key === result.key ? result : s);
      return [...prev, result].sort((a, b) => a.key.localeCompare(b.key));
    });
  };

  const handleDelete = async (key) => {
    setDeletingInFlight(key);
    setDeletingKey(null);
    try {
      await api.deleteSecret(key);
      setSecrets(prev => prev.filter(s => s.key !== key));
    } catch (err) {
      setError(err?.message || `Failed to delete '${key}'.`);
    } finally {
      setDeletingInFlight(null);
    }
  };

  return (
    <div style={{ marginBottom: 32 }}>
      {/* Section header */}
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 12, marginBottom: 16 }}>
        <div>
          <h2 style={{ fontSize: 15, fontWeight: 600, margin: 0, color: 'var(--text-primary)' }}>API Secrets</h2>
          <p style={{ fontSize: 12, margin: '4px 0 0', color: 'var(--text-secondary)' }}>
            Store API keys for LLM providers and third-party integrations. Values are encrypted at rest and never exposed after saving.
          </p>
        </div>
        <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
          <button
            onClick={refresh}
            disabled={loading}
            title="Refresh"
            style={{ background: 'none', border: 'none', cursor: 'pointer', padding: 4, color: 'var(--accent-blue)', display: 'flex', alignItems: 'center' }}
          >
            <RefreshCw size={15} className={loading ? 'animate-spin' : ''} />
          </button>
          <button
            onClick={openAdd}
            style={{
              display: 'flex', alignItems: 'center', gap: 6,
              background: 'var(--accent-blue)', color: '#fff',
              border: 'none', borderRadius: 8, padding: '7px 12px',
              fontSize: 12, fontWeight: 600, cursor: 'pointer',
            }}
          >
            <Plus size={13} />
            Add Secret
          </button>
        </div>
      </div>

      {/* Error banner */}
      {error && (
        <div style={{ marginBottom: 12, display: 'flex', alignItems: 'center', gap: 8, padding: '10px 12px', borderRadius: 8, background: 'var(--color-error-bg)', border: '1px solid var(--color-error)30', color: 'var(--color-error)', fontSize: 12 }}>
          <AlertCircle size={13} />
          {error}
        </div>
      )}

      {/* Secrets table */}
      <div style={{ border: '1px solid var(--border-main)', borderRadius: 12, overflow: 'hidden', background: 'var(--bg-surface)' }}>
        <table style={{ width: '100%', borderCollapse: 'collapse' }}>
          <thead>
            <tr style={{ background: 'var(--bg-surface-raised)' }}>
              <th style={{ textAlign: 'left', padding: '11px 16px', fontSize: 11, color: 'var(--text-secondary)', textTransform: 'uppercase', letterSpacing: '0.06em', fontWeight: 700 }}>Key</th>
              <th style={{ textAlign: 'left', padding: '11px 16px', fontSize: 11, color: 'var(--text-secondary)', textTransform: 'uppercase', letterSpacing: '0.06em', fontWeight: 700 }}>Value</th>
              <th style={{ textAlign: 'left', padding: '11px 16px', fontSize: 11, color: 'var(--text-secondary)', textTransform: 'uppercase', letterSpacing: '0.06em', fontWeight: 700 }}>Last Updated</th>
              <th style={{ textAlign: 'right', padding: '11px 16px', fontSize: 11, color: 'var(--text-secondary)', textTransform: 'uppercase', letterSpacing: '0.06em', fontWeight: 700 }}>Actions</th>
            </tr>
          </thead>
          <tbody>
            {loading ? (
              <tr>
                <td colSpan="4" style={{ padding: '20px 16px', color: 'var(--text-tertiary)', fontSize: 12 }}>Loading secrets…</td>
              </tr>
            ) : secrets.length === 0 ? (
              <tr>
                <td colSpan="4" style={{ padding: '28px 16px', textAlign: 'center' }}>
                  <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 8 }}>
                    <KeyRound size={28} color="var(--text-tertiary)" />
                    <span style={{ color: 'var(--text-tertiary)', fontSize: 13 }}>No secrets stored yet.</span>
                    <button
                      onClick={openAdd}
                      style={{ background: 'none', border: 'none', color: 'var(--accent-blue)', cursor: 'pointer', fontSize: 12, fontWeight: 600, padding: 0 }}
                    >
                      Add your first secret →
                    </button>
                  </div>
                </td>
              </tr>
            ) : (
              secrets.map(secret => (
                <tr key={secret.key} style={{ borderTop: '1px solid var(--border-main)' }}>
                  {/* Key */}
                  <td style={{ padding: '12px 16px' }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                      <KeyRound size={13} color="var(--text-tertiary)" />
                      <span style={{ fontFamily: 'monospace', fontSize: 13, fontWeight: 600, color: 'var(--text-primary)' }}>
                        {secret.key}
                      </span>
                    </div>
                  </td>

                  {/* Hint */}
                  <td style={{ padding: '12px 16px' }}>
                    <span style={{
                      fontFamily: 'monospace', fontSize: 12,
                      color: 'var(--text-secondary)',
                      background: 'var(--bg-surface-raised)',
                      padding: '3px 8px', borderRadius: 5,
                      border: '1px solid var(--border-light)',
                      letterSpacing: 2,
                    }}>
                      {secret.hint}
                    </span>
                  </td>

                  {/* Updated */}
                  <td style={{ padding: '12px 16px', fontSize: 12, color: 'var(--text-tertiary)' }}>
                    {formatRelative(secret.updated_at)}
                  </td>

                  {/* Actions */}
                  <td style={{ padding: '12px 16px', textAlign: 'right' }}>
                    {deletingKey === secret.key ? (
                      // Inline confirm state
                      <div style={{ display: 'inline-flex', alignItems: 'center', gap: 6 }}>
                        <span style={{ fontSize: 11, color: 'var(--text-secondary)' }}>Delete?</span>
                        <button
                          onClick={() => handleDelete(secret.key)}
                          disabled={deletingInFlight === secret.key}
                          style={{ fontSize: 11, fontWeight: 600, padding: '4px 10px', borderRadius: 6, background: 'var(--color-error)', color: '#fff', border: 'none', cursor: 'pointer' }}
                        >
                          {deletingInFlight === secret.key ? '…' : 'Yes, delete'}
                        </button>
                        <button
                          onClick={() => setDeletingKey(null)}
                          style={{ fontSize: 11, padding: '4px 10px', borderRadius: 6, background: 'transparent', color: 'var(--text-secondary)', border: '1px solid var(--border-main)', cursor: 'pointer' }}
                        >
                          Cancel
                        </button>
                      </div>
                    ) : (
                      <div style={{ display: 'inline-flex', alignItems: 'center', gap: 6 }}>
                        <button
                          onClick={() => openEdit(secret.key)}
                          title="Update value"
                          style={{ padding: '5px 10px', borderRadius: 6, border: '1px solid var(--border-main)', background: 'transparent', color: 'var(--text-secondary)', fontSize: 12, cursor: 'pointer', fontWeight: 500 }}
                        >
                          Update
                        </button>
                        <button
                          onClick={() => setDeletingKey(secret.key)}
                          title="Delete secret"
                          style={{ padding: 5, borderRadius: 6, border: 'none', background: 'transparent', color: 'var(--color-error)', cursor: 'pointer', display: 'flex', alignItems: 'center' }}
                        >
                          <Trash2 size={14} />
                        </button>
                      </div>
                    )}
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>

      {/* Add / Edit modal */}
      <SecretModal
        open={modalOpen}
        onClose={() => setModalOpen(false)}
        onSaved={handleSaved}
        editKey={editKey}
      />
    </div>
  );
}

import { useState, useEffect, useRef } from 'react';
import {
    Clock,
    Radio,
    RefreshCw,
} from 'lucide-react';
import { api } from '../utils/api';
import { useLogs } from '../context/LogsContext';
import useProjectSync from '../hooks/useProjectSync';
import { useSyncStatusStore } from '../context/SyncStatusContext';

// The timezone chosen in Settings (falls back to the browser's own).
function preferredTimeZone() {
    try {
        return localStorage.getItem('semabridge-timezone') || Intl.DateTimeFormat().resolvedOptions().timeZone || 'UTC';
    } catch {
        return 'UTC';
    }
}

function extractRunError(run) {
    const direct = [run?.error_message, run?.error].filter(Boolean).join(' | ');
    if (direct) return direct;

    const summaryErrors = run?.summary?.errors;
    if (Array.isArray(summaryErrors) && summaryErrors.length > 0) {
        return String(summaryErrors[0]?.message || summaryErrors[0]?.error_type || '').trim();
    }

    const nestedErrors = run?.results?.[0]?.summary?.errors;
    if (Array.isArray(nestedErrors) && nestedErrors.length > 0) {
        return String(nestedErrors[0]?.message || nestedErrors[0]?.error_type || '').trim();
    }

    return '';
}

export default function StatusBar({ variant = 'bar', collapsed = false }) {
    // Remove showSyncBar, always render the bar
    const [connected, setConnected] = useState(false);
    const { wsConnected, addLog } = useLogs();
    const seenStatusRef = useRef(new Map());
    const { runs, currentSyncId } = useSyncStatusStore();
    const {
        status: currentSyncStatus,
        progress,
        indeterminate,
        warning,
    } = useProjectSync();

    // No-op: always show the bar, only sync status is conditional

    // Replicating PyQt ProgressBar behavior + Health Checking
    useEffect(() => {
        const checkHealth = async () => {
            try {
                const res = await api.getHealth();
                setConnected(res.status === 'ok');
            } catch (err) {
                setConnected(false);
            }
        };

        checkHealth();
        const interval = setInterval(checkHealth, 5000);
        return () => clearInterval(interval);
    }, []);

    useEffect(() => {
        runs.forEach((run) => {
            const runId = String(run?.run_id || run?.id || '');
            if (!runId) return;
            const status = String(run?.status || '').toLowerCase();
            const previous = seenStatusRef.current.get(runId);
            if (previous === 'running' && status && status !== 'running') {
                const projectName = run?.project_name || run?.project_id || 'project';
                if (status === 'success') {
                    addLog('success', 'Sync', `${projectName} sync completed successfully.`);
                } else if (status === 'warning' || status === 'partial') {
                    addLog('warning', 'Sync', `${projectName} sync completed with warnings.`);
                } else {
                    const reason = extractRunError(run);
                    addLog('error', 'Sync', `${projectName} sync failed${reason ? `: ${reason}` : '.'}`);
                }
            }
            seenStatusRef.current.set(runId, status);
        });
    }, [runs, addLog]);


    const latestSuccessfulRun = runs.find((run) => {
        const status = String(run?.status || '').toLowerCase();
        return status === 'success';
    });

    let lastSyncLabel = 'Never';
    if (latestSuccessfulRun) {
        const ts = latestSuccessfulRun.completed_at || latestSuccessfulRun.started_at;
        if (ts) {
            const dateStr = ts.includes('Z') || ts.includes('+') ? ts : `${ts}Z`;
            const d = new Date(dateStr);
            if (!isNaN(d.getTime())) {
                lastSyncLabel = d.toLocaleString(undefined, {
                    timeZone: preferredTimeZone(),
                    year: 'numeric',
                    month: 'short',
                    day: 'numeric',
                    hour: '2-digit',
                    minute: '2-digit',
                    second: '2-digit',
                    hour12: true
                });
            }
        }
    }


    const safeProgress = progress ?? 0;
    const isSyncing = (currentSyncStatus === 'running' || currentSyncStatus === 'starting' || currentSyncStatus === 'pending') && currentSyncId;
    const isStarting = safeProgress < 5;
    const transitionStyle = isStarting ? 'none' : 'width 1s linear';

    if (variant === 'sidebar') {
        const tone = !connected ? 'var(--color-danger)' : isSyncing ? 'var(--accent-blue)' : 'var(--color-success)';
        const text = !connected ? 'API unreachable' : isSyncing ? 'Sync running…' : 'All systems OK';
        return (
            <div
                className="sidebar-status"
                role="status"
                title={`${connected ? 'API connected' : 'API unreachable'} \u00b7 Last sync: ${lastSyncLabel}`}
            >
                <span className="status-dot-wrap">
                    {isSyncing
                        ? <RefreshCw size={11} className="animate-spin" style={{ color: tone }} />
                        : <span className="w-2 h-2 rounded-full" style={{ background: tone, display: 'inline-block' }} />}
                </span>
                {!collapsed && (
                    <span className="nav-label" style={{ display: 'flex', flexDirection: 'column', lineHeight: 1.3, minWidth: 0 }}>
                        <span style={{ color: connected ? 'var(--text-secondary)' : tone, fontWeight: 600 }}>{text}</span>
                        <span style={{ fontSize: 10.5, color: 'var(--text-tertiary)', overflow: 'hidden', textOverflow: 'ellipsis' }}>Last sync: {lastSyncLabel}</span>
                    </span>
                )}
            </div>
        );
    }

    // The bar is always visible; only the sync progress section is conditional
    return (
        <footer
            className="theme-transition flex items-center justify-between px-4 h-8 shrink-0 text-[11px] select-none"
            style={{
                background: 'var(--bg-surface)',
                borderTop: '1px solid var(--border-main)',
                color: 'var(--text-secondary)',
                zIndex: 50,
            }}
        >
            {/* Left section */}
            <div className="flex items-center gap-4">
                <div className="flex items-center gap-1.5">
                    <div className="relative flex items-center justify-center w-4 h-4">
                        <span
                            className={`absolute w-2 h-2 rounded-full ${connected ? 'status-pulse status-pulse-success' : 'status-pulse status-pulse-danger'}`}
                        />
                        <span
                            className="relative w-2 h-2 rounded-full"
                            style={{ background: connected ? 'var(--color-success)' : 'var(--color-danger)' }}
                        />
                    </div>
                    <span className="flex items-center gap-1 font-medium" style={{ color: connected ? 'var(--color-success)' : 'var(--color-danger)' }}>
                        {connected ? 'API Connected' : 'API Unreachable'}
                    </span>
                </div>



                {isSyncing && (
                    <div className="flex items-center gap-3 ml-4">
                        <span className="text-indigo-400 font-bold animate-pulse inline-flex items-center gap-1">
                            <RefreshCw size={11} className="animate-spin" />
                            Sync in progress
                        </span>
                    </div>
                )}
            </div>

            {/* Right section */}
            <div className="flex items-center gap-4">
                <div className="flex items-center gap-1">
                    <Clock size={11} className="text-slate-500" />
                    <span>Last sync: {lastSyncLabel}</span>
                </div>
            </div>
        </footer>
    );
}

import { useEffect, useMemo, useState } from 'react';
import { Loader2, Plus, RotateCcw, X } from 'lucide-react';
import Modal from './common/Modal';
import { api } from '../utils/api';

const buttonBase = {
  display: 'inline-flex',
  alignItems: 'center',
  justifyContent: 'center',
  gap: 6,
  padding: '8px 12px',
  borderRadius: 8,
  fontSize: 12,
  fontWeight: 700,
  cursor: 'pointer',
};

function normalizeSynonyms(values) {
  const result = [];
  const seen = new Set();
  (values || []).forEach((value) => {
    const text = String(value || '').trim();
    const key = text.toLowerCase();
    if (text && !seen.has(key)) {
      seen.add(key);
      result.push(text);
    }
  });
  return result;
}

export default function SynonymEditModal({
  open,
  onClose,
  projectId,
  modelName,
  tableName,
  columnName,
  currentSynonyms = [],
  currentDescription = '',
  currentRules = [],
  currentSteward = '',
  onSave,
}) {
  const [synonyms, setSynonyms] = useState([]);
  const [description, setDescription] = useState('');
  const [businessRules, setBusinessRules] = useState([]);
  const [ruleInput, setRuleInput] = useState('');
  const [dataSteward, setDataSteward] = useState('');
  const [inputValue, setInputValue] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const identity = useMemo(() => ({
    projectId,
    modelName,
    tableName,
    columnName,
  }), [projectId, modelName, tableName, columnName]);

  useEffect(() => {
    if (!open) return;
    setSynonyms(normalizeSynonyms(currentSynonyms));
    setDescription(currentDescription || '');
    setBusinessRules(Array.isArray(currentRules) ? currentRules : []);
    setDataSteward(currentSteward || '');
    setInputValue('');
    setRuleInput('');
    setError('');

    // Fetch live backend override values if available
    if (projectId && modelName && tableName && columnName) {
      api.getSynonymOverride(identity)
        .then((res) => {
          if (res) {
            if (Array.isArray(res.synonyms) && res.synonyms.length > 0) {
              setSynonyms(normalizeSynonyms(res.synonyms));
            }
            if (res.description) setDescription(res.description);
            if (Array.isArray(res.business_rules) && res.business_rules.length > 0) {
              setBusinessRules(res.business_rules);
            }
            if (res.data_steward) setDataSteward(res.data_steward);
          }
        })
        .catch(() => {});
    }
  }, [open, currentSynonyms, currentDescription, currentRules, currentSteward, identity]);

  function addSynonym(raw = inputValue) {
    const parts = String(raw || '')
      .split(',')
      .map((part) => part.trim())
      .filter(Boolean);
    if (!parts.length) return;
    setSynonyms((prev) => normalizeSynonyms([...prev, ...parts]));
    setInputValue('');
  }

  function handleKeyDown(event) {
    if (event.key === 'Enter' || event.key === ',') {
      event.preventDefault();
      addSynonym();
    }
  }

  function removeSynonym(value) {
    setSynonyms((prev) => prev.filter((item) => item !== value));
  }

  function addRule() {
    const text = String(ruleInput || '').trim();
    if (!text) return;
    if (!businessRules.includes(text)) {
      setBusinessRules((prev) => [...prev, text]);
    }
    setRuleInput('');
  }

  function removeRule(index) {
    setBusinessRules((prev) => prev.filter((_, i) => i !== index));
  }

  async function save() {
    setLoading(true);
    setError('');
    try {
      const response = await api.saveSynonymOverride({
        project_id: projectId,
        model_name: modelName,
        table_name: tableName,
        column_name: columnName,
        synonyms,
        // '' (not null) so clearing the field actually clears it server-side.
        description: description.trim(),
        business_rules: businessRules,
        data_steward: dataSteward.trim(),
      });
      onSave?.(response?.synonyms || synonyms, {
        description: response?.description || description,
        business_rules: response?.business_rules || businessRules,
        data_steward: response?.data_steward || dataSteward,
      });
      onClose?.();
    } catch (err) {
      setError(err?.message || 'Failed to save ontology metadata.');
    } finally {
      setLoading(false);
    }
  }

  async function reset() {
    setLoading(true);
    setError('');
    try {
      await api.deleteSynonymOverride(identity);
      onSave?.([], { description: '', business_rules: [], data_steward: '' });
      onClose?.();
    } catch (err) {
      setError(err?.message || 'Failed to reset metadata.');
    } finally {
      setLoading(false);
    }
  }

  const footer = (
    <>
      <button
        type="button"
        onClick={onClose}
        disabled={loading}
        style={{ ...buttonBase, border: '1px solid var(--border-main)', background: 'var(--bg-surface-raised)', color: 'var(--text-secondary)' }}
      >
        Cancel
      </button>
      <button
        type="button"
        onClick={reset}
        disabled={loading}
        style={{ ...buttonBase, border: '1px solid rgba(239, 68, 68, 0.45)', background: 'rgba(239, 68, 68, 0.10)', color: 'var(--color-error)' }}
      >
        <RotateCcw size={13} />
        Reset
