      <div style={{ ...CARD, flexDirection: 'row', alignItems: 'center', color: 'var(--text-secondary)', fontSize: 13 }} aria-live="polite">
        <Loader2 size={16} className="animate-spin" style={{ animation: 'spin 1s linear infinite' }} />
        Finding governed metrics and running on {engineLabel(target)}…
      </div>
    );
  }

  if (status === 'error') {
    return (
      <div role="alert" style={{ ...CARD, borderColor: 'var(--color-error)', background: 'var(--color-error-bg)' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 8, flexWrap: 'wrap' }}>
          <AlertTriangle size={16} color="var(--color-error)" />
          <b style={{ fontSize: 13.5, color: 'var(--text-primary)' }}>
            {errorStage === 'run'
              ? 'The query could not be run'
              : String(error || '').toLowerCase().includes('refus') || String(error || '').toLowerCase().includes('reject')
                ? 'Query refused by safety guard'
                : candidateViews.length > 0
                  ? 'Several models can answer this'
                  : cortexUnavailable ? 'Cortex unavailable' : 'The question could not be interpreted'}
          </b>
          <span style={{ flex: 1 }} />
          {cortexUnavailable && onOfflineDraft && (
            <button
              type="button"
              style={{ ...BTN, borderColor: 'var(--accent-blue)', color: 'var(--accent-blue)' }}
              onClick={onOfflineDraft}
            >
              Generate offline draft
            </button>
          )}
          <button type="button" style={BTN} onClick={onRetry}>
            <RotateCcw size={13} /> Try again
          </button>
        </div>
        <div style={{ fontSize: 12.5, color: 'var(--text-secondary)', wordBreak: 'break-word' }}>{error}</div>
        {candidateViews.length > 0 && onPickView && (
          <div style={{ display: 'flex', alignItems: 'center', gap: 6, flexWrap: 'wrap' }}>
            <span style={{ fontSize: 12, color: 'var(--text-secondary)' }}>Ask this view:</span>
            {candidateViews.map((v) => (
              <button key={v} type="button" style={BTN} title={v} onClick={() => onPickView(v)}>
                {viewTail(v)}
              </button>
            ))}
          </div>
        )}
        <AnsweredBy plan={plan} />
        {plan?.generated_sql && <HowAnswered plan={plan} result={null} target={target} />}
      </div>
    );
  }

  const usesCertified = (plan?.detected_metrics || []).length > 0;
  const allWarnings = [
    ...(plan?.warnings || []),
    ...(result?.warnings || []),
  ];
  const hasCertifiedSource = Boolean(plan?.is_verified_query || plan?.has_certified_metric || plan?.certified_source || result?.certified_source);
  const isCertifiedAnswer = Boolean(
    (result?.certified || hasCertifiedSource) &&
    allWarnings.length === 0 &&
    result && result.success !== false
  );
  const queryPath = result?.query_path || (usesCertified ? 'semantic view' : (plan?.route === 'cortex' ? 'free-form SQL' : 'semantic view'));
  const certified = certifyState === 'done' || isCertifiedAnswer;
  // Only answers computed by a live warehouse can be certified, never preview rows.
  // (0 rows is a valid answer; the backend also requires a recorded real run.)
  const canCertify = Boolean(result && result.success !== false && !result.is_simulated);

  return (
    <div style={CARD}>
      <div style={{ display: 'flex', alignItems: 'center', gap: 8, flexWrap: 'wrap' }}>
        <b style={{ fontSize: 14, color: 'var(--text-primary)' }}>{answerTitle(plan, question)}</b>
        {isCertifiedAnswer ? (
          <span style={pill('ok')}><ShieldCheck size={12} /> Certified</span>
        ) : (
          <>
            <span style={pill(queryPath === 'free-form SQL' ? 'warn' : 'neutral')}>
              {queryPath}
            </span>
            {allWarnings.map((w, idx) => (
              <span key={idx} style={pill('warn')} title={w}>
                {w}
              </span>
            ))}
          </>
        )}
        <span style={{ flex: 1 }} />
        <button
          type="button"
          style={{ ...BTN, ...(certified ? { color: 'var(--color-success)', cursor: 'default' } : {}) }}
          disabled={certified || certifyState === 'saving' || !canCertify || confirming}
          onClick={() => setConfirming(true)}
          title={canCertify
            ? 'Save this question and its SQL as a verified query so AI engines reuse it'
            : 'Run the question against a live warehouse (not a preview) before certifying it'}
        >
          {certified ? <Check size={13} /> : <ShieldCheck size={13} />}
          {certified ? 'Certified' : certifyState === 'saving' ? 'Certifying…' : 'Certify answer'}
        </button>
      </div>
      {confirming && !certified && (
        <div role="alertdialog" aria-label="Confirm certification" style={{ display: 'flex', alignItems: 'center', gap: 8, flexWrap: 'wrap', padding: '8px 10px', borderRadius: 8, border: '1px solid var(--border-main)', background: 'var(--bg-surface-raised)', fontSize: 12.5 }}>
          <span style={{ flex: 1, minWidth: 200 }}>Is this answer correct? Certifying saves the question and its SQL so AI engines reuse it.</span>
          <button type="button" style={BTN} onClick={() => setConfirming(false)}>Cancel</button>
          <button type="button" style={{ ...BTN, background: 'var(--accent-blue)', color: '#fff', borderColor: 'var(--accent-blue)' }} onClick={() => { setConfirming(false); onCertify(); }}>Yes, certify</button>
        </div>
      )}

      {result?.is_simulated && (
        <div style={{ fontSize: 12, color: 'var(--color-warning)' }}>
          Preview data · {result.message || 'the warehouse is not connected, so these rows are a sample.'}
        </div>
      )}
      {certifyError && <div style={{ fontSize: 12, color: 'var(--color-error)' }}>{certifyError}</div>}

      <AnsweredBy plan={plan} />

      <AnswerResult columns={result?.columns} rows={result?.rows} />

      <HowAnswered plan={plan} result={result} target={target} />
    </div>
  );
}

import React from 'react';
import { toNumber } from './askApi';

/**
 * Shows a query result: a horizontal bar chart when the result is exactly one
 * label column + one numeric column, otherwise a compact table.
 */
function barShape(columns, rows) {
  if (columns?.length !== 2 || !rows?.length || rows.length > 30) return null;
  const numericCol = [0, 1].find((ci) => rows.every((r) => toNumber(r[ci]) !== null));
  if (numericCol === undefined) return null;
  const labelCol = numericCol === 0 ? 1 : 0;
  // Two numeric columns: not a "dimension + number" result.
  if (rows.every((r) => toNumber(r[labelCol]) !== null)) return null;
  return { labelCol, numericCol };
}

export default function AnswerResult({ columns, rows }) {
  if (!columns?.length) {
    return <div style={{ fontSize: 12.5, color: 'var(--text-secondary)' }}>The query returned no columns.</div>;
  }
  if (!rows?.length) {
    return <div style={{ fontSize: 12.5, color: 'var(--text-secondary)' }}>No rows matched this question.</div>;
  }

  const shape = barShape(columns, rows);
  if (shape) {
    const values = rows.map((r) => toNumber(r[shape.numericCol]));
    const max = Math.max(...values.map((v) => Math.abs(v)), 0) || 1;
    return (
      <div role="list" aria-label={`${columns[shape.numericCol]} by ${columns[shape.labelCol]}`} style={{ display: 'flex', flexDirection: 'column', gap: 6 }}>
        <div style={{ display: 'flex', fontSize: 11, color: 'var(--text-tertiary)', gap: 10 }}>
          <span style={{ width: 160, flexShrink: 0 }}>{columns[shape.labelCol]}</span>
          <span>{columns[shape.numericCol]}</span>
        </div>
        {rows.map((r, i) => (
          <div key={i} role="listitem" style={{ display: 'grid', gridTemplateColumns: '160px minmax(0,1fr) auto', alignItems: 'center', gap: 10, fontSize: 12.5 }}>
            <span title={String(r[shape.labelCol] ?? '')} style={{ color: 'var(--text-secondary)', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
              {String(r[shape.labelCol] ?? '—')}
            </span>
            <span style={{ height: 12, borderRadius: 3, background: 'var(--bg-surface-raised)', overflow: 'hidden' }}>
              <span style={{ display: 'block', height: '100%', width: `${Math.max(2, (Math.abs(values[i]) / max) * 100)}%`, background: 'var(--accent-blue)', borderRadius: 3 }} />
            </span>
            <span style={{ fontVariantNumeric: 'tabular-nums', color: 'var(--text-primary)', fontWeight: 600, textAlign: 'right', minWidth: 64 }}>
              {String(r[shape.numericCol])}
            </span>
          </div>
        ))}
      </div>
    );
  }

  return (
    <div style={{ border: '1px solid var(--border-main)', borderRadius: 8, overflowX: 'auto', maxHeight: 360 }}>
      <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: 12 }}>
        <thead>
          <tr style={{ background: 'var(--bg-surface-raised)', textAlign: 'left' }}>
            {columns.map((c, i) => (
              <th key={i} style={{ padding: '7px 10px', borderBottom: '1px solid var(--border-main)', fontWeight: 600, color: 'var(--text-secondary)', whiteSpace: 'nowrap', position: 'sticky', top: 0, background: 'var(--bg-surface-raised)' }}>
                {c}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {rows.map((r, ri) => (
            <tr key={ri} style={{ borderBottom: ri === rows.length - 1 ? 'none' : '1px solid var(--border-main)' }}>
              {r.map((cell, ci) => (
                <td key={ci} style={{ padding: '7px 10px', color: 'var(--text-primary)', whiteSpace: 'nowrap', textAlign: toNumber(cell) !== null ? 'right' : 'left', fontVariantNumeric: 'tabular-nums' }}>
                  {cell === null || cell === undefined ? <span style={{ color: 'var(--text-tertiary)' }}>NULL</span> : String(cell)}
                </td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

import React from 'react';
import { ShieldCheck } from 'lucide-react';
import { LABEL, pill } from './askStyles';

const ITEM = {
  display: 'flex',
  alignItems: 'center',
  gap: 6,
  width: '100%',
  textAlign: 'left',
  padding: '7px 9px',
  borderRadius: 8,
  border: '1px solid transparent',
  background: 'none',
  color: 'var(--text-secondary)',
  fontSize: 12.5,
  lineHeight: 1.4,
  cursor: 'pointer',
};

/**
 * Right rail: dynamic suggestions derived from the project's ontology and
 * verified queries persisted per project in the database.
 */
export default function AskRail({ suggestions = [], certified = [], onPick, disabled }) {
  return (
    <aside
      aria-label="Suggested questions"
      style={{
        borderLeft: '1px solid var(--border-main)',
        padding: '16px 14px',
        display: 'flex',
        flexDirection: 'column',
        gap: 6,
        overflowY: 'auto',
        minHeight: 0,
      }}
    >
      <span style={LABEL}>Try asking</span>
