import { useState } from 'react';
import { ChevronLeft, ChevronRight } from 'lucide-react';

/**
 * DataTable — generic sortable, paginated table.
 * Props:
 *   columns  : [{ key, label, render?, align? }]
 *   data     : array of objects
 *   pageSize : number (default 10)
 *   loading  : boolean
 *   emptyText: string
 *   getRowStyle: (row, index) => style object (optional)
 */
export default function DataTable({
  columns = [],
  data = [],
  pageSize = 10,
  loading = false,
  emptyText = 'No data found.',
  getRowStyle = null,
}) {
  const [page, setPage] = useState(1);
  const totalPages = Math.max(1, Math.ceil(data.length / pageSize));
  const slice = data.slice((page - 1) * pageSize, page * pageSize);

  const thStyle = {
    padding: '10px 14px',
    fontSize: 11,
    fontWeight: 600,
    textTransform: 'uppercase',
    letterSpacing: '0.06em',
    color: 'var(--text-tertiary)',
    borderBottom: '1px solid var(--border-main)',
    background: 'var(--bg-surface-raised)',
    whiteSpace: 'nowrap',
  };
  const tdStyle = {
    padding: '11px 14px',
    fontSize: 13,
    color: 'var(--text-primary)',
    borderBottom: '1px solid var(--border-main)',
    verticalAlign: 'middle',
  };

  return (
    <div
      className="rounded-xl overflow-hidden"
      style={{ border: '1px solid var(--border-main)' }}
    >
      <div className="overflow-x-auto">
        <table style={{ width: '100%', borderCollapse: 'collapse' }}>
          <thead>
            <tr>
              {columns.map((col) => (
                <th
                  key={col.key}
                  style={{ ...thStyle, textAlign: col.align === 'right' ? 'right' : col.align === 'center' ? 'center' : 'left' }}
                >
                  {col.label}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {loading ? (
              <tr>
                <td colSpan={columns.length} style={{ ...tdStyle, textAlign: 'center', padding: '32px' }}>
                  <span className="text-tertiary text-sm">Loading…</span>
                </td>
              </tr>
            ) : slice.length === 0 ? (
              <tr>
                <td colSpan={columns.length} style={{ ...tdStyle, textAlign: 'center', padding: '32px' }}>
                  <span className="text-tertiary text-sm">{emptyText}</span>
                </td>
              </tr>
            ) : (
              slice.map((row, i) => {
                const baseStyle = { background: i % 2 === 0 ? 'transparent' : 'var(--bg-surface-raised)' };
                const customStyle = getRowStyle ? getRowStyle(row, i) : {};
                const mergedStyle = { ...baseStyle, ...customStyle };
                
                return (
                <tr
                  key={row.id ?? i}
                  style={mergedStyle}
                  onMouseEnter={(e) => { e.currentTarget.style.background = 'var(--bg-surface-hover)'; }}
                  onMouseLeave={(e) => { e.currentTarget.style.background = mergedStyle.background; }}
                >
                  {columns.map((col) => (
                    <td
                      key={col.key}
                      style={{ ...tdStyle, textAlign: col.align === 'right' ? 'right' : col.align === 'center' ? 'center' : 'left' }}
                    >
                      {col.render ? col.render(row[col.key], row) : String(row[col.key] ?? '—')}
                    </td>
                  ))}
                </tr>
                );
              })
            )}
          </tbody>
        </table>
      </div>

      {/* Pagination */}
      {totalPages > 1 && (
        <div
          className="flex items-center justify-between px-4 py-3"
          style={{ borderTop: '1px solid var(--border-main)', background: 'var(--bg-surface-raised)' }}
        >
          <span className="text-tertiary text-xs">
            {(page - 1) * pageSize + 1}–{Math.min(page * pageSize, data.length)} of {data.length}
          </span>
          <div className="flex items-center gap-1">
            <PaginationBtn onClick={() => setPage(p => Math.max(1, p - 1))} disabled={page === 1}>
              <ChevronLeft size={14} />
            </PaginationBtn>
            {Array.from({ length: totalPages }, (_, i) => i + 1)
              .filter(p => p === 1 || p === totalPages || Math.abs(p - page) <= 1)
              .reduce((acc, p, i, arr) => {
                if (i > 0 && p - arr[i - 1] > 1) acc.push('…');
                acc.push(p);
                return acc;
              }, [])
              .map((p, i) =>
                p === '…' ? (
                  <span key={`ellipsis-${i}`} className="text-tertiary text-xs px-1">…</span>
                ) : (
                  <PaginationBtn key={p} active={p === page} onClick={() => setPage(p)}>
                    {p}
                  </PaginationBtn>
                )
              )}
            <PaginationBtn onClick={() => setPage(p => Math.min(totalPages, p + 1))} disabled={page === totalPages}>
              <ChevronRight size={14} />
            </PaginationBtn>
          </div>
        </div>
      )}
    </div>
  );
}

function PaginationBtn({ children, onClick, disabled, active }) {
  return (
    <button
      onClick={onClick}
      disabled={disabled}
      className="flex items-center justify-center rounded-md text-xs font-medium"
      style={{
        minWidth: 28,
        height: 28,
        padding: '0 6px',
        border: active ? `1px solid var(--accent-blue)` : '1px solid var(--border-main)',
        background: active ? 'var(--accent-blue)' : 'transparent',
        color: active ? '#fff' : disabled ? 'var(--text-tertiary)' : 'var(--text-primary)',
        cursor: disabled ? 'not-allowed' : 'pointer',
        opacity: disabled ? 0.4 : 1,
      }}
    >
      {children}
    </button>
  );
}

import { useState } from 'react';
import { X, FileText } from 'lucide-react';

/**
 * DraftBanner — non-intrusive banner shown when an unsaved draft exists.
 *
 * Props:
 *   visible  — whether to render the banner
 *   onResume — called when user clicks "Resume"
 *   onDiscard — called when user clicks the dismiss (✕) button
 */
export default function DraftBanner({ visible, onResume, onDiscard }) {
  const [dismissed, setDismissed] = useState(false);

  if (!visible || dismissed) return null;

  const handleDiscard = () => {
    setDismissed(true);
    onDiscard?.();
  };

  return (
    <div
      style={{
        margin: '16px 32px 0',
        padding: '10px 16px',
        borderRadius: 8,
        background: 'var(--color-accent-faint, rgba(88,166,255,0.08))',
        border: '1.5px solid var(--accent-blue, #58a6ff)40',
        display: 'flex',
        alignItems: 'center',
        gap: 10,
        animation: 'draftBannerSlideIn 0.3s ease-out',
      }}
    >
      <FileText size={16} style={{ color: 'var(--accent-blue)', flexShrink: 0 }} />
      <span style={{ flex: 1, fontSize: 13, color: 'var(--text-secondary)' }}>
        You have an unsaved project draft.
      </span>
      <button
        onClick={onResume}
        style={{
          padding: '5px 14px',
          borderRadius: 6,
          background: 'var(--accent-blue)',
          color: '#fff',
          border: 'none',
          fontSize: 12,
          fontWeight: 600,
          cursor: 'pointer',
          transition: 'opacity 0.15s',
        }}
        onMouseEnter={e => { e.currentTarget.style.opacity = '0.85'; }}
        onMouseLeave={e => { e.currentTarget.style.opacity = '1'; }}
      >
        Resume
      </button>
      <button
        onClick={handleDiscard}
        title="Discard draft"
        style={{
          background: 'none',
          border: 'none',
          cursor: 'pointer',
          color: 'var(--text-tertiary)',
          display: 'flex',
          alignItems: 'center',
          padding: 2,
          transition: 'color 0.15s',
        }}
        onMouseEnter={e => { e.currentTarget.style.color = 'var(--color-error, #f85149)'; }}
        onMouseLeave={e => { e.currentTarget.style.color = 'var(--text-tertiary)'; }}
      >
        <X size={16} />
      </button>

      {/* Inline keyframe for the slide-in animation */}
      <style>{`
        @keyframes draftBannerSlideIn {
          from { opacity: 0; transform: translateY(-8px); }
          to   { opacity: 1; transform: translateY(0); }
        }
      `}</style>
    </div>
  );
}

import { X, RefreshCcw } from 'lucide-react';
import { useEffect, useState } from 'react';

/**
 * DraftToast — non-intrusive notification in the bottom right.
 * Shown when a project draft has been automatically resumed.
 * 
 * Props:
 *   visible      — whether to render the toast
 *   onStartFresh — called when user clicks "Start Fresh"
 *   onDismiss    — called when user dismisses the toast
 */
export default function DraftToast({ visible, onStartFresh, onDismiss }) {
  const [shouldRender, setShouldRender] = useState(visible);

  useEffect(() => {
    if (visible) {
      setShouldRender(true);
    } else {
      const timer = setTimeout(() => setShouldRender(false), 300);
      return () => clearTimeout(timer);
    }
  }, [visible]);

  if (!shouldRender) return null;

  return (
    <div
      style={{
        position: 'fixed',
        bottom: 24,
        right: 24,
        zIndex: 9999,
        padding: '12px 16px',
        background: '#1c2128',
        border: '1px solid var(--border-main, rgba(255,255,255,0.1))',
        borderRadius: 12,
        boxShadow: '0 8px 24px rgba(0,0,0,0.5)',
        display: 'flex',
        alignItems: 'center',
        gap: 12,
        animation: visible ? 'toastSlideIn 0.4s cubic-bezier(0.16, 1, 0.3, 1)' : 'toastSlideOut 0.3s ease-in forwards',
        backdropFilter: 'blur(8px)',
      }}
    >
      <div style={{
        width: 32,
        height: 32,
        borderRadius: 8,
        background: 'rgba(56, 189, 248, 0.1)',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        color: '#38bdf8'
      }}>
        <RefreshCcw size={16} />
      </div>
      
      <div style={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
        <span style={{ fontSize: 13, fontWeight: 600, color: '#fff' }}>Draft restored</span>
        <span style={{ fontSize: 12, color: 'var(--text-secondary)' }}>You are picking up where you left off.</span>
      </div>

      <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginLeft: 8 }}>
        <button
          onClick={onStartFresh}
          style={{
            padding: '6px 12px',
            borderRadius: 6,
            background: 'rgba(255,255,255,0.05)',
            border: '1px solid rgba(255,255,255,0.1)',
            color: '#fff',
            fontSize: 12,
            fontWeight: 500,
            cursor: 'pointer',
            transition: 'all 0.2s',
          }}
          onMouseEnter={e => { e.currentTarget.style.background = 'rgba(255,255,255,0.1)'; }}
          onMouseLeave={e => { e.currentTarget.style.background = 'rgba(255,255,255,0.05)'; }}
        >
          Start Fresh
        </button>
        
        <button
          onClick={onDismiss}
          style={{
            background: 'none',
            border: 'none',
            padding: 4,
            cursor: 'pointer',
            color: 'var(--text-tertiary)',
            display: 'flex',
            alignItems: 'center',
            transition: 'color 0.2s',
          }}
          onMouseEnter={e => { e.currentTarget.style.color = '#fff'; }}
          onMouseLeave={e => { e.currentTarget.style.color = 'var(--text-tertiary)'; }}
        >
          <X size={16} />
        </button>
      </div>

      <style>{`
        @keyframes toastSlideIn {
          from { opacity: 0; transform: translateY(20px) scale(0.95); }
          to   { opacity: 1; transform: translateY(0) scale(1); }
        }
        @keyframes toastSlideOut {
          from { opacity: 1; transform: translateY(0) scale(1); }
          to   { opacity: 0; transform: translateY(10px) scale(0.95); }
        }
      `}</style>
    </div>
  );
}

/**
 * DroppedFieldsPanel — "what got dropped and why" transparency panel.
 *
 * Renders a flat list of DropRecord-shaped entries (see
 * semabridge/core/drop_ledger.py) grouped by pipeline stage, entirely
 * data-driven off whatever `stage`/`reason` values are actually present —
 * no fixed vocabulary is assumed beyond a friendly label for the five known
 * stages. `by_design` entries (intentional exclusions, e.g. auto-hidden date
 * tables) are visually de-emphasized rather than hidden, since they're still
 * useful context but not something the user needs to act on.
 *
 * Used on both the pre-deploy dry-run mapping page and the post-deployment
 * run summary — same shape, same component, two call sites.
 *
 * A multi-PBIX batch run's entries all land in one flat array with no
 * indication of which file each came from (e.g. "61 excluded" for a 2-file
 * batch, no way to tell it's 60 from one file and 1 from the other) --
 * pass a `model` field on each entry (the caller's own result.model) to get
 * an extra per-file grouping level above the existing per-stage one. Falls
 * back to the original flat-by-stage-only rendering when entries carry no
 * model field, or all share the same one (single-file dry-run/run), so the
 * dry-run mapping page call site (DryRunMappingTable.jsx, always
 * single-model) renders identically to before.
 *
 * Props:
 *   entries : Array<{ entity_kind, entity_name, dataset, stage, reason, detail, by_design, model? }>
 *   title   : optional heading override (default "Dropped Fields")
 */
import { useState, useMemo } from 'react';
import { AlertTriangle, ChevronRight, Info } from 'lucide-react';
import { cleanPbixLabel } from '../../utils/pbixLabel';
import { PLACEHOLDER_NOTE, isPlaceholderEntry, isInternalAutoTable } from '../../utils/placeholderMetric';

const STAGE_LABELS = {
  extraction: 'Extraction',
  dax_translation: 'DAX Translation',
  schema_validation: 'Schema Validation',
  ddl_emission: 'DDL Emission',
  ddl_deployment: 'DDL Deployment',
};

// Known stages sort first, in pipeline order; any stage not in this list
// (future stages, typos, etc.) is appended after, in first-seen order —
// nothing here assumes the five known stages are the only ones possible.
const STAGE_ORDER = Object.keys(STAGE_LABELS);

function stageLabel(stage) {
  const key = String(stage || '').toLowerCase().trim();
  if (STAGE_LABELS[key]) return STAGE_LABELS[key];
  const word = key.replace(/[_-]+/g, ' ').trim();
  return word ? word.replace(/\b\w/g, (c) => c.toUpperCase()) : 'Unknown Stage';
}

function groupByStage(entries) {
  const order = [];
  const buckets = new Map();
  entries.forEach((entry) => {
    const key = String(entry?.stage || 'unknown').toLowerCase().trim() || 'unknown';
    if (!buckets.has(key)) {
      buckets.set(key, []);
      order.push(key);
    }
    buckets.get(key).push(entry);
  });
  const known = STAGE_ORDER.filter((k) => order.includes(k));
  const unknown = order.filter((k) => !STAGE_ORDER.includes(k));
  return [...known, ...unknown].map((key) => ({
    key,
    label: stageLabel(key),
    entries: buckets.get(key),
  }));
}

function groupByModel(entries) {
  const order = [];
  const buckets = new Map();
  entries.forEach((entry) => {
    const key = entry?.model ? String(entry.model) : '';
    if (!buckets.has(key)) {
      buckets.set(key, []);
      order.push(key);
    }
    buckets.get(key).push(entry);
  });
  return order.map((key) => ({ key, label: cleanPbixLabel(key) || '(unknown file)', entries: buckets.get(key) }));
}

function DropStageGroups({ groups }) {
  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 14 }}>
      {groups.map((group) => (
        <div key={group.key} style={{ display: 'flex', flexDirection: 'column', gap: 6 }}>
          <div style={{ fontSize: 11, fontWeight: 700, color: 'var(--text-tertiary)', textTransform: 'uppercase', letterSpacing: 0.4 }}>
            {group.label} · {group.entries.length}
          </div>
          {group.entries.map((entry, idx) => (
            <DropEntryRow key={`${entry?.entity_kind}-${entry?.entity_name}-${idx}`} entry={entry} />
          ))}
        </div>
      ))}
    </div>
  );
}

function DropEntryRow({ entry }) {
  const [showRawDetail, setShowRawDetail] = useState(false);
  const isAutoTable = isInternalAutoTable(entry);
  const byDesign = Boolean(entry?.by_design || isAutoTable);
  const isPlaceholder = isPlaceholderEntry(entry);

  const displayReason = isAutoTable
    ? 'Power BI internal auto date/time table omitted to preserve warehouse schema hygiene.'
    : (entry?.reason || 'Excluded during sync.');

  return (
    <div
      style={{
        padding: '10px 12px',
        borderRadius: 6,
        background: byDesign ? 'transparent' : 'var(--bg-surface)',
        border: `1px solid ${byDesign ? 'var(--border-main)' : 'rgba(245,158,11,0.3)'}`,
        opacity: byDesign ? 0.75 : 1,
        display: 'flex',
        alignItems: 'flex-start',
        gap: 8,
      }}
    >
      {byDesign ? (
        <Info size={13} style={{ color: 'var(--text-tertiary)', flexShrink: 0, marginTop: 2 }} />
      ) : (
        <AlertTriangle size={13} style={{ color: '#f59e0b', flexShrink: 0, marginTop: 2 }} />
      )}
      <div style={{ flex: 1, minWidth: 0 }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 8, flexWrap: 'wrap' }}>
          <span style={{ fontFamily: 'monospace', fontSize: 12, fontWeight: 700, color: 'var(--text-primary)' }}>
            {entry?.entity_name || 'unknown'}
          </span>
          <span style={{ fontSize: 10, padding: '1px 6px', borderRadius: 4, background: 'var(--bg-surface-raised)', color: 'var(--text-tertiary)', fontWeight: 700, textTransform: 'uppercase' }}>
            {isAutoTable ? 'Internal Table' : (entry?.entity_kind || 'entity')}
          </span>
          {entry?.dataset && (
            <span style={{ fontSize: 11, color: 'var(--text-tertiary)' }}>
              in <span style={{ fontFamily: 'monospace' }}>{entry.dataset}</span>
            </span>
          )}
          {byDesign && (
            <span style={{ fontSize: 10, padding: '1px 6px', borderRadius: 4, background: 'rgba(100, 116, 139, 0.15)', color: 'var(--text-secondary)', fontWeight: 600 }}>
              By Design
            </span>
          )}
          {isPlaceholder && (
            <span style={{ fontSize: 10, padding: '1px 6px', borderRadius: 4, background: 'rgba(245,158,11,0.15)', color: '#f59e0b', fontWeight: 700, border: '1px solid rgba(245,158,11,0.35)' }}>
              NULL placeholder
            </span>
          )}
        </div>
        <p style={{ margin: '4px 0 0 0', fontSize: 12, color: 'var(--text-secondary)', lineHeight: 1.5 }}>
          {displayReason}
        </p>
        {entry?.detail && (
          <div style={{ marginTop: 4 }}>
            {isAutoTable ? (
              <div>
                <button
                  type="button"
                  onClick={() => setShowRawDetail(!showRawDetail)}
                  style={{
                    background: 'none',
                    border: 'none',
                    padding: 0,
                    color: 'var(--accent-blue)',
                    fontSize: 10,
                    cursor: 'pointer',
                    textDecoration: 'underline',
                  }}
                >
                  {showRawDetail ? 'Hide internal metadata' : 'View internal metadata'}
                </button>
                {showRawDetail && (
                  <p style={{ margin: '4px 0 0 0', fontSize: 11, color: 'var(--text-tertiary)', fontFamily: 'monospace', wordBreak: 'break-word' }}>
                    {typeof entry.detail === 'object' ? JSON.stringify(entry.detail) : String(entry.detail)}
                  </p>
                )}
              </div>
            ) : (
              <p style={{ margin: '4px 0 0 0', fontSize: 11, color: 'var(--text-tertiary)', fontFamily: 'monospace', wordBreak: 'break-word' }}>
                {typeof entry.detail === 'object' ? JSON.stringify(entry.detail) : String(entry.detail)}
              </p>
            )}
          </div>
        )}
        {isPlaceholder && (
          <p style={{ margin: '6px 0 0 0', fontSize: 12, color: '#f59e0b', lineHeight: 1.5 }}>
            {PLACEHOLDER_NOTE}
          </p>
        )}
      </div>
    </div>
  );
}

export default function DroppedFieldsPanel({ entries = [], title = 'Dropped Fields', defaultExpanded = false }) {
  const [expanded, setExpanded] = useState(defaultExpanded);
  const cleanEntries = useMemo(() => entries.filter(Boolean), [entries]);
  const groups = useMemo(() => groupByStage(cleanEntries), [cleanEntries]);
  const modelGroups = useMemo(() => groupByModel(cleanEntries), [cleanEntries]);
  // Only worth a per-file breakdown when entries genuinely span more than
  // one model -- a single-file run (or the dry-run mapping page, which
  // never sets `model` at all) renders exactly as before.
  const isMultiModel = modelGroups.length > 1;
  const total = entries.length;
  const actionableCount = entries.filter((e) => !e?.by_design).length;
  const placeholderCount = entries.filter(isPlaceholderEntry).length;
  const excludedCount = actionableCount - placeholderCount;

  if (total === 0) return null;

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
      <button
        type="button"
        onClick={() => setExpanded((v) => !v)}
        style={{
          display: 'flex',
          alignItems: 'center',
          gap: 8,
          padding: '10px 12px',
          borderRadius: 8,
          border: '1px solid rgba(245,158,11,0.35)',
          background: 'rgba(245,158,11,0.08)',
          cursor: 'pointer',
          textAlign: 'left',
          width: '100%',
        }}
      >
        <ChevronRight
          size={14}
          style={{ color: '#f59e0b', transform: expanded ? 'rotate(90deg)' : 'none', transition: 'transform 0.15s', flexShrink: 0 }}
        />
        <AlertTriangle size={14} style={{ color: '#f59e0b', flexShrink: 0 }} />
        <span style={{ fontSize: 13, fontWeight: 700, color: 'var(--text-primary)' }}>
          {title}
        </span>
        <span style={{ fontSize: 11, color: 'var(--text-tertiary)' }}>
          {[
            placeholderCount > 0 && `${placeholderCount} deployed as NULL placeholder${placeholderCount !== 1 ? 's' : ''}`,
            excludedCount > 0 && `${excludedCount} excluded from the deployed model`,
            total > actionableCount && `${total - actionableCount} by design`,
          ].filter(Boolean).join(', ')}
        </span>
      </button>

      {expanded && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 14, padding: '4px 4px 4px 8px' }}>
          {isMultiModel ? (
            modelGroups.map((modelGroup) => {
              const modelActionable = modelGroup.entries.filter((e) => !e?.by_design).length;
              return (
                <div
                  key={modelGroup.key}
                  style={{
                    display: 'flex', flexDirection: 'column', gap: 10,
                    padding: 10, borderRadius: 8, border: '1px solid var(--border-main)',
                  }}
                >
                  <div style={{ display: 'flex', alignItems: 'baseline', gap: 8, flexWrap: 'wrap' }}>
                    <span style={{ fontSize: 12, fontWeight: 700, color: 'var(--text-primary)', fontFamily: 'monospace' }}>
                      {modelGroup.label}
                    </span>
                    <span style={{ fontSize: 11, color: 'var(--text-tertiary)' }}>
                      {modelActionable > 0
                        ? `${modelActionable} excluded${modelGroup.entries.length > modelActionable ? `, ${modelGroup.entries.length - modelActionable} by design` : ''}`
                        : `${modelGroup.entries.length} by design`}
                    </span>
                  </div>
                  <DropStageGroups groups={groupByStage(modelGroup.entries)} />
                </div>
              );
            })
          ) : (
            <DropStageGroups groups={groups} />
          )}
        </div>
      )}
    </div>
  );
}

import { useNavigate } from 'react-router-dom';
import Modal from './Modal';
import { useDuplicateSyncPrompt } from '../../utils/duplicateSyncPrompt';

const BTN = { padding: '7px 14px', borderRadius: 8, fontSize: 12.5, fontWeight: 600, cursor: 'pointer' };
const SECONDARY_BTN = { ...BTN, background: 'transparent', border: '1px solid var(--border-main)', color: 'var(--text-secondary)' };
const PRIMARY_BTN = { ...BTN, background: 'var(--accent-blue)', border: '1px solid var(--accent-blue)', color: '#fff' };
const CELL = { padding: '8px' };
const HEAD = { padding: '6px 8px' };
const MAX_BLOCKERS_SHOWN = 25;

const REASON_LABELS = {
  same_file: 'Same PBIX file (identical content)',
  same_view: 'Same view name — this sync would overwrite it',
  same_model: 'Same model name',
  same_content: 'Same metrics and columns',
  same_file_in_progress: 'Same PBIX file — another project is syncing it right now',
  same_file_dry_run: 'Same PBIX file — dry-run by another project, not synced yet',
};

const TITLES = {
  duplicate: 'Model already synced',
  duplicate_check_failed: 'Could not check for duplicates',
  already_running: 'Sync already running',
  blocked: 'Dry run has unresolved issues',
  removed_fields: 'Fields will be removed',
};

const MAX_REMOVED_SHOWN = 50;

function RemovedFieldsBody({ detail, message }) {
  const models = Array.isArray(detail?.models) ? detail.models : [];
  const unverifiable = Array.isArray(detail?.unverifiable) ? detail.unverifiable : [];
  const promoted = Boolean(detail?.promoted_from_upsert);
  return (
    <>
      <p style={{ margin: '0 0 8px', fontSize: 13, color: 'var(--text-secondary)' }}>
        {message || 'Some fields in the deployed semantic view are no longer in the source.'}
      </p>
      {promoted ? (
        <p style={{ margin: '0 0 12px', fontSize: 12.5, color: 'var(--text-tertiary)' }}>
          This sync runs as a <b>Copy</b> because at least one model has never been deployed by this project
          (a first deployment creates its objects). <b>Remove them and sync</b> runs that Copy.
        </p>
      ) : (
        <p style={{ margin: '0 0 12px', fontSize: 12.5, color: 'var(--text-tertiary)' }}>
          <b>Remove them</b> runs the Copy sync (full rebuild from the source). <b>Keep them</b> runs this sync
          as an Upsert: new and changed fields are deployed and these stay in Snowflake.
        </p>
      )}
      {unverifiable.length > 0 && (
        <div style={{ margin: '0 0 12px', fontSize: 12.5 }}>
          <div style={{ fontWeight: 600, marginBottom: 4 }}>Cannot verify</div>
          <div style={{ color: 'var(--text-tertiary)', marginBottom: 4 }}>
            These models are deployed, but there is no successful dry run of the content about to be synced,
            so the fields a Copy would remove are unknown. Re-run the dry run to see them.
          </div>
          <ul style={{ margin: 0, paddingLeft: 18, color: 'var(--text-secondary)' }}>
            {unverifiable.map((m) => (
              <li key={`${m.model}-${m.view_name}`}>
                <b>{m.model}</b>
                {m.view_name && <span style={{ color: 'var(--text-tertiary)' }}> ({m.view_name})</span>}
              </li>
            ))}
          </ul>
        </div>
      )}
      <div style={{ maxHeight: 320, overflowY: 'auto' }}>
        {models.map((m) => (
          <div key={`${m.model}-${m.view_name}`} style={{ marginBottom: 10 }}>
            <div style={{ fontSize: 12.5, fontWeight: 600, marginBottom: 4 }}>
              {m.model} <span style={{ color: 'var(--text-tertiary)', fontWeight: 400 }}>({m.count} field{m.count === 1 ? '' : 's'})</span>
            </div>
            <ul style={{ margin: 0, paddingLeft: 18, fontSize: 12, color: 'var(--text-secondary)' }}>
              {(m.removed || []).slice(0, MAX_REMOVED_SHOWN).map((f) => (
                <li key={`${f.kind}-${f.name}`}>
                  <code>{f.name}</code> <span style={{ color: 'var(--text-tertiary)' }}>{f.kind}</span>
                </li>
              ))}
              {(m.removed || []).length > MAX_REMOVED_SHOWN && (
                <li style={{ color: 'var(--text-tertiary)' }}>…and {m.removed.length - MAX_REMOVED_SHOWN} more</li>
              )}
            </ul>
          </div>
        ))}
      </div>
    </>
  );
}

function overlapText(part) {
  if (!part || !part.total) return '—';
  return `${part.shared} of ${part.total}`;
}

function DuplicateBody({ duplicates, message, overwrites }) {
  return (
    <>
      <p style={{ margin: '0 0 12px', fontSize: 13, color: 'var(--text-secondary)' }}>
        {message || 'Some models in this project are already synced by another project.'}
        {overwrites && ' At least one would replace the other project\'s semantic view.'}
      </p>
      <div style={{ overflowX: 'auto' }}>
        <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: 12.5 }}>
          <thead>
            <tr style={{ textAlign: 'left', color: 'var(--text-tertiary)' }}>
              <th style={HEAD}>Model</th>
              <th style={HEAD}>Already synced by</th>
              <th style={HEAD}>Why</th>
              <th style={HEAD}>Metrics</th>
              <th style={HEAD}>Columns</th>
            </tr>
          </thead>
          <tbody>
            {duplicates.map((d) => (
              <tr key={`${d.model}-${d.other_project_id}-${d.other_view_name}`} style={{ borderTop: '1px solid var(--border-main)' }}>
                <td style={CELL}>
                  <b>{d.model}</b>
                  <div style={{ color: 'var(--text-tertiary)', fontSize: 11.5 }}>{d.view_name}</div>
                </td>
                <td style={CELL}>
                  {d.other_project_name}
                  <div style={{ color: 'var(--text-tertiary)', fontSize: 11.5 }}>{d.target}.{d.other_view_name}</div>
                </td>
                <td style={CELL}>
                  {(d.reasons || []).map((r) => <div key={r}>{REASON_LABELS[r] || r}</div>)}
                </td>
                <td style={{ ...CELL, whiteSpace: 'nowrap' }}>{overlapText(d.metrics)}</td>
                <td style={{ ...CELL, whiteSpace: 'nowrap' }}>{overlapText(d.columns)}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </>
  );
}

function BlockedBody({ detail, message }) {
  const blockers = Array.isArray(detail?.blockers) ? detail.blockers : [];
  const shown = blockers.slice(0, MAX_BLOCKERS_SHOWN);
  return (
    <>
      <p style={{ margin: '0 0 12px', fontSize: 13, color: 'var(--text-secondary)' }}>
        {message || 'The dry run for this project has unresolved issues, so the sync was not started.'}
        {' '}Nothing was deployed. Open the dry run, resolve the issues, then sync again.
      </p>
      {shown.length > 0 && (
        <div style={{ overflowX: 'auto', maxHeight: 320 }}>
          <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: 12.5 }}>
            <thead>
              <tr style={{ textAlign: 'left', color: 'var(--text-tertiary)' }}>
                <th style={HEAD}>Field</th>
                <th style={HEAD}>Target name</th>
                <th style={HEAD}>Issue</th>
              </tr>
            </thead>
            <tbody>
              {shown.map((b, i) => (
                <tr key={b.id || `${b.source_path}-${i}`} style={{ borderTop: '1px solid var(--border-main)' }}>
                  <td style={CELL}>
                    <b>{b.source_name || b.source_path}</b>
                    {b.source_path && b.source_name && (
                      <div style={{ color: 'var(--text-tertiary)', fontSize: 11.5 }}>{b.source_path}</div>
                    )}
                  </td>
                  <td style={CELL}><code>{b.target_name || '—'}</code></td>
                  <td style={CELL}>
                    {b.validation_code && <div style={{ fontWeight: 600 }}>{b.validation_code}</div>}
                    <div style={{ color: 'var(--text-secondary)' }}>{b.validation_message || b.validation_status || b.status}</div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
          {blockers.length > shown.length && (
            <div style={{ fontSize: 12, color: 'var(--text-tertiary)', padding: '6px 8px' }}>
              …and {blockers.length - shown.length} more in the dry run.
            </div>
          )}
        </div>
      )}
    </>
  );
}

/** Mounted once in the app layout; opened by api.runProjectNow / retryFailedModels. */
export default function DuplicateSyncDialog() {
  const navigate = useNavigate();
  const { open, kind, projectId, detail, duplicates, message, resolve, close } = useDuplicateSyncPrompt();

  const answer = (choice) => {
    resolve?.(choice);
    close();
    if (choice === 'view_run') {
      const runId = detail?.run_id;
      navigate(runId ? `/runs?run=${encodeURIComponent(runId)}` : '/runs', {
        state: runId ? { runId, autoExpand: true } : undefined,
      });
    } else if (choice === 'open_dry_run' && projectId) {
      // The edit wizard re-runs the dry run and shows the resolver.
      navigate(`/projects/${encodeURIComponent(projectId)}/edit`);
    }
  };

  const overwrites = duplicates.some((d) => d.overwrites);

  let footer;
  if (kind === 'already_running') {
    footer = (
      <>
        <button type="button" style={SECONDARY_BTN} onClick={() => answer('cancel')}>Close</button>
        <button type="button" style={PRIMARY_BTN} onClick={() => answer('view_run')}>View running sync</button>
      </>
    );
  } else if (kind === 'removed_fields') {
    const hasUnverifiable = Array.isArray(detail?.unverifiable) && detail.unverifiable.length > 0;
    const promoted = Boolean(detail?.promoted_from_upsert);
    footer = (
      <>
        <button type="button" style={SECONDARY_BTN} onClick={() => answer('cancel')}>Cancel sync</button>
        {hasUnverifiable && projectId && (
          <button type="button" style={SECONDARY_BTN} onClick={() => answer('open_dry_run')}>Re-run dry run</button>
        )}
        {!promoted && (
          <button type="button" style={SECONDARY_BTN} onClick={() => answer('upsert')}>Keep them (sync as Upsert)</button>
        )}
        <button type="button" style={PRIMARY_BTN} onClick={() => answer('confirm')}>
          {hasUnverifiable && !(detail?.models || []).length ? 'Sync as Copy anyway' : 'Remove them and sync'}
        </button>
      </>
    );
  } else if (kind === 'duplicate_check_failed') {
    footer = (
      <>
        <button type="button" style={SECONDARY_BTN} onClick={() => answer('cancel')}>Cancel sync</button>
        <button type="button" style={PRIMARY_BTN} onClick={() => answer('confirm')}>Sync anyway</button>
      </>
    );
  } else if (kind === 'blocked') {
    footer = (
      <>
        <button type="button" style={SECONDARY_BTN} onClick={() => answer('cancel')}>Close</button>
        {projectId && (
          <button type="button" style={PRIMARY_BTN} onClick={() => answer('open_dry_run')}>Open dry run to resolve</button>
        )}
      </>
    );
  } else {
    footer = (
      <>
        <button type="button" style={SECONDARY_BTN} onClick={() => answer('cancel')}>Cancel sync</button>
        <button type="button" style={PRIMARY_BTN} onClick={() => answer('confirm')}>
          {overwrites ? 'Overwrite and sync' : 'Sync anyway'}
        </button>
      </>
    );
  }

  return (
    <Modal
      open={open}
      onClose={() => answer('cancel')}
      title={TITLES[kind] || TITLES.duplicate}
      size="lg"
      footer={<div style={{ display: 'flex', justifyContent: 'flex-end', gap: 8 }}>{footer}</div>}
    >
      {kind === 'already_running' && (
        <p style={{ margin: 0, fontSize: 13, color: 'var(--text-secondary)' }}>
          {message || 'A sync of this project is already running.'}
          {' '}Only one sync per project runs at a time, so this one was not started. Nothing was changed.
        </p>
      )}
      {kind === 'duplicate_check_failed' && (
        <p style={{ margin: 0, fontSize: 13, color: 'var(--text-secondary)' }}>
          {message || 'The check for models already synced by another project could not run.'}
          {' '}Nothing was deployed yet.
        </p>
      )}
      {kind === 'blocked' && <BlockedBody detail={detail} message={message} />}
      {kind === 'removed_fields' && <RemovedFieldsBody detail={detail} message={message} />}
      {kind === 'duplicate' && <DuplicateBody duplicates={duplicates} message={message} overwrites={overwrites} />}
    </Modal>
  );
}

import { X, Maximize2, Minimize2 } from 'lucide-react';
import { useEffect } from 'react';

/**
 * Modal — generic overlay dialog.
 * Props:
 *   open     : boolean — controls visibility
 *   onClose  : () => void
 *   title    : string
 *   size     : 'sm' | 'md' | 'lg' | 'xl'  (default 'md')
 *   children : modal body content
 *   footer   : ReactNode — custom footer (optional)
 *   allowMaximize : boolean — show maximize/minimize toggle in header
