 *   onToggleMaximize : () => void — toggle callback
 */
export default function Modal({
  open,
  onClose,
  title,
  size = 'md',
  children,
  footer,
  allowMaximize = false,
  isMaximized = false,
  onToggleMaximize,
  width,
