    return () => document.removeEventListener('keydown', handler);
  }, [open, onClose]);

  if (!open) return null;

  const maxWidths = { sm: 400, md: 520, lg: 680, xl: 860, '2xl': 960 };
  const maxW = width ?? (maxWidths[size] ?? 520);

  return (
    <div
      style={{ 
        position: 'fixed', inset: 0, zIndex: 50,
        display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 16,
        background: 'var(--bg-backdrop)', backdropFilter: 'blur(4px)' 
      }}
      onClick={(e) => { if (e.target === e.currentTarget) onClose?.(); }}
    >
      <div
        style={{
          width: '100%', borderRadius: 16, display: 'flex', flexDirection: 'column', overflow: 'hidden',
          maxWidth: isMaximized ? '96vw' : maxW,
          background: 'var(--bg-surface)',
          border: '1px solid var(--border-main)',
          boxShadow: 'var(--shadow-lg)',
          maxHeight: isMaximized ? '95vh' : 'min(90vh, 800px)',
          ...customStyle,
        }}
      >
        {/* Header */}
        <div
          style={{ 
            display: 'flex', alignItems: 'center', justifyContent: 'space-between', 
            padding: '16px 24px', flexShrink: 0,
            borderBottom: '1px solid var(--border-main)' 
          }}
        >
          <h2 style={{ margin: 0, color: 'var(--text-primary)', fontWeight: 600, fontSize: 16 }}>
            {title}
          </h2>
          <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
            {allowMaximize && (
              <button
                onClick={onToggleMaximize}
                style={{
                  display: 'flex', alignItems: 'center', justifyContent: 'center', borderRadius: 8, transition: 'background-color 0.2s',
                  width: 28, height: 28, padding: 0, margin: 0,
                  color: 'var(--text-secondary)', background: 'transparent', border: 'none', cursor: 'pointer', outline: 'none'
                }}
                onMouseEnter={(e) => { e.currentTarget.style.background = 'var(--bg-surface-hover)'; e.currentTarget.style.color = 'var(--text-primary)'; }}
                onMouseLeave={(e) => { e.currentTarget.style.background = 'transparent'; e.currentTarget.style.color = 'var(--text-secondary)'; }}
                title={isMaximized ? 'Exit fullscreen' : 'Maximize'}
                aria-label={isMaximized ? 'Exit fullscreen' : 'Maximize'}
              >
                {isMaximized ? <Minimize2 size={16} /> : <Maximize2 size={16} />}
              </button>
            )}
            <button
              onClick={onClose}
              style={{
                display: 'flex', alignItems: 'center', justifyContent: 'center', borderRadius: 8, transition: 'background-color 0.2s',
                width: 28, height: 28, padding: 0, margin: 0,
                color: 'var(--text-secondary)', background: 'transparent', border: 'none', cursor: 'pointer', outline: 'none'
              }}
              onMouseEnter={(e) => { e.currentTarget.style.background = 'var(--bg-surface-hover)'; e.currentTarget.style.color = 'var(--text-primary)'; }}
              onMouseLeave={(e) => { e.currentTarget.style.background = 'transparent'; e.currentTarget.style.color = 'var(--text-secondary)'; }}
            >
              <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" style={{ flexShrink: 0 }}>
                <line x1="18" y1="6" x2="6" y2="18"></line>
                <line x1="6" y1="6" x2="18" y2="18"></line>
              </svg>
            </button>
          </div>
        </div>

        {/* Body */}
        <div className="custom-scrollbar" style={{ flex: 1, overflowY: 'auto', padding: 24 }}>
          {children}
        </div>

        {/* Footer */}
        {footer && (
          <div
            style={{ 
              display: 'flex', alignItems: 'center', justifyContent: 'flex-end', gap: 12, 
              padding: '16px 24px', flexShrink: 0,
              borderTop: '1px solid var(--border-main)' 
            }}
          >
            {footer}
          </div>
        )}
      </div>
    </div>
  );
}

import { Navigate, Outlet, useLocation } from 'react-router-dom';
import { useAuth } from '../../context/AuthContext';
import { Hexagon } from 'lucide-react';

/**
 * ProtectedRoute — wraps private routes.
 * If not authenticated, redirects to /login preserving the intended destination.
 * Shows a loading spinner while auth state is being confirmed.
 *
 * Accepts an optional `requiredRole` prop. When provided, the authenticated
 * user's role must match; otherwise the user is redirected to /unauthorized.
 *
 * Security: never renders protected content until isAuthenticated is
 * confirmed true AND loading has resolved. This prevents an unauthenticated
 * user with a stale/invalid token in localStorage from accessing app routes
 * while the bootstrap check is still in-flight.
 */
export default function ProtectedRoute({ requiredRole } = {}) {
  const { isAuthenticated, loading, user } = useAuth();
  const location = useLocation();

  // Block rendering until auth resolution is complete — show spinner.
  if (loading) {
    return (
      <div
        className="flex items-center justify-center h-screen bg-app"
        style={{ flexDirection: 'column', gap: 12 }}
      >
        <Hexagon size={28} className="text-accent-blue animate-pulse" />
        <span className="text-secondary text-sm">Loading…</span>
      </div>
    );
  }

  // Auth resolved and user is not authenticated — redirect to login.
  if (!isAuthenticated) {
    const nextPath = `${location.pathname}${location.search}${location.hash}`;
    return <Navigate to="/login" replace state={{ from: nextPath }} />;
  }

  // Role check — if a required role is specified and the user doesn't have it,
  // redirect to the unauthorized page instead of rendering the route.
  if (requiredRole && user?.role !== requiredRole) {
    return <Navigate to="/unauthorized" replace />;
  }

  return <Outlet />;
}

