import { Search, X } from 'lucide-react';
import { getSmartQueryError } from './smartSearchQuery.js';

/**
 * SearchInput — styled search field with prepended icon.
 * Props:
 *   value       : string
 *   onChange    : (value: string) => void
 *   placeholder : string
 *   className   : string  (wrapper extra classes)
 *   width       : number | string  (default 260)
 */
export default function SearchInput({
  value,
  onChange,
  placeholder = 'Search…',
  className = '',
  width = 260,
  useRegex = false,
  allowRegex = false,
  helperText = '',
  ...inputProps
}) {
  const query = String(value || '');
  const regexError = allowRegex ? getSmartQueryError(query, useRegex) : '';

  return (
    <div style={{ width, display: 'flex', flexDirection: 'column', gap: 4 }}>
      <div
        className={`relative flex items-center ${className}`}
        style={{ width: '100%' }}
      >
        <Search
          size={14}
          style={{
            position: 'absolute',
            left: 10,
            color: 'var(--text-tertiary)',
            pointerEvents: 'none',
            flexShrink: 0,
          }}
        />
        <input
          type="text"
          value={query}
          readOnly={Boolean(inputProps.onFocus)}
          onChange={(e) => onChange?.(e.target.value)}
          placeholder={placeholder}
          className="w-full text-sm rounded-lg theme-transition cursor-text"
          style={{
            background: 'var(--bg-input)',
            border: `1px solid ${regexError ? 'var(--color-error)' : 'var(--border-main)'}`,
            color: 'var(--text-primary)',
            padding: '7px 12px 7px 30px',
            paddingRight: query ? 30 : 12,
            outline: 'none',
            fontFamily: 'inherit',
            width: '100%',
            cursor: inputProps.onFocus ? 'pointer' : 'text',
          }}
          onMouseEnter={(e) => {
            if (!regexError) e.currentTarget.style.borderColor = 'var(--accent-blue)';
            e.currentTarget.style.background = 'var(--bg-input-hover)';
          }}
          onMouseLeave={(e) => {
            if (!regexError && document.activeElement !== e.currentTarget) {
              e.currentTarget.style.borderColor = 'var(--border-main)';
              e.currentTarget.style.background = 'var(--bg-input)';
            }
          }}
          onFocus={(e) => {
            if (!regexError) e.currentTarget.style.borderColor = 'var(--accent-blue)';
            inputProps.onFocus?.(e);
          }}
          onBlur={(e) => {
            e.currentTarget.style.borderColor = regexError ? 'var(--color-error)' : 'var(--border-main)';
            e.currentTarget.style.background = 'var(--bg-input)';
            inputProps.onBlur?.(e);
          }}
        />

        {query && (
          <button
            type="button"
            onMouseDown={(e) => {
              e.stopPropagation();
            }}
            onClick={(e) => {
              e.stopPropagation();
              onChange?.('');
            }}
            title="Clear"
            style={{
              position: 'absolute',
              right: 6,
              zIndex: 2,
              width: 22,
              height: 22,
              border: '1px solid var(--border-main)',
              borderRadius: 6,
              background: 'var(--bg-surface-raised)',
              color: 'var(--text-secondary)',
              cursor: 'pointer',
              display: 'inline-flex',
              alignItems: 'center',
              justifyContent: 'center',
              boxShadow: '0 2px 4px rgba(0,0,0,0.2)',
            }}
          >
