function SummaryCard({ label, value, color }) {
    return (
        <Card style={{ padding: '12px 14px', flex: '1 1 140px', minWidth: 0 }}>
            <div style={{ fontSize: 12, color: 'var(--text-tertiary)' }}>{label}</div>
            <div style={{ fontSize: 24, fontWeight: 700, marginTop: 2, color: value ? color : 'var(--text-primary)' }}>
                {Number(value ?? 0).toLocaleString()}
            </div>
        </Card>
    );
}

function Value({ v, muted, mono }) {
    if (v === null || v === undefined || v === '') {
        return <span style={{ color: 'var(--text-tertiary)' }}>—</span>;
    }
    if (v === true || v === false) return <span>{v ? 'Yes' : 'No'}</span>;
    return (
        <span style={{
            fontFamily: mono && !muted ? 'var(--font-mono, ui-monospace, monospace)' : 'inherit',
            fontSize: 12, color: muted ? 'var(--text-tertiary)' : 'inherit',
            whiteSpace: 'pre-wrap', wordBreak: 'break-word',
        }}>
            {String(v)}
        </span>
    );
}

const MONO_PROPS = new Set(['expression', 'type', 'sql', 'expr']);

const VERDICT_TONE = {
    EQUIVALENT: { color: 'var(--color-success)', bg: 'var(--color-success-bg)', text: 'AI: same meaning' },
    PARTIAL: { color: 'var(--color-warning)', bg: 'var(--color-warning-bg)', text: 'AI: partly the same' },
    DIFFERENT: { color: 'var(--color-error)', bg: 'var(--color-error-bg)', text: 'AI: different' },
};

function VerdictPill({ verdict, open, onToggle }) {
    if (!verdict) return null;
    const t = verdict.error
        ? { color: 'var(--text-tertiary)', bg: 'var(--bg-surface-raised)', text: 'AI check unavailable' }
        : (VERDICT_TONE[verdict.verdict] || VERDICT_TONE.DIFFERENT);
    return (
        <button
            type="button"
            onClick={onToggle}
            aria-expanded={open}
            title={verdict.error || verdict.reasoning}
            style={{
                display: 'inline-flex', alignItems: 'center', gap: 2, marginTop: 4,
                fontSize: 11, padding: '1px 7px', borderRadius: 999, border: 'none', cursor: 'pointer',
                color: t.color, background: t.bg,
            }}
        >
            <ChevronRight size={11} style={{ transform: open ? 'rotate(90deg)' : 'none' }} />{t.text}
        </button>
    );
}

/**
 * Results of a two-file compare: four summary cards, then one card with a
 * Tables/Columns/Measures/Relationships switch, a Changed/All filter and a
 * Name · Property · File 1 · File 2 table.
 */
export default function CompareResults({ results, file1Name, file2Name }) {
    const [category, setCategory] = useState('metrics');
    const [scope, setScope] = useState('changed');
    const [query, setQuery] = useState('');
    const [openVerdicts, setOpenVerdicts] = useState({});

    const s = results.summary || {};
    const cat = CATEGORIES.find((c) => c.id === category);

    const rows = useMemo(() => {
        const all = buildRows(category, results[category], scope === 'all');
        const q = query.trim().toLowerCase();
        return q ? all.filter((r) => r.name.toLowerCase().includes(q)) : all;
    }, [results, category, scope, query]);

    const th = { padding: '8px 12px', fontSize: 12, fontWeight: 600, color: 'var(--text-tertiary)', textAlign: 'left', borderBottom: '1px solid var(--border-light)', whiteSpace: 'nowrap' };
    const td = { padding: '8px 12px', fontSize: 13, verticalAlign: 'top', color: 'var(--text-primary)' };

    return (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
            <div style={{ display: 'flex', gap: 12, flexWrap: 'wrap' }}>
                <SummaryCard label="Identical" value={s.identical} color="var(--color-success)" />
                <SummaryCard label="Changed" value={s.modified} color="var(--color-warning)" />
                <SummaryCard label="Only in file 1" value={s.only_in_1} color="var(--accent-blue)" />
                <SummaryCard label="Only in file 2" value={s.only_in_2} color="var(--accent-purple)" />
            </div>

            <Card style={{ overflow: 'hidden' }}>
                <div style={{ display: 'flex', alignItems: 'center', gap: 10, flexWrap: 'wrap', padding: '10px 12px', borderBottom: '1px solid var(--border-light)' }}>
                    <Segmented
                        value={category}
                        onChange={setCategory}
                        options={CATEGORIES.map((c) => ({ id: c.id, label: c.label, count: changedCount(results[c.id]) || null }))}
                    />
                    <Segmented
                        value={scope}
                        onChange={setScope}
                        options={[{ id: 'changed', label: 'Changed' }, { id: 'all', label: 'All' }]}
                    />
                    <div style={{ marginLeft: 'auto', display: 'flex', alignItems: 'center', gap: 6, padding: '4px 10px', borderRadius: 6, border: '1px solid var(--border-main)', background: 'var(--bg-input)' }}>
                        <Search size={13} color="var(--text-tertiary)" />
                        <input value={query} onChange={(e) => setQuery(e.target.value)} placeholder={`Filter ${cat.label.toLowerCase()}…`} aria-label={`Filter ${cat.label.toLowerCase()}`}
                            style={{ border: 'none', outline: 'none', background: 'transparent', fontSize: 13, color: 'var(--text-primary)', width: 160 }} />
                    </div>
                </div>

                {rows.length === 0 ? (
                    <div style={{ padding: 16, fontSize: 13, color: 'var(--text-tertiary)' }}>
                        {query ? 'Nothing matches this filter.' : scope === 'changed' ? `No differences in ${cat.label.toLowerCase()}.` : `No ${cat.label.toLowerCase()} in either file.`}
                    </div>
                ) : (
                    <div style={{ overflowX: 'auto' }}>
                        <table style={{ width: '100%', borderCollapse: 'collapse', tableLayout: 'fixed', minWidth: 640 }}>
                            <colgroup>
                                <col style={{ width: '28%' }} /><col style={{ width: '14%' }} /><col style={{ width: '29%' }} /><col style={{ width: '29%' }} />
                            </colgroup>
                            <thead>
                                <tr>
                                    <th style={th}>{cat.singular}</th>
                                    <th style={th}>Property</th>
                                    <th style={th} title={file1Name}>File 1</th>
                                    <th style={th} title={file2Name}>File 2</th>
                                </tr>
                            </thead>
                            <tbody>
                                {rows.map((r) => {
                                    const verdict = r.first ? r.item._llm_verdict : null;
                                    const open = Boolean(openVerdicts[r.item._id]);
                                    return (
                                        <Fragment key={r.key}>
                                            <tr style={{ borderTop: r.first ? '1px solid var(--border-light)' : 'none' }}>
                                                <td style={{ ...td, fontWeight: 600, wordBreak: 'break-word' }}>
                                                    {r.first ? r.name : ''}
                                                    {verdict && (
                                                        <div><VerdictPill verdict={verdict} open={open} onToggle={() => setOpenVerdicts((o) => ({ ...o, [r.item._id]: !o[r.item._id] }))} /></div>
                                                    )}
                                                </td>
                                                <td style={{ ...td, color: 'var(--text-secondary)' }}>{r.property}</td>
                                                <td style={td}>
                                                    <Value v={r.missing === 1 ? null : r.v1} muted={r.same || r.missing === 2} mono={MONO_PROPS.has(r.property)} />
                                                </td>
                                                <td style={td}>
                                                    <Value v={r.missing === 2 ? null : r.v2} muted={r.same || r.missing === 1} mono={MONO_PROPS.has(r.property)} />
                                                </td>
                                            </tr>
                                            {verdict && open && (
                                                <tr>
                                                    <td colSpan={4} style={{ padding: '0 12px 10px' }}>
                                                        <div style={{ fontSize: 12, color: 'var(--text-secondary)', padding: '8px 10px', borderRadius: 6, background: 'var(--bg-surface-raised)' }}>
                                                            {verdict.error || verdict.reasoning}
                                                            {Array.isArray(verdict.key_differences) && verdict.key_differences.length > 0 && (
                                                                <ul style={{ margin: '6px 0 0', paddingLeft: 18 }}>
                                                                    {verdict.key_differences.map((d, i) => <li key={i}>{d}</li>)}
                                                                </ul>
                                                            )}
                                                            {verdict.model_used && <div style={{ marginTop: 6, fontSize: 11, color: 'var(--text-tertiary)' }}>via {verdict.model_used}</div>}
                                                        </div>
                                                    </td>
                                                </tr>
                                            )}
                                        </Fragment>
                                    );
                                })}
                            </tbody>
                        </table>
                    </div>
                )}
            </Card>
        </div>
    );
}

import { useRef, useState } from 'react';
import { UploadCloud, FileText, Loader2, AlertTriangle, X } from 'lucide-react';
import { formatLabel } from './compareUtils';

const plural = (n, word) => `${Number(n ?? 0).toLocaleString()} ${word}${n === 1 ? '' : 's'}`;

/**
 * One file slot on the Compare screen. Accepts drag-and-drop or a file
 * picker and shows "Detected: <format> · N tables · N measures" once parsed.
 */
export default function DropZone({ label, optional, file, parsed, parsing, error, expectedFormat, onFile, onClear }) {
    const inputRef = useRef(null);
    const [dragging, setDragging] = useState(false);

    const pick = () => inputRef.current?.click();
    const onDrop = (e) => {
        e.preventDefault();
        setDragging(false);
        const f = e.dataTransfer?.files?.[0];
        if (f) onFile(f);
    };

    const mismatch = parsed && expectedFormat && expectedFormat !== 'auto'
        && String(parsed.format).toUpperCase() !== expectedFormat;

    return (
        <div
            onDragOver={(e) => { e.preventDefault(); setDragging(true); }}
            onDragLeave={() => setDragging(false)}
            onDrop={onDrop}
            onClick={file ? undefined : pick}
            role={file ? undefined : 'button'}
            tabIndex={file ? undefined : 0}
            onKeyDown={file ? undefined : (e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); pick(); } }}
            aria-label={file ? undefined : `${label}: drop a YAML file or browse`}
            style={{
                flex: '1 1 260px', minWidth: 0, minHeight: 112,
                borderRadius: 10, padding: 16,
                border: file ? '1px solid var(--border-main)' : `2px dashed ${dragging ? 'var(--accent-blue)' : 'var(--border-main)'}`,
                background: dragging ? 'var(--color-accent-faint)' : 'var(--bg-surface)',
                display: 'flex', flexDirection: 'column', justifyContent: 'center', gap: 6,
                cursor: file ? 'default' : 'pointer',
                transition: 'border-color 120ms, background 120ms',
            }}
        >
            <input
                ref={inputRef}
                type="file"
                accept=".yaml,.yml"
                style={{ display: 'none' }}
                onChange={(e) => { const f = e.target.files?.[0]; if (f) onFile(f); e.target.value = ''; }}
            />
            <div style={{ fontSize: 12, fontWeight: 600, color: 'var(--text-tertiary)' }}>
                {label}{optional && !file ? ' · optional' : ''}
            </div>

            {!file ? (
                <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
                    <UploadCloud size={20} color="var(--text-tertiary)" />
                    <div>
                        <div style={{ fontSize: 13, color: 'var(--text-primary)' }}>
                            Drop a YAML file here or <span style={{ color: 'var(--accent-blue)', fontWeight: 600 }}>browse</span>
                        </div>
                        <div style={{ fontSize: 12, color: 'var(--text-tertiary)' }}>
                            {optional ? 'Add a second file to compare, or leave empty to inspect one.' : 'OSI, SML, Snowflake, dbt, Cube and more — detected automatically.'}
                        </div>
                    </div>
                </div>
            ) : (
                <>
                    <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                        <FileText size={16} color="var(--accent-blue)" />
                        <span style={{ fontSize: 14, fontWeight: 600, color: 'var(--text-primary)', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap', minWidth: 0 }}>{file.name}</span>
                        <div style={{ marginLeft: 'auto', display: 'flex', gap: 6, flexShrink: 0 }}>
                            <button type="button" onClick={pick} style={{ fontSize: 12, padding: '3px 10px', borderRadius: 6, border: '1px solid var(--border-main)', background: 'var(--bg-surface)', color: 'var(--text-primary)', cursor: 'pointer' }}>
                                Change
                            </button>
                            {onClear && (
                                <button type="button" onClick={onClear} aria-label={`Remove ${label}`} title="Remove" style={{ padding: '3px 6px', borderRadius: 6, border: '1px solid var(--border-main)', background: 'var(--bg-surface)', color: 'var(--text-tertiary)', cursor: 'pointer', display: 'inline-flex' }}>
                                    <X size={13} />
                                </button>
                            )}
                        </div>
                    </div>
                    <div style={{ fontSize: 12, color: 'var(--text-secondary)', minHeight: 18 }}>
                        {parsing && <span style={{ display: 'inline-flex', alignItems: 'center', gap: 6 }}><Loader2 size={12} className="animate-spin" /> Reading file…</span>}
                        {!parsing && error && <span style={{ color: 'var(--color-error)', display: 'inline-flex', alignItems: 'center', gap: 6 }}><AlertTriangle size={12} /> {error}</span>}
                        {!parsing && !error && parsed && (
                            <>Detected: <strong style={{ color: 'var(--text-primary)', fontWeight: 600 }}>{formatLabel(parsed.format)}</strong>
                                {' · '}{plural(parsed.summary?.total_tables, 'table')}
                                {' · '}{plural(parsed.summary?.total_metrics, 'measure')}</>
                        )}
                    </div>
                    {mismatch && (
                        <div style={{ fontSize: 12, color: 'var(--color-warning)', display: 'flex', alignItems: 'center', gap: 6 }}>
                            <AlertTriangle size={12} /> Expected {formatLabel(expectedFormat)}, but this file looks like {formatLabel(parsed.format)}.
                        </div>
                    )}
                </>
            )}
        </div>
    );
}

import { useEffect, useState } from 'react';
import { Loader2, RotateCcw } from 'lucide-react';
import { api } from '../../utils/api';
import { Btn } from './ui';

const plural = (n, one, many) => `${n} ${n === 1 ? one : many}`;

/**
 * The single confirmation step for "Restore this version": loads the dry-run
 * impact (current state vs. the chosen version) and states it in plain words.
 */
export default function RestoreDialog({ projectId, projectName, snapshotId, versionLabel, busy, onConfirm, onCancel }) {
    const [preview, setPreview] = useState(null);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState('');

    useEffect(() => {
        // Mounted fresh for each restore, so loading starts as true.
        let cancelled = false;
        api.previewRestore(projectId, snapshotId)
            .then((data) => { if (!cancelled) setPreview(data); })
            .catch((e) => { if (!cancelled) setError(e?.message || 'Could not work out the impact of this restore.'); })
            .finally(() => { if (!cancelled) setLoading(false); });
        return () => { cancelled = true; };
    }, [projectId, snapshotId]);

    useEffect(() => {
        const onKey = (e) => { if (e.key === 'Escape' && !busy) onCancel(); };
        document.addEventListener('keydown', onKey);
        return () => document.removeEventListener('keydown', onKey);
    }, [busy, onCancel]);

    const s = preview?.impact_summary;
    const affected = (preview?.models || []).filter((m) => m.status !== 'UNCHANGED');

    // previewRestore diffs CURRENT -> TARGET, so "ADDED" means the model
    // comes back with the restore and "REMOVED" means it goes away.
    const sentences = [];
    if (s) {
        if (s.added) sentences.push(`${plural(s.added, 'model comes', 'models come')} back`);
        if (s.modified) sentences.push(`${plural(s.modified, 'model is', 'models are')} rolled back to the earlier definition`);
        if (s.removed) sentences.push(`${plural(s.removed, 'model', 'models')} added since then ${s.removed === 1 ? 'is' : 'are'} removed`);
        if (s.unchanged) sentences.push(`${plural(s.unchanged, 'model stays', 'models stay')} the same`);
    }

    return (
        <div role="dialog" aria-modal="true" aria-labelledby="restore-title" style={{ position: 'fixed', inset: 0, zIndex: 200, display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 16 }}>
            <div onClick={() => !busy && onCancel()} style={{ position: 'absolute', inset: 0, background: 'var(--bg-backdrop, rgba(0,0,0,0.5))' }} />
            <div style={{
                position: 'relative', width: '100%', maxWidth: 520,
                background: 'var(--bg-surface)', border: '1px solid var(--border-main)', borderRadius: 12,
                boxShadow: 'var(--shadow-lg)', padding: 20,
            }}>
                <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 12 }}>
                    <RotateCcw size={18} color="var(--color-error)" />
                    <h3 id="restore-title" style={{ margin: 0, fontSize: 16, fontWeight: 700, color: 'var(--text-primary)' }}>
                        Restore {versionLabel}?
                    </h3>
                </div>

                {loading ? (
                    <div style={{ display: 'flex', alignItems: 'center', gap: 8, fontSize: 13, color: 'var(--text-tertiary)', padding: '12px 0' }}>
                        <Loader2 size={14} className="animate-spin" /> Checking what would change…
                    </div>
                ) : error ? (
                    <p style={{ fontSize: 13, color: 'var(--color-warning)', margin: '0 0 12px' }}>
                        {error} You can still restore, but the impact could not be shown.
                    </p>
                ) : (
                    <>
                        <p style={{ fontSize: 13, color: 'var(--text-secondary)', lineHeight: 1.55, margin: '0 0 10px' }}>
                            This replaces the current model of <strong style={{ color: 'var(--text-primary)' }}>{projectName || 'this project'}</strong> with {versionLabel} and pushes it to the target.
                            {sentences.length > 0 ? ` ${sentences.join('; ')}.` : ' Nothing would change — the current model already matches this version.'}
                        </p>
                        {affected.length > 0 && (
                            <ul style={{
                                listStyle: 'none', margin: '0 0 10px', padding: '6px 10px', maxHeight: 160, overflowY: 'auto',
                                border: '1px solid var(--border-light)', borderRadius: 8, background: 'var(--bg-surface-raised)',
                            }}>
                                {affected.map((m) => (
                                    <li key={`${m.status}:${m.name}`} style={{ fontSize: 12, padding: '2px 0', color: 'var(--text-primary)' }}>
                                        <span style={{ display: 'inline-block', width: 14, fontFamily: 'monospace', color: m.status === 'ADDED' ? 'var(--color-success)' : m.status === 'REMOVED' ? 'var(--color-error)' : 'var(--color-warning)' }}>
                                            {m.status === 'ADDED' ? '+' : m.status === 'REMOVED' ? '−' : '~'}
                                        </span>
                                        {m.name}
                                    </li>
                                ))}
                            </ul>
                        )}
                        <p style={{ fontSize: 12, color: 'var(--text-tertiary)', margin: '0 0 4px' }}>
                            The restore runs like a normal run, so it is saved as a new version you can undo from here.
                        </p>
                    </>
                )}

                <div style={{ display: 'flex', justifyContent: 'flex-end', gap: 8, marginTop: 16 }}>
                    <Btn onClick={onCancel} disabled={busy}>Cancel</Btn>
                    <Btn variant="dangerSolid" onClick={onConfirm} disabled={busy || loading}>
                        {busy ? <Loader2 size={14} className="animate-spin" /> : <RotateCcw size={14} />} Restore this version
                    </Btn>
                </div>
            </div>
        </div>
    );
}

import { useEffect, useState } from 'react';
import { ChevronRight } from 'lucide-react';
import { api } from '../../utils/api';
import { longTime } from './historyUtils';

/**
 * Collapsed "Storage" footer for the History screen. Replaces the old
 * "Pruning Intelligence" box and the Stats tab; shows only values the
 * backend actually returns (nothing when a call fails).
 */
export default function StorageDisclosure({ projectId, oldestRun, versionCount }) {
    const [open, setOpen] = useState(false);
    const [stats, setStats] = useState(null);
    const [vcStats, setVcStats] = useState(null);

    useEffect(() => {
        if (!open || !projectId) return undefined;
        let cancelled = false;
        const load = async (path, set) => {
            try {
                const res = await api.apiFetch(path);
                if (!res.ok) return;
                const json = await res.json();
                if (!cancelled) set(json);
            } catch {
                /* leave empty: show nothing rather than a made-up number */
            }
        };
        load(`/projects/${projectId}/stats`, setStats);
        load(`/projects/${projectId}/vc/stats`, setVcStats);
        return () => { cancelled = true; };
    }, [open, projectId]);

    const rows = [
        ['Versions (runs)', versionCount],
        ['Saved snapshots', stats?.total_snapshots ?? vcStats?.snapshot_count],
        ['Pinned', stats?.pinned_count],
        ['Storage used', vcStats?.estimated_size_kb != null ? `${Number(vcStats.estimated_size_kb).toLocaleString(undefined, { maximumFractionDigits: 1 })} KB` : stats?.storage_estimate],
        ['Oldest version', oldestRun ? longTime(oldestRun.started_at) : null],
    ].filter(([, v]) => v != null && v !== '');

    return (
        <div style={{ marginTop: 20, borderTop: '1px solid var(--border-light)', paddingTop: 10 }}>
            <button
                type="button"
                onClick={() => setOpen((v) => !v)}
                aria-expanded={open}
                style={{ display: 'inline-flex', alignItems: 'center', gap: 6, padding: 0, border: 'none', background: 'none', cursor: 'pointer', fontSize: 13, color: 'var(--text-secondary)' }}
            >
                <ChevronRight size={14} style={{ transform: open ? 'rotate(90deg)' : 'none', transition: 'transform 120ms' }} />
                Storage
            </button>
            {open && (
                <div style={{ marginTop: 8, display: 'flex', flexWrap: 'wrap', gap: '6px 28px' }}>
                    {rows.map(([k, v]) => (
                        <div key={k} style={{ fontSize: 12 }}>
                            <span style={{ color: 'var(--text-tertiary)' }}>{k}: </span>
                            <span style={{ color: 'var(--text-primary)', fontWeight: 600 }}>{v}</span>
                        </div>
                    ))}
                    <div style={{ fontSize: 12, color: 'var(--text-tertiary)', flexBasis: '100%' }}>
                        Pinned versions are kept when old versions are cleaned up.
                    </div>
                </div>
            )}
        </div>
    );
}

import { useMemo, useState } from 'react';
import { Download, Pin, RotateCcw, Tag, Loader2, AlertTriangle } from 'lucide-react';
import { Btn, Card, MenuButton, Pill, Segmented } from './ui';
import { countDiff, longTime, modelWord, statusLabel, triggerLabel } from './historyUtils';

const ROW_STYLE = {
    ADDED: { sign: '+', color: 'var(--color-success)', word: 'new model' },
    MODIFIED: { sign: '~', color: 'var(--color-warning)', word: 'changed' },
    REMOVED: { sign: '−', color: 'var(--color-error)', word: 'model removed' },
};

const FILTERS = [
    { id: 'ALL', label: 'All' },
    { id: 'ADDED', label: 'Added' },
    { id: 'MODIFIED', label: 'Changed' },
    { id: 'REMOVED', label: 'Removed' },
];

function CountCard({ label, value, color }) {
    return (
        <Card style={{ padding: '12px 14px', flex: '1 1 120px', minWidth: 0 }}>
            <div style={{ fontSize: 12, color: 'var(--text-tertiary)' }}>{label}</div>
            <div style={{ display: 'flex', alignItems: 'baseline', gap: 6, marginTop: 4 }}>
                <span style={{ fontSize: 22, fontWeight: 700, color: value ? color : 'var(--text-primary)' }}>{value ?? '—'}</span>
                {value != null && <span style={{ fontSize: 12, color: 'var(--text-secondary)' }}>{modelWord(value)}</span>}
            </div>
        </Card>
    );
}

/**
 * Right column of the Versions tab: the selected version, its actions, the
 * four count cards and the "Changes vs <base>" list.
 */
export default function VersionDetail({
    run, runNumber, pinned, tag,
    compareItems, baseLabel,
    diff, onModelClick,
    onDownload, modelReports, onDownloadModel,
    onTogglePin, onAddTag, onRestore, canRestore,
}) {
    const [filter, setFilter] = useState('ALL');
    const [tagDraft, setTagDraft] = useState(null);

    const counts = useMemo(() => (diff?.models ? countDiff(diff.models) : null), [diff]);
    const changed = useMemo(
        () => (diff?.models || []).filter((m) => m.status !== 'UNCHANGED' && (filter === 'ALL' || m.status === filter)),
        [diff, filter],
    );

    const st = statusLabel(run.status);
    const hasPerFileReports = Array.isArray(modelReports) && modelReports.length > 0;

    return (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 16, minWidth: 0 }}>
            {/* Title + actions */}
            <div style={{ display: 'flex', flexWrap: 'wrap', gap: 12, alignItems: 'flex-start', justifyContent: 'space-between' }}>
                <div style={{ minWidth: 0 }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: 8, flexWrap: 'wrap' }}>
                        <h2 style={{ margin: 0, fontSize: 18, fontWeight: 700, color: 'var(--text-primary)' }}>Run #{runNumber}</h2>
                        <Pill tone={st.tone}>{st.text}</Pill>
                        {(pinned || tag) && (
                            <Pill tone="warning">{pinned && <Pin size={10} />}{tag || 'Pinned'}</Pill>
                        )}
                    </div>
                    <div style={{ fontSize: 13, color: 'var(--text-secondary)', marginTop: 4 }}>
                        {longTime(run.started_at)} · {triggerLabel(run)}
                        <span style={{ color: 'var(--text-tertiary)', fontFamily: 'monospace', fontSize: 11, marginLeft: 8 }}>{run.run_id}</span>
                    </div>
                    {tagDraft == null ? (
                        <button
                            type="button"
                            onClick={() => setTagDraft(tag || '')}
                            style={{ marginTop: 4, padding: 0, border: 'none', background: 'none', cursor: 'pointer', fontSize: 12, color: 'var(--accent-blue)', display: 'inline-flex', alignItems: 'center', gap: 4 }}
                        >
                            <Tag size={11} /> {tag ? 'Edit label' : 'Add label'}
                        </button>
                    ) : (
                        <form
                            onSubmit={(e) => { e.preventDefault(); if (tagDraft.trim()) onAddTag(tagDraft.trim()); setTagDraft(null); }}
                            style={{ display: 'flex', gap: 6, marginTop: 6 }}
                        >
                            <input
                                autoFocus
                                value={tagDraft}
                                onChange={(e) => setTagDraft(e.target.value)}
                                placeholder="e.g. Q3 baseline"
                                aria-label="Version label"
                                style={{ padding: '4px 8px', fontSize: 12, borderRadius: 6, border: '1px solid var(--border-main)', background: 'var(--bg-input)', color: 'var(--text-primary)' }}
                            />
                            <Btn type="submit" style={{ padding: '3px 10px', fontSize: 12 }}>Save</Btn>
                            <Btn variant="ghost" onClick={() => setTagDraft(null)} style={{ padding: '3px 8px', fontSize: 12 }}>Cancel</Btn>
                        </form>
                    )}
                </div>

                <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap' }}>
                    <MenuButton label="Compare with…" items={compareItems} />
                    {hasPerFileReports ? (
                        <MenuButton
                            label="Download"
                            icon={<Download size={14} />}
                            items={modelReports.map((entry) => ({
                                key: entry.model,
                                label: entry.model,
                                hint: 'Run report for this file',
                                onClick: () => onDownloadModel(entry.model),
                            }))}
                        />
                    ) : (
                        <Btn onClick={onDownload} title="Download the run report (available for every run, success or failure)">
                            <Download size={14} /> Download
                        </Btn>
                    )}
                    <Btn onClick={onTogglePin} aria-pressed={pinned} title={pinned ? 'Unpin: allow this version to be cleaned up' : 'Pin: keep this version when old versions are cleaned up'}>
                        <Pin size={14} style={pinned ? { fill: 'currentColor' } : undefined} /> {pinned ? 'Unpin' : 'Pin'}
                    </Btn>
                    <Btn variant="danger" onClick={onRestore} disabled={!canRestore} title={canRestore ? undefined : 'This version has no saved model to restore'}>
                        <RotateCcw size={14} /> Restore this version
                    </Btn>
                </div>
            </div>

            {/* Count cards */}
            <div style={{ display: 'flex', gap: 12, flexWrap: 'wrap' }}>
                <CountCard label="Added" value={counts?.added} color="var(--color-success)" />
                <CountCard label="Changed" value={counts?.changed} color="var(--color-warning)" />
                <CountCard label="Removed" value={counts?.removed} color="var(--color-error)" />
                <CountCard label="Unchanged" value={counts?.unchanged} color="var(--text-primary)" />
            </div>

            {/* Changes list */}
            <Card>
                <div style={{
                    display: 'flex', alignItems: 'center', gap: 12, flexWrap: 'wrap',
                    padding: '10px 14px', borderBottom: '1px solid var(--border-light)',
                }}>
                    <span style={{ fontSize: 14, fontWeight: 600, color: 'var(--text-primary)' }}>Changes vs {baseLabel || '—'}</span>
                    <div style={{ marginLeft: 'auto' }}>
                        <Segmented options={FILTERS} value={filter} onChange={setFilter} />
                    </div>
                </div>

                {diff?.loading && (
                    <div style={{ padding: 16, fontSize: 13, color: 'var(--text-tertiary)', display: 'flex', alignItems: 'center', gap: 8 }}>
                        <Loader2 size={14} className="animate-spin" /> Working out what changed…
                    </div>
                )}
                {diff?.error && (
                    <div style={{ padding: 16, fontSize: 13, color: 'var(--color-warning)', display: 'flex', alignItems: 'center', gap: 8 }}>
                        <AlertTriangle size={14} /> {diff.error}
                    </div>
                )}
                {!diff && (
                    <div style={{ padding: 16, fontSize: 13, color: 'var(--text-tertiary)' }}>
                        There is no earlier version to compare with. Pick one from “Compare with…”.
                    </div>
                )}
                {diff?.models && !diff.loading && changed.length === 0 && (
                    <div style={{ padding: 16, fontSize: 13, color: 'var(--text-tertiary)' }}>
                        {filter === 'ALL' ? 'No changes — the models are identical.' : 'Nothing in this category.'}
                    </div>
                )}
                {diff?.models && !diff.loading && changed.map((m) => {
                    const s = ROW_STYLE[m.status] || ROW_STYLE.MODIFIED;
                    return (
                        <button
                            key={`${m.status}:${m.name}`}
                            type="button"
                            onClick={() => onModelClick?.(m.name)}
                            title="Show this model's history"
                            style={{
                                display: 'flex', alignItems: 'baseline', gap: 10, width: '100%', textAlign: 'left',
                                padding: '8px 14px', border: 'none', borderTop: '1px solid var(--border-light)',
                                background: 'transparent', cursor: 'pointer',
                            }}
                            onMouseEnter={(e) => { e.currentTarget.style.background = 'var(--bg-surface-hover)'; }}
                            onMouseLeave={(e) => { e.currentTarget.style.background = 'transparent'; }}
                        >
                            <span style={{ width: 12, fontFamily: 'monospace', fontWeight: 700, color: s.color }}>{s.sign}</span>
                            <span style={{ fontSize: 13, fontWeight: 600, color: 'var(--text-primary)', wordBreak: 'break-word' }}>{m.name}</span>
                            <span style={{ fontSize: 12, color: 'var(--text-tertiary)' }}>{s.word}</span>
                        </button>
                    );
                })}
            </Card>
        </div>
    );
}

import { useMemo } from 'react';
import { Pin, Search } from 'lucide-react';
import { groupRunsByDay, shortTime, statusLabel } from './historyUtils';

/**
 * Left column of the Versions tab: runs grouped by day, newest first.
 * Props:
 *   runs          newest-first run list (already filtered)
 *   runNumber     (run) => number shown as "Run #N"
 *   selectedId    run_id of the selected version
 *   onSelect      (run) => void
 *   summaries     { [run_id]: string }  short change summary per run, when known
 *   pinInfo       (run) => { pinned, tag }
 *   query/onQuery filter text
 */
export default function VersionList({ runs, runNumber, selectedId, onSelect, summaries, pinInfo, query, onQuery, loading }) {
    const groups = useMemo(() => groupRunsByDay(runs), [runs]);

    return (
        <div style={{ display: 'flex', flexDirection: 'column', minHeight: 0 }}>
            <div style={{ padding: 10, borderBottom: '1px solid var(--border-light)' }}>
                <div style={{
                    display: 'flex', alignItems: 'center', gap: 6, padding: '6px 10px', borderRadius: 6,
                    border: '1px solid var(--border-main)', background: 'var(--bg-input)',
                }}>
                    <Search size={14} color="var(--text-tertiary)" />
                    <input
                        type="text"
                        value={query}
                        onChange={(e) => onQuery(e.target.value)}
                        placeholder="Filter by run or tag…"
                        aria-label="Filter versions by run or tag"
                        style={{ flex: 1, minWidth: 0, border: 'none', outline: 'none', background: 'transparent', fontSize: 13, color: 'var(--text-primary)' }}
                    />
                </div>
            </div>

            <div style={{ overflowY: 'auto', maxHeight: 'calc(100vh - 300px)', minHeight: 200 }}>
                {loading && runs.length === 0 && (
                    <div style={{ padding: 16, fontSize: 13, color: 'var(--text-tertiary)' }}>Loading versions…</div>
                )}
                {!loading && runs.length === 0 && (
                    <div style={{ padding: 16, fontSize: 13, color: 'var(--text-tertiary)' }}>
                        {query ? 'No versions match this filter.' : 'No versions yet. A version is saved every time this project runs.'}
                    </div>
                )}
                {groups.map((g) => (
                    <div key={g.label}>
                        <div style={{
                            padding: '10px 14px 4px', fontSize: 11, fontWeight: 600,
                            color: 'var(--text-tertiary)', textTransform: 'uppercase', letterSpacing: '0.04em',
                        }}>
                            {g.label}
                        </div>
                        {g.runs.map((run) => {
                            const active = run.run_id === selectedId;
                            const { pinned, tag } = pinInfo(run);
                            const st = statusLabel(run.status);
                            const summary = summaries[run.run_id];
                            return (
                                <button
                                    key={run.run_id}
                                    type="button"
                                    onClick={() => onSelect(run)}
                                    aria-current={active ? 'true' : undefined}
                                    style={{
                                        display: 'block', width: '100%', textAlign: 'left',
                                        padding: '8px 14px', border: 'none',
                                        borderLeft: `3px solid ${active ? 'var(--accent-blue)' : 'transparent'}`,
                                        background: active ? 'var(--color-accent-faint)' : 'transparent',
                                        cursor: 'pointer',
                                    }}
                                    onMouseEnter={(e) => { if (!active) e.currentTarget.style.background = 'var(--bg-surface-hover)'; }}
                                    onMouseLeave={(e) => { e.currentTarget.style.background = active ? 'var(--color-accent-faint)' : 'transparent'; }}
                                >
                                    <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
                                        <span style={{ fontSize: 13, fontWeight: 600, color: 'var(--text-primary)' }}>Run #{runNumber(run)}</span>
                                        {(pinned || tag) && (
                                            <span style={{
                                                display: 'inline-flex', alignItems: 'center', gap: 3,
                                                fontSize: 11, padding: '0 6px', borderRadius: 999,
                                                background: 'var(--color-warning-bg)', color: 'var(--color-warning)',
                                            }}>
                                                {pinned && <Pin size={10} />}{tag || 'Pinned'}
                                            </span>
                                        )}
                                        {st.tone === 'error' && (
                                            <span style={{ fontSize: 11, color: 'var(--color-error)' }}>Failed</span>
                                        )}
                                        <span style={{ marginLeft: 'auto', fontSize: 12, color: 'var(--text-tertiary)' }}>{shortTime(run.started_at)}</span>
                                    </div>
                                    <div style={{ fontSize: 12, color: 'var(--text-secondary)', marginTop: 2, minHeight: 16 }}>
                                        {summary || ' '}
                                    </div>
                                </button>
                            );
                        })}
                    </div>
                ))}
            </div>
        </div>
    );
}

import { useEffect, useRef, useState } from 'react';
import { ChevronDown } from 'lucide-react';

// Small, theme-aware building blocks shared by the History screen.
// Inline styles + CSS variables only, matching the redesign spec.

const BTN_VARIANTS = {
    default: {
        background: 'var(--bg-surface)',
        color: 'var(--text-primary)',
        border: '1px solid var(--border-main)',
    },
    primary: {
        background: 'var(--accent-blue)',
        color: '#fff',
        border: '1px solid var(--accent-blue)',
    },
    danger: {
        background: 'transparent',
        color: 'var(--color-error)',
        border: '1px solid var(--color-error)',
    },
    dangerSolid: {
        background: 'var(--color-error)',
        color: '#fff',
        border: '1px solid var(--color-error)',
    },
    ghost: {
        background: 'transparent',
        color: 'var(--text-secondary)',
        border: '1px solid transparent',
    },
};

export function Btn({ variant = 'default', children, style, disabled, ...rest }) {
    return (
        <button
            type="button"
            disabled={disabled}
            style={{
                display: 'inline-flex', alignItems: 'center', gap: 6,
                padding: '6px 12px', borderRadius: 6,
                fontSize: 13, fontWeight: 500, lineHeight: 1.4,
                cursor: disabled ? 'not-allowed' : 'pointer',
                opacity: disabled ? 0.55 : 1,
                whiteSpace: 'nowrap',
                ...BTN_VARIANTS[variant],
                ...style,
            }}
