}

const TONES = {
    success: { color: 'var(--color-success)', bg: 'var(--color-success-bg)' },
    warning: { color: 'var(--color-warning)', bg: 'var(--color-warning-bg)' },
    error: { color: 'var(--color-error)', bg: 'var(--color-error-bg)' },
    info: { color: 'var(--accent-blue)', bg: 'var(--color-accent-faint)' },
    default: { color: 'var(--text-secondary)', bg: 'var(--bg-surface-raised)' },
};

export function Pill({ tone = 'default', children, style }) {
    const t = TONES[tone] || TONES.default;
    return (
        <span style={{
            display: 'inline-flex', alignItems: 'center', gap: 4,
            padding: '1px 8px', borderRadius: 999,
            fontSize: 11, fontWeight: 600,
            color: t.color, background: t.bg,
            ...style,
        }}>
            {children}
        </span>
    );
}

/**
 * Button + popover menu. `items` = [{ key, label, hint, onClick, disabled, danger }]
 * or a `{ key, divider: true }` / `{ key, heading }` entry.
 */
export function MenuButton({ label, items, variant = 'default', align = 'right', icon, buttonStyle }) {
    const [open, setOpen] = useState(false);
    const ref = useRef(null);

    useEffect(() => {
        if (!open) return undefined;
        const onDown = (e) => { if (ref.current && !ref.current.contains(e.target)) setOpen(false); };
        const onKey = (e) => { if (e.key === 'Escape') setOpen(false); };
        document.addEventListener('mousedown', onDown);
        document.addEventListener('keydown', onKey);
        return () => {
            document.removeEventListener('mousedown', onDown);
            document.removeEventListener('keydown', onKey);
        };
    }, [open]);

    return (
        <div ref={ref} style={{ position: 'relative', display: 'inline-block' }}>
            <Btn variant={variant} onClick={() => setOpen((v) => !v)} aria-haspopup="menu" aria-expanded={open} style={buttonStyle}>
                {icon}{label}<ChevronDown size={14} style={{ opacity: 0.7 }} />
            </Btn>
            {open && (
                <div
                    role="menu"
                    style={{
                        position: 'absolute', top: 'calc(100% + 4px)', [align]: 0,
                        minWidth: 220, maxHeight: 320, overflowY: 'auto',
                        background: 'var(--bg-surface)', border: '1px solid var(--border-main)',
                        borderRadius: 8, boxShadow: 'var(--shadow-lg)', padding: 4, zIndex: 60,
                    }}
                >
                    {items.length === 0 && (
                        <div style={{ padding: '8px 10px', fontSize: 12, color: 'var(--text-tertiary)' }}>Nothing to show</div>
                    )}
                    {items.map((it) => {
                        if (it.divider) return <div key={it.key} style={{ height: 1, background: 'var(--border-light)', margin: '4px 0' }} />;
                        if (it.heading) {
                            return (
                                <div key={it.key} style={{ padding: '6px 10px 2px', fontSize: 11, fontWeight: 600, color: 'var(--text-tertiary)' }}>
                                    {it.heading}
                                </div>
                            );
                        }
                        return (
                            <button
                                key={it.key}
                                type="button"
                                role="menuitem"
                                disabled={it.disabled}
                                onClick={() => { setOpen(false); it.onClick?.(); }}
                                style={{
                                    display: 'flex', flexDirection: 'column', alignItems: 'flex-start', gap: 1,
                                    width: '100%', textAlign: 'left', padding: '7px 10px', borderRadius: 6,
                                    background: it.active ? 'var(--color-accent-faint)' : 'transparent',
                                    border: 'none', cursor: it.disabled ? 'not-allowed' : 'pointer',
                                    opacity: it.disabled ? 0.5 : 1,
                                    color: it.danger ? 'var(--color-error)' : 'var(--text-primary)', fontSize: 13,
                                }}
                                onMouseEnter={(e) => { if (!it.active) e.currentTarget.style.background = 'var(--bg-surface-hover)'; }}
                                onMouseLeave={(e) => { e.currentTarget.style.background = it.active ? 'var(--color-accent-faint)' : 'transparent'; }}
                            >
                                <span>{it.label}</span>
                                {it.hint && <span style={{ fontSize: 11, color: 'var(--text-tertiary)' }}>{it.hint}</span>}
                            </button>
                        );
                    })}
                </div>
            )}
        </div>
    );
}

/** Pill-shaped segmented filter: options = [{ id, label, count? }] */
export function Segmented({ options, value, onChange, size = 'sm' }) {
    return (
        <div style={{
            display: 'inline-flex', padding: 2, gap: 2, borderRadius: 8,
            background: 'var(--bg-surface-raised)', border: '1px solid var(--border-light)',
        }}>
            {options.map((o) => {
                const active = o.id === value;
                return (
                    <button
                        key={o.id}
                        type="button"
                        aria-pressed={active}
                        onClick={() => onChange(o.id)}
                        style={{
                            padding: size === 'sm' ? '3px 10px' : '5px 12px', borderRadius: 6, border: 'none',
                            fontSize: 12, fontWeight: active ? 600 : 500, cursor: 'pointer',
                            background: active ? 'var(--bg-surface)' : 'transparent',
                            color: active ? 'var(--text-primary)' : 'var(--text-secondary)',
                            boxShadow: active ? 'var(--shadow-sm)' : 'none',
                        }}
                    >
                        {o.label}{o.count != null && <span style={{ marginLeft: 5, color: 'var(--text-tertiary)' }}>{o.count}</span>}
                    </button>
                );
            })}
        </div>
    );
}

import React, { useState } from 'react';
import { RefreshCw, Search, Sparkles } from 'lucide-react';
import { BTN, BTN_SM, BTN_PRIMARY, CARD, INPUT_STYLE, MONO, plural } from './styles';
import { Pill, Segmented } from './ui';
import { groupDomainsByProject, viewTail } from './domainGroups';

const TH = {
  padding: '9px 14px',
  textAlign: 'left',
  fontSize: 11,
  fontWeight: 600,
  color: 'var(--text-tertiary)',
  textTransform: 'uppercase',
  letterSpacing: '0.04em',
  borderBottom: '1px solid var(--border-main)',
  whiteSpace: 'nowrap',
};
const TD = { padding: '10px 14px', fontSize: 12.5, verticalAlign: 'top', borderBottom: '1px solid var(--border-main)' };
const SUB = { fontSize: 11.5, color: 'var(--text-tertiary)', marginTop: 2, lineHeight: 1.4 };

function Empty({ children }) {
  return <div style={{ padding: 36, textAlign: 'center', color: 'var(--text-tertiary)', fontSize: 13 }}>{children}</div>;
}

function DomainRail({ domains, selected, onSelect, issueCountFor }) {
  const [q, setQ] = useState('');
  const ql = q.trim().toLowerCase();
  const list = ql
    ? domains.filter((d) =>
        [d.domain, d.source_model_name, d.source_project_id].some((v) => String(v || '').toLowerCase().includes(ql)))
    : domains;
  const groups = groupDomainsByProject(list);
  const showHeaders = groups.length > 1 || groups.some((g) => g.multiModel);
  return (
    <div style={{ borderRight: '1px solid var(--border-main)', padding: 10, display: 'flex', flexDirection: 'column', gap: 4, minWidth: 0 }}>
      <input
        type="text"
        value={q}
        onChange={(e) => setQ(e.target.value)}
        placeholder="Filter models…"
        style={{ ...INPUT_STYLE, width: '100%', boxSizing: 'border-box', marginBottom: 6 }}
      />
      {groups.map((g) => (
        <React.Fragment key={g.key || '_other'}>
          {showHeaders && (
            <div
              style={{
                fontSize: 10.5,
                fontWeight: 700,
                textTransform: 'uppercase',
                letterSpacing: '0.05em',
                color: 'var(--text-tertiary)',
                padding: '8px 10px 2px',
              }}
              title={g.multiModel ? 'One domain per model (semantic view)' : undefined}
            >
              {g.label}
              {g.multiModel && <span style={{ fontWeight: 500, textTransform: 'none', letterSpacing: 0 }}> · {plural(g.items.filter((d) => d.source_model_id).length, 'model')}</span>}
            </div>
          )}
          {g.items.map((d) => {
        const on = d.domain === selected;
        const issues = issueCountFor(d);
        const isModel = Boolean(d.source_model_id);
        const title = g.multiModel ? (isModel ? d.source_model_name || d.source_model_id : 'Shared') : d.domain;
        return (
          <button
            key={d.domain}
            type="button"
            onClick={() => onSelect(d.domain)}
            style={{
              textAlign: 'left',
              padding: '8px 10px',
              borderRadius: 8,
              border: 'none',
              cursor: 'pointer',
              background: on ? 'color-mix(in srgb, var(--accent-blue) 12%, transparent)' : 'transparent',
              color: 'var(--text-primary)',
              display: 'flex',
              flexDirection: 'column',
              gap: 2,
            }}
          >
            <b style={{ fontSize: 13, color: on ? 'var(--accent-blue)' : 'var(--text-primary)' }} title={d.domain}>{title}</b>
            <span style={{ fontSize: 11.5, color: 'var(--text-tertiary)', display: 'flex', alignItems: 'center', gap: 6 }}>
              <span style={{ overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                {g.multiModel && isModel && d.semantic_view_name ? `${viewTail(d.semantic_view_name)} · ` : ''}
                {!g.multiModel && d.owner ? `${d.owner} · ` : ''}
                {plural(d.metric_count || 0, 'metric')}
              </span>
              {issues > 0 && <Pill tone="warn" style={{ padding: '0 6px' }}>{issues}</Pill>}
            </span>
          </button>
        );
          })}
        </React.Fragment>
      ))}
      {list.length === 0 && <div style={{ fontSize: 12, color: 'var(--text-tertiary)', padding: 8 }}>No match</div>}
    </div>
  );
}

