            />
          </div>
          <div style={{ maxHeight: 300, overflowY: 'auto', border: '1px solid var(--border-main)', borderRadius: 8 }}>
            {TIMEZONES.filter((tz) => tz.toLowerCase().includes(query.toLowerCase())).map((tz) => (
              <button
                key={tz}
                type="button"
                onClick={() => pickTimezone(tz)}
                style={{
                  width: '100%', display: 'flex', alignItems: 'center', justifyContent: 'space-between',
                  padding: '10px 14px', fontSize: 13, textAlign: 'left', cursor: 'pointer',
                  border: 'none', borderBottom: '1px solid var(--border-main)',
                  background: timezone === tz ? 'var(--bg-surface-hover)' : 'transparent',
                  color: 'var(--text-primary)',
                }}
              >
                <span style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
                  <Globe size={14} style={{ color: 'var(--text-tertiary)' }} /> {tz}
                </span>
                {timezone === tz && <Check size={14} style={{ color: 'var(--accent-blue)' }} />}
              </button>
            ))}
          </div>
          <p style={{ fontSize: 11, color: 'var(--text-tertiary)', textAlign: 'center', margin: '12px 0 0' }}>
            Detected from this computer: {systemTimeZone()}
          </p>
        </div>
      </Modal>
    </div>
  );
}

import { useState, useEffect, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import { History, RefreshCw } from 'lucide-react';
import { api } from '../../utils/api';
import { SectionHeader, Card, ActionButton } from './settingsUi';

const MAX_PROJECTS = 50;

async function getJson(url) {
  const res = await api.apiFetch(url);
  if (!res.ok) throw new Error(`HTTP ${res.status}`);
  return res.json();
}

function formatSize(kb) {
  const n = Number(kb || 0);
  if (n >= 1024 * 1024) return `${(n / 1024 / 1024).toFixed(1)} GB`;
  if (n >= 1024) return `${(n / 1024).toFixed(1)} MB`;
  return `${Math.round(n)} KB`;
}

function describePolicy(policy) {
  if (!policy || policy.strategy === 'unlimited') return 'Keep everything';
  if (policy.strategy === 'count' && policy.max_snapshots_per_connector) {
    return `Keep last ${policy.max_snapshots_per_connector}`;
  }
  if (policy.strategy === 'days' && policy.max_age_days) {
    return `Keep ${policy.max_age_days} days`;
  }
  return policy.strategy;
}

/**
 * Settings › Storage & history — how many saved versions each project keeps,
 * how much space they use and the retention rule that prunes them.
 * Read-only; versions themselves are managed on the History page.
 */
export default function SettingsStorage() {
  const navigate = useNavigate();
  const [rows, setRows] = useState([]);
  const [total, setTotal] = useState(0);
  const [loading, setLoading] = useState(true);
  const [reloadKey, setReloadKey] = useState(0);

  useEffect(() => {
    let active = true;
    (async () => {
      let projects = [];
      try {
        projects = await api.listProjects({ limit: 200 });
      } catch {
        projects = [];
      }
      const list = (Array.isArray(projects) ? projects : [])
        .slice()
        .sort((a, b) => new Date(b?.updated_at || 0) - new Date(a?.updated_at || 0));
      const scoped = list.slice(0, MAX_PROJECTS);
      const results = await Promise.all(scoped.map(async (p) => {
        const id = p.id || p.project_id;
        const enc = encodeURIComponent(id);
        const [stats, policy] = await Promise.allSettled([
          getJson(`/version-control/stats?project_id=${enc}`),
          getJson(`/version-control/retention-policy?project_id=${enc}`),
        ]);
        return {
          id,
          name: p.name || id,
          versions: stats.status === 'fulfilled' ? Number(stats.value?.snapshot_count || 0) : null,
          sizeKb: stats.status === 'fulfilled' ? Number(stats.value?.estimated_size_kb || 0) : null,
          policy: policy.status === 'fulfilled' && policy.value?.status === 'success' ? policy.value.policy : null,
        };
      }));
      if (!active) return;
      setRows(results);
      setTotal(list.length);
      setLoading(false);
    })();
    return () => { active = false; };
  }, [reloadKey]);

  const totals = useMemo(() => rows.reduce((acc, r) => ({
    versions: acc.versions + (r.versions || 0),
    sizeKb: acc.sizeKb + (r.sizeKb || 0),
  }), { versions: 0, sizeKb: 0 }), [rows]);

  const th = { textAlign: 'left', padding: '10px 14px', fontSize: 11, fontWeight: 600, color: 'var(--text-secondary)', textTransform: 'uppercase', letterSpacing: '0.05em' };
  const td = { padding: '10px 14px', fontSize: 13, color: 'var(--text-primary)', borderTop: '1px solid var(--border-main)' };

  return (
    <div>
      <SectionHeader
        title="Storage & history"
        description="Every run saves a version of the model so you can compare and restore. Old versions are pruned by each project's retention rule; pinned versions and versions used by a run are never removed."
        action={(
          <div style={{ display: 'flex', gap: 8 }}>
            <ActionButton onClick={() => { setLoading(true); setReloadKey((k) => k + 1); }} disabled={loading} aria-label="Refresh">
              <RefreshCw size={13} className={loading ? 'animate-spin' : ''} />
            </ActionButton>
            <ActionButton onClick={() => navigate('/history')}>
              <History size={13} /> Open History
            </ActionButton>
          </div>
        )}
      />

      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(180px, 1fr))', gap: 12, marginBottom: 16 }}>
        <Stat label="Saved versions" value={loading ? '…' : totals.versions.toLocaleString()} />
        <Stat label="Space used" value={loading ? '…' : formatSize(totals.sizeKb)} />
        <Stat label="Projects" value={loading ? '…' : total.toLocaleString()} />
      </div>

      <Card style={{ padding: 0, overflow: 'hidden' }}>
        <table style={{ width: '100%', borderCollapse: 'collapse' }}>
          <thead>
            <tr style={{ background: 'var(--bg-surface-raised)' }}>
              <th style={th}>Project</th>
              <th style={{ ...th, textAlign: 'right' }}>Versions</th>
              <th style={{ ...th, textAlign: 'right' }}>Size</th>
              <th style={th}>Retention</th>
            </tr>
          </thead>
          <tbody>
            {loading ? (
              <tr><td colSpan={4} style={{ ...td, color: 'var(--text-tertiary)' }}>Loading…</td></tr>
            ) : rows.length === 0 ? (
              <tr><td colSpan={4} style={{ ...td, color: 'var(--text-tertiary)' }}>No projects yet.</td></tr>
            ) : rows.map((r) => (
              <tr key={r.id}>
                <td style={{ ...td, fontWeight: 600 }}>{r.name}</td>
                <td style={{ ...td, textAlign: 'right' }}>{r.versions ?? '—'}</td>
                <td style={{ ...td, textAlign: 'right', color: 'var(--text-secondary)' }}>{r.sizeKb == null ? '—' : formatSize(r.sizeKb)}</td>
                <td style={{ ...td, color: 'var(--text-secondary)' }}>{describePolicy(r.policy)}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </Card>
      {!loading && total > MAX_PROJECTS && (
        <p style={{ fontSize: 12, color: 'var(--text-tertiary)', margin: '8px 2px 0' }}>
          Showing the {MAX_PROJECTS} most recently updated of {total} projects.
        </p>
      )}
    </div>
  );
}

function Stat({ label, value }) {
  return (
    <div style={{ padding: '12px 14px', borderRadius: 10, border: '1px solid var(--border-main)', background: 'var(--bg-surface)' }}>
      <div style={{ fontSize: 11, fontWeight: 600, color: 'var(--text-tertiary)', textTransform: 'uppercase', letterSpacing: '.05em' }}>{label}</div>
      <div style={{ fontSize: 20, fontWeight: 700, color: 'var(--text-primary)', marginTop: 4 }}>{value}</div>
    </div>
  );
}

import { createContext, useContext, useState, useEffect, useCallback, useMemo, useRef } from 'react';
import { useQueryClient } from '@tanstack/react-query';
import { clearUIStoreStorage } from '../store/uiStore';
import { fetchWithTimeout, tryRefreshToken, resetRefreshCooldown } from '../utils/api';


const AUTH_BASE = (import.meta.env.VITE_AUTH_BASE_URL || '/auth').replace(/\/$/, '');
const AUTH_REQUEST_TIMEOUT_MS = 8000;
const AUTH_BOOTSTRAP_RETRY_DELAY_MS = 350;

const AuthContext = createContext(undefined);

/**
 * Provides authentication state & helpers to the entire app.
 *
 * In development mode, automatically calls /auth/auto-login to get a JWT
 * without showing any login page. The login page is available at /login
 * for future production use.
 *
 * Industry best practice: Never clear UI state until all recovery attempts
 * have been exhausted. Uses proactive refresh to avoid 401 flashes.
 */
export function AuthProvider({ children }) {
  const queryClient = useQueryClient();
  const [user, setUser] = useState(null);
  const [token, setToken] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  // Guard against concurrent recovery attempts
  const recoveringRef = useRef(false);
  // Timer for proactive token refresh
  const refreshTimerRef = useRef(null);
  const previousTokenRef = useRef(token);

  // ── helpers ──────────────────────────────────────────────────

  const saveToken = useCallback((jwt) => {
    previousTokenRef.current = jwt;
    setToken(jwt);
  }, []);

  const clearAuth = useCallback(() => {
    setToken(null);
    setUser(null);
  }, []);

  /** Fetch /auth/me — sends Bearer token if available, falls back to HttpOnly cookie */
  const fetchMe = useCallback(async (jwt) => {
    try {
      const currentToken = jwt || previousTokenRef.current;
      const headers = currentToken ? { Authorization: `Bearer ${currentToken}` } : {};
      const res = await fetchWithTimeout(`${AUTH_BASE}/me`, {
        credentials: 'include',
        headers,
      }, AUTH_REQUEST_TIMEOUT_MS);
      if (!res.ok) {
        return false;
      }
      const data = await res.json();
      setUser(data);
      return true;
    } catch {
      return false;
    }
  }, []);

  /**
   * Schedule a proactive token refresh at ~80% of the token's TTL.
   * This prevents the token from ever actually expiring during use,
   * eliminating 401 flashes entirely.
   */
  const scheduleProactiveRefresh = useCallback(function scheduleRefresh(jwt) {
    if (refreshTimerRef.current) {
      clearTimeout(refreshTimerRef.current);
      refreshTimerRef.current = null;
    }

    try {
      // Decode JWT payload (base64url) to read exp claim
      const parts = jwt.split('.');
      if (parts.length !== 3) return;
      const payload = JSON.parse(atob(parts[1].replace(/-/g, '+').replace(/_/g, '/')));
      const exp = payload.exp;
      if (!exp) return;

      const nowSec = Math.floor(Date.now() / 1000);
      const ttlSec = exp - nowSec;

      if (ttlSec <= 0) return; // Already expired

      // Refresh at 80% of TTL (e.g., 12 min into a 15-min token)
      const refreshInMs = Math.max(ttlSec * 0.8, 30) * 1000;

      refreshTimerRef.current = setTimeout(async () => {
        try {
          // Delegate to api.js singleton to avoid one-time-use refresh
          // token race conditions between this timer and 401 recovery.
          const newToken = await tryRefreshToken();
          if (newToken) {
            saveToken(newToken);
            resetRefreshCooldown();
            scheduleRefresh(newToken);
            return;
          }
          // tryRefreshToken already tried /auth/refresh + /auth/auto-login
          // and both failed. Schedule another attempt after a short delay.
        } catch {
          // Network error — will retry on next API call
        }
      }, refreshInMs);
    } catch {
      // JWT decode failed — skip proactive refresh
    }
  }, [saveToken]);

  /** Auto-login: create a dev user and get JWT without credentials */
  const autoLogin = useCallback(async () => {
    try {
      const res = await fetchWithTimeout(`${AUTH_BASE}/auto-login`, {
        method: 'POST',
        credentials: 'include',
      }, AUTH_REQUEST_TIMEOUT_MS);
      if (!res.ok) return false;
      const data = await res.json();
      if (data.access_token) {
        saveToken(data.access_token);
        // Use inline user data from response to avoid extra /auth/me round trip
        if (data.user) {
          setUser(data.user);
        } else {
          await fetchMe();
        }
        scheduleProactiveRefresh(data.access_token);
        return true;
      }
      return false;
    } catch {
      return false;
    }
  }, [saveToken, fetchMe, scheduleProactiveRefresh]);

  const autoLoginWithRetry = useCallback(async (attempts = 2) => {
    for (let i = 0; i < attempts; i += 1) {
      const ok = await autoLogin();
      if (ok) return true;
      if (i < attempts - 1) {
        await new Promise((resolve) => window.setTimeout(resolve, AUTH_BOOTSTRAP_RETRY_DELAY_MS));
      }
    }
    return false;
  }, [autoLogin]);

  /**
   * Silent recovery: attempt to restore the session WITHOUT clearing
   * UI state first. Only clears state if ALL recovery paths fail.
   * This prevents the "flash to Disconnected" problem.
   */
  const silentRecover = useCallback(async () => {
    if (recoveringRef.current) return; // Already recovering
    recoveringRef.current = true;

    try {
      // Step 1: Try refresh via HttpOnly cookie
      try {
        const res = await fetchWithTimeout(`${AUTH_BASE}/refresh`, {
          method: 'POST',
          credentials: 'include',
        }, AUTH_REQUEST_TIMEOUT_MS);
        if (res.ok) {
          const data = await res.json();
          if (data.access_token) {
            saveToken(data.access_token);
            await fetchMe(data.access_token);
            scheduleProactiveRefresh(data.access_token);
            return; // Success — UI state preserved
          }
        }
      } catch {
        // Network error on refresh
      }

      // Step 2: Try auto-login (dev mode fallback)
      const recovered = await autoLogin();
      if (recovered) return; // Success — UI state preserved

      // Step 3: All recovery failed — only clear state if there is
      // genuinely no usable token.  A transient network hiccup during
      // page navigation should NOT wipe the session; the proactive
      // refresh timer will retry later.
      if (!token) {
        clearAuth();
      }
    } finally {
      recoveringRef.current = false;
    }
  }, [saveToken, fetchMe, clearAuth, autoLogin, scheduleProactiveRefresh]);

  // On mount: validate existing token, or auto-login if none
  useEffect(() => {
    let cancelled = false;
    const markLoaded = () => {
      if (!cancelled) setLoading(false);
    };

    (async () => {
      // Try /auth/me using the HttpOnly cookie — if it succeeds the session is alive
      const valid = await fetchMe();
      if (valid) {
        // Cookie is valid. We don't have the raw JWT in memory yet, so we cannot
        // schedule proactive refresh by TTL. silentRecover (via /auth/refresh) will
        // re-establish the in-memory token when the cookie nears expiry.
        return;
      }

      // Cookie missing or expired — try to recover via refresh cookie / auto-login
      await silentRecover();
    })()
      .catch(() => {
        // Non-blocking bootstrap: app can still render login and public UI states.
      })
      .finally(() => {
        markLoaded();
      });

    return () => {
      cancelled = true;
      if (refreshTimerRef.current) {
        clearTimeout(refreshTimerRef.current);
      }
    };
  }, [fetchMe, silentRecover, autoLoginWithRetry]); // eslint-disable-line react-hooks/exhaustive-deps

  // Listen for auth events from api.js 401 handler
  useEffect(() => {
    const expiredHandler = async () => {
      await silentRecover();
    };
    
    // api.js interceptor successfully got a new token
    const refreshHandler = (e) => {
      const newToken = e.detail;
      saveToken(newToken);
      resetRefreshCooldown();
      scheduleProactiveRefresh(newToken);
    };

    window.addEventListener('semabridge:auth-expired', expiredHandler);
    window.addEventListener('semabridge:token-refreshed', refreshHandler);
    // Fabric token lifecycle: update UI/data when Fabric token becomes available
    const fabricRefreshedHandler = (e) => {
      // e.detail contains { access_token, expires_at }
      // Invalidate queries that may depend on Fabric credentials so consumers
      // (workspaces, models, reports) pick up the new token without a reload.
      try {
        queryClient.invalidateQueries();
      } catch (err) {
        // best-effort
      }
    };

    const fabricRemovedHandler = () => {
      try {
        queryClient.invalidateQueries();
      } catch (err) {
        // best-effort
      }
    };
    window.addEventListener('semabridge:fabric-token-refreshed', fabricRefreshedHandler);
    window.addEventListener('semabridge:fabric-token-removed', fabricRemovedHandler);
    
    return () => {
      window.removeEventListener('semabridge:auth-expired', expiredHandler);
      window.removeEventListener('semabridge:token-refreshed', refreshHandler);
      window.removeEventListener('semabridge:fabric-token-refreshed', fabricRefreshedHandler);
      window.removeEventListener('semabridge:fabric-token-removed', fabricRemovedHandler);
    };
  }, [silentRecover, saveToken, scheduleProactiveRefresh]);

  // If token changes (auto-login / refresh / login), refetch stale query data.
  // On INITIAL login (previousToken is null), skip blanket invalidation since
  // there is no stale data yet — this prevents a thundering herd of redundant
  // API requests right after authentication.
  useEffect(() => {
    const previousToken = previousTokenRef.current;
    if (!token || token === previousToken) return;
    const isInitialLogin = !previousToken;
    previousTokenRef.current = token;
    if (isInitialLogin) return; // No stale data on first login
    // Targeted invalidation: only refetch queries that depend on auth state
    queryClient.invalidateQueries({ queryKey: ['projects'] });
    queryClient.invalidateQueries({ queryKey: ['folders'] });
    queryClient.invalidateQueries({ queryKey: ['workspaces'] });
  }, [token, queryClient]);

  // ── public API ───────────────────────────────────────────────

  const register = useCallback(async (username, email, password) => {
    setError(null);
    let res;
    try {
      res = await fetchWithTimeout(`${AUTH_BASE}/register`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ username, email, password }),
      }, AUTH_REQUEST_TIMEOUT_MS);
    } catch (err) {
      const msg = err?.name === 'AbortError' ? 'Request timed out. Please try again.' : 'Network error. Please check your connection.';
      setError(msg);
      throw new Error(msg);
    }
    if (!res.ok) {
      const body = await res.json().catch(() => ({}));
      const msg = body.detail || `Registration failed (${res.status})`;
      setError(msg);
      throw new Error(msg);
    }
    return res.json();
  }, []);

  const login = useCallback(async (username, password) => {
    setError(null);
    let res;
    try {
      res = await fetchWithTimeout(`${AUTH_BASE}/login`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({ username, password }),
      }, AUTH_REQUEST_TIMEOUT_MS);
    } catch (err) {
      const msg = err?.name === 'AbortError' ? 'Request timed out. Please try again.' : 'Network error. Please check your connection.';
      setError(msg);
      throw new Error(msg);
    }
    if (!res.ok) {
      const body = await res.json().catch(() => ({}));
      const msg = body.detail || `Login failed (${res.status})`;
      setError(msg);
      throw new Error(msg);
    }
    const data = await res.json();
    // The backend now sets the access_token as an HttpOnly cookie on login.
    // Keep the in-memory token only for proactive refresh scheduling.
    if (data.access_token) {
      saveToken(data.access_token);
      scheduleProactiveRefresh(data.access_token);
    }
    // Use inline user data from login response to skip the blocking /auth/me round trip.
    if (data.user) {
      setUser(data.user);
    } else {
      await fetchMe(data.access_token);
    }
    return data;
  }, [saveToken, fetchMe, scheduleProactiveRefresh]);

  const logout = useCallback(async () => {
    if (refreshTimerRef.current) {
      clearTimeout(refreshTimerRef.current);
      refreshTimerRef.current = null;
    }
    try {
      await fetch(`${AUTH_BASE}/logout`, {
        method: 'POST',
        credentials: 'include',
      });
    } catch {
      // Network error — still clear local state
    }
    clearAuth();
    clearUIStoreStorage();
    sessionStorage.clear();
  }, [clearAuth]);

  const value = useMemo(() => ({
    user,
    token,
    loading,
    error,
    isAuthenticated: !!user,
    register,
    login,
    logout,
    clearError: () => setError(null),
  }), [user, token, loading, error, register, login, logout]);

  return (
    <AuthContext.Provider value={value}>
      {children}
    </AuthContext.Provider>
  );
}

export function useAuth() {
  const ctx = useContext(AuthContext);
  if (!ctx) throw new Error('useAuth must be used within AuthProvider');
  return ctx;
}

import { createContext, useContext, useState, useEffect } from 'react';
import { api } from '../utils/api';
import { useAuth } from './AuthContext';

const ConfigurationContext = createContext();

// Safe error message extraction — handles API error shapes, plain Error objects,
// strings, and null/undefined without throwing on unexpected shapes.
function getErrorMessage(err) {
  if (!err) return 'Unknown error';
  if (err.detail && Array.isArray(err.detail)) {
    return err.detail.map(d => d.msg || d).join(', ');
  }
  if (typeof err.message === 'string') return err.message;
  if (typeof err === 'string') return err;
  return 'An error occurred';
}

export function ConfigurationProvider({ children }) {
  const [config, setConfig] = useState(null);
  const [globalConfig, setGlobalConfig] = useState(null);
  const [ghostConfig, setGhostConfig] = useState(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState(null);
  const { isAuthenticated, token } = useAuth();

  const fetchConfig = async () => {
    setIsLoading(true);
    setError(null);
    try {
      const data = await api.getConfig();
      setConfig(data.project);
      setGlobalConfig(data.global_config);
      setGhostConfig(data.ghost);
    } catch (err) {
      setError(getErrorMessage(err));
    } finally {
      setIsLoading(false);
    }
  };

  const saveConfig = async (newConfig) => {
    setError(null);
    try {
      const data = await api.saveConfig(newConfig);
      // Re-fetch to get updated ghosting and confirmed saves
      await fetchConfig();
      return { success: true };
    } catch (err) {
      if (err && err.detail && Array.isArray(err.detail)) {
        return { success: false, validationErrors: err.detail };
      }
      const msg = getErrorMessage(err) || 'Error saving configuration';
      setError(msg);
      return { success: false, error: msg };
    }
  };

  useEffect(() => {
    if (isAuthenticated || token) {
      fetchConfig();
    } else {
      setConfig(null);
      setGlobalConfig(null);
      setGhostConfig(null);
      setIsLoading(false);
      setError(null);
    }
  }, [isAuthenticated, token]);

  return (
    <ConfigurationContext.Provider value={{
      config,
      globalConfig,
      ghostConfig,
      isLoading,
      error,
      saveConfig,
      fetchConfig
    }}>
      {children}
    </ConfigurationContext.Provider>
  );
}

export const useConfiguration = () => useContext(ConfigurationContext);

import React, { createContext, useState, useEffect } from 'react';
import { api } from '../utils/api';
import { useAuth } from './AuthContext';

export const SyncContext = createContext();
const ACTIVE_POLL_MS = 5000;
const BACKGROUND_POLL_MS = 15000;

export const SyncProvider = ({ children }) => {
  const [activeRuns, setActiveRuns] = useState([]);
  const { token } = useAuth();

  useEffect(() => {
    if (!token) {
      return undefined;
    }

    let timerId;
    let isMounted = true;
    let consecutiveErrors = 0;

    const pollGlobalRuns = async () => {
      try {
        const data = await api.listJobRuns();
        if (isMounted) {
          consecutiveErrors = 0; // Reset on success
          setActiveRuns(data);
          const interval = document.hidden ? BACKGROUND_POLL_MS : ACTIVE_POLL_MS;
          timerId = setTimeout(pollGlobalRuns, interval);
        }
      } catch (error) {
        // Silently handle auth-related errors during polling.
        // The AuthContext silentRecover will handle token refresh.
        // Don't spam the console on transient 401s.
        if (isMounted) {
          consecutiveErrors++;
          // Exponential backoff: 3s, 6s, 12s, max 30s
          const backoff = Math.min(3000 * Math.pow(2, consecutiveErrors - 1), 30000);
          if (consecutiveErrors <= 3) {
            // Suppress first few errors — likely just a token refresh in progress
          } else {
            console.warn('Global polling error (attempt %d)', consecutiveErrors, error.message);
          }
          timerId = setTimeout(pollGlobalRuns, backoff);
        }
      }
    };

    // Delay the first poll to let higher-priority post-login API calls
    // (projects, config) complete before this background polling begins.
    const initialTimer = setTimeout(pollGlobalRuns, 1000);
    return () => {
      isMounted = false;
      clearTimeout(timerId);
      clearTimeout(initialTimer);
    };
  }, [token]);

  return (
    <SyncContext.Provider value={{ activeRuns }}>
      {children}
    </SyncContext.Provider>
  );
};

import { createContext, useContext, useEffect, useMemo, useRef, useState } from 'react';
import { api } from '../utils/api';
import { useAuth } from './AuthContext';

const SyncStatusContext = createContext(null);
const RUNNING_POLL_INTERVAL_MS = 4000;
const IDLE_POLL_INTERVAL_MS = 10000;
const ENABLE_JOBS_SSE = String(import.meta.env.VITE_ENABLE_JOBS_SSE || '').toLowerCase() === 'true';

// ---------------------------------------------------------------------------
// SSE connection helper — falls back to polling if SSE is unavailable
// ---------------------------------------------------------------------------
function tryConnectSSE(onMessage, onError) {
  if (!ENABLE_JOBS_SSE) {
    onError();
    return null;
  }
  try {
    const url = '/api/jobs/stream';
    const es = new EventSource(url);
    es.onmessage = (e) => {
      try { onMessage(JSON.parse(e.data)); } catch { /* ignore malformed frames */ }
    };
    es.onerror = () => {
      es.close();
      onError();
    };
    return es;
  } catch {
    onError();
    return null;
  }
}

function shallowEqualObject(a, b) {
  if (a === b) return true;
  const aObj = a && typeof a === 'object' ? a : {};
  const bObj = b && typeof b === 'object' ? b : {};
  const aKeys = Object.keys(aObj);
  const bKeys = Object.keys(bObj);
  if (aKeys.length !== bKeys.length) return false;
  for (const key of aKeys) {
    if (aObj[key] !== bObj[key]) return false;
  }
  return true;
}

function normalizeStatus(status) {
  const s = String(status || 'draft').toLowerCase();
  if (s === 'running' || s === 'success' || s === 'failed' || s === 'draft') return s;
  if (s === 'warning' || s === 'partial' || s === 'completed') return 'success';
  if (s === 'error' || s === 'cancelled') return 'failed';
  return 'draft';
}

function deriveProgressFromRun(run) {
  if (!run) return 0;
  const explicit = Number(run?.progress_pct);
  if (!Number.isNaN(explicit) && explicit >= 0) {
    return Math.max(0, Math.min(100, Math.round(explicit)));
  }
  const total = Number(run?.total_models || 0);
  const synced = Number(run?.models_synced || 0);
  if (total > 0) {
    return Math.round(Math.max(0, Math.min(1, synced / total)) * 100);
  }
  return 0;
}

function getRunSortTimestamp(run) {
  const started = run?.started_at ? Date.parse(run.started_at) : NaN;
  if (!Number.isNaN(started) && started > 0) return started;
  const updated = run?.updated_at ? Date.parse(run.updated_at) : NaN;
  if (!Number.isNaN(updated) && updated > 0) return updated;
  const created = run?.created_at ? Date.parse(run.created_at) : NaN;
  if (!Number.isNaN(created) && created > 0) return created;
  const numericId = Number(run?.id || run?.run_id || 0);
  if (!Number.isNaN(numericId) && numericId > 0) return numericId;
  return 0;
}

export function SyncStatusProvider({ children }) {
  const [runs, setRuns] = useState([]);
  const [projectStatusById, setProjectStatusById] = useState({});
  const [projectProgressById, setProjectProgressById] = useState({});
  const [currentSyncId, setCurrentSyncId] = useState('');
  const [currentSyncStatus, setCurrentSyncStatus] = useState('draft');
  const [currentProgress, setCurrentProgress] = useState(0);
  const [indeterminate, setIndeterminate] = useState(false);
  const [warning, setWarning] = useState('');
  const { isAuthenticated, token } = useAuth();

  const realProgressRef = useRef(0);
  const lastRealChangeAtRef = useRef(Date.now());
  const previousSyncIdRef = useRef('');
  const completionTimeoutRef = useRef(null);

  useEffect(() => {
    // Don't start SSE or polling until authenticated
    if (!isAuthenticated && !token) return;

    let disposed = false;
    let timeoutId;
    let esRef = null;
    let sseActive = false;

    // ── SSE handler: process a single run-list frame from the server ──────
    function processRunList(runList) {
      if (disposed) return;
      if (!Array.isArray(runList)) return;

      const sortedRuns = [...runList].sort((a, b) => getRunSortTimestamp(b) - getRunSortTimestamp(a));
      setRuns(runList);

      const nextStatusById = {};
      const nextProgressById = {};
      for (const run of sortedRuns) {
        const pid = String(run?.project_id || '');
        if (!pid) continue;
        if (!(pid in nextStatusById)) nextStatusById[pid] = normalizeStatus(run?.status);
        if (!(pid in nextProgressById)) nextProgressById[pid] = deriveProgressFromRun(run);
      }

      setProjectStatusById((prev) => {
        const merged = { ...prev, ...nextStatusById };
        return shallowEqualObject(prev, merged) ? prev : merged;
      });
      setProjectProgressById((prev) => {
        const merged = { ...prev, ...nextProgressById };
        return shallowEqualObject(prev, merged) ? prev : merged;
      });

      const completedRun = sortedRuns.find((r) => normalizeStatus(r?.status) === 'success');
      if (completedRun) {
        setCurrentProgress(100);
        setCurrentSyncStatus('success');
      }

      const now = Date.now();
      const activeRun = sortedRuns.find((r) => {
        if (normalizeStatus(r?.status) !== 'running') return false;
        const started = r?.started_at ? new Date(r.started_at).getTime() : 0;
        if (!started) {
          const fallbackTs = getRunSortTimestamp(r);
          return fallbackTs > 0 && (Date.now() - fallbackTs) < 3600000;
        }
        return (now - started) < 3600000;
      }) || null;

      if (!activeRun) {
        setCurrentSyncStatus((prev) => (prev === 'draft' ? prev : 'draft'));
        if (completionTimeoutRef.current) {
          clearTimeout(completionTimeoutRef.current);
          completionTimeoutRef.current = null;
        }
        if (currentSyncId) {
          completionTimeoutRef.current = setTimeout(() => {
            setCurrentSyncId((prev) => (prev === '' ? prev : ''));
            setCurrentProgress((prev) => (prev === 0 ? prev : 0));
            realProgressRef.current = 0;
            previousSyncIdRef.current = '';
            completionTimeoutRef.current = null;
          }, 2000);
        } else {
          setCurrentSyncId((prev) => (prev === '' ? prev : ''));
          setCurrentProgress((prev) => (prev === 0 ? prev : 0));
          realProgressRef.current = 0;
          previousSyncIdRef.current = '';
        }
        lastRealChangeAtRef.current = Date.now();
        setIndeterminate((prev) => (prev ? false : prev));
        setWarning((prev) => (prev ? '' : prev));
        return;
      }

      const pid = String(activeRun?.project_id || '');
      const realProgress = deriveProgressFromRun(activeRun);

      if (completionTimeoutRef.current) {
        clearTimeout(completionTimeoutRef.current);
        completionTimeoutRef.current = null;
      }

      if (pid !== previousSyncIdRef.current) {
        previousSyncIdRef.current = pid;
        setCurrentProgress((prev) => (prev === 0 ? prev : 0));
        realProgressRef.current = 0;
        lastRealChangeAtRef.current = Date.now();
      }

      setCurrentSyncId((prev) => (prev === pid ? prev : pid));
      setCurrentSyncStatus((prev) => (prev === 'running' ? prev : 'running'));

      if (realProgress !== realProgressRef.current) {
        realProgressRef.current = realProgress;
        lastRealChangeAtRef.current = Date.now();
        setCurrentProgress((prev) => {
          const next = Math.max(prev, realProgress);
          return next === prev ? prev : next;
        });
        setIndeterminate((prev) => (prev ? false : prev));
        setWarning((prev) => (prev ? '' : prev));
      }

      const stalledMs = Date.now() - lastRealChangeAtRef.current;
      if (stalledMs > 60000) {
        setIndeterminate((prev) => (prev ? prev : true));
        setWarning((prev) => (prev === 'Sync is taking longer than expected...' ? prev : 'Sync is taking longer than expected...'));
      }
    }

    // ── Try SSE first; fall back to polling on error ───────────────────────
    function startSSE() {
      esRef = tryConnectSSE(
        (data) => {
          // Server sends either a run-list array or a single run object
          const list = Array.isArray(data) ? data : (data?.runs ?? null);
          if (list) processRunList(list);
        },
        () => {
          // SSE unavailable — fall back to polling
          sseActive = false;
          if (!disposed) schedulePoll(IDLE_POLL_INTERVAL_MS);
        },
      );
      if (esRef) sseActive = true;
    }

    function schedulePoll(delay) {
      if (disposed || sseActive) return;
      timeoutId = setTimeout(poll, delay);
    }

    // Listen for fallback event from sync POST
    function handleFallback(e) {
      const { projectId, status, progress } = e.detail || {};
      const normalizedProjectId = String(projectId || '');
      const normalizedStatus = normalizeStatus(status);
      const normalizedProgress = Number(progress);

      if (normalizedProjectId) {
        setCurrentSyncId(normalizedProjectId);
      }

      if (normalizedStatus === 'running') {
        setCurrentSyncStatus('running');
        setCurrentProgress((prev) => (prev > 5 ? prev : 5));
        setIndeterminate(false);
        setWarning('');
        lastRealChangeAtRef.current = Date.now();
        return;
      }

      if (normalizedStatus === 'success' || normalizedProgress === 100) {
        setCurrentProgress(100);
        setCurrentSyncStatus('success');
        setIndeterminate(false);
        setWarning('');
        lastRealChangeAtRef.current = Date.now();
      } else if (normalizedStatus === 'failed') {
        setCurrentSyncStatus('failed');
        setIndeterminate(false);
        setWarning('');
        lastRealChangeAtRef.current = Date.now();
      }
    }
    window.addEventListener('semabridge-sync-fallback', handleFallback);

    const poll = async () => {
      if (disposed || sseActive) return;
      try {
        const data = await api.listJobRuns();
        if (disposed) return;

        const runList = Array.isArray(data) ? data : [];
        processRunList(runList);

        // Schedule next poll only when SSE is not active
        if (!disposed && !sseActive) {
          const hasActive = runList.some(r => normalizeStatus(r?.status) === 'running');
          schedulePoll(hasActive ? RUNNING_POLL_INTERVAL_MS : IDLE_POLL_INTERVAL_MS);
        }
      } catch {
        if (!disposed && !sseActive) schedulePoll(RUNNING_POLL_INTERVAL_MS);
      }
    };

    // Prefer SSE; polling is the fallback
    startSSE();
    // Delay the first poll slightly to let higher-priority post-login API
    // calls (projects, config) go through first, reducing request congestion.
    const initialPollTimer = setTimeout(poll, 500);

    return () => {
      disposed = true;
      clearTimeout(timeoutId);
      clearTimeout(initialPollTimer);
      if (esRef) { esRef.close(); esRef = null; }
      if (completionTimeoutRef.current) {
        clearTimeout(completionTimeoutRef.current);
      }
      window.removeEventListener('semabridge-sync-fallback', handleFallback);
    };
  }, [isAuthenticated, token]);

  // Completion watcher: when progress hits 100, force status to 'success' after a short delay
  useEffect(() => {
    if (currentProgress === 100) {
      const timer = setTimeout(() => {
        setCurrentSyncStatus('success');
      }, 1000);
      return () => clearTimeout(timer);
    }
  }, [currentProgress]);

  useEffect(() => {
    if (currentSyncStatus !== 'running') return undefined;

    const crawl = setInterval(() => {
      setCurrentProgress(prev => {
        const floor = realProgressRef.current;
        if (prev < floor) return floor;
        if (prev >= 90) return prev;
        return prev + 1;
      });
    }, 1000);

    return () => clearInterval(crawl);
  }, [currentSyncStatus]);

  const value = useMemo(() => ({
    runs,
    currentSyncId,
    currentSyncStatus,
    currentProgress,
    indeterminate,
    warning,
    projectStatusById,
    projectProgressById,
  }), [runs, currentSyncId, currentSyncStatus, currentProgress, indeterminate, warning, projectStatusById, projectProgressById]);

  return <SyncStatusContext.Provider value={value}>{children}</SyncStatusContext.Provider>;
}

export function useSyncStatusStore() {
  const ctx = useContext(SyncStatusContext);
  if (!ctx) {
    throw new Error('useSyncStatusStore must be used within SyncStatusProvider');
  }
  return ctx;
}

import { createContext, useContext, useState, useEffect, useCallback } from 'react';

const ThemeContext = createContext(undefined);

function getInitialTheme() {
    const stored = localStorage.getItem('semabridge-theme');
    if (stored === 'dark' || stored === 'light' || stored === 'system') return stored;
    return 'system'; // Default to system
}

export function ThemeProvider({ children }) {
    const [theme, setTheme] = useState(getInitialTheme);
    const [resolvedTheme, setResolvedTheme] = useState(() => {
        const initial = getInitialTheme();
        if (initial === 'system') {
            return window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
        }
        return initial;
    });

    useEffect(() => {
        const root = document.documentElement;
        
        const applyTheme = (t) => {
            let resolved = t;
            if (t === 'system') {
                resolved = window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
            }
            setResolvedTheme(resolved);
            root.setAttribute('data-theme', resolved);
            document.body.setAttribute('data-theme', resolved);
        };

        applyTheme(theme);
        localStorage.setItem('semabridge-theme', theme);

        if (theme === 'system') {
            const mediaQuery = window.matchMedia('(prefers-color-scheme: dark)');
            const handleChange = () => applyTheme('system');
            mediaQuery.addEventListener('change', handleChange);
            return () => mediaQuery.removeEventListener('change', handleChange);
        }
    }, [theme]);

    return (
        <ThemeContext.Provider value={{ theme, setTheme, resolvedTheme }}>
            {children}
        </ThemeContext.Provider>
    );
}

export function useTheme() {
    const ctx = useContext(ThemeContext);
    if (!ctx) throw new Error('useTheme must be used within ThemeProvider');
    return ctx;
}

import { useState, useEffect, useCallback } from 'react';
import FlexSearch from 'flexsearch';

export function useConnectorAPI(workspaceId, sourcePlatform) {
  const [data, setData] = useState([]);
  const [index, setIndex] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  const fetchSemanticObjects = useCallback(async () => {
    if (!sourcePlatform) return;
    setLoading(true);
    setError(null);

    let apiUrl = '/api/discovery/';
    
    // Choose API endpoint based on platform type or sync
    if (sourcePlatform === 'fabric') {
      apiUrl += 'fabric'; // ?workspace_id could be added if needed
    } else if (sourcePlatform === 'snowflake') {
      apiUrl += 'snowflake';
    } else {
       apiUrl += 'semantic'; // fallback to both if not targeted
    }

    try {
      const resp = await fetch(apiUrl);
      if (!resp.ok) throw new Error(`API returned ${resp.status}`);
      const result = await resp.json();
      
      const objectsToIndex = result.fabric || result.snowflake || result || [];
      setData(objectsToIndex);

      // Build flexsearch Index
      const docIndex = new FlexSearch.Document({
        document: {
          id: "id",
          index: ["name", "description", "type"],
        },
        tokenize: "forward",
      });

      objectsToIndex.forEach(doc => {
        docIndex.add(doc);
      });
      setIndex(docIndex);
      
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  }, [sourcePlatform, workspaceId]);

  useEffect(() => {
    fetchSemanticObjects();
  }, [fetchSemanticObjects]);

  const search = useCallback((query) => {
    if (!index || !query) return data;
    
    // Search across fields
    const results = index.search(query, { enrich: true });
    
    // Reconstruct results array. Flexsearch returns arrays of matches per field.
    const searchMap = new Map();
    results.forEach(resField => {
      resField.result.forEach(r => {
        searchMap.set(r.id, r.doc);
      });
    });

    return Array.from(searchMap.values());
  }, [index, data]);

  return { data, search, loading, error, refresh: fetchSemanticObjects };
}

import { useState, useEffect, useCallback, useRef } from 'react';
import { api } from '../utils/api';

/**
 * useConnectorAccounts
 * Fetches Fabric / Snowflake / Databricks accounts whenever step 2 opens.
 * Also owns workspace discovery triggered by account-id changes.
 */
export function useConnectorAccounts({
  step,
  sourceConnector,
  targetConnectors,
  selectedConnectionId,
  snowflakeAccountId,
  databricksAccountId,
  setSelectedConnectionId,
  setFabricAccountId,
  setSnowflakeAccountId,
  setDatabricksAccountId,
  setFabricWorkspaceId,
  setAllWorkspacesFromApi,
  setWorkspaces,
}) {
  const resolveAccountId = useCallback((account) => (
    String(account?.id || account?.identity_id || account?.account_id || '')
  ), []);

  const [fabricAccounts, setFabricAccounts]       = useState([]);
  const [snowflakeAccounts, setSnowflakeAccounts] = useState([]);
  const [databricksAccounts, setDatabricksAccounts] = useState([]);
  const [isRefreshingWorkspaces, setIsRefreshingWorkspaces] = useState(false);
  const [workspaceDiscoveryError, setWorkspaceDiscoveryError] = useState('');
  const workspaceFetchSeqRef = useRef(0);

  const fetchFabricWorkspaces = useCallback(async (accountId) => {
    const resolvedAccountId = String(accountId || '').trim();
    const requestSeq = ++workspaceFetchSeqRef.current;

    if (!resolvedAccountId) {
      setAllWorkspacesFromApi([]);
      setWorkspaces([]);
      setWorkspaceDiscoveryError('');
      console.warn('[SemaBridge][FabricDiscovery] hook:skip-empty-account', { requestSeq });
      return;
    }

    setWorkspaceDiscoveryError('');
    setIsRefreshingWorkspaces(true);
    try {
      const listData = await api.fabricListWorkspaces(resolvedAccountId);

      if (requestSeq !== workspaceFetchSeqRef.current) {
        console.info('[SemaBridge][FabricDiscovery] hook:stale-response-ignored', {
          accountId: resolvedAccountId,
          requestSeq,
          latestSeq: workspaceFetchSeqRef.current,
        });
        return;
      }

      const discovered = Array.isArray(listData?.workspaces) ? listData.workspaces : [];
      const apiWorkspaces = discovered
        .map(ws => ({
          id: ws.id || ws.workspace_id,
          name: ws.name || ws.displayName || ws.workspace_name || ws.id || ws.workspace_id,
          displayName: ws.name || ws.displayName || ws.workspace_name,
          type: ws.type,
        }))
        .filter(ws => ws.id);

      const deduped = [];
      const seen = new Set();
      for (const ws of apiWorkspaces) {
        if (seen.has(ws.id)) continue;
        seen.add(ws.id);
        deduped.push(ws);
      }
      console.info('[SemaBridge][FabricDiscovery] hook:success', {
        accountId: resolvedAccountId,
        requestSeq,
        discoveredCount: discovered.length,
        resolvedCount: deduped.length,
      });
      setWorkspaceDiscoveryError('');
      setAllWorkspacesFromApi(deduped);
    } catch (err) {
      if (requestSeq !== workspaceFetchSeqRef.current) {
        console.info('[SemaBridge][FabricDiscovery] hook:stale-error-ignored', {
          accountId: resolvedAccountId,
          requestSeq,
          latestSeq: workspaceFetchSeqRef.current,
          error: err?.message || String(err),
        });
        return;
      }

      console.error('[SemaBridge][FabricDiscovery] hook:error', {
        accountId: resolvedAccountId,
        requestSeq,
        message: err?.message || 'Unknown error',
        status: err?.status,
        payload: err?.payload,
      });
      setWorkspaceDiscoveryError(err?.message || 'Failed to discover Fabric workspaces for the selected account.');
      setAllWorkspacesFromApi([]);
    } finally {
      if (requestSeq === workspaceFetchSeqRef.current) {
        setIsRefreshingWorkspaces(false);
      }
    }
  }, [setAllWorkspacesFromApi, setWorkspaces]);

  // Fetch accounts when entering Step 2
  useEffect(() => {
    const needsFabric     = sourceConnector === 'fabric'     || targetConnectors.has('fabric');
    const needsSnowflake  = sourceConnector === 'snowflake'  || targetConnectors.has('snowflake');
    const needsDatabricks = sourceConnector === 'databricks' || targetConnectors.has('databricks');

    if (step !== 2) return;

    if (needsFabric) {
      api.getAccounts('FABRIC').then(res => {
        const list = Array.isArray(res) ? res : (res?.accounts || []);
        setFabricAccounts(list);
        if (!list.length) { setSelectedConnectionId(''); setFabricAccountId(''); return; }
        const hasSelection = list.some(acc => resolveAccountId(acc) === String(selectedConnectionId || ''));
        const nextId = hasSelection ? selectedConnectionId : resolveAccountId(list[0]);
        if (nextId) { setSelectedConnectionId(nextId); setFabricAccountId(nextId); }
      }).catch(e => console.warn('[SemaBridge] Failed to fetch Fabric Accounts', e));
    }

    if (needsSnowflake) {
      api.getAccounts('SNOWFLAKE').then(res => {
        const list = Array.isArray(res) ? res : (res?.accounts || []);
        setSnowflakeAccounts(list);
        if (!list.length) { setSnowflakeAccountId(''); return; }
        const hasSelection = list.some(acc => resolveAccountId(acc) === String(snowflakeAccountId || ''));
        if (!hasSelection) setSnowflakeAccountId(resolveAccountId(list[0]));
      }).catch(e => console.warn('[SemaBridge] Failed to fetch Snowflake Accounts', e));
    }

    if (needsDatabricks) {
      api.getAccounts('DATABRICKS').then(res => {
        const list = Array.isArray(res) ? res : (res?.accounts || []);
        setDatabricksAccounts(list);
        if (!list.length) { setDatabricksAccountId(''); return; }
        const hasSelection = list.some(acc => resolveAccountId(acc) === String(databricksAccountId || ''));
        if (!hasSelection) setDatabricksAccountId(resolveAccountId(list[0]));
      }).catch(e => console.warn('[SemaBridge] Failed to fetch Databricks Accounts', e));
    }
  }, [
    step,
    sourceConnector,
    targetConnectors,
    selectedConnectionId,
    snowflakeAccountId,
    databricksAccountId,
    resolveAccountId,
  ]);  // eslint-disable-line

  // Re-fetch workspaces when connection account changes
  useEffect(() => {
    const needsFabric = sourceConnector === 'fabric' || targetConnectors.has('fabric');
    if (step !== 2 || !needsFabric) return;

    setAllWorkspacesFromApi([]);
    setWorkspaces([]);
    setFabricWorkspaceId('');
    if (!selectedConnectionId) return;

    setFabricAccountId(selectedConnectionId);
    fetchFabricWorkspaces(selectedConnectionId);
  }, [step, sourceConnector, targetConnectors, selectedConnectionId, fetchFabricWorkspaces]); // eslint-disable-line

  return {
    fabricAccounts,
    snowflakeAccounts,
    databricksAccounts,
    isRefreshingWorkspaces,
    fetchFabricWorkspaces,
    workspaceDiscoveryError,
  };
}

import { useState, useEffect, useCallback, useRef } from 'react';
import { api } from '../utils/api';

/**
 * useModelBrowser
 * Owns Step 3 logic: loading workspace/snowflake models, toggling selections,
 * and loading PBIX files from tagged folders.
 */
export function useModelBrowser({
  step,
  sourceConnector,
  fabricWorkspaceId,
  selectedConnectionId,
  selectedWorkspace,
  liveFabricWorkspaces,
  selectedModels,
  setSelectedModels,
  setSelectedModelNameByKey,
  expandedWs,
  setExpandedWs,
  setWizardState,
  pbixSourceMode,
  selectedLocalFolderTag,
  setSelectedPbixFilePath,
  setRunWarning,
  editMode,
  initialData,
  isHydratedRef,
}) {
  const [workspaces,      setWorkspaces]      = useState([]);
  const [wsLoading,       setWsLoading]       = useState(false);
  const [wsModels,        setWsModels]        = useState({});
  const [databricksObjects, setDatabricksObjects] = useState([]);
  const [databricksLoading, setDatabricksLoading] = useState(false);
  const [pbixFiles,       setPbixFiles]       = useState([]);
  const [pbixFilesLoading, setPbixFilesLoading] = useState(false);
  const [pbixFilesError,  setPbixFilesError]  = useState('');

  const prevWorkspaceIdRef      = useRef(null);
  const prevSourceConnectorRef  = useRef(null);

  /* ── Ghost-purge: clear stale fabricWorkspaceId ── */
  useEffect(() => {
    if (!fabricWorkspaceId || liveFabricWorkspaces.length === 0) return;
    if (!liveFabricWorkspaces.some(ws => ws.id === fabricWorkspaceId)) {
      console.warn('[SemaBridge] Ghost workspace detected — force-clearing:', fabricWorkspaceId);
      setWizardState({ fabricWorkspaceId: '' });
    }
  }, [fabricWorkspaceId, liveFabricWorkspaces, setWizardState]);

  /* ── Defensive auto-select first workspace if empty on Step 3 ── */
  useEffect(() => {
    if (step === 3 && sourceConnector === 'fabric' && !fabricWorkspaceId && !wsLoading) {
      if (liveFabricWorkspaces.length > 0) {
        setWizardState({ fabricWorkspaceId: liveFabricWorkspaces[0].id });
      }
    }
  }, [step, sourceConnector, fabricWorkspaceId, wsLoading, liveFabricWorkspaces, setWizardState]);

  /* ── Clear model selections when workspace or source changes ── */
  useEffect(() => {
    const wsChanged  = fabricWorkspaceId !== prevWorkspaceIdRef.current;
    const scChanged  = sourceConnector   !== prevSourceConnectorRef.current;

    if (!isHydratedRef.current || (!wsChanged && !scChanged)) {
      if (fabricWorkspaceId) prevWorkspaceIdRef.current = fabricWorkspaceId;
      if (sourceConnector)   prevSourceConnectorRef.current = sourceConnector;
      return;
    }
    if (editMode && wsChanged && fabricWorkspaceId === initialData?.workspace_id) {
      prevWorkspaceIdRef.current = fabricWorkspaceId;
      return;
    }

    console.log('[SemaBridge] Source/Workspace changed, clearing selections');
    setSelectedModels(new Set());
    setSelectedModelNameByKey({});
    setExpandedWs({});
    setWsModels({});

    prevWorkspaceIdRef.current     = fabricWorkspaceId;
    prevSourceConnectorRef.current = sourceConnector;
  }, [fabricWorkspaceId, sourceConnector, editMode, initialData?.workspace_id]); // eslint-disable-line

  /* ── Load models for the selected workspace when entering Step 3 ── */
  useEffect(() => {
    if (step !== 3) return;

    if (sourceConnector === 'fabric') {
      if (!fabricWorkspaceId) { setWorkspaces([]); return; }

      const workspace = selectedWorkspace || { id: fabricWorkspaceId, name: fabricWorkspaceId };
      setWorkspaces([workspace]);
      setExpandedWs(prev => ({ ...prev, [fabricWorkspaceId]: true }));
      setWsLoading(true);

      api.discoverFabricModels(fabricWorkspaceId, selectedConnectionId)
        .then(data => {
          if (!Array.isArray(data) || data.length === 0) {
            setRunWarning('No semantic models found for this workspace.');
          } else {
            setRunWarning('');
          }
          const models = data ?? [];
          setWsModels({ [fabricWorkspaceId]: models });

          if (models.length > 0 && selectedModels.size > 0) {
            setSelectedModelNameByKey(prev => {
              const next = { ...prev };
              let changed = false;
              selectedModels.forEach(key => {
                const id = key.includes('::') ? key.split('::')[1] : key;
                const match = models.find(m => m.id === id);
                if (match?.name && next[key] !== match.name) { next[key] = match.name; changed = true; }
              });
              return changed ? next : prev;
            });
          }
          setWsLoading(false);
        })
        .catch(err => {
          setRunWarning('Failed to load semantic models: ' + (err?.message || 'Unknown error'));
          setWsModels({ [fabricWorkspaceId]: [] });
          setWsLoading(false);
        });
      return;
    }

    if (sourceConnector === 'snowflake') {
      const rootId = 'snowflake';
      setWorkspaces([{ id: rootId, name: 'Snowflake' }]);
      setExpandedWs(prev => ({ ...prev, [rootId]: true }));
      setWsLoading(true);
      api.discoverSnowflakeModels()
        .then(data => {
          const normalized = (data ?? []).map((m, idx) => ({
            ...m,
            id:   m?.id   || m?.name || m?.displayName || `snowflake_model_${idx + 1}`,
            name: m?.name || m?.displayName || m?.id || `model_${idx + 1}`,
          }));
          setWsModels({ [rootId]: normalized });
        })
        .catch(() => setWsModels({ snowflake: [] }))
        .finally(() => setWsLoading(false));
      return;
    }

    setWorkspaces([]);
  }, [step, sourceConnector, fabricWorkspaceId, selectedConnectionId, selectedWorkspace]); // eslint-disable-line

  /* ── PBIX file discovery for TAG mode ── */
  useEffect(() => {
    if (pbixSourceMode !== 'TAG' || sourceConnector !== 'pbix' || !selectedLocalFolderTag || step !== 3) {
      setPbixFiles([]);
      setPbixFilesError('');
      setSelectedPbixFilePath('');
      return;
    }

    let active = true;
    setPbixFilesLoading(true);
    setPbixFilesError('');

    api.getLocalFolderFiles(selectedLocalFolderTag)
      .then(data => {
        if (!active) return;
        const files = Array.isArray(data?.files) ? data.files : [];
        setPbixFiles(files);
        if (!files.length) { setSelectedPbixFilePath(''); return; }
        setSelectedPbixFilePath(cur => (cur && files.some(f => f.path === cur)) ? cur : (files[0]?.path || ''));
      })
      .catch(err => {
        if (!active) return;
        setPbixFiles([]);
        setSelectedPbixFilePath('');
        setPbixFilesError(err?.message || 'Failed to discover PBIX files.');
      })
      .finally(() => { if (active) setPbixFilesLoading(false); });

    return () => { active = false; };
  }, [pbixSourceMode, selectedLocalFolderTag, sourceConnector, step]); // eslint-disable-line

  /* ── Workspace lazy-load ── */
  const loadWsModels = useCallback(async (wsid) => {
    if (wsModels[wsid]) return;
    try {
      const models = await api.discoverFabricModels(wsid, selectedConnectionId);
      setWsModels(prev => ({ ...prev, [wsid]: models ?? [] }));
    } catch {
      setWsModels(prev => ({ ...prev, [wsid]: [] }));
    }
  }, [wsModels, selectedConnectionId]);

  const toggleWorkspace = (wsid) => {
    const next = { ...expandedWs, [wsid]: !expandedWs[wsid] };
    setExpandedWs(next);
    if (next[wsid]) loadWsModels(wsid);
  };

  const toggleModel = (modelKey, modelName = '') => {
    setSelectedModels(prev => {
      const s = new Set(prev);
      s.has(modelKey) ? s.delete(modelKey) : s.add(modelKey);
      return s;
    });
    setSelectedModelNameByKey(prev => {
      const next = { ...prev };
      if (modelKey in next) { delete next[modelKey]; }
      else if (modelName) { next[modelKey] = modelName; }
      return next;
    });
  };

  const clearSelectedModels = () => {
    setSelectedModels(new Set());
    setSelectedModelNameByKey({});
  };

  return {
    workspaces,
    wsLoading,
    wsModels,
    databricksObjects,
    databricksLoading,
    pbixFiles,
    pbixFilesLoading,
    pbixFilesError,
    toggleWorkspace,
    toggleModel,
    clearSelectedModels,
  };
}

import { useState, useCallback, useRef, useEffect } from 'react';

/**
 * usePageCache — auto-restoring session state cache for a single page.
 *
 * Stores UI state in sessionStorage under `key` so it survives SPA navigation
 * within the same browser tab. Cleared automatically when the tab closes.
 *
 * Unlike useSessionDraft, this hook:
 * - Immediately restores the cached state on mount (no explicit resumeDraft call).
 * - Returns a plain [state, setState] tuple — drop-in for useState.
 * - Debounces writes to avoid thrashing sessionStorage on rapid updates.
 *
 * @param {string}  key          Unique sessionStorage key (use kebab-case route slug)
 * @param {object}  defaultState Initial / fallback state object
 * @param {object}  [opts]
 * @param {number}  [opts.debounceMs=250]  Debounce delay for writes (ms)
 * @returns {[object, (partial: object|function) => void, () => void]}
 *          [state, setState, clearCache]
 *
 * @example
 * const [cache, setCache, clearJobsCache] = usePageCache('jobs-page', {
 *   search: '',
 *   statusFilter: 'all',
 *   expandedRunId: null,
 * });
 * // Read:  cache.search
 * // Write: setCache({ search: 'new value' })       // partial merge
 *          setCache(prev => ({ ...prev, x: 1 }))   // functional update
 */
export default function usePageCache(key, defaultState, { debounceMs = 250 } = {}) {
  // Hydrate from sessionStorage on first render.
  const [state, _setState] = useState(() => {
    try {
      const raw = sessionStorage.getItem(key);
      if (raw) {
        const parsed = JSON.parse(raw);
        // Only merge if BOTH are non-null objects.
        if (
          typeof defaultState === 'object' && defaultState !== null &&
          typeof parsed === 'object' && parsed !== null &&
          !Array.isArray(defaultState)
        ) {
          return { ...defaultState, ...parsed };
        }
        return parsed;
      }
    } catch {
      // Corrupt storage entry — fall back to defaults.
    }
    return defaultState;
  });

  // Debounce timer ref.
  const timerRef = useRef(null);

  // Write to sessionStorage (debounced).
  const persist = useCallback(
    (nextState) => {
      if (timerRef.current) clearTimeout(timerRef.current);
      timerRef.current = setTimeout(() => {
        try {
          sessionStorage.setItem(key, JSON.stringify(nextState));
        } catch (e) {
          console.warn('[usePageCache] Failed to persist state:', e);
        }
      }, debounceMs);
    },
    [key, debounceMs],
  );

  // Cleanup timer on unmount.
  useEffect(() => () => {
    if (timerRef.current) clearTimeout(timerRef.current);
  }, []);

  /**
   * setState — accepts a partial object or a functional updater.
   * If state is an object, it merges. Otherwise, it replaces.
   */
  const setState = useCallback(
    (updater) => {
      _setState((prev) => {
        let next;
        if (typeof updater === 'function') {
          next = updater(prev);
        } else if (
          typeof prev === 'object' && prev !== null &&
          typeof updater === 'object' && updater !== null &&
          !Array.isArray(prev)
        ) {
          next = { ...prev, ...updater };
        } else {
          next = updater;
        }
        persist(next);
        return next;
      });
    },
    [persist],
  );

  /** clearCache — remove the sessionStorage entry and reset to defaults. */
  const clearCache = useCallback(() => {
    if (timerRef.current) clearTimeout(timerRef.current);
    try {
      sessionStorage.removeItem(key);
    } catch { /* noop */ }
    _setState(defaultState);
  }, [key, defaultState]); // eslint-disable-line react-hooks/exhaustive-deps

  return [state, setState, clearCache];
}

