import { useState } from 'react';
import { useNavigate, useLocation, Navigate, Link } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { Hexagon, Eye, EyeOff, LogIn, UserPlus, AlertCircle } from 'lucide-react';

/**
 * LoginPage — authentication screen.
 * After successful login, redirects to the originally requested page (or /explore).
 */
export default function LoginPage() {
  const { login, register, error, clearError, loading, isAuthenticated, token } = useAuth();
  const navigate = useNavigate();
  const location = useLocation();
  const from = typeof location.state?.from === 'string'
    ? location.state.from
    : (location.state?.from?.pathname ?? '/projects');

  const [mode, setMode] = useState('login'); // 'login' | 'register'
  const [username, setUsername] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const [successMsg, setSuccessMsg] = useState('');
  const [passwordError, setPasswordError] = useState('');

  function validatePassword(pwd) {
    if (pwd.length < 8) return 'Password must be at least 8 characters';
    if (!/[0-9]/.test(pwd) && !/[^A-Za-z0-9]/.test(pwd))
      return 'Password must contain at least one number or special character';
    return null;
  }

  if (isAuthenticated) {
    return <Navigate to={from} replace />;
  }

  const switchMode = (newMode) => {
    setMode(newMode);
    clearError();
    setSuccessMsg('');
    setPasswordError('');
    setUsername('');
    setEmail('');
    setPassword('');
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    // On register, enforce password strength before submitting.
    if (mode === 'register') {
      const pwdErr = validatePassword(password);
      if (pwdErr) {
        setPasswordError(pwdErr);
        return;
      }
    }
    setSubmitting(true);
    setSuccessMsg('');
    setPasswordError('');
    clearError();
    try {
      if (mode === 'register') {
        await register(username, email, password);
        setSuccessMsg('Account created! You can now sign in.');
        switchMode('login');
      } else {
        await login(username, password);
        navigate(from, { replace: true });
      }
    } catch {
      // error is set in context
    } finally {
      setSubmitting(false);
    }
  };

  if (loading && !token) {
    return (
      <div className="flex items-center justify-center h-screen bg-app">
        <div className="flex flex-col items-center gap-3">
          <Hexagon size={32} className="text-accent-blue animate-pulse" />
          <span className="text-secondary text-sm">Loading…</span>
        </div>
      </div>
    );
  }

  return (
    <div
      className="flex h-screen bg-app"
      style={{ fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif' }}
    >
      {/* What the product does, for people invited by a teammate (hidden on small screens) */}
      <section
        className="hidden md:flex flex-col justify-between"
        style={{
          flex: '1.1 1 0', padding: 48, color: '#fff',
          background: 'linear-gradient(150deg, var(--accent-blue) 0%, var(--accent-cyan, #06B6D4) 100%)',
        }}
      >
        <div className="flex items-center gap-2" style={{ fontWeight: 700, fontSize: 15 }}>
          <Hexagon size={22} strokeWidth={2.5} /> SemaBridge
        </div>
        <div style={{ maxWidth: 460 }}>
          <h2 style={{ fontSize: 30, lineHeight: 1.2, fontWeight: 700, margin: 0, letterSpacing: '-0.01em' }}>
            Move your semantic models between BI platforms without losing a single definition.
          </h2>
          <div style={{ marginTop: 18, display: 'flex', flexDirection: 'column', gap: 8, fontSize: 14, opacity: 0.92 }}>
            <span>Power BI · Fabric → Snowflake · Databricks</span>
            <span>Governed metrics shared by every dashboard and AI agent</span>
          </div>
        </div>
        <span style={{ fontSize: 12, opacity: 0.75 }}>Semantic model migration and governance</span>
      </section>
      <div className="flex items-center justify-center" style={{ flex: '1 1 0', padding: 24 }}>
      <div
        className="w-full max-w-sm rounded-xl bg-surface border border-main p-8"
        style={{ boxShadow: 'var(--shadow-lg)' }}
      >
        {/* Logo */}
        <div className="flex flex-col items-center gap-2 mb-8">
          <Hexagon size={28} className="text-accent-blue" strokeWidth={2.5} />
          <h1 className="text-lg font-bold tracking-tight text-primary">SemaBridge</h1>
          <p className="text-xs text-tertiary">
            {mode === 'login' ? 'Sign in to your account' : 'Create a new account'}
          </p>
        </div>

        {/* Success message */}
        {successMsg && (
          <div
            className="flex items-center gap-2 px-3 py-2 mb-4 rounded-md text-xs font-medium"
            style={{ background: 'var(--color-success-muted)', color: 'var(--color-success)' }}
          >
            {successMsg}
          </div>
        )}

        {/* Error message */}
        {error && (
          <div
            className="flex items-center gap-2 px-3 py-2 mb-4 rounded-md text-xs font-medium"
            style={{ background: 'var(--color-danger-muted)', color: 'var(--color-danger)' }}
          >
            <AlertCircle size={14} />
            {error}
          </div>
        )}

        <form onSubmit={handleSubmit} className="flex flex-col gap-4">
          {/* Username */}
          <div className="flex flex-col gap-1.5">
            <label className="text-xs font-medium text-secondary">Username</label>
            <input
              type="text"
              value={username}
              onChange={(e) => setUsername(e.target.value)}
              required
              autoFocus
              placeholder="Enter username"
              className="h-9 px-3 rounded-md text-sm bg-app border border-main text-primary"
              style={{ outline: 'none' }}
              onFocus={(e) => { e.target.style.borderColor = 'var(--accent-blue)'; }}
              onBlur={(e) => { e.target.style.borderColor = 'var(--border-main)'; }}
            />
          </div>

          {/* Email (register only) */}
          {mode === 'register' && (
            <div className="flex flex-col gap-1.5">
              <label className="text-xs font-medium text-secondary">Email</label>
              <input
                type="email"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                required
                placeholder="you@example.com"
                className="h-9 px-3 rounded-md text-sm bg-app border border-main text-primary"
                style={{ outline: 'none' }}
                onFocus={(e) => { e.target.style.borderColor = 'var(--accent-blue)'; }}
                onBlur={(e) => { e.target.style.borderColor = 'var(--border-main)'; }}
              />
            </div>
          )}

          {/* Password */}
          <div className="flex flex-col gap-1.5">
            <label className="text-xs font-medium text-secondary">Password</label>
            <div className="relative">
              <input
                type={showPassword ? 'text' : 'password'}
                value={password}
                onChange={(e) => {
                  setPassword(e.target.value);
                  if (mode === 'register' && passwordError) {
                    setPasswordError(validatePassword(e.target.value) || '');
                  }
                }}
                required
                minLength={mode === 'register' ? 8 : 1}
                placeholder="Enter password"
                className="w-full h-9 px-3 pr-9 rounded-md text-sm bg-app border border-main text-primary"
                style={{ outline: 'none', borderColor: passwordError ? 'var(--color-danger)' : undefined }}
                onFocus={(e) => { e.target.style.borderColor = passwordError ? 'var(--color-danger)' : 'var(--accent-blue)'; }}
                onBlur={(e) => { e.target.style.borderColor = passwordError ? 'var(--color-danger)' : 'var(--border-main)'; }}
              />
              <button
                type="button"
                onClick={() => setShowPassword(!showPassword)}
                className="absolute right-2 top-1/2 -translate-y-1/2 text-tertiary hover:text-secondary"
                tabIndex={-1}
              >
                {showPassword ? <EyeOff size={14} /> : <Eye size={14} />}
              </button>
            </div>
            {/* Inline password strength error — only shown on register */}
            {mode === 'register' && passwordError && (
              <span className="text-xs" style={{ color: 'var(--color-danger)' }}>
                {passwordError}
              </span>
            )}
          </div>

          {/* Forgot password — only shown on login form */}
          {mode === 'login' && (
            <div className="text-right -mt-2">
              <Link
                to="/auth/forgot-password"
                className="text-xs text-accent-blue hover:underline"
              >
                Forgot password?
              </Link>
            </div>
          )}

          {/* Submit — disabled on register if password fails strength check */}
          <button
            type="submit"
            disabled={submitting || (mode === 'register' && Boolean(validatePassword(password)))}
            className="flex items-center justify-center gap-2 h-9 rounded-md text-sm font-medium"
            style={{
              background: (submitting || (mode === 'register' && Boolean(validatePassword(password)))) ? 'var(--color-accent-faint)' : 'var(--accent-blue)',
              color: (submitting || (mode === 'register' && Boolean(validatePassword(password)))) ? 'var(--text-tertiary)' : '#fff',
              cursor: (submitting || (mode === 'register' && Boolean(validatePassword(password)))) ? 'not-allowed' : 'pointer',
              border: 'none',
            }}
          >
            {mode === 'login' ? <LogIn size={14} /> : <UserPlus size={14} />}
            {submitting ? 'Please wait…' : mode === 'login' ? 'Sign In' : 'Create Account'}
          </button>
        </form>

        {/* Toggle mode */}
        <div className="mt-6 text-center text-xs text-tertiary">
          {mode === 'login' ? (
            <>
              Don&apos;t have an account?{' '}
              <button
                onClick={() => switchMode('register')}
                className="text-accent-blue hover:underline font-medium"
                style={{ background: 'none', border: 'none', cursor: 'pointer' }}
              >
                Sign up
              </button>
            </>
          ) : (
            <>
              Already have an account?{' '}
              <button
                onClick={() => switchMode('login')}
                className="text-accent-blue hover:underline font-medium"
                style={{ background: 'none', border: 'none', cursor: 'pointer' }}
              >
                Sign in
              </button>
            </>
          )}
        </div>
      </div>
      </div>
    </div>
  );
}

