const SegmentedControl = ({ options, value, onChange, label }) => (
  <div style={{ marginBottom: 20 }}>
    {label && <FormLabel>{label}</FormLabel>}
    <div style={{ 
      display: 'flex', 
      background: 'var(--bg-surface-raised)', 
      borderRadius: 10, 
      padding: 3, 
      border: '1px solid var(--border-main)',
      width: 'fit-content',
      gap: 2
    }}>
      {options.map((opt) => {
        const isDisabled = Boolean(opt.disabled);
        const isActive = value === opt.value && !isDisabled;
        return (
          <button
            key={opt.value}
            disabled={isDisabled}
            title={opt.tooltip || (isDisabled ? 'Option unavailable' : undefined)}
            onClick={() => !isDisabled && onChange(opt.value)}
            style={{
              padding: '8px 16px',
              borderRadius: 8,
              border: 'none',
              cursor: isDisabled ? 'not-allowed' : 'pointer',
              fontSize: 12,
              fontWeight: 700,
              opacity: isDisabled ? 0.45 : 1,
              transition: 'all 0.2s cubic-bezier(0.4, 0, 0.2, 1)',
              background: isActive ? 'var(--accent-blue)' : 'transparent',
              color: isActive ? 'white' : 'var(--text-tertiary)',
              display: 'flex',
              flexDirection: 'column',
              alignItems: 'center',
              minWidth: 120,
              boxShadow: isActive ? '0 4px 12px rgba(88, 166, 255, 0.25)' : 'none'
            }}
          >
            <span>{opt.label}</span>
            {opt.subtext && <span style={{ fontSize: 10, fontWeight: 400, opacity: 0.8, marginTop: 2 }}>{opt.subtext}</span>}
          </button>
        );
      })}
    </div>
  </div>
);

