function ProjectDashboard({ project, configForm, setConfigForm, connectionStatus }) {
  const updateField = (field, value) => {
    setConfigForm({ ...configForm, [field]: value });
  };

  const isSourceConnected = (() => {
    const srcType = String(configForm.source_type || 'fabric').toLowerCase();
    if (srcType === 'pbix') {
      return Boolean(configForm.pbix_path || configForm.pbix_folder || (Array.isArray(configForm.pbix_models) && configForm.pbix_models.length > 0));
    }
    return connectionStatus?.[srcType]?.status === 'connected';
  })();

  const isTargetConnected = (() => {
    const tgtType = String(configForm.target_type || 'snowflake').toLowerCase();
    return connectionStatus?.[tgtType]?.status === 'connected';
  })();

  return (
    <div style={{ maxWidth: 900, margin: '0 auto', paddingBottom: 120 }}>
      <FormCard title="Pipeline Configuration" subtitle="Control data sources, targets, and synchronization routing.">
        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 24 }}>
          <div>
            <div style={{ display: 'flex', alignItems: 'center' }}>
              <FormLabel>Source Type</FormLabel>
              <ConnectionStatus connected={isSourceConnected} />
            </div>
            <FormSelect value={configForm.source_type || 'fabric'} onChange={e => updateField('source_type', e.target.value)}>
              <option value="fabric">Microsoft Fabric</option>
              <option value="snowflake">Snowflake</option>
              <option value="pbix">Local PBIX</option>
            </FormSelect>
          </div>

          <div>
            <div style={{ display: 'flex', alignItems: 'center' }}>
              <FormLabel>Target Destination</FormLabel>
              <ConnectionStatus connected={isTargetConnected} />
            </div>
            <FormSelect value={configForm.target_type || 'snowflake'} onChange={e => updateField('target_type', e.target.value)}>
              <option value="snowflake">Snowflake</option>
            </FormSelect>
          </div>

          <div style={{ gridColumn: 'span 2' }}>
            {(() => {
              const hasPriorRuns = canProjectUpsert(project);
              return (
                <>
                  <SegmentedControl 
                    label="Sync Strategy"
                    value={hasPriorRuns ? (configForm.write_strategy || 'copy') : 'copy'}
                    onChange={val => {
                      if (val === 'upsert' && !hasPriorRuns) return;
                      updateField('write_strategy', val);
                    }}
                    options={[
                      { label: 'Copy', value: 'copy', subtext: 'Overwrite destination' },
                      { 
                        label: 'Upsert', 
                        value: 'upsert', 
                        disabled: !hasPriorRuns,
                        subtext: hasPriorRuns ? 'Incremental update' : 'Requires first run',
                        tooltip: !hasPriorRuns ? 'Initial deployment requires Copy to establish target views and baseline schemas. Upsert unlocks after first run.' : undefined
                      }
                    ]}
                  />
                  {!hasPriorRuns && (
                    <div style={{ fontSize: 11, color: 'var(--text-tertiary)', marginTop: -14, marginBottom: 16 }}>
                      ℹ️ Initial deployment must use <strong>Copy</strong> to generate target views and tables. <strong>Upsert</strong> will unlock automatically after your first successful run.
                    </div>
                  )}
                </>
              );
            })()}
          </div>

          {String(configForm.source_type || '').toLowerCase() === 'pbix' && (
            <div style={{ gridColumn: 'span 2' }}>
              <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 6 }}>
                <FormLabel>PBIX Source File</FormLabel>
                <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
                  <input
                    type="file"
                    id="pbix-replace-input"
                    accept=".pbix"
                    style={{ display: 'none' }}
                    onChange={async (e) => {
                      const file = e.target.files?.[0];
                      if (!file) return;
                      try {
                        const targetId = project?.id || project?.project_id || configForm?.project_id;
                        const res = targetId
                          ? await api.uploadProjectPbix(targetId, file)
                          : await api.uploadPbix(file);
                        if (res?.path) {
                          updateField('pbix_path', res.path);
                          updateField('pbix_uploaded_path', res.path);
                        }
                      } catch (err) {
                        console.error('Failed to upload PBIX:', err);
                      } finally {
                        e.target.value = '';
                      }
                    }}
                  />
                  <button
                    type="button"
                    onClick={() => document.getElementById('pbix-replace-input')?.click()}
                    style={{
                      background: 'none',
                      border: 'none',
                      color: 'var(--accent-blue)',
                      cursor: 'pointer',
                      fontSize: 12,
                      fontWeight: 600,
                      padding: 0,
                    }}
                  >
                    Replace / Upload PBIX
                  </button>
                </div>
              </div>
              <FormInput
                value={configForm.pbix_path || configForm.pbix_uploaded_path || ''}
                onChange={e => updateField('pbix_path', e.target.value)}
                placeholder="C:/models/Finance.pbix"
              />
              <div style={{ fontSize: 11, color: 'var(--text-tertiary)', marginTop: 4 }}>
                Active PBIX file path for this project. Click 'Replace / Upload PBIX' to upload a modified file.
              </div>
            </div>
          )}

          {/* Workspace Identity / ID and Include Models (Allow-list) fields hidden as requested
          <div style={{ gridColumn: 'span 2' }}>
             <div style={{ display: 'flex', alignItems: 'center' }}>
               <FormLabel>Workspace Identity / ID</FormLabel>
               <HelpTooltip text="Find this UUID in your Microsoft Fabric workspace settings under 'Workspace Settings' -> 'General' -> 'Workspace ID'." />
             </div>
             <FormInput 
               value={configForm.workspace_id || ''} 
               onChange={e => updateField('workspace_id', e.target.value)} 
               placeholder="UUID or Workspace Name"
             />
          </div>

          <div style={{ gridColumn: 'span 2' }}>
            <div style={{ display: 'flex', alignItems: 'center' }}>
              <FormLabel>Include Models (Allow-list)</FormLabel>
              <HelpTooltip text="Comma-separated list of model names to include. Use '*' to include all models in the workspace." />
            </div>
            <FormInput 
              value={configForm.allow_models || ''} 
              onChange={e => updateField('allow_models', e.target.value)} 
              placeholder="model1, model2 or * for all"
            />
          </div>
          */}
        </div>
      </FormCard>

      <FormCard title="Synchronization Options" subtitle="Configure automated relationship detection and metadata generation.">
        <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
          <ToggleSwitch 
            label="Auto-Detect Relationships" 
            description="Automatically map primary/foreign keys based on naming conventions and metadata."
            checked={!!configForm.auto_relationships}
            onChange={val => updateField('auto_relationships', val)}
            showBorder={true}
          />
          <ToggleSwitch
            label="Generate Descriptions"
            description="Use semantic intelligence to automatically generate business descriptions for all fields."
            checked={!!configForm.generate_descriptions}
            onChange={val => updateField('generate_descriptions', val)}
            showBorder={true}
          />
        </div>
      </FormCard>

      <FormCard title="Advanced System Settings" subtitle="Fine-tune technical output formats and system behaviors.">
        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 20 }}>
          <div>
            <div style={{ display: 'flex', alignItems: 'center' }}>
              <FormLabel>Intermediate Format</FormLabel>
              <HelpTooltip text="OSI is the recommended open standard for semantic metadata. JSON is used for raw debugging." />
            </div>
            <FormSelect value={configForm.output_format || 'osi'} onChange={e => updateField('output_format', e.target.value)}>
              <option value="osi">Open Semantic Interface (OSI)</option>
              <option value="json">Raw JSON Metadata</option>
            </FormSelect>
          </div>
          <div>
            <div style={{ display: 'flex', alignItems: 'center' }}>
              <FormLabel>Validation Level</FormLabel>
              <HelpTooltip text="Strict mode ensures all metadata mappings are perfectly valid before deployment." />
            </div>
            <FormSelect value={configForm.validation_level || 'strict'} onChange={e => updateField('validation_level', e.target.value)}>
              <option value="strict">Strict (Fail on Warning)</option>
              <option value="relaxed">Relaxed (Allow Warnings)</option>
            </FormSelect>
          </div>
        </div>
      </FormCard>
    </div>
  );
}

