  const normalizeTreeForYaml = (value) => {
    if (Array.isArray(value)) return value.map(normalizeTreeForYaml);
    if (value && typeof value === 'object') {
      const out = {};
      Object.entries(value).forEach(([k, v]) => {
        if (v === undefined) return;
