          target_type: fallbackTarget,
          output_format: 'osi',
          pbix_path: '',
          pbix_folder: '',
          pbix_uploaded_path: '',
          pbix_models: [],
          identity_id: '',
          workspace_id: '',
          database: '',
          schema: '',
