                placeholder="0 0 0 * * ?"
              />
              <div style={{ fontSize: 11, color: 'var(--text-tertiary)', marginTop: 4 }}>
                Quartz/Oracle format (6 fields): <strong>sec min hour dom month dow</strong>.
