            <div style={{ fontSize: 12, color: 'var(--text-tertiary)' }}>No source snapshots found for this project yet.</div>
          ) : (
            <>
              <div>
                <label style={{ ...LABEL, marginBottom: 6 }}>Snapshot Version</label>
