                    <button
                      type="button"
                      onClick={() => setOverridePbixPath(prev => !prev)}
                      style={{
                        background: 'none',
                        border: 'none',
                        color: 'var(--accent-blue)',
                        cursor: 'pointer',
                        fontSize: 11,
                        fontWeight: 600,
                        padding: 0,
