// Real projects are "active"; drafts (never configured/synced) and transient
// dry-run previews are hidden unless "Show drafts" is on.
function isActiveProject(p) {
  return String(p?.status || '').toLowerCase() === 'active' && !p?.is_transient_preview;
}

const SHOW_DRAFTS_KEY = 'semabridge:projects:showDrafts';

function readShowDrafts() {
  try {
    return localStorage.getItem(SHOW_DRAFTS_KEY) === 'true';
  } catch {
    return false;
  }
}

function readCachedList(key) {
  try {
    const raw = localStorage.getItem(key);
    const parsed = raw ? JSON.parse(raw) : [];
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
}

function writeCachedList(key, value) {
  try {
    localStorage.setItem(key, JSON.stringify(Array.isArray(value) ? value : []));
  } catch {
    // Ignore storage write errors (private mode / quota).
  }
}

