                    })}
                  </div>
                </div>

                {/* Target Filter */}
                <div>
                  <label style={{ fontSize: 11, fontWeight: 600, color: 'var(--text-secondary)', display: 'block', marginBottom: 6 }}>
                    Target (multi-select)
