                          onMouseLeave={e => { if (!tagFilters.has(tag)) { e.currentTarget.style.borderColor = 'var(--border-main)'; } }}
                        >
                          {tag}
                        </button>
                      ))}
                    </div>
                  </div>
                )}

                {/* Clear Filters */}
                {isAnyFilterActive && (
                  <div style={{ display: 'flex', alignItems: 'flex-end' }}>
                    <button
                      onClick={() => {
                        setFilterOptions({
                          sourceFilter: 'all',
                          targetFilter: 'all',
                          targetFilters: [],
                          tagFilters: [],
                        });
                      }}
                      style={{
                        width: '100%', padding: '8px 12px', fontSize: 11, fontWeight: 600,
                        background: 'var(--color-error)20', border: '1.5px solid var(--color-error)40',
                        borderRadius: 6, color: 'var(--color-error)', cursor: 'pointer',
                        transition: 'all 0.2s',
                      }}
                      onMouseEnter={e => { e.currentTarget.style.background = 'var(--color-error)30'; }}
                      onMouseLeave={e => { e.currentTarget.style.background = 'var(--color-error)20'; }}
                    >
                      ✕ Clear All
                    </button>
                  </div>
                )}
              </div>
            </div>
          )}
        </div>

        {/* Table (default) or cards grid */}
        {layout === 'table' && !loading && filtered.length > 0 ? (
          <ProjectsTable
            projects={filtered}
            perProject={portfolio?.per_project || {}}
            ontologyHealth={ontologyHealth}
            allSelected={allVisibleSelected}
            someSelected={selectedVisible.length > 0}
            onToggleAll={toggleSelectAll}
            selectedIds={selectedIds}
            onToggleSelect={toggleSelect}
            onOpen={(p) => { setActiveProjectId(p.id); navigate(`/projects/${p.id}`); }}
            onOpenOntology={(p) => { setActiveProjectId(p.id); navigate(`/projects/${p.id}?tab=ontology`); }}
