    const [query, setQuery] = useState('');

    useEffect(() => {
        const load = async () => {
            setLoading(true);
            try {
                const data = await api.listMappings(projectId);
                // The backend returns { mappings: [...], collisions: [...] }
                // or a direct array in some legacy paths.
                setMappings(Array.isArray(data) ? data : (data?.mappings || []));
            } catch (e) {
                console.error(e);
                setMappings([]);
            } finally {
                setLoading(false);
