                <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 10 }}>
                    {nodes.map((node) => (
                        <div key={node.id} style={{
                            width: 'min(320px, 100%)', padding: '8px 12px', borderRadius: 8,
