                    const fallback = getCachedApiValue(cacheKey);
                    if (fallback != null) {
                        return setCachedApiValue(cacheKey, fallback, 4000);
                    }
                    const persistent = dedupeProjects(readPersistentListCache('semabridge:cache:projects'));
                    if (persistent.length > 0) {
