     * wizard without requiring the user to re-select the same workspace.
     */
    async getFabricDefaultWorkspace(accountId = '') {
        const query = accountId ? `?identity_id=${encodeURIComponent(accountId)}` : '';
        const res = await authFetch(`${API_BASE_URL}/connections/fabric/default-workspace${query}`);
        return handleResponse(res);
    },

    /**
     * Persist a workspace selection globally (mirrors the Settings flow).
     */
    async selectFabricWorkspace({ workspace_id, workspace_name = '' }) {
        const res = await authFetch(`${API_BASE_URL}/connections/fabric/select-workspace`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ workspace_id, workspace_name }),
        });
        return handleResponse(res);
    },

    // ── API Secrets (user-scoped key-value store) ─────────────────────────

    /**
     * List all stored secret keys for the current user.
     * Values are NEVER returned — only the key name, masked hint, and updated_at.
     */
    async listSecrets() {
        const res = await authFetch(`${API_BASE_URL}/settings/secrets`);
        return handleResponse(res);
    },

    /**
     * Create or update a secret for the current user.
     * Key is normalized to UPPER_SNAKE_CASE by the backend.
     */
    async saveSecret({ key, value }) {
        const res = await authFetch(`${API_BASE_URL}/settings/secrets`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ key, value }),
        });
        return handleResponse(res);
    },

    /**
     * Delete a secret by key name for the current user.
     * Also removes the key from the backend os.environ.
     */
    async deleteSecret(key) {
        const res = await authFetch(`${API_BASE_URL}/settings/secrets/${encodeURIComponent(key)}`, {
            method: 'DELETE',
        });
        if (res.status === 204) return null;
        return handleResponse(res);
    },

    // ── LLM Provider Configuration (Tier 5 DAX translation) ────────────────

    /**
     * Status for all 5 LLM providers (OpenAI/Gemini/Groq/Featherless/Anthropic):
     * which source (Settings vs .env vs none) is supplying the key, whether a
     * model has been selected, and a masked hint when Settings-configured.
     */
    async getLlmProviders() {
        const res = await authFetch(`${API_BASE_URL}/settings/llm-providers`);
        return handleResponse(res);
    },

    /**
     * Save (or overwrite) the Settings-configured API key for a provider.
     * The raw key is never returned again after saving.
     */
    async saveLlmProviderApiKey(provider, apiKey) {
        const res = await authFetch(`${API_BASE_URL}/settings/llm-providers/${encodeURIComponent(provider)}/api-key`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ api_key: apiKey }),
        });
        if (res.status === 204) return null;
        return handleResponse(res);
    },

    /**
     * Remove the Settings-configured key for a provider, reverting it to
     * .env-only (if a .env value exists).
     */
    async deleteLlmProviderApiKey(provider) {
        const res = await authFetch(`${API_BASE_URL}/settings/llm-providers/${encodeURIComponent(provider)}/api-key`, {
            method: 'DELETE',
        });
        if (res.status === 204) return null;
        return handleResponse(res);
    },

    /**
     * Live model discovery against the provider's currently effective key
     * (Settings, else .env). Returns { provider, models, truncated, total_available }.
     * Throws on failure — callers should surface err.message (400 no key,
     * 401 bad key, 502 network/provider error, each with a distinct detail).
     */
    async discoverLlmProviderModels(provider) {
        const res = await authFetch(`${API_BASE_URL}/settings/llm-providers/${encodeURIComponent(provider)}/discover-models`, {
            method: 'POST',
        });
        return handleResponse(res);
    },

    /** Save the selected model for a provider (not validated server-side — trust the discovered-models dropdown). */
    async saveLlmProviderModel(provider, model) {
        const res = await authFetch(`${API_BASE_URL}/settings/llm-providers/${encodeURIComponent(provider)}/model`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ model }),
        });
        if (res.status === 204) return null;
        return handleResponse(res);
    },

    async browseDirectory(pathValue = '') {
        const params = new URLSearchParams();
        const normalizedPath = String(pathValue || '').trim();
        if (normalizedPath) params.set('path', normalizedPath);
        const query = params.toString();
        let res = await authFetch(`${API_BASE_URL}/browse-directory${query ? `?${query}` : ''}`);
        if (!res.ok && res.status === 404) {
            res = await authFetch(`${API_BASE_URL}/utils/browse-directory${query ? `?${query}` : ''}`);
        }
        return handleResponse(res);
    },

    // Backward-compatible local-folder APIs used by settings and wizard flows.
    async listLocalFolders(includeInactive = false) {
        try {
            const params = new URLSearchParams();
            if (includeInactive) params.set('include_inactive', 'true');
            const query = params.toString();
            const res = await authFetch(`${API_BASE_URL}/settings/local-folders${query ? `?${query}` : ''}`);
            const data = await handleResponse(res);
            return (data || []).map(normalizeLocalFolder);
        } catch (error) {
            if (isAuthError(error)) return [];
            throw error;
        }
    },

    async saveLocalFolder(payload) {
        const res = await authFetch(`${API_BASE_URL}/settings/local-folders`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(payload || {}),
        });
        const data = await handleResponse(res);
        return normalizeLocalFolder(data);
    },

    async getLocalFolderFiles(tagName) {
        const tag = String(tagName || '').trim();
        if (!tag) throw new Error('Folder tag is required.');
        const res = await authFetch(`${API_BASE_URL}/folders/${encodeURIComponent(tag)}/files`);
        return handleResponse(res);
    },
    async getDatabricksSources(connectionId = '') {
        return _getDatabricksSources(connectionId);
    },

    // ── Password Reset ────────────────────────────────────────────────────

    /**
     * Request a password reset email for the given address.
     * Uses plain fetch — called before the user is authenticated.
     */
    async requestPasswordReset(email) {
        const res = await fetch(`${AUTH_BASE}/forgot-password`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ email }),
        });
        if (!res.ok) {
            const err = await res.json().catch(() => ({}));
            throw new Error(err.detail || 'Failed to request password reset');
        }
        return res.json();
    },

    /**
     * Complete a password reset using the token from the email link.
     * Uses plain fetch — called before the user is authenticated.
     */
    async resetPassword(token, newPassword) {
        const res = await fetch(`${AUTH_BASE}/reset-password`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ token, new_password: newPassword }),
        });
        if (!res.ok) {
            const err = await res.json().catch(() => ({}));
            throw new Error(err.detail || 'Failed to reset password');
        }
        return res.json();
    },
};

// ---------------------------------------------------------------------------
// Internal helper: trigger a file download from a Blob
// ---------------------------------------------------------------------------
function _triggerDownload(blob, filename) {
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 5000);
}

/**
 * cronTranslator.js — Human-friendly cron expression translator & schedule utilities.
 */

const DAYS = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
const MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];

function formatTime(hour, minute) {
  const h = parseInt(hour, 10);
  const m = parseInt(minute, 10);
  if (isNaN(h) || isNaN(m)) return `${hour}:${minute}`;
  const period = h >= 12 ? 'PM' : 'AM';
  const displayHour = h % 12 === 0 ? 12 : h % 12;
  const displayMinute = m < 10 ? `0${m}` : `${m}`;
  return `${displayHour}:${displayMinute} ${period}`;
}

function getOrdinal(n) {
  const num = parseInt(n, 10);
  if (isNaN(num)) return `${n}`;
  const s = ['th', 'st', 'nd', 'rd'];
  const v = num % 100;
  return num + (s[(v - 20) % 10] || s[v] || s[0]);
}

/**
 * Translates a 5-part cron expression into human-readable English.
 * Format: minute hour day-of-month month day-of-week
 */
export function translateCron(cronStr) {
  if (!cronStr || typeof cronStr !== 'string') return 'Manual / On-demand';
  const parts = cronStr.trim().split(/\s+/);
  if (parts.length < 5) return cronStr;

  const [min, hour, dom, mon, dow] = parts;

  // Pattern: Every N minutes (*/N * * * *)
  if (min.startsWith('*/') && hour === '*' && dom === '*' && mon === '*' && dow === '*') {
    const step = min.replace('*/', '');
    return `Every ${step} minutes`;
  }

  // Pattern: Every minute (* * * * *)
  if (min === '*' && hour === '*' && dom === '*' && mon === '*' && dow === '*') {
    return 'Every minute';
  }

  // Pattern: Hourly (0 * * * *)
  if (min === '0' && hour === '*' && dom === '*' && mon === '*' && dow === '*') {
    return 'Every hour, on the hour';
  }

  // Pattern: Every N hours (0 */N * * *)
  if (min === '0' && hour.startsWith('*/') && dom === '*' && mon === '*' && dow === '*') {
    const step = hour.replace('*/', '');
    return `Every ${step} hours`;
  }

  // Exact time specified (min, hour are numbers)
  const isFixedTime = /^\d+$/.test(min) && /^\d+$/.test(hour);
  const timeStr = isFixedTime ? formatTime(hour, min) : null;

  if (timeStr) {
    // Pattern: Daily at HH:MM (M H * * *)
    if (dom === '*' && mon === '*' && dow === '*') {
      return `Every day at ${timeStr}`;
    }

    // Pattern: Weekdays (M H * * 1-5)
    if (dom === '*' && mon === '*' && (dow === '1-5' || dow === 'MON-FRI')) {
      return `Every weekday (Mon–Fri) at ${timeStr}`;
    }

    // Pattern: Specific day of week (M H * * D)
    if (dom === '*' && mon === '*' && /^[0-7]$/.test(dow)) {
      const dayIndex = parseInt(dow, 10) % 7;
      return `Every ${DAYS[dayIndex]} at ${timeStr}`;
    }

    // Pattern: Specific day of month (M H D * *)
    if (/^\d+$/.test(dom) && mon === '*' && dow === '*') {
      return `Monthly on the ${getOrdinal(dom)} at ${timeStr}`;
    }
  }

  // Fallback for custom or multi-value schedules
  return `Custom: ${cronStr}`;
}

/**
 * Formats a relative countdown string from an ISO timestamp.
 * e.g., "in 35 minutes", "tomorrow at 2:00 AM", "in 4 hours"
 */
export function formatRelativeCountdown(nextRunIso) {
  if (!nextRunIso) return null;
  const target = new Date(nextRunIso);
  const now = new Date();
  const diffMs = target.getTime() - now.getTime();

  if (isNaN(diffMs)) return null;
  if (diffMs < 0) return 'Overdue / Running soon';

  const diffMinutes = Math.round(diffMs / (1000 * 60));
  const diffHours = Math.round(diffMs / (1000 * 60 * 60));
  const diffDays = Math.round(diffMs / (1000 * 60 * 60 * 24));

  if (diffMinutes < 60) {
    return `in ${diffMinutes} min${diffMinutes === 1 ? '' : 's'}`;
  }
  if (diffHours < 24) {
    return `in ${diffHours} hour${diffHours === 1 ? '' : 's'}`;
  }
  if (diffDays === 1) {
    return 'Tomorrow';
  }
  return `in ${diffDays} days`;
}

/**
 * Builds a 5-part cron string from friendly preset parameters.
 */
export function buildCronFromPreset({ preset = 'daily', hour = 2, minute = 0, dayOfWeek = 1, dayOfMonth = 1 }) {
  const m = parseInt(minute, 10) || 0;
  const h = parseInt(hour, 10) || 0;

  switch (preset) {
    case 'hourly':
      return `${m} * * * *`;
    case 'daily':
      return `${m} ${h} * * *`;
    case 'weekdays':
      return `${m} ${h} * * 1-5`;
    case 'weekly':
      return `${m} ${h} * * ${dayOfWeek}`;
    case 'monthly':
      return `${m} ${h} ${dayOfMonth} * *`;
    default:
      return `${m} ${h} * * *`;
  }
}

/**
 * normalizeRows — converts a raw /dry-run (or dry-run-job file) API response
 * into the flat row shape DryRunMappingTable and friends consume.
 *
 * Moved verbatim out of CreateProjectPage.jsx so the single-model and the
 * multi-model (per-model dry-run job) flows share exactly ONE normalizer and
 * it can be tested with Node's built-in test runner. The only addition is the
 * `source_file` passthrough used by multi-model rows.
 *
 * The returned object literal is an EXPLICIT ALLOWLIST, not a spread of the
 * raw API row -- any backend field not listed below is dropped before it
 * reaches the rendered table.
 */

export function normalizeStatus(item) {
  const validationStatus = String(item?.validation_status || '').toLowerCase();
  const validationCode = String(item?.validation_code || '').toUpperCase();
  const explicit = String(item?.status || '').toLowerCase();
  const targetField = String(item?.target_field || item?.target_name || item?.target || '').trim();

  if (
    item?.collision_detected === true ||
    validationStatus === 'invalid' ||
    validationStatus === 'collision' ||
    (validationCode && validationCode !== 'OK')
  ) return 'collision';

  if (!targetField) return 'unmapped';
  if (explicit === 'manual') return 'manual';
  // needs_review: a metric that translated to real, deployable SQL via a
  // fallback (e.g. an unshifted time-intelligence approximation) that a
  // human should double-check -- passed through as-is (not collapsed to
  // 'auto') so rowNeedsAttention() in mappingFilterUtils.js can catch it,
  // since 'needs_review' isn't in that file's CLEAN_STATUSES set.
  if (explicit === 'needs_review') return 'needs_review';
  return 'auto';
}

export function parseDatasetFromPath(pathValue) {
  const path = String(pathValue || '').trim();
  if (!path) return '';
  const direct = /^datasets\.([^.]+)$/i.exec(path);
  if (direct?.[1]) return String(direct[1]).trim();
  const nested = /^datasets\.([^.]+)\./i.exec(path);
  if (nested?.[1]) return String(nested[1]).trim();
  return '';
}

export function resolveMeasureSourceTables(row) {
  const fromRow = Array.isArray(row?.measure_source_tables)
    ? row.measure_source_tables.map((item) => String(item || '').trim()).filter(Boolean)
    : [];
  if (fromRow.length > 0) return [...new Set(fromRow)];

  const fallback = parseDatasetFromPath(row?.parent_source_path);
  return fallback ? [fallback] : [];
}

export function resolveColumnSourceTable(row, parentTable = '') {
  const fromPath = parseDatasetFromPath(row?.source_path);
  if (fromPath) return fromPath;

  const fromParentPath = parseDatasetFromPath(row?.parent_source_path);
  if (fromParentPath) return fromParentPath;

  return String(parentTable || row?.parent_table || row?.source_table_name || '').trim();
}

export function resolveMeasureExpression(row) {
  return String(row?.source_expression || row?.measure_expression || row?.expression || '').trim();
}

export function normalizeRows(data) {
  console.log('[normalizeRows] Input data:', data);
  const entityRows = Array.isArray(data?.entity_mappings) ? data.entity_mappings : [];
  console.log('[normalizeRows] Total entity rows:', entityRows.length);
  console.log('[normalizeRows] Entity kinds:', entityRows.map(r => r?.entity_kind));

  if (entityRows.length > 0) {
    const fieldRows = entityRows.filter((row) => {
      const kind = String(row?.entity_kind || '').toLowerCase();
      const isTable = kind === 'table';
      if (isTable) {
        console.log('[normalizeRows] Filtering out table row:', row?.source_entity || row?.source_name);
      }
      return !isTable;
    });

    console.log('[normalizeRows] Field rows after filtering:', fieldRows.length);
    if (fieldRows.length === 0 && entityRows.length > 0) {
      console.error('[normalizeRows] No field rows! Entity kinds present:',
        [...new Set(entityRows.map(r => r?.entity_kind))]);
    }

    return fieldRows.map((row, index) => {
      const kind = String(row?.entity_kind || 'column').toLowerCase();
      const isMeasure = kind === 'metric' || kind === 'measure';
      const sourceName = String(row?.source_name || row?.name || '').trim();
      const targetName = String(row?.target_name || row?.name || '').trim();
      return {
        id: String(row?.id || `entity-${index}`),
        project_id: String(row?.project_id || data?.project_id || ''),
        model_name: String(row?.model_name || data?.model_name || data?.semantic_model_name || ''),
        source_field: sourceName || `field_${index + 1}`,
        source_path: String(row?.source_path || '').trim(),
        entity_kind: kind,
        parent_source_path: String(row?.parent_source_path || '').trim(),
        source_type: String(row?.source_data_type || row?.data_type || kind || 'unknown'),
        field_type: isMeasure ? 'measure' : 'column',
        measure_source_tables: isMeasure ? resolveMeasureSourceTables(row) : [],
        source_table_name: !isMeasure ? resolveColumnSourceTable(row) : '',
        measure_expression: isMeasure ? resolveMeasureExpression(row) : '',
        target_field: targetName,
        target_type: String(row?.target_data_type || row?.source_data_type || row?.data_type || 'unknown'),
        status: row?.collision_detected ? 'collision' : normalizeStatus({ ...row, target_field: targetName }),
        validation_status: String(row?.validation_status || ''),
        validation_code: String(row?.validation_code || ''),
        validation_message: String(row?.validation_message || ''),
        suggested_target_name: String(row?.suggested_target_name || ''),
        collision_detected: Boolean(row?.collision_detected),
        // Backend rename options for a collision (emitter's to_alias rules,
        // first = recommended, unique in the row's namespace) and that
        // namespace (columns: per logical table) -- Resolve / Resolve All
        // use these before any local fallback.
        resolution_suggestions: Array.isArray(row?.resolution_suggestions)
          ? row.resolution_suggestions.map(String).filter(Boolean)
          : [],
        mapping_scope: String(row?.mapping_scope || ''),
        // { from, to } when the column's Snowflake name differs from its
        // last deployed name (e.g. COL_DATE -> DATE); see nameChanges.js.
        deployed_name_change: (row?.deployed_name_change && row.deployed_name_change.from && row.deployed_name_change.to)
          ? { from: String(row.deployed_name_change.from), to: String(row.deployed_name_change.to) }
          : null,
        target_expression: row?.target_expression || '',
        sync_enabled: row?.sync_enabled === false || (isMeasure && Boolean((row?.source_expression || row?.measure_expression || row?.expression || '').trim()) && !Boolean(String(row?.target_expression || '').trim())) ? false : true,
        sync_failure_reason: row?.sync_failure_reason || (isMeasure && Boolean((row?.source_expression || row?.measure_expression || row?.expression || '').trim()) && !Boolean(String(row?.target_expression || '').trim()) ? 'DAX translation unavailable: no SQL expression produced' : ''),
        depends_on_measures: Array.isArray(row?.depends_on_measures) ? row.depends_on_measures : [],
        synonym_overrides: Array.isArray(row?.synonym_overrides) ? row.synonym_overrides : [],
        synonyms: Array.isArray(row?.synonyms) ? row.synonyms : [],
        // Provenance per synonym ('report_alias' | 'tmsl_authored' |
        // 'manual_override' | 'auto_generated') -- the backend has sent
        // this correctly all along; it was silently dropped here by the
        // same allowlist-gap pattern as static_risk_tier/advisory_categories
        // below, so DryRunMappingTable's synonymSources lookup always saw
        // undefined and rendered every synonym as "Unknown Source".
        synonym_sources: (row?.synonym_sources && typeof row.synonym_sources === 'object') ? row.synonym_sources : {},
        has_report_alias: Boolean(row?.has_report_alias),
        // Static risk tier (metric-only; null for columns) and the Tier-5
        // provider's own self-reported estimate (metric-only, Tier-5-
        // only; null otherwise) -- see utils/riskLabels.js and
        // project_mapping_engine.py's _compute_static_risk_tier. Passed
        // through as-is (no renaming/coercion): both are already null
        // for every row that shouldn't show them, straight from the
        // backend.
        static_risk_tier: row?.static_risk_tier ?? null,
        static_risk_label: row?.static_risk_label ?? null,
        llm_self_reported_confidence: row?.llm_self_reported_confidence ?? null,
        // advisory_categories: general-purpose, informational-only tags
        // (see sml/models.py's SMLMetric.advisory_categories) -- e.g.
        // 'enrichment_column_unverifiable' (utils/riskLabels.js's
        // getEnrichmentUnverifiableCaveat). Was already returned by the
        // backend but silently dropped here before this fix -- same
        // allowlist-gap pattern as static_risk_tier/llm_self_reported_
        // confidence above.
        advisory_categories: Array.isArray(row?.advisory_categories) ? row.advisory_categories : [],
        // Which source file this row came from (multi-model dry runs only;
        // null for single-model rows). Display-only -- see
        // mappingFilterUtils.rowSourceFileName.
        source_file: row?.source_file || data?.source_file || null,
        advisory_notes: Array.isArray(row?.advisory_notes) ? row.advisory_notes : [],
        // Tables that have a column with this same name (info only; see
        // project_mapping_engine._flag_hidden_collisions).
        shared_name_tables: Array.isArray(row?.shared_name_tables) ? row.shared_name_tables : [],
        // Original source name when conversion renamed the column because
        // another column of its table becomes the same Snowflake name.
        renamed_from: row?.renamed_from ? String(row.renamed_from) : '',
        complexity_tier: row?.complexity_tier ?? null,
        isDirty: false,
      };
    });
  }

  const rows = [];
  const tableMappings = Array.isArray(data?.mappings) ? data.mappings : [];
  tableMappings.forEach((table, tableIndex) => {
    const tableSource = String(table?.source || table?.name || '').trim();
    const columns = Array.isArray(table?.columns) ? table.columns : [];

    if (columns.length === 0) {
      return;
    }

    columns.forEach((column, columnIndex) => {
      const colSource = String(column?.source || column?.name || '').trim();
      const colTarget = String(column?.target || '').trim();
      const fieldType = String(column?.field_type || '').toLowerCase() === 'measure' ? 'measure' : 'column';
      rows.push({
        id: `${table?.id || tableSource || `t${tableIndex}`}::${column?.source_path || colSource || columnIndex}`,
        project_id: String(column?.project_id || data?.project_id || ''),
        model_name: String(column?.model_name || data?.model_name || data?.semantic_model_name || ''),
        source_field: colSource || `column_${columnIndex + 1}`,
        source_path: String(column?.source_path || '').trim(),
        entity_kind: String(column?.entity_kind || 'column').toLowerCase(),
        source_type: String(column?.type || column?.data_type || 'unknown'),
        field_type: fieldType,
        source_table_name: resolveColumnSourceTable(column, tableSource),
        measure_source_tables: [],
        measure_expression: '',
        target_field: colTarget,
        target_type: String(column?.type || column?.data_type || 'unknown'),
        status: normalizeStatus({ ...column, target_field: colTarget }),
        validation_status: String(column?.validation_status || ''),
        validation_code: String(column?.validation_code || ''),
        validation_message: String(column?.validation_message || ''),
        suggested_target_name: String(column?.suggested_target_name || ''),
        collision_detected: Boolean(column?.collision_detected),
        target_expression: column?.target_expression || '',
        sync_enabled: column?.sync_enabled !== false,
        sync_failure_reason: column?.sync_failure_reason || '',
        depends_on_measures: Array.isArray(column?.depends_on_measures) ? column.depends_on_measures : [],
        parent_table: tableSource,
        synonym_overrides: Array.isArray(column?.synonym_overrides) ? column.synonym_overrides : [],
        isDirty: false,
      });
    });
  });

  return rows;
}

